insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'bank', 0, $official_bank_source${"code":"LAG-BUA125","courseId":"caf0ea5d-6cc0-5bd0-8719-c6f1a95ceec1","seedActor":"00000000-0000-4000-8000-000000000042","actor":"00000000-0000-4000-8000-000000000043","bankCount":572,"shell":{"contentKey":"managerial-economics","titles":["Managerial Economics"],"level":"100-level","semesters":["first-semester"]},"rows":{"audited":0,"keep":0,"retire":0,"add":572}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 1, $official_bank_source${"itemId":"6cdf10e3-0ba6-5d73-b68f-20366ed96ce0","questionId":"0bad2140-fdfa-55fd-abdd-c7e300aaa138","sourceKey":"bank:LAG-BUA125:PQ-001-a","payload":{"prompt":"Which of the following best defines Managerial Economics?","options":["The use of economic theories, concepts and models to make business decisions in any type of organisation","The study of how a central bank controls the money supply and interest rates","The study of how managers motivate and lead their employees","The recording and summarising of a firm's financial transactions"],"correctOption":0,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Managerial economics applies economic theories, concepts and models to improve decision making, whatever the type of organisation, so option A is right. Option B describes monetary policy, which is a government and central bank matter. Option D is accounting, and option C is about leadership and human relations, not economic analysis of decisions."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 2, $official_bank_source${"itemId":"c3c0e57a-d107-5335-9ce5-4a660c3a55cf","questionId":"6b18b738-53f3-5248-83c4-40738ccfc5c6","sourceKey":"bank:LAG-BUA125:PQ-001-b","payload":{"prompt":"Managerial economics is useful for decision making in which of the following?","options":["Profit-making companies only","Profit-making organisations, non-profit organisations and the public sector","Government ministries and agencies only","Multinational companies only"],"correctOption":1,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Option B is correct because managers in every kind of organisation, from a sole proprietorship to an NGO or a government ministry, must decide how to use scarce resources, and managerial economics tools apply to all of them. Options A, C and D each wrongly limit it to one group; a Vice Chancellor, a Commissioner or the head of a charity also performs managerial decision making."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 3, $official_bank_source${"itemId":"dc993ebb-96b7-5027-9ac0-0c35a824f606","questionId":"3cc493cc-103b-5bed-be50-26c6d824db51","sourceKey":"bank:LAG-BUA125:PQ-002-a","payload":{"prompt":"Which of the following is a goal of managerial economics?","options":["Employing as many workers as possible regardless of output","Removing every form of risk from business decisions","Replacing managers' decisions with government directives","Achieving optimum allocation of the organisation's resources"],"correctOption":3,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"A central goal of managerial economics is optimum resource allocation: putting scarce men, money and materials to their best use, so option D is right. Option A ignores efficiency, which is another important goal. Option B is impossible, since decisions are always made with some risk, and option C contradicts the whole idea of improving managers' own decision making."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 4, $official_bank_source${"itemId":"a19d3ef6-0039-505e-a7fb-f32a6e3db6f9","questionId":"fa9ca3d6-be03-58b3-b899-96fe601744f4","sourceKey":"bank:LAG-BUA125:PQ-002-b","payload":{"prompt":"A firm is choosing whether to finance its expansion with a bank loan, new equity or debentures. Which type of managerial decision is this?","options":["A decision on the use of capital","A decision on labour usage and size","A decision on production techniques","A decision on equipment replacement"],"correctOption":0,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Choosing between loans, equity, debentures, bonds and similar funding sources is a decision on the use of capital, option A. Option D would be about when to replace old machines, option C about the mix of labour and technology used in production, and option B about how many and what category of workers to employ."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 5, $official_bank_source${"itemId":"f3149f45-c741-53a3-9eb7-54808dd06892","questionId":"ad0cd767-6c0e-5caf-a8f2-b8a2ca50d5cf","sourceKey":"bank:LAG-BUA125:PQ-006-a","payload":{"prompt":"Which of the following belongs to the macroeconomic side of the scope of managerial economics?","options":["A firm's production decisions","Demand and supply of a product","Interest rates and foreign exchange","Profit maximisation by a firm"],"correctOption":2,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Macroeconomics deals with economy-wide variables such as interest rates, foreign exchange, total output, unemployment and income distribution, so option C is right. Options B, A and D are microeconomic topics because they concern individual products, firms and their decisions."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 6, $official_bank_source${"itemId":"0575a75a-a37d-5019-8646-7d0381de7419","questionId":"21f4469a-44bf-579b-a9d3-a268178de4c2","sourceKey":"bank:LAG-BUA125:PQ-006-b","payload":{"prompt":"The management board of a hospital is deciding whether to replace its old X-ray machines now or keep using them for another two years. This is a managerial decision on:","options":["Labour usage and size","Equipment replacement","Price discrimination","Market segmentation"],"correctOption":1,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Deciding when to replace ageing machines is an equipment replacement decision, option B, and it shows that managerial economics applies to non-profit and public organisations too. Option A concerns the number and category of staff, option D is about dividing customers into groups, and option C is a pricing practice of monopolies."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 7, $official_bank_source${"itemId":"d10bcfbb-dba0-5ea5-93a8-926cf2e1e1fe","questionId":"f6cae5de-94b0-502c-9db7-1a787a7744d3","sourceKey":"bank:LAG-BUA125:PQ-006-c","payload":{"prompt":"When managerial economics helps a firm achieve optimum resource allocation, it means the firm's resources are:","options":["Kept idle as a reserve for emergencies","Spent as quickly as possible","Put to the uses that give the greatest benefit at the lowest cost","Shared equally among all departments"],"correctOption":2,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Optimum allocation means directing scarce resources to the uses that create the most value for the least cost, option C. Option D sounds fair but ignores which department gives the best return. Options B and A describe spending fast or hoarding, neither of which is efficient use of resources."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 8, $official_bank_source${"itemId":"44accb74-590c-5359-b2b9-b4acb3386d0b","questionId":"b835c047-a87e-5f98-b645-f1c7e2118333","sourceKey":"bank:LAG-BUA125:PQ-019","payload":{"prompt":"Which of the following is NOT a factor of production?","options":["Land","A bank loan","Capital","Labour"],"correctOption":1,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"A bank loan, option B, is a form of finance that a firm uses to buy real resources; it is not itself a factor of production. Land, labour and capital (options A, D and C), together with entrepreneurship, are the factors of production. In economics, capital means man-made goods such as machines and buildings, not money."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 9, $official_bank_source${"itemId":"b1dada3a-abcb-514b-a297-7fa831ac0678","questionId":"ccb188f8-cc66-522a-b09e-36fdcb1a25d1","sourceKey":"bank:LAG-BUA125:PQ-020","payload":{"prompt":"Macroeconomics deals with:","options":["Economic aggregates such as total output and unemployment","The behaviour of a single industry such as electronics","The activities of individual units such as households","The behaviour of individual firms"],"correctOption":0,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Macroeconomics studies the economy as a whole, using aggregates such as national output, unemployment, interest rates and foreign exchange, so option A is right. Options D, C and B all concern individual decision-making units or single industries, which is microeconomics."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 10, $official_bank_source${"itemId":"3a83fa8d-e168-53d6-9a40-abb027f0af8a","questionId":"62e5dfc5-24d8-5026-ba86-012ea927a58e","sourceKey":"bank:LAG-BUA125:PQ-021","payload":{"prompt":"Microeconomics is NOT concerned with the behaviour of:","options":["Aggregate demand","Consumers","Industries","Firms"],"correctOption":0,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Aggregate demand, option A, is the total demand in the whole economy, so it belongs to macroeconomics. Microeconomics studies individual units such as consumers, firms and particular industries, which rules out options B, C and D."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 11, $official_bank_source${"itemId":"e6ac0c55-2801-55b8-9bc7-4d8bb8eada00","questionId":"f530d97a-6808-58a0-b64e-37fa777dd3b6","sourceKey":"bank:LAG-BUA125:PQ-025","payload":{"prompt":"If the marginal benefit of an activity is greater than its marginal cost, a rational decision maker should:","options":["Do more of the activity","Do less of the activity","Stop the activity completely","Keep the activity at its current level"],"correctOption":0,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"When the extra benefit of one more unit exceeds its extra cost, doing more adds to net benefit, so option A is right; the rational stopping point is where marginal benefit equals marginal cost. Option B would reduce net benefit, and options C and D ignore the gain still available from expanding."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 12, $official_bank_source${"itemId":"ec8d8001-89e9-574d-9844-8701720841f5","questionId":"8950a3a3-b718-5e93-bbb1-9828bb3c7697","sourceKey":"bank:LAG-BUA125:PQ-044","payload":{"prompt":"Which of the following correctly lists the four factors of production?","options":["Labour, capital, money and technology","Land, labour, capital and entrepreneurship","Land, labour, money and entrepreneurship","Land, labour, money and machinery"],"correctOption":1,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"The four factors of production are land, labour, capital and entrepreneurship, option B. Options C, D and A all include money, which is a medium of exchange used to buy resources, not a factor of production itself."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 13, $official_bank_source${"itemId":"a1cc33f4-0885-561f-8b36-0b8dfb233c6b","questionId":"c5e65e55-4614-520c-8052-4633dedeff8e","sourceKey":"bank:LAG-BUA125:PQ-171","payload":{"prompt":"In standard economic theory, the owners of a business firm are typically assumed to aim to:","options":["maximise profits","minimise the prices charged to customers","maximise the number of workers employed","maximise the firm's tax payments"],"correctOption":0,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"The traditional theory of the firm assumes that owners of profit-seeking firms want the largest possible difference between total revenue and total cost. Options C, B and D are not the goal economists assume for owners, even though a firm may consider employment or pricing as part of its strategy."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 14, $official_bank_source${"itemId":"47ab23da-40a3-5113-8396-be26261ce029","questionId":"60e82839-1539-5109-b3ee-648c0b039930","sourceKey":"bank:LAG-BUA125:INT-001","payload":{"prompt":"The use of economic theories, concepts and models to make business decisions, irrespective of the type or category of organisation, is called:","options":["Managerial economics","Financial accounting","Macroeconomic policy","Business law"],"correctOption":0,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Managerial economics applies economic theories, concepts and models to business decisions in any kind of organisation. Option B is about recording and reporting transactions, Option C concerns government management of the whole economy, and Option D deals with the legal rules of business, not economic analysis of decisions."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 15, $official_bank_source${"itemId":"f18b42ad-1916-50ae-a96a-ad629257aa84","questionId":"4c577291-726a-5c50-b853-79a5cbedee35","sourceKey":"bank:LAG-BUA125:INT-002","payload":{"prompt":"Which of the following best describes managerial economics?","options":["The study of how laws on company formation are made and enforced","The recording and summarising of a firm's financial transactions for shareholders","The application of economic tools to improve and enhance managers' decision making","The study of how the central bank controls the money supply of a country"],"correctOption":2,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Managerial economics is about applying economic tools to help managers make better decisions. Option B describes accounting, Option D describes monetary policy, and Option A describes company law; none of these is the decision-focused use of economics."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 16, $official_bank_source${"itemId":"f1361eff-bd66-5147-b835-4dd0970e6091","questionId":"cce16d0b-d150-5d3f-87d9-acb2ab52f553","sourceKey":"bank:LAG-BUA125:INT-003","payload":{"prompt":"Managerial economics is regarded as a subfield of economics mainly because it:","options":["Is concerned only with the keeping of cash books and ledgers","Focuses on the production, distribution and consumption of goods and services","Is concerned only with the personal behaviour of workers in groups","Focuses on the legal registration of business names and companies"],"correctOption":1,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Like economics as a whole, managerial economics deals with how goods and services are produced, distributed and consumed, which is why it sits inside economics. Option D is a legal matter, Option A is bookkeeping, and Option C belongs to organisational behaviour."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 17, $official_bank_source${"itemId":"e9903a09-e43f-50c7-bc7e-6186f69f20ab","questionId":"b73e3e2e-977b-5f02-8d30-871e0b2c4388","sourceKey":"bank:LAG-BUA125:INT-004","payload":{"prompt":"The application of managerial economics covers which types of organisations?","options":["Profit-making organisations, non-profit-making organisations and the public sector","Profit-making organisations only","Public-sector organisations only","Multinational companies and their foreign subsidiaries only"],"correctOption":0,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Managerial economics is useful wherever decisions about production, distribution and consumption are made, so it covers profit-making firms, non-profit bodies and government. Options B, C and D each wrongly limit it to one group of organisations."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 18, $official_bank_source${"itemId":"1a42818c-47f6-5adc-9733-51f381cfcc58","questionId":"3850e025-013e-57cd-94ea-a521e4d2e601","sourceKey":"bank:LAG-BUA125:INT-005","payload":{"prompt":"Which of the following is NOT one of the three business categories in which managerial economics is applied?","options":["Profit-making organisations","Non-profit-making organisations","Foreign exchange markets","The public sector"],"correctOption":2,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"The three business categories are profit-making organisations, non-profit-making organisations and the public sector. Foreign exchange is a macroeconomic variable within the scope of the subject, not a category of organisation, so Options A, B and D are all genuine categories."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 19, $official_bank_source${"itemId":"5f3b72d0-5e7f-5871-be56-66b5efc2edd4","questionId":"21fed273-53bd-537a-a9c3-5b4ca9778322","sourceKey":"bank:LAG-BUA125:INT-006","payload":{"prompt":"Managerial economics is described as strategic in business mainly because its application covers:","options":["Only the spending decisions of households","Both microeconomic and macroeconomic concepts","Only the pricing decisions of monopolies","Only the accounting records of public companies"],"correctOption":1,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Managerial economics is strategic because it draws on microeconomics (households, individuals and firms) as well as macroeconomics (the nation, region or wider society). Options C, A and D each pick out one narrow area and miss this two-level coverage."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 20, $official_bank_source${"itemId":"c0aa24c8-c006-513f-a3b1-1061ff1f4e93","questionId":"f8118f89-bcf8-5635-87aa-9f612efd526d","sourceKey":"bank:LAG-BUA125:INT-007","payload":{"prompt":"Which of the following falls under the MICROECONOMIC part of the scope of managerial economics?","options":["Interest rates","Foreign exchange","Unemployment","Opportunity cost"],"correctOption":3,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Opportunity cost is a decision concept used at the level of the individual firm or household, so it belongs to the microeconomic scope. Options A, C and B are economy-wide variables that make up the macroeconomic scope."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 21, $official_bank_source${"itemId":"a2b76629-36e7-5851-9f5f-a4653f052c04","questionId":"6f0ee128-117f-58ee-a8d3-c71dc48d4b7e","sourceKey":"bank:LAG-BUA125:INT-008","payload":{"prompt":"Which of the following falls under the MACROECONOMIC part of the scope of managerial economics?","options":["Market equilibrium","Production","Market competition","Distribution of income"],"correctOption":3,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Distribution of income across the society is an economy-wide issue, so it belongs to the macroeconomic scope together with output, unemployment, interest rates and foreign exchange. Options A, B and C are microeconomic topics that deal with individual markets and firms."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 22, $official_bank_source${"itemId":"fc52d2f6-84ea-590d-bc46-ea65965d7680","questionId":"e34773c5-4ec1-523e-bd0e-6f56e084c9ed","sourceKey":"bank:LAG-BUA125:INT-009","payload":{"prompt":"Which of the following is NOT part of the microeconomic scope of managerial economics?","options":["Demand and supply","Profit maximisation","Equilibrium","Interest rates"],"correctOption":3,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Interest rates are set at the level of the whole economy, so they belong to the macroeconomic scope. Options A, B and C are all microeconomic topics that managers apply to individual products, firms and markets."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 23, $official_bank_source${"itemId":"260bac1a-307a-55d2-bf9d-3b3781df6d6e","questionId":"de59ab11-3983-5a29-991e-1f82c783fac3","sourceKey":"bank:LAG-BUA125:INT-010","payload":{"prompt":"Which of the following is NOT part of the macroeconomic scope of managerial economics?","options":["Output","Population and distribution","Unemployment","Market competition"],"correctOption":3,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Market competition describes rivalry between firms in a particular market, which is a microeconomic topic. Options A, B and C are national or regional aggregates and therefore belong to the macroeconomic scope."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 24, $official_bank_source${"itemId":"cc694f61-f163-5d3e-8751-2f7f4b199168","questionId":"e602cd81-2eae-5f98-9058-3ef7c78eeb2d","sourceKey":"bank:LAG-BUA125:INT-011","payload":{"prompt":"Which statement about managerial positions is correct?","options":["They exist only in multinational companies with foreign branches","They also exist in public and non-profit organisations under titles such as Minister, Dean or Coordinator","They exist only in profit-making firms that use the job title 'manager'","They exist only in companies whose shares are quoted on a stock exchange"],"correctOption":1,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Managerial roles are not limited to profit-making firms; they are found in the public sector and non-profit bodies under titles such as HoD, Minister, Commissioner, DG, Vice Chancellor, Provost or Dean. Options C, D and A wrongly tie management to one kind of firm or one job title."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 25, $official_bank_source${"itemId":"4d5ec039-e5e2-5a53-ba19-7455f6f02a76","questionId":"239dc95a-5823-5925-a35f-183fcbe14f44","sourceKey":"bank:LAG-BUA125:INT-012","payload":{"prompt":"A State Commissioner for Health uses population figures and cost estimates to decide where to site three new primary health centres. This is an application of managerial economics in:","options":["A multinational company","A non-profit-making organisation","A profit-making organisation","The public sector"],"correctOption":3,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"A Commissioner works for a State Government, which is part of the public sector, and is using economic tools to allocate public resources. Option C and Option A are business firms, and Option B would be a body such as an NGO, club or faith-based organisation."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 26, $official_bank_source${"itemId":"135ee982-d2a9-51d4-b163-62da9314e59e","questionId":"a56f9d16-e3cb-5611-89dd-35ceaa10eaa1","sourceKey":"bank:LAG-BUA125:INT-013","payload":{"prompt":"A Red Cross Society branch in Ibadan must decide how to split donated funds between first-aid training and flood relief. Which category of organisation is applying managerial economics here?","options":["A non-profit-making organisation","The public sector","A partnership","A profit-making organisation"],"correctOption":0,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"The Red Cross Society is an NGO, which is a non-profit-making organisation, and it still has to allocate scarce funds between competing uses. Options D and C are profit-seeking businesses, while Option B refers to government and its agencies."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 27, $official_bank_source${"itemId":"752daa90-cab5-5580-afd3-cd566dcb0fc7","questionId":"037a1567-db65-52e8-ab34-5da2cae2a6eb","sourceKey":"bank:LAG-BUA125:INT-014","payload":{"prompt":"Which of the following is an example of a non-profit-making organisation?","options":["A partnership of two lawyers","A multinational oil company","A Federal Ministry","The Rotary Club"],"correctOption":3,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Clubs and societies such as the Rotary Club or Lions Club are non-profit-making organisations. Option C is part of the public sector, while Options A and B are profit-making organisations."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 28, $official_bank_source${"itemId":"b45e5f47-aee9-5b56-9570-a05484534064","questionId":"68ab1aa5-fd45-50b4-baea-e9ca7568f751","sourceKey":"bank:LAG-BUA125:INT-015","payload":{"prompt":"Which of the following belongs to the public sector?","options":["An orphanage such as SOS Children's Village","A Local Government council","A sole proprietorship","An Islamic society such as NASFAT"],"correctOption":1,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Local Governments are part of the public sector, along with State and Federal Government bodies, public corporations and welfare boards. Options A and D are non-profit-making organisations, and Option C is a profit-making business."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 29, $official_bank_source${"itemId":"cd0fcf3a-f13f-5a35-a0dd-ccd1725f0354","questionId":"8abd6446-b29c-5bae-924b-276792694ec5","sourceKey":"bank:LAG-BUA125:INT-016","payload":{"prompt":"Which of the following is NOT a profit-making organisation?","options":["A sole proprietorship","A partnership","A faith-based organisation such as a church","A limited liability company"],"correctOption":2,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Faith-based organisations, such as churches and Islamic societies, are non-profit-making organisations. Options A, B and D are all forms of profit-making business."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 30, $official_bank_source${"itemId":"3bc50ffa-c40a-5759-bf1c-de356d2ada8e","questionId":"49d0e2f9-dc0e-5c44-8bee-9f33b80acff4","sourceKey":"bank:LAG-BUA125:INT-017","payload":{"prompt":"Which of the following is NOT a non-profit-making organisation?","options":["A traditional age grade","A real-estate limited liability company","The Girls' Brigade","Doctors Without Borders (MSF)"],"correctOption":1,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"A real-estate limited liability company exists to earn profit for its owners, so it is a profit-making organisation. Options D, C and A are an NGO, a youth organisation and a traditional society, all non-profit-making."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 31, $official_bank_source${"itemId":"39dec66d-0541-52f5-976c-4281b3628804","questionId":"dab49217-a7cd-5938-87bf-5c3f2bbbed4b","sourceKey":"bank:LAG-BUA125:INT-018","payload":{"prompt":"Which group contains ONLY public-sector bodies?","options":["Churches, Islamic societies and age grades","State government agencies, local governments and public corporations","NGOs, orphanages and international clubs","Sole proprietorships, partnerships and multinational companies"],"correctOption":1,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"The public sector is made up of Federal, State and Local Governments, their agencies, public corporations and welfare boards. Options C and A list non-profit-making organisations, and Option D lists profit-making organisations."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 32, $official_bank_source${"itemId":"ed78a3b4-982e-510d-8478-da81fb9e0b12","questionId":"ae513cbf-e1ab-5cfa-b7cf-4321fd121d52","sourceKey":"bank:LAG-BUA125:INT-020","payload":{"prompt":"Which of the following is NOT one of the goals and objectives of managerial economics?","options":["Achieving operational efficiency in business administration","Preparing the statutory audit report of a company","Enhancing and improving decision making in business","Guiding decisions on equipment replacement"],"correctOption":1,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Preparing a statutory audit report is an auditing task, not a goal of managerial economics. Options A, C and D are all goals of the subject, which aims at efficiency, better decisions and sound choices such as when to replace equipment."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 33, $official_bank_source${"itemId":"7de125a2-5778-5b42-bf4b-50e8dd3effae","questionId":"7c23dc89-35bd-51d0-bbdf-1fb2466ae1a2","sourceKey":"bank:LAG-BUA125:INT-021","payload":{"prompt":"A non-profit school is choosing between financing a new hostel with donations or with a bank overdraft. This is a decision on:","options":["Labour usage and size","The use of capital","Production technique","Equipment replacement"],"correctOption":1,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Choosing among sources of funds such as loans, overdrafts, equity, debentures, bonds or donations is a decision on the use of capital. Option A is about how many and what kind of workers to employ, Option C is about combining labour and technology, and Option D is about when to replace machines."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 34, $official_bank_source${"itemId":"403a5f6b-b6e9-5ed1-b91e-be5f0119a96e","questionId":"924b2a14-a520-59c7-8a46-d8c651f2ca43","sourceKey":"bank:LAG-BUA125:INT-022","payload":{"prompt":"A Lagos bank decides to cut its staff by 150 and to recruit more IT specialists. In managerial economics this is a decision on:","options":["Labour usage and size","Foreign exchange","The use of capital","Equipment replacement"],"correctOption":0,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Decisions about the number and category of workers, employment and down-sizing are decisions on labour usage and size. Option C concerns sources of funds, Option D concerns replacing machines, and Option B is a macroeconomic variable rather than a decision area."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 35, $official_bank_source${"itemId":"df1ac914-0b89-57ac-aee2-7ba0cba03760","questionId":"e3c98e67-7d47-5653-be11-9b54003f8bb3","sourceKey":"bank:LAG-BUA125:INT-023","payload":{"prompt":"A garment factory in Aba is deciding how many sewing machines to install and how many tailors to keep so as to produce at the lowest cost. This is mainly a decision on:","options":["Production technique and the balance between labour and technology","The choice of legal form of the business","The use of capital such as debentures and bonds","The distribution of national income"],"correctOption":0,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Deciding how to combine machines (technology) and workers (labour) to produce efficiently is a decision on production technique. Option C is about how to raise money, Option D is a macroeconomic issue, and Option B is about whether the firm is a sole proprietorship, partnership or company."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 36, $official_bank_source${"itemId":"a4d17ba9-3f0c-5312-8f9e-f3836b98ad3d","questionId":"fdda9881-bd33-5376-902a-96f4fde92f00","sourceKey":"bank:LAG-BUA125:INT-025","payload":{"prompt":"Managerial economics is often described as a link between traditional economic theory and:","options":["The decision sciences, such as mathematics, statistics and econometrics","History and archaeology","Constitutional and criminal law","Literature and the creative arts"],"correctOption":0,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Managerial economics combines economic theory with decision-science tools such as mathematics, statistics and econometrics to solve management problems. Options D, B and C are disciplines that do not supply the quantitative tools used in business decision making."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 37, $official_bank_source${"itemId":"734b22b0-a2ca-5e6e-ba7c-d6056d6942aa","questionId":"d74f39ea-2bb9-5259-bbd1-8b40c3de00bd","sourceKey":"bank:LAG-BUA125:INT-026","payload":{"prompt":"Managerial economics is said to be largely normative (prescriptive) because it:","options":["Only describes what happened in the past without recommending any action","Deals only with the total output of the national economy","Is concerned with what managers ought to do to achieve their objectives","Avoids the use of quantitative tools in analysis"],"correctOption":2,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Managerial economics is prescriptive: it recommends the course of action that best achieves the organisation's goals. Option A describes a purely positive, descriptive approach, Option B describes macroeconomics, and Option D is wrong because the subject relies heavily on quantitative tools."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 38, $official_bank_source${"itemId":"f7612032-bfda-5116-b587-50d7db0227f6","questionId":"ef6028b3-fa52-5902-9382-e24b4444edce","sourceKey":"bank:LAG-BUA125:INT-027","payload":{"prompt":"Which statement about the nature of managerial economics is correct?","options":["It is mainly concerned with decision problems of the individual organisation but also takes account of macroeconomic conditions","It is concerned only with the economy as a whole and ignores individual firms","It applies only to firms that are owned by the government","It is a purely theoretical subject with no practical business use"],"correctOption":0,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Managerial economics focuses on decisions inside individual organisations (a microeconomic orientation) while still using macroeconomic conditions such as interest rates and exchange rates as background. Option B reverses this focus, Option D ignores its applied nature, and Option C wrongly restricts it to government-owned firms."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 39, $official_bank_source${"itemId":"b0efeaa9-53ee-57f2-976d-968b8dc42faf","questionId":"55717056-bad0-508a-a1cb-9abde4cc7d64","sourceKey":"bank:LAG-BUA125:INT-028","payload":{"prompt":"How does managerial economics mainly differ from traditional economic theory?","options":["It uses no economic concepts at all","It deals only with the history of economic ideas","It is concerned only with consumers and ignores producers","It is applied and practical, aiming to solve real decision problems of organisations"],"correctOption":3,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Managerial economics takes economic theory and applies it to practical problems such as pricing, production and investment decisions. Option A is false because it is built on economic concepts, Option B describes the history of economic thought, and Option C wrongly ignores producers, who are its main users."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 40, $official_bank_source${"itemId":"0ec040e3-8ddd-5d58-9e82-93abfeac5ef2","questionId":"c29fb271-bd9b-5c2f-b3d0-a4c9dcbfe5d3","sourceKey":"bank:LAG-BUA125:INT-029","payload":{"prompt":"The objective of choosing output and price so as to make the largest possible difference between total revenue and total cost is called:","options":["Sales maximisation","Profit maximisation","Social welfare maximisation","Satisficing"],"correctOption":1,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Profit is total revenue minus total cost, so making that difference as large as possible is profit maximisation. Option A aims at the largest total revenue, Option D aims at a satisfactory rather than a maximum result, and Option C is the goal of the public sector."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 41, $official_bank_source${"itemId":"d28719a9-e767-5e3b-84d3-6bd51f1eef19","questionId":"d826326b-2b37-5b1b-bf50-e60ee6c51752","sourceKey":"bank:LAG-BUA125:INT-031","payload":{"prompt":"The objective of maximising the present value of the firm's expected future profits is known as:","options":["Short-run profit maximisation","Satisficing","Sales maximisation","Wealth (value) maximisation"],"correctOption":3,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Wealth or value maximisation means maximising the present value of all expected future profits, which for a company is reflected in the value of its shares. Option A looks only at the current period, Option C targets revenue rather than value, and Option B accepts a satisfactory result rather than the maximum."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 42, $official_bank_source${"itemId":"ba681e77-31d9-5161-92af-b6fb57598f6f","questionId":"64525327-daa7-52c2-b663-39aaea6f6be0","sourceKey":"bank:LAG-BUA125:INT-032","payload":{"prompt":"Why is wealth (value) maximisation usually considered a better goal than simple profit maximisation?","options":["It ignores the time value of money","It looks only at the current year's profit","It takes account of the timing and riskiness of profits over many years","It requires the firm to maximise sales revenue"],"correctOption":2,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Value maximisation discounts future profits, so it considers when profits arrive and how risky they are, not just how large they are. Option A is the opposite of what it does, Option B describes the weakness of short-run profit maximisation, and Option D describes sales maximisation."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 43, $official_bank_source${"itemId":"7fa54e61-193f-5ea6-afd0-9f1a66598c41","questionId":"8a1ca209-749c-5907-9b10-55ed6a82b9ea","sourceKey":"bank:LAG-BUA125:INT-033","payload":{"prompt":"The expression: sum of [expected profit in year t / (1 + i)^t] for t = 1 to n, where i is the discount rate, measures:","options":["The marginal cost of the last unit produced","The firm's accounting profit for the current year","The present value (value) of the firm","The total sales revenue of the firm in year n"],"correctOption":2,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Discounting each year's expected profit at rate i and adding them up gives the present value of the firm, the quantity a value maximiser tries to make as large as possible. Option D is not discounted and is not a sum of profits, Option A relates to one extra unit of output, and Option B covers only one year with no discounting."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 44, $official_bank_source${"itemId":"ac6cd776-f104-5288-b229-36a09e96ea6b","questionId":"c40052da-c477-524a-9821-e369b667243e","sourceKey":"bank:LAG-BUA125:INT-034","payload":{"prompt":"Managers who aim at a satisfactory level of profit or performance, rather than the maximum possible, are said to be:","options":["Satisficing","Wealth maximising","Profit maximising","Sales maximising"],"correctOption":0,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Satisficing means setting an acceptable target and stopping once it is reached, instead of searching for the very best outcome. Options C, B and D all describe maximising behaviour of some kind."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 45, $official_bank_source${"itemId":"01bc3c27-bf74-5a34-924e-2bacfc65a579","questionId":"97d1641b-7fd9-5f4f-bed0-0ba0f1da4315","sourceKey":"bank:LAG-BUA125:INT-035","payload":{"prompt":"The satisficing theory of the firm is associated with:","options":["William Baumol","Adam Smith","Herbert Simon","John Maynard Keynes"],"correctOption":2,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Herbert Simon argued that, because of limited information and bounded rationality, managers aim for satisfactory rather than maximum results. Option A is linked with sales revenue maximisation, Option B with the classical idea of self-interest and markets, and Option D with macroeconomic theory of aggregate demand."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 46, $official_bank_source${"itemId":"68b79a5b-9720-58a9-81c0-53a620ba7d2f","questionId":"34ec0024-4c4a-51c6-b869-ec360f8d6bf0","sourceKey":"bank:LAG-BUA125:INT-036","payload":{"prompt":"Satisficing behaviour by managers arises mainly because:","options":["Managers always have complete information about all alternatives","Shareholders demand that profits be kept as low as possible","Managers have limited information and cannot evaluate every possible alternative","The law forbids firms from making large profits"],"correctOption":2,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Satisficing is explained by bounded rationality: information is incomplete and costly, so managers settle for an outcome that meets an acceptable standard. Option A is the assumption behind strict maximisation, and Options D and B are not true of business in general."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 47, $official_bank_source${"itemId":"7758959b-c2d7-5ef3-9bfa-92772289c069","questionId":"30713c19-2c7a-59ae-b35c-8eb05c0a6246","sourceKey":"bank:LAG-BUA125:INT-037","payload":{"prompt":"The goal of making total sales revenue as large as possible, subject to earning at least a minimum acceptable profit, is called:","options":["Sales maximisation","Social welfare maximisation","Profit maximisation","Satisficing"],"correctOption":0,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Sales (revenue) maximisation means pushing total revenue as high as possible while keeping profit above a minimum level that satisfies shareholders. Option C targets the largest profit, Option D has no maximisation at all, and Option B is the goal of government."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 48, $official_bank_source${"itemId":"4fee0903-373d-5100-992c-8aa8c75a64d9","questionId":"08ac12b2-395a-5ef1-bd01-b2ee36c87fad","sourceKey":"bank:LAG-BUA125:INT-038","payload":{"prompt":"The sales revenue maximisation model, in which a firm maximises revenue subject to a minimum profit constraint, is associated with:","options":["Herbert Simon","Alfred Marshall","William Baumol","Adam Smith"],"correctOption":2,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"William Baumol suggested that managers often maximise sales revenue, provided profit does not fall below a minimum acceptable level. Option A is linked with satisficing, while Options B and D are classical and neoclassical economists not linked to this model."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 49, $official_bank_source${"itemId":"ec2402d7-2206-589e-be74-944c5c2e5804","questionId":"74ac6482-f57d-5472-a4b5-ba7cc80ca025","sourceKey":"bank:LAG-BUA125:INT-039","payload":{"prompt":"The managing director of a Lagos detergent company tells the board: 'We will push our sales revenue as high as we can, provided profit does not fall below N50 million.' The firm's goal is:","options":["Social welfare maximisation","Pure profit maximisation","Sales maximisation subject to a profit constraint","Satisficing with no revenue target"],"correctOption":2,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Maximising revenue while keeping profit above a stated minimum is exactly the sales maximisation goal. Option B would aim at the largest profit, not the largest revenue, Option D ignores the revenue target, and Option A is the goal of public-sector bodies."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 50, $official_bank_source${"itemId":"0218f3a5-f32d-59b2-977c-dcf9d0396c16","questionId":"007b0175-87ee-59cf-b171-5629e5e330fd","sourceKey":"bank:LAG-BUA125:INT-040","payload":{"prompt":"A bakery owner in Ibadan earns about N200,000 profit a month. She says this is good enough and stops looking for cheaper suppliers or new markets. Her behaviour is best described as:","options":["Satisficing","Wealth maximisation","Sales maximisation","Profit maximisation"],"correctOption":0,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"She has set an acceptable profit level and stopped searching once it was reached, which is satisficing. Options D and B would require her to keep searching for the highest profit or value, and Option C would require her to push revenue as high as possible."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 51, $official_bank_source${"itemId":"3cb88a59-308f-597b-9c79-5ebbb394101c","questionId":"40492804-c6f6-53c4-a81b-f1eca01cb83d","sourceKey":"bank:LAG-BUA125:INT-041","payload":{"prompt":"A mission hospital owned by a church is most likely to have which main objective?","options":["Providing as much quality health service as possible while covering its costs","Maximising profit for distribution to shareholders","Maximising sales revenue subject to a minimum profit","Maximising the market price of its shares"],"correctOption":0,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"A non-profit organisation has no shareholders to reward, so it usually aims to provide the most service it can within its budget. Options B, D and C are goals of profit-making firms that serve owners."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 52, $official_bank_source${"itemId":"1a62b224-c7f7-569b-b6ad-9dc317db41b9","questionId":"78ba7a6b-4d78-5a1b-a1c2-13be375eae1d","sourceKey":"bank:LAG-BUA125:INT-042","payload":{"prompt":"When a Federal Ministry decides whether to build a new highway, its main objective should be to:","options":["Maximise net social benefit (social welfare)","Maximise sales revenue from tolls whatever the cost","Maximise the ministry's accounting profit","Maximise the ministry's share price"],"correctOption":0,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Public-sector decisions aim at social welfare, which means comparing all benefits to society with all costs to society. Options C, D and B are profit-seeking or revenue-seeking goals that ignore the wider benefits and costs to the public."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 53, $official_bank_source${"itemId":"bc51081c-6b4b-55f2-97f7-567193959c2b","questionId":"b4485999-47fd-59c5-af4d-32997e1f47f3","sourceKey":"bank:LAG-BUA125:INT-043","payload":{"prompt":"The technique the public sector commonly uses to compare the total benefits of a project to society with its total costs to society is:","options":["Break-even analysis","Ratio analysis","Stock control analysis","Cost-benefit analysis"],"correctOption":3,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Cost-benefit analysis values all the social benefits and social costs of a project to see whether it raises social welfare. Option A finds the sales level at which a firm covers its costs, Option B interprets financial statements, and Option C manages inventory."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 54, $official_bank_source${"itemId":"f741c84f-5a9b-5b4f-acf8-0249354b68c0","questionId":"520ecbc5-d1ac-59ae-99cb-8c78edaefd0a","sourceKey":"bank:LAG-BUA125:INT-044","payload":{"prompt":"The conflict that arises when managers pursue their own interests (such as large offices or high salaries) instead of maximising the value of the firm for its owners is called:","options":["The free-rider problem","Economies of scale","The principal-agent problem","Diminishing returns"],"correctOption":2,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Shareholders (principals) hire managers (agents), and when the agents' goals differ from the owners' goal of value maximisation, a principal-agent problem exists. Option A is about people enjoying a benefit without paying for it, while Options D and B describe how output and costs change with inputs and scale."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 55, $official_bank_source${"itemId":"94c451ab-1381-5399-b2be-0ab5dfffeaa4","questionId":"c42344a5-3980-5d5a-b590-0aa319e33d15","sourceKey":"bank:LAG-BUA125:INT-045","payload":{"prompt":"What is the FIRST step in the managerial decision-making process?","options":["Implementing the decision","Defining the problem","Choosing the best alternative","Evaluating the results"],"correctOption":1,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"A manager must first be clear about the problem to be solved before setting objectives and looking for alternatives. Options C, A and D are later steps that make no sense until the problem has been defined."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 56, $official_bank_source${"itemId":"1f77b683-9766-51b0-8572-c532fcce7bda","questionId":"ef50491e-ed4c-5f3b-8f1e-02b446e78b0b","sourceKey":"bank:LAG-BUA125:INT-046","payload":{"prompt":"The logistics manager of a Kano distributor has listed three possible ways of reducing delivery delays. Which step should come next?","options":["Restate the company's mission statement","Monitor the results of the chosen alternative","Evaluate the likely costs and benefits of each alternative","Implement the first alternative on the list"],"correctOption":2,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"After alternatives have been identified, each must be analysed for its expected costs and benefits so that the best one can be chosen. Option D skips the evaluation, Option B can only happen after a choice has been implemented, and Option A is not part of solving this decision."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 57, $official_bank_source${"itemId":"36f4ea2e-2867-5eec-b1bc-30be0b5cb047","questionId":"8ce77e80-5ad1-5119-bdb2-354e04be230d","sourceKey":"bank:LAG-BUA125:INT-047","payload":{"prompt":"Which sequence shows the correct order of these steps in decision making?","options":["Evaluate alternatives -> define the problem -> choose and implement -> identify alternatives","Identify alternatives -> choose and implement -> define the problem -> evaluate alternatives","Choose and implement -> evaluate alternatives -> identify alternatives -> define the problem","Define the problem -> identify alternatives -> evaluate alternatives -> choose and implement"],"correctOption":3,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Rational decision making starts by defining the problem, then lists possible courses of action, evaluates them and finally chooses and implements the best. Options B, A and C put choosing or evaluating before the problem or the alternatives are known."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 58, $official_bank_source${"itemId":"cbff354b-05b6-55bf-9720-4d9cabac2198","questionId":"bc708001-b17f-5c32-ad3b-2f02313d5861","sourceKey":"bank:LAG-BUA125:INT-048","payload":{"prompt":"Testing how the best decision would change if key assumptions, such as the expected price or cost, turned out to be different is called:","options":["Job evaluation","Ratio analysis","Market segmentation","Sensitivity analysis"],"correctOption":3,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Sensitivity analysis changes the key assumptions one at a time to see whether the chosen alternative remains the best. Option B interprets financial statements, Option C divides a market into groups of buyers, and Option A ranks jobs for pay purposes."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 59, $official_bank_source${"itemId":"04a927c4-1a55-5523-bcfc-b764ddea45be","questionId":"483344ef-fd61-5482-ace0-d21bd3159c8c","sourceKey":"bank:LAG-BUA125:INT-049","payload":{"prompt":"Which of the following is NOT a typical function of a managerial economist in a firm?","options":["Signing the statutory audit report on the firm's accounts","Forecasting demand for the firm's products","Advising on pricing policy","Analysing investment and expansion proposals"],"correctOption":0,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"A managerial economist supports decisions by forecasting demand, advising on prices and analysing investment proposals. Signing the statutory audit report is the job of an external auditor, so Options B, C and D are the genuine functions."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 60, $official_bank_source${"itemId":"312b8c1f-69c3-552d-b2ee-014e3c037d4e","questionId":"e905b462-c916-55dc-80c6-c754033b63c2","sourceKey":"bank:LAG-BUA125:INT-050","payload":{"prompt":"An economist at a Lagos cement company studies expected changes in interest rates, exchange rates and government spending, and advises the board on whether to build a new plant. This shows the managerial economist's role of:","options":["Supervising factory workers on the production line","Designing the firm's advertisements","Keeping the firm's daily cash book","Analysing the external economic environment to guide business decisions"],"correctOption":3,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"A managerial economist studies macroeconomic conditions such as interest rates and exchange rates and turns them into advice for decisions like expansion. Option C is a bookkeeping task, Option A is a supervisory task, and Option B is a marketing communication task."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 61, $official_bank_source${"itemId":"c3ab9ce2-1d3a-5322-a64a-69eb176e1e6a","questionId":"449c21ea-c818-5cbe-82d2-d3a01d5479c1","sourceKey":"bank:LAG-BUA125:INT-051","payload":{"prompt":"A Lagos snack maker has the following daily figures (Q = units, TR = total revenue, TC = total cost): Q = 10: TR = N100,000, TC = N70,000; Q = 20: TR = N180,000, TC = N110,000; Q = 30: TR = N240,000, TC = N150,000; Q = 40: TR = N280,000, TC = N200,000; Q = 50: TR = N300,000, TC = N270,000. If the firm's goal is profit maximisation, what output should it produce?","options":["40 units","50 units","30 units","20 units"],"correctOption":2,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Profit = TR - TC gives N30,000, N70,000, N90,000, N80,000 and N30,000, so profit peaks at 30 units (N90,000). Option B is where total revenue is highest, which a sales maximiser would choose, and Options D and A give lower profits of N70,000 and N80,000."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 62, $official_bank_source${"itemId":"34c0e751-7473-5c53-9180-120a9ed629c9","questionId":"ac5d2df4-c66e-5d88-a240-934d0b75d8e0","sourceKey":"bank:LAG-BUA125:INT-052","payload":{"prompt":"Given these daily figures (Q = 10: TR = N100,000, TC = N70,000; Q = 20: TR = N180,000, TC = N110,000; Q = 30: TR = N240,000, TC = N150,000; Q = 40: TR = N280,000, TC = N200,000; Q = 50: TR = N300,000, TC = N270,000), suppose the firm maximises total revenue subject to earning a profit of at least N75,000 a day. What output will it choose?","options":["20 units","50 units","30 units","40 units"],"correctOption":3,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Profits are N30,000, N70,000, N90,000, N80,000 and N30,000, so only 30 and 40 units meet the N75,000 minimum; of these, 40 units gives the higher revenue (N280,000). Option C is the profit-maximising output, and Option B has the highest revenue but earns only N30,000 profit, breaking the constraint."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 63, $official_bank_source${"itemId":"96e041db-5445-5a9e-ae54-67e99689d1d2","questionId":"c9e65e82-168b-5c89-a436-703fab733ff4","sourceKey":"bank:LAG-BUA125:INT-053","payload":{"prompt":"A firm expects profits of N10 million at the end of year 1 and N12 million at the end of year 2, and nothing after that. Using a discount rate of 10% per year (compounded annually), what is the present value of these profits? (Give your answer to 2 decimal places in millions.)","options":["N20.00 million","N19.01 million","N18.18 million","N22.00 million"],"correctOption":1,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Present value = 10/(1.1) + 12/(1.1)^2 = 9.09 + 9.92 = N19.01 million. Option D simply adds the profits without discounting, while Options A and C wrongly discount the total for one year only or for two years only."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 64, $official_bank_source${"itemId":"4afa71b4-ef58-52a6-a255-bb6531a73236","questionId":"0d876774-7a96-59a1-b25b-8f7ec23bee6e","sourceKey":"bank:LAG-BUA125:INT-054","payload":{"prompt":"A value-maximising firm can choose only one of two projects. Project X yields a single profit of N15 million at the end of year 1; Project Y yields a single profit of N16.2 million at the end of year 2. The discount rate is 10% per year (compounded annually). Which project should it choose?","options":["Project Y, because its present value (about N14.73 million) is higher than X's (about N13.64 million)","Either project, because both have the same present value","Project X, because its present value (about N13.64 million) is higher than Y's (about N13.39 million)","Project Y, because its profit of N16.2 million is larger than N15 million"],"correctOption":2,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Present values are 15/1.1 = N13.64 million for X and 16.2/(1.1)^2 = N13.39 million for Y, so X adds more value. Option D ignores the timing of profits, Option A discounts Y for only one year (16.2/1.1 = 14.73), and Option B is false because the two present values differ."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 65, $official_bank_source${"itemId":"4ada3647-74f9-5415-a691-d926793a9d78","questionId":"aa4a5996-eff7-5c84-96f0-3f887ce8fa86","sourceKey":"bank:LAG-BUA125:INT-055","payload":{"prompt":"A Kaduna cosmetics firm must choose one of three price levels. Expected monthly figures are: a low price gives total revenue N4.5 million and total cost N3.1 million; a medium price gives total revenue N6.0 million and total cost N4.4 million; a high price gives total revenue N7.2 million and total cost N5.9 million. Which price should a profit-maximising firm choose?","options":["The low price, with the lowest total cost of N3.1 million","The high price, with profit of N1.6 million","The high price, with the highest revenue of N7.2 million","The medium price, with profit of N1.6 million"],"correctOption":3,"section":"Introduction to Managerial Economics and Managerial Decisions","explanation":"Profit = TR - TC gives 4.5 - 3.1 = N1.4 million at the low price, 6.0 - 4.4 = N1.6 million at the medium price and 7.2 - 5.9 = N1.3 million at the high price, so the medium price maximises profit. Option C is the sales-maximising choice, Option A looks only at cost, and Option B wrongly gives the high price a profit of N1.6 million when it is only N1.3 million."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 66, $official_bank_source${"itemId":"7ece3ff5-b415-5e65-9584-2e4be7c34834","questionId":"ceb4329a-981d-58be-a3e6-69bd04028d63","sourceKey":"bank:LAG-BUA125:PQ-004-a","payload":{"prompt":"Opportunity cost is best described as:","options":["The amount of money actually paid out for the chosen option","Money already spent in the past that cannot be recovered","The cost of producing one extra unit of output","The benefit given up from the best alternative not chosen"],"correctOption":3,"section":"Opportunity Cost in Business","explanation":"Opportunity cost is the forgone benefit of the next best alternative you gave up when you made a choice, which is why there is no such thing as a free lunch. Option A is an explicit, out-of-pocket cost. Option B is a sunk cost and option C is marginal cost; both are different cost concepts."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 67, $official_bank_source${"itemId":"fb5ef92f-393a-5a01-a455-6a407f2ebf3c","questionId":"0fe75c14-827f-5222-afa2-c0752aca280d","sourceKey":"bank:LAG-BUA125:PQ-004-b","payload":{"prompt":"A firm can invest its spare N5,000,000 either in treasury bills, expected to return N600,000 this year, or in new equipment, expected to add N450,000 to profit this year. It chooses the equipment. Using the formula Opportunity cost = return on the most profitable choice minus return on the choice pursued, what is the opportunity cost?","options":["N1,050,000","N150,000","N450,000","N50,000"],"correctOption":1,"section":"Opportunity Cost in Business","explanation":"Applying the formula gives N600,000 - N450,000 = N150,000, option B: by choosing the equipment the firm gives up N150,000 of extra return it could have earned on treasury bills this year. Option C is simply the return on the equipment itself, and option A wrongly adds the two returns instead of subtracting."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 68, $official_bank_source${"itemId":"b4b37103-3b51-53a9-9af8-c8b17e877508","questionId":"4a61f97d-f232-5ffe-8996-5deec91a209f","sourceKey":"bank:LAG-BUA125:PQ-007-a","payload":{"prompt":"A bakery spends its N3 million budget on a new oven. Its next best alternative was to spend the money on a marketing campaign. What is the opportunity cost of buying the oven?","options":["Money spent repairing the old oven last year","The oven's annual depreciation charge","The bread the new oven will produce","The marketing campaign it gave up"],"correctOption":3,"section":"Opportunity Cost in Business","explanation":"Opportunity cost is the next best alternative given up, here the marketing campaign, so option D is right. Option C is the benefit of the choice made, not what was sacrificed. Option A is a sunk cost from the past, and option B is an accounting charge, not the forgone alternative."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 69, $official_bank_source${"itemId":"b2c9bff7-77ad-5084-b122-7a95225e9651","questionId":"96e0af81-1abe-57bc-a7a4-8552f7ea260e","sourceKey":"bank:LAG-BUA125:PQ-007-b","payload":{"prompt":"Money a business has already spent on machinery, which it cannot get back whatever it decides next, is called:","options":["Opportunity cost","Sunk cost","Incremental cost","Marginal cost"],"correctOption":1,"section":"Opportunity Cost in Business","explanation":"A sunk cost, option B, is money already spent in the past that cannot be recovered. Option A looks forward to returns given up on alternatives, while options D and C are the extra costs of producing one more unit or of increasing output in larger steps."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 70, $official_bank_source${"itemId":"aec6115e-e69d-5cf0-bef7-9673f5bb38d6","questionId":"aec28400-16b9-56c1-90e6-805d684e1455","sourceKey":"bank:LAG-BUA125:PQ-007-c","payload":{"prompt":"A shop owner runs his business in a building he owns instead of renting it out. The rent he gives up, which involves no cash payment, is an example of:","options":["An implicit (imputed) cost","A marginal cost","A sunk cost","An explicit cost"],"correctOption":0,"section":"Opportunity Cost in Business","explanation":"Implicit or imputed costs, option A, involve no cash exchange and are really opportunity costs, like the rent the owner could have earned. Option D refers to out-of-pocket payments such as salaries and rent actually paid, which appear in financial statements. Options C and B describe past unrecoverable spending and the cost of one extra unit."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 71, $official_bank_source${"itemId":"5fcfcf74-a90a-50e7-a576-0e59e9a24a73","questionId":"635790dc-6657-569c-9a03-5ec1cc848059","sourceKey":"bank:LAG-BUA125:PQ-009-a","payload":{"prompt":"A business with N20 million can either buy securities earning 10% a year compounded (N2.0m, N2.2m and N2.42m in years 1 to 3) or buy a machine expected to add N0.5m, N2.0m and N5.0m in profit in years 1 to 3. Over the three years, by how much does the machine's total gain exceed the securities' total gain?","options":["N7.50 million","N1.50 million","N6.62 million","N0.88 million"],"correctOption":3,"section":"Opportunity Cost in Business","explanation":"The machine earns N0.5m + N2.0m + N5.0m = N7.5m while the securities earn N2.0m + N2.2m + N2.42m = N6.62m, so the machine is better by N0.88m over three years, option D. Options C and A are just the separate totals for each choice, not the difference. The securities look better in years 1 and 2, which is why the opportunity cost must be judged over the whole period."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 72, $official_bank_source${"itemId":"58f92452-b559-5d9e-bcd7-f45e19277b39","questionId":"1ae3bb25-da16-5b12-9741-3dd471386124","sourceKey":"bank:LAG-BUA125:PQ-009-b","payload":{"prompt":"The combination of debt and equity that a firm uses to fund its operations and growth is called its:","options":["Working capital","Capital structure","Market structure","Cost structure"],"correctOption":1,"section":"Opportunity Cost in Business","explanation":"Capital structure, option B, is the mix of debt and equity used to finance a firm, often expressed as a debt-to-equity ratio, and each funding choice carries an opportunity cost. Option A is the money tied up in day-to-day operations, option C describes the level of competition in an industry, and option D is the make-up of a firm's costs."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 73, $official_bank_source${"itemId":"69d44825-cde4-580f-a67a-4f8357b1a5f1","questionId":"600f69f8-480f-5bbb-a5bb-7d0cbbeb9de1","sourceKey":"bank:LAG-BUA125:PQ-009-c","payload":{"prompt":"Which of the following is a limitation of opportunity cost analysis?","options":["It can only be used by non-profit organisations","It is always recorded exactly in a firm's financial statements","It relies on assumptions about future returns, so it can be subjective","It ignores alternative uses of resources"],"correctOption":2,"section":"Opportunity Cost in Business","explanation":"Opportunity cost is forward-looking, so it depends on estimates and assumptions that may be biased or wrong, option C. Option A is false because every type of organisation can use it. Option D is the opposite of what the concept does, and option B is wrong because opportunity costs are hard to quantify and record."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 74, $official_bank_source${"itemId":"d4d2388a-ccdd-5e61-b37c-60726555154a","questionId":"e24b20d7-b0c6-5967-918a-03477c3f5be8","sourceKey":"bank:LAG-BUA125:PQ-010-b","payload":{"prompt":"XYZ Corporation expects annual profit of N50 million in Market A and N35 million in Market B, and it chooses Market B. Using Opportunity cost = return on the most profitable choice minus return on the choice pursued, what is the opportunity cost of this choice?","options":["N85 million","Zero, because Market B was chosen","N35 million","N15 million"],"correctOption":3,"section":"Opportunity Cost in Business","explanation":"The formula gives N50 million - N35 million = N15 million, option D, the extra profit XYZ forgoes by not choosing Market A. Option C is just the profit from the chosen market, option A wrongly adds the two figures, and option B forgets that every choice has an opportunity cost."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 75, $official_bank_source${"itemId":"94d5f256-57e0-5807-aaf7-a93d89a364a3","questionId":"9b32aadf-3932-5291-952a-371a8122af0a","sourceKey":"bank:LAG-BUA125:PQ-018","payload":{"prompt":"In economics, the central problem is:","options":["Consumption","Allocation","Money","Scarcity"],"correctOption":3,"section":"Opportunity Cost in Business","explanation":"Scarcity, option D, is the central economic problem: wants are unlimited but resources are limited, which is why every choice has an opportunity cost. Option B is how societies respond to scarcity, not the problem itself. Options A and C are only parts of economic activity."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 76, $official_bank_source${"itemId":"10894ee3-cfe6-5b51-b343-c39eeb646c59","questionId":"b5457cd3-b097-594a-b11c-390200b427ac","sourceKey":"bank:LAG-BUA125:PQ-026","payload":{"prompt":"A student chooses to spend an extra hour studying because the marginal benefit of that hour is greater than its ________ cost.","options":["average","total","marginal","sunk"],"correctOption":2,"section":"Opportunity Cost in Business","explanation":"Rational choices are made at the margin: the student compares the benefit of one more hour with the marginal cost of that hour, option C, which includes the opportunity cost of what else the hour could be used for. Options A and B look at all hours together rather than the next one. Option D is cost already incurred, which should not affect the decision."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 77, $official_bank_source${"itemId":"0fca778d-9452-5401-950b-54263ac085b4","questionId":"cb21d2bd-3451-57ea-b62d-c45f98750e1f","sourceKey":"bank:LAG-BUA125:PQ-027","payload":{"prompt":"Periods of less than full employment of resources correspond to:","options":["Points outside the production possibility curve","Points inside the production possibility curve","Either points inside or outside the production possibility curve","Points on the production possibility curve"],"correctOption":1,"section":"Opportunity Cost in Business","explanation":"Points inside the production possibility curve mean some resources are idle or unemployed, so the economy produces less than it could, option B. Points on the curve, option D, show full and efficient use of resources, where producing more of one good has an opportunity cost in the other. Points outside the curve, option A, cannot be reached with current resources."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 78, $official_bank_source${"itemId":"2cac4627-15e3-5968-bb03-13b838a3257e","questionId":"bd945802-2089-57bf-9b42-8d21046ca318","sourceKey":"bank:LAG-BUA125:PQ-161","payload":{"prompt":"When a firm is deciding whether to replace an old machine, the machine's book value is:","options":["relevant, because it shows what the firm originally paid","the opportunity cost of keeping the old machine","irrelevant, because it is a sunk cost that cannot be changed by the decision","an explicit cost that must be recovered before replacement"],"correctOption":2,"section":"Opportunity Cost in Business","explanation":"Book value reflects money already spent in the past, and no future choice can bring it back, so it should not influence the decision. Option B is wrong because the opportunity cost of keeping the machine is what it could be sold for now, not its book value, and option A confuses past spending with future costs."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 79, $official_bank_source${"itemId":"a39f6bcd-51bd-5850-8015-8a5c482dfc53","questionId":"6ea9acbc-1755-54a0-b5c3-82374bdd40da","sourceKey":"bank:LAG-BUA125:PQ-170","payload":{"prompt":"A cost incurred in the past that cannot be changed by any future action is a(n):","options":["opportunity cost","sunk cost","avoidable cost","relevant cost"],"correctOption":1,"section":"Opportunity Cost in Business","explanation":"A sunk cost is money already spent, such as on machinery or stock, which cannot be recovered whatever the firm decides next. Option A is the benefit of the next best alternative given up, while options D and C are future costs that still depend on the decision."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 80, $official_bank_source${"itemId":"18325910-eaf0-50bc-ac4e-5f306c62113f","questionId":"319dc1ba-123d-53fb-a587-49ab0aa2a613","sourceKey":"bank:LAG-BUA125:PQ-192","payload":{"prompt":"An implicit cost is best described as:","options":["a cash payment such as rent or salaries recorded in the accounts","money already spent in the past that cannot be recovered","the value of a forgone alternative for which no cash payment is made","the cost of producing one extra unit of output"],"correctOption":2,"section":"Opportunity Cost in Business","explanation":"Implicit costs involve no cash exchange; they are opportunity costs, such as the income an owner gives up by using their own building or time in the business. Option A describes an explicit cost, option B a sunk cost, and option D marginal cost."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 81, $official_bank_source${"itemId":"66a3d739-c63c-5199-b981-d7a5f1d06cb4","questionId":"34ad59bf-4be9-5cbb-a051-3323b4e06589","sourceKey":"bank:LAG-BUA125:PQ-194","payload":{"prompt":"Which of the following is an example of an explicit cost to a business?","options":["Wages paid to employees","Rent the owner could have charged on a building the firm uses free of charge","Interest the owner could have earned on money invested in the business","The salary the owner gave up to run the business"],"correctOption":0,"section":"Opportunity Cost in Business","explanation":"Explicit costs are out-of-pocket payments, such as wages, rent and materials, that are easily identified and recorded in the financial statements. Options C, D and B are all implicit costs, because they are earnings given up rather than cash actually paid out."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 82, $official_bank_source${"itemId":"23d8e884-d614-50f4-be6a-3e8a82dc950f","questionId":"53714851-6eb7-5043-acc2-f6ff24c68876","sourceKey":"bank:LAG-BUA125:PQ-209","payload":{"prompt":"Which of the following can form part of an opportunity cost?","options":["Only the price of the option that was chosen","Only costs incurred in the past","Both the money and the time or effort given up by choosing one option","Only cash payments recorded in the financial statements"],"correctOption":2,"section":"Opportunity Cost in Business","explanation":"Opportunity cost is the benefit forgone from the next best alternative, and that sacrifice can be money, time, effort or energy. Option D describes explicit costs only, option B describes sunk costs, and option A ignores the forgone alternative altogether."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 83, $official_bank_source${"itemId":"878388da-3bc7-55a6-a65f-b2e1bc8d0ab2","questionId":"5162efdc-2efb-507d-814d-0883a6fb7542","sourceKey":"bank:LAG-BUA125:PQ-210","payload":{"prompt":"An explicit cost is best described as:","options":["a cost borne by third parties outside the business","the income an owner gives up by working in their own business","an out-of-pocket payment, such as rent or salaries, recorded in the firm's accounts","the value of an alternative given up with no cash payment"],"correctOption":2,"section":"Opportunity Cost in Business","explanation":"Explicit costs are actual cash expenses paid out by the business and recorded in its financial statements. Options D and B are implicit (opportunity) costs, and option A is an external cost."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 84, $official_bank_source${"itemId":"cf35f733-3d78-5665-8e0f-e90e5cd48373","questionId":"bd72bbd7-614d-5366-9db0-0a15e132a5f2","sourceKey":"bank:LAG-BUA125:PQ-291","payload":{"prompt":"The rent an entrepreneur could have earned from his own land, which he uses in his own business instead, is an example of:","options":["a marginal cost","a sunk cost","an implicit cost","an explicit cost"],"correctOption":2,"section":"Opportunity Cost in Business","explanation":"An implicit cost is the opportunity cost of using resources the owner already has, such as his own land, time or money, so no cash is actually paid out. Option D is an out-of-pocket payment such as rent paid to a landlord. Option B is money already spent that cannot be recovered, and option A is the cost of producing one more unit."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 85, $official_bank_source${"itemId":"63f02325-098a-589d-b953-afc7c2757c3b","questionId":"29e9f41f-0583-53c2-bc5c-9c8d0bff5ccd","sourceKey":"bank:LAG-BUA125:OPP-001","payload":{"prompt":"The forgone benefit that would have been derived from an option other than the one chosen is called:","options":["Sunk cost","Opportunity cost","Marginal cost","Explicit cost"],"correctOption":1,"section":"Opportunity Cost in Business","explanation":"Opportunity cost is the benefit a business, investor or consumer gives up by choosing one alternative over another. Option A is money already spent in the past, Option C is the cost of one extra unit, and Option D is an out-of-pocket expense recorded in the accounts."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 86, $official_bank_source${"itemId":"000d3bba-4206-5b4c-8579-07f1d5891241","questionId":"343c6bd8-ad20-5d85-9151-cdc906495f1f","sourceKey":"bank:LAG-BUA125:OPP-002","payload":{"prompt":"In economics, the opportunity cost of a choice is measured by:","options":["The total value of every alternative given up","The value of the next best alternative given up","The money price paid for the item chosen","The value of the alternative that was chosen"],"correctOption":1,"section":"Opportunity Cost in Business","explanation":"Because only one alternative could have been taken instead, opportunity cost is the value of the best alternative forgone. Option A adds alternatives that could not all have been taken together, Option C counts only money and ignores what is given up, and Option D is the benefit received, not the cost."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 87, $official_bank_source${"itemId":"f2fabdfa-8c82-5948-ab60-8537d353771c","questionId":"afd26537-40c3-55ab-a6dc-9793a44db088","sourceKey":"bank:LAG-BUA125:OPP-003","payload":{"prompt":"The saying 'There is no such thing as a free lunch' means that:","options":["Every choice has a cost, even when no money is paid, because time and energy are given up","Restaurants must never give meals away for free","Opportunity cost exists only for businesses, not for individuals","Only choices that involve money have a cost"],"correctOption":0,"section":"Opportunity Cost in Business","explanation":"Even when a choice costs no money, it uses resources such as time and energy that could have gone to something else, so it still has an opportunity cost. Option B takes the saying literally, Option D contradicts its meaning, and Option C is wrong because individuals face opportunity costs too."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 88, $official_bank_source${"itemId":"b2768bc6-adc1-5d11-b645-cfc5381aba74","questionId":"844493da-f9be-5e1c-9829-3f8ca54ed6b8","sourceKey":"bank:LAG-BUA125:OPP-004","payload":{"prompt":"Tolu, a sales executive, can attend either a product launch or a client meeting, both at 2 pm on Friday. She goes to the product launch. Her opportunity cost is:","options":["Nothing, because the launch was free","The product launch she attended","The client meeting she could have attended","The transport fare to the launch"],"correctOption":2,"section":"Opportunity Cost in Business","explanation":"She cannot be in two places at once, so choosing the launch means giving up the client meeting, which is her opportunity cost. Option B is the choice itself, Option D is an explicit money cost of the choice, and Option A ignores the fact that time is a scarce resource."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 89, $official_bank_source${"itemId":"4760c74c-7714-5b1d-bf8d-10d276954116","questionId":"8ce62aab-6eba-5bce-802a-58209e26cca6","sourceKey":"bank:LAG-BUA125:OPP-005","payload":{"prompt":"Opportunity cost arises mainly because:","options":["Firms are required by law to record all costs","Resources are scarce and have alternative uses, so choosing one use means giving up another","Resources are unlimited and can be used for everything at once","Governments set prices for all goods"],"correctOption":1,"section":"Opportunity Cost in Business","explanation":"Scarcity forces choice: a resource used for Choice A can no longer be used for Choice B, and what is given up is the opportunity cost. Option C describes a world with no scarcity and so no opportunity cost, while Options D and A are not the reason opportunity cost exists."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 90, $official_bank_source${"itemId":"a1507458-7043-5436-87cc-c86f4224ef2c","questionId":"cf867927-0167-5c40-abda-82f8cead9ef3","sourceKey":"bank:LAG-BUA125:OPP-006","payload":{"prompt":"Which of the following is an EXPLICIT cost for a printing shop in Yaba?","options":["Rent the owner could collect by leasing her own building to someone else","Interest the owner gives up on savings put into the shop","The salary the owner could earn working for another firm","The monthly rent paid to the landlord"],"correctOption":3,"section":"Opportunity Cost in Business","explanation":"Explicit costs are out-of-pocket expenses, such as rent and salaries, that are paid out and recorded in the financial statements. Options C, B and A involve no cash payment; they are forgone incomes, which makes them implicit (opportunity) costs."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 91, $official_bank_source${"itemId":"73b82183-7b31-5bf5-b673-d7e81f0d9ab4","questionId":"e6ae49db-f577-5f22-a271-a12fd5fb36de","sourceKey":"bank:LAG-BUA125:OPP-007","payload":{"prompt":"Which of the following is an IMPLICIT cost of running a business?","options":["Payments made to suppliers for raw materials","Wages paid to the shop assistants","The income the owner gives up by working in her own business instead of taking a paid job","Electricity bills paid to the distribution company"],"correctOption":2,"section":"Opportunity Cost in Business","explanation":"An implicit cost involves no cash payment; it is the value of the owner's own resources used in the business, such as the salary she gives up. Options B, D and A are cash payments recorded in the accounts, so they are explicit costs."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 92, $official_bank_source${"itemId":"a5b275a0-64ea-5b25-93e5-8bfa5b84516f","questionId":"7ee07487-6707-57fc-828d-1108880323eb","sourceKey":"bank:LAG-BUA125:OPP-008","payload":{"prompt":"Because implicit costs are opportunity costs that involve no cash payment, they are also called:","options":["Imputed costs","Marginal costs","Out-of-pocket costs","Sunk costs"],"correctOption":0,"section":"Opportunity Cost in Business","explanation":"Implicit costs are synonymous with imputed costs, because their value has to be estimated rather than taken from a cash payment. Option C is another name for explicit costs, Option D refers to money already spent, and Option B is the cost of one extra unit."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 93, $official_bank_source${"itemId":"71e48aeb-ea2f-5094-9048-fa8d8dae0913","questionId":"02411374-7852-5504-816f-13fa8a3a3633","sourceKey":"bank:LAG-BUA125:OPP-009","payload":{"prompt":"Money that has already been spent on a business decision in the past and cannot be recovered is called:","options":["Incremental cost","Sunk cost","Opportunity cost","Implicit cost"],"correctOption":1,"section":"Opportunity Cost in Business","explanation":"A sunk cost is money already put behind a decision, such as money spent on machinery or stock, which cannot be got back. Option C refers to future returns given up, Option A is the extra cost of a large increase in output, and Option D is a non-cash cost of using the owner's resources."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 94, $official_bank_source${"itemId":"3bf44b73-a75c-56b0-bcc1-4ac30eb6bdd2","questionId":"8ddd3d31-cb5a-5c5d-9fa9-5ccf9c4ba6dc","sourceKey":"bank:LAG-BUA125:OPP-010","payload":{"prompt":"What is the key difference between a sunk cost and an opportunity cost?","options":["A sunk cost is always smaller than an opportunity cost","A sunk cost is a future cost, while opportunity cost is a past cost","A sunk cost has already been spent in the past, while opportunity cost is the future return given up by using money elsewhere","There is no difference; the two terms mean the same thing"],"correctOption":2,"section":"Opportunity Cost in Business","explanation":"Sunk cost looks backwards at money already spent, while opportunity cost looks forward at returns that will not be earned because the money went elsewhere. Option B reverses the time direction, Option A has no basis, and Option D ignores the clear difference in timing."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 95, $official_bank_source${"itemId":"87c9c192-14cd-59e2-84ac-d7cd65920c6c","questionId":"885c4cd0-5ba9-52c7-a611-ba67c66e4766","sourceKey":"bank:LAG-BUA125:OPP-011","payload":{"prompt":"A juice company in Ogun spent N2.5 million last year on a feasibility study for a new drink. The money cannot be recovered whatever the company decides now. The N2.5 million is:","options":["An opportunity cost","An implicit cost","A marginal cost","A sunk cost"],"correctOption":3,"section":"Opportunity Cost in Business","explanation":"The money was spent in the past and cannot be got back, which is what makes it a sunk cost. Option A would be the return given up on a future alternative, Option C is the cost of one extra unit of output, and Option B involves no cash payment, whereas this study was paid for in cash."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 96, $official_bank_source${"itemId":"ad4a3898-3d0f-50e4-88e1-1982d748e400","questionId":"9f646593-1fce-50e6-8651-0fb038999eca","sourceKey":"bank:LAG-BUA125:OPP-012","payload":{"prompt":"The cost of producing one extra unit of an item for sale is called:","options":["Marginal cost","Fixed cost","Sunk cost","Incremental cost"],"correctOption":0,"section":"Opportunity Cost in Business","explanation":"Marginal cost is the addition to total cost from producing one more unit. Option D looks at increases in production of more than one unit at a time, Option C is past spending that cannot be recovered, and Option B does not change with output at all."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 97, $official_bank_source${"itemId":"5dca4509-f604-5088-b0d3-c354f6a013ac","questionId":"615079b2-634e-5395-86c8-f991ec8f8ce6","sourceKey":"bank:LAG-BUA125:OPP-013","payload":{"prompt":"How does incremental cost differ from marginal cost?","options":["Incremental cost is money already spent, while marginal cost is a future cost","Incremental cost looks at increasing production by more than one unit at a time, while marginal cost is for one extra unit","Incremental cost applies only to non-profit organisations","Incremental cost involves no cash payment, while marginal cost is always paid in cash"],"correctOption":1,"section":"Opportunity Cost in Business","explanation":"Both measure extra cost from producing more, but marginal cost refers to one additional unit while incremental cost refers to a larger step up in production. Option A describes sunk cost, Option D confuses it with implicit cost, and Option C has no basis."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 98, $official_bank_source${"itemId":"eda6c358-c292-5e07-89e9-d9bd35a16ad4","questionId":"c4436da7-0e5f-5b01-9734-62b19fe42840","sourceKey":"bank:LAG-BUA125:OPP-014","payload":{"prompt":"Which of the following is NOT a limitation of opportunity cost analysis?","options":["It cannot cover every factor, such as changes in the economy or public policy","Its calculations can be subjective because they rest on assumptions","It can be difficult to quantify because some costs are not financial","It always produces a precise and certain figure"],"correctOption":3,"section":"Opportunity Cost in Business","explanation":"Opportunity cost is forward-looking and cannot be predicted with total certainty, so claiming it always gives a precise figure is false. Options B, C and A are genuine limitations: subjectivity, difficulty in quantifying non-financial costs, and inability to cover all factors."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 99, $official_bank_source${"itemId":"14360a61-19b9-587a-9d85-d0a14c468c83","questionId":"565132c8-83fe-5b59-a204-4cc31f86e732","sourceKey":"bank:LAG-BUA125:OPP-015","payload":{"prompt":"A manager compares two projects using projected returns that depend on her own guesses about future demand. A colleague warns that the result may be biased. Which limitation of opportunity cost is the colleague pointing to?","options":["Opportunity costs are always zero for new projects","Opportunity costs apply only to sunk investments","Opportunity cost calculations can be subjective","Opportunity costs can be hard to record"],"correctOption":2,"section":"Opportunity Cost in Business","explanation":"When figures are based on assumptions rather than absolute fact, the calculation is subjective and open to error or bias. Option D is a real limitation but refers to the difficulty of reaching a clear decision from a mix of measures, not to biased assumptions, and Options A and B are false."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 100, $official_bank_source${"itemId":"ed445f0f-52ef-54ac-bd11-bfe32555fde1","questionId":"b2b1f1f2-c972-54bb-a6cc-9e57d6760a25","sourceKey":"bank:LAG-BUA125:OPP-016","payload":{"prompt":"Which of the following is an implication of opportunity cost for business operations?","options":["It allows firms to ignore the returns on alternatives","It guarantees that every investment will be profitable","It helps businesses allocate resources so that they are used in the most profitable way","It removes the need to compare alternatives"],"correctOption":2,"section":"Opportunity Cost in Business","explanation":"Considering opportunity cost leads to better decision making and more efficient resource allocation, directing resources to their most profitable use. Options D and A contradict the idea, which is all about comparing alternatives, and Option B is false because returns are uncertain."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 101, $official_bank_source${"itemId":"82e5fcd9-8534-51ce-911d-cc0ce17fe561","questionId":"525e8789-9727-5c01-a364-b393035d0e6f","sourceKey":"bank:LAG-BUA125:OPP-018","payload":{"prompt":"Why does taking on debt carry an opportunity cost for a company?","options":["Debt payments are sunk costs that never affect future decisions","Money used to make payments on the debt cannot be invested for other purposes","Debt always earns a higher return than any outside investment","Debt has no explicit cost because lenders are not paid"],"correctOption":1,"section":"Opportunity Cost in Business","explanation":"Cash used to service bonds or loans is no longer available for other uses, so the firm must ask whether the borrowing-funded expansion earns more than outside investments would. Option D is false because lenders must be compensated, Option A confuses future payments with past spending, and Option C has no basis."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 102, $official_bank_source${"itemId":"9a7ff3ca-39ea-5bb2-bb75-7a555bd58193","questionId":"c38806ee-fb6e-5c27-b4e5-b094a594f691","sourceKey":"bank:LAG-BUA125:OPP-019","payload":{"prompt":"Why is it difficult in practice to use opportunity cost to choose between borrowing and issuing shares?","options":["Opportunity cost is forward-looking, so the actual rate of return on each option is unknown when the choice is made","Borrowing and issuing shares both have zero cost","Opportunity cost can only be calculated after the company is wound up","Shareholders are not allowed to receive any return"],"correctOption":0,"section":"Opportunity Cost in Business","explanation":"Because opportunity cost looks to the future, the actual returns on both options are not known at the time of the decision, which makes the evaluation tricky. Option B ignores the explicit cost of compensating lenders and shareholders, and Options C and D are simply untrue."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 103, $official_bank_source${"itemId":"29eaaf2a-7cae-5b41-90cf-0a842bce763b","questionId":"dbdaab0b-a72d-50d2-b5ae-df08ae435d2d","sourceKey":"bank:LAG-BUA125:OPP-020","payload":{"prompt":"Apart from opportunity cost, which of the following is NOT one of the four common factors to consider when making business decisions?","options":["Popularity","Utility","Time","Effort"],"correctOption":0,"section":"Opportunity Cost in Business","explanation":"The four common factors are cost, time, utility and effort. Popularity is not among them, while Options C, B and D are three of the four."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 104, $official_bank_source${"itemId":"b491e226-898c-5443-b626-57eb10e7b35b","questionId":"438f94f4-dfe4-5833-89c3-92a758faa102","sourceKey":"bank:LAG-BUA125:OPP-021","payload":{"prompt":"Which guiding principle should a manager follow when making business decisions?","options":["Minimise utility while maximising the time spent on each decision","Maximise utility and value created while minimising the cost incurred, time spent and effort required","Maximise effort required so that staff remain busy","Ignore cost as long as the decision saves time"],"correctOption":1,"section":"Opportunity Cost in Business","explanation":"The guiding principle is to get the most utility and value while using the least cost, time and effort. Options A and C reverse this principle, and Option D ignores one of the factors that must be weighed together."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 105, $official_bank_source${"itemId":"c066dfcf-4173-5ef2-8f13-2da615852469","questionId":"f39f212d-1165-5136-9e9f-17e62b06cb7c","sourceKey":"bank:LAG-BUA125:OPP-022","payload":{"prompt":"An office manager spends the furniture budget on a sofa. With the same money she could have bought a water cooler and new wallpaper. What is the opportunity cost of the sofa?","options":["The sofa itself","Nothing, since the sofa was within budget","The rent on the office","The water cooler and the wallpaper"],"correctOption":3,"section":"Opportunity Cost in Business","explanation":"The water cooler and wallpaper are what the same money could have bought instead, so they are the opportunity cost of the sofa. Option A is the item chosen, Option B wrongly assumes there is no cost when spending within a budget, and Option C is unrelated to the choice."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 106, $official_bank_source${"itemId":"c04c93fe-a764-53be-9e88-ff852131ecca","questionId":"b059c884-bd0b-53f1-b0e9-6e9be37db24a","sourceKey":"bank:LAG-BUA125:OPP-023","payload":{"prompt":"How is economic profit different from accounting profit?","options":["Economic profit subtracts both explicit and implicit costs from revenue, while accounting profit subtracts only explicit costs","There is no difference between economic profit and accounting profit","Economic profit subtracts only explicit costs, while accounting profit subtracts both explicit and implicit costs","Economic profit ignores all costs, while accounting profit subtracts only implicit costs"],"correctOption":0,"section":"Opportunity Cost in Business","explanation":"Accounting profit = total revenue - explicit costs, while economic profit = total revenue - explicit costs - implicit (opportunity) costs. Option C reverses the two definitions, Option D makes no sense for either, and Option B ignores the treatment of implicit costs."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 107, $official_bank_source${"itemId":"9cccb400-93f9-553b-8c93-f9c9874ddfdc","questionId":"b470572a-ba06-5d31-a294-37eab68f2161","sourceKey":"bank:LAG-BUA125:OPP-024","payload":{"prompt":"Using the formula Opportunity cost = RMPIC - RICP (return on the most profitable investment choice minus return on the investment chosen), a firm expects 14% from treasury bills and 9% from upgrading its equipment. It chooses the equipment upgrade. What is the opportunity cost?","options":["14%","23%","5%","9%"],"correctOption":2,"section":"Opportunity Cost in Business","explanation":"Opportunity cost = 14% - 9% = 5%, the extra return the firm gives up by not choosing the most profitable option. Option B adds the returns instead of subtracting, Option D is the return actually earned, and Option A is the full return of the alternative rather than the difference."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 108, $official_bank_source${"itemId":"c9d35048-5a79-51fa-bc54-6872b3de8602","questionId":"6f934712-80e9-566a-8532-1bf0bae82d9d","sourceKey":"bank:LAG-BUA125:OPP-025","payload":{"prompt":"A Port Harcourt firm has N8,000,000 of spare cash. Investing it in treasury bills would return N1,200,000 in a year, while expanding its workshop would return N900,000 in the same year. It chooses the expansion. Using Opportunity cost = return on most profitable choice - return on choice made, what is the opportunity cost?","options":["N300,000","N7,100,000","N900,000","N2,100,000"],"correctOption":0,"section":"Opportunity Cost in Business","explanation":"Opportunity cost = N1,200,000 - N900,000 = N300,000. Option D adds the two returns, Option C is the return actually earned, and Option B wrongly subtracts the return from the amount invested."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 109, $official_bank_source${"itemId":"61db1b6c-e798-50d9-97cc-cd7794a71757","questionId":"6727a68c-2557-581a-83ca-f9383cd866a1","sourceKey":"bank:LAG-BUA125:OPP-026","payload":{"prompt":"A company can invest its surplus funds in only one of three options with expected one-year returns of 12% (Option P), 15% (Option Q) and 9% (Option R). It chooses Option R. Using Opportunity cost = RMPIC - RICP, what is the opportunity cost?","options":["3%","27%","18%","6%"],"correctOption":3,"section":"Opportunity Cost in Business","explanation":"The most profitable choice is Q at 15%, so opportunity cost = 15% - 9% = 6%. Option A wrongly uses P (12% - 9%) instead of the most profitable choice, Option C adds P and Q and subtracts R, and Option B adds 12% and 15%."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 110, $official_bank_source${"itemId":"6541f361-5479-5d3d-ad1d-36e423cf14f7","questionId":"f8aa5381-1683-5fce-8ec8-c4ef05e2ecde","sourceKey":"bank:LAG-BUA125:OPP-027","payload":{"prompt":"Investing N4,000,000 in Project X is expected to return N520,000 in a year, while investing the same N4,000,000 in Project Y is expected to return N360,000. The firm chooses Project Y. Express the opportunity cost as a percentage return using Opportunity cost = RMPIC - RICP.","options":["22%","4%","9%","13%"],"correctOption":1,"section":"Opportunity Cost in Business","explanation":"Returns are 520,000/4,000,000 = 13% for Project X and 360,000/4,000,000 = 9% for Project Y, so opportunity cost = 13% - 9% = 4%. Option D is Project X's return, Option C is Project Y's return, and Option A adds the two rates."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 111, $official_bank_source${"itemId":"59bd9018-3143-57ea-86cb-9f13e4454616","questionId":"c9e9ad25-914b-5e6b-90db-808f98796000","sourceKey":"bank:LAG-BUA125:OPP-028","payload":{"prompt":"A farmer in Oyo can use one plot of land for only one crop this season. Expected net returns are: maize N450,000, cassava N380,000 and yam N520,000. He plants yam. If opportunity cost is measured as the value of the next best alternative forgone, what is his opportunity cost?","options":["N70,000","N830,000","N450,000","N520,000"],"correctOption":2,"section":"Opportunity Cost in Business","explanation":"Of the alternatives he gave up, maize (N450,000) is the best, so that is his opportunity cost. Option B adds maize and cassava, but he could only have planted one of them, Option D is the return from the crop he chose, and Option A is the advantage of yam over maize, not the value forgone."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 112, $official_bank_source${"itemId":"cb59c2ea-6902-5bd7-9f5f-feeb05738e44","questionId":"b0f9f1a6-a655-5e98-9331-a35ebd631e14","sourceKey":"bank:LAG-BUA125:OPP-029","payload":{"prompt":"A firm has N5,000,000 to invest in securities expected to earn 12% a year, with each year's return reinvested (compounded annually). How much return would the securities earn in year 3 alone?","options":["N672,000","N752,640","N2,024,640","N600,000"],"correctOption":1,"section":"Opportunity Cost in Business","explanation":"With reinvestment the balance grows to 5,000,000 x (1.12)^2 = N6,272,000 at the start of year 3, so year-3 return = 6,272,000 x 0.12 = N752,640. Option D is simple interest on the original amount, Option A is the year-2 return, and Option C is the total of all three years."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 113, $official_bank_source${"itemId":"939bfd3a-1e63-508e-a4ef-cbfe35f57abe","questionId":"e100da98-123a-5e69-a2d5-19648c2c841a","sourceKey":"bank:LAG-BUA125:OPP-030","payload":{"prompt":"A firm with N5,000,000 can either buy securities earning 12% a year compounded annually (returns of N600,000, N672,000 and N752,640 in years 1-3) or buy a machine expected to add N300,000, N800,000 and N1,200,000 to profit in years 1-3. Comparing total returns over the three years, which option is better and by how much?","options":["The securities, by N275,360","The machine, by N500,000","The machine, by N275,360","The securities, by N300,000"],"correctOption":2,"section":"Opportunity Cost in Business","explanation":"Total from securities = 600,000 + 672,000 + 752,640 = N2,024,640, and total from the machine = N2,300,000, so the machine is better by N275,360. Option A gets the direction wrong, Option B uses simple 12% returns of N600,000 each year, and Option D looks only at year 1."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 114, $official_bank_source${"itemId":"c29b35e3-25f4-535e-80cc-3c1c8151dc42","questionId":"ed1418ce-cfa1-549c-8024-4111955a4555","sourceKey":"bank:LAG-BUA125:OPP-031","payload":{"prompt":"Given these returns (securities: N600,000, N672,000 and N752,640 in years 1-3; machine: N300,000, N800,000 and N1,200,000 in years 1-3), in which year does the machine's cumulative return first exceed the securities' cumulative return?","options":["Year 3","It never exceeds it within three years","Year 1","Year 2"],"correctOption":0,"section":"Opportunity Cost in Business","explanation":"Cumulative returns are N600,000 vs N300,000 after year 1, N1,272,000 vs N1,100,000 after year 2, and N2,024,640 vs N2,300,000 after year 3, so the machine first pulls ahead in year 3. Option D is tempting because the machine earns more than the securities in year 2 alone, but it is still behind on a cumulative basis, and Options C and B contradict the totals."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 115, $official_bank_source${"itemId":"3449880a-3245-55d6-8879-674de16ec98a","questionId":"f2e2b45e-2749-5dad-96bf-14d8ce423da7","sourceKey":"bank:LAG-BUA125:OPP-032","payload":{"prompt":"A boutique owner in Lekki had total revenue of N12,000,000 and explicit costs of N7,500,000 for the year. She gave up a salary of N2,400,000 to run the boutique and put in N5,000,000 of her own savings, which could have earned 10% a year. What is her economic profit?","options":["N4,500,000","N1,600,000","-N2,900,000","N2,100,000"],"correctOption":1,"section":"Opportunity Cost in Business","explanation":"Accounting profit = 12,000,000 - 7,500,000 = N4,500,000; implicit costs = 2,400,000 + (10% x 5,000,000) = N2,900,000; economic profit = N1,600,000. Option A is accounting profit, Option D forgets the forgone interest, and Option C deducts the whole N5,000,000 of savings instead of only the interest given up."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 116, $official_bank_source${"itemId":"3c213fa4-7f80-55d6-a138-a8125c094b14","questionId":"fe3ebffc-f047-5cbe-9099-5f10e0fcfa31","sourceKey":"bank:LAG-BUA125:OPP-033","payload":{"prompt":"Using the same boutique (revenue N12,000,000; explicit costs N7,500,000; forgone salary N2,400,000; N5,000,000 of own savings that could earn 10% a year), what are her total implicit costs?","options":["N7,400,000","N9,900,000","N2,900,000","N2,400,000"],"correctOption":2,"section":"Opportunity Cost in Business","explanation":"Implicit costs = forgone salary + forgone interest = 2,400,000 + (0.10 x 5,000,000) = N2,900,000. Option A counts the full savings rather than the interest given up, Option B mixes explicit costs with the salary, and Option D leaves out the forgone interest."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 117, $official_bank_source${"itemId":"c9b61a1f-ec9c-530e-b332-d47cb4ec6db8","questionId":"4287c9b9-b5f3-59f8-ab31-f9fc9004a2b1","sourceKey":"bank:LAG-BUA125:OPP-034","payload":{"prompt":"Emeka's printing business earned revenue of N6,000,000 with explicit costs of N4,200,000. To run it, he gave up a job paying N2,100,000 a year. What are his accounting profit and economic profit?","options":["Accounting profit N3,900,000; economic profit N1,800,000","Accounting profit N1,800,000; economic profit -N300,000","Accounting profit -N300,000; economic profit N1,800,000","Accounting profit N1,800,000; economic profit N1,800,000"],"correctOption":1,"section":"Opportunity Cost in Business","explanation":"Accounting profit = 6,000,000 - 4,200,000 = N1,800,000, while economic profit = 1,800,000 - 2,100,000 = -N300,000, an economic loss. Option D ignores the forgone salary, Option C swaps the two figures, and Option A deducts the forgone salary instead of the explicit costs for accounting profit."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 118, $official_bank_source${"itemId":"b8212318-26ab-52d9-88f2-8f819cdaa7c8","questionId":"df2edf44-f1d2-5dba-ba39-ca24e085fadb","sourceKey":"bank:LAG-BUA125:OPP-035","payload":{"prompt":"Following the figures in which a business shows an accounting profit of N1,800,000 but an economic loss of N300,000 once the owner's forgone salary of N2,100,000 is counted, what does the economic loss tell the owner?","options":["His business is making a cash loss of N300,000 on its accounts","He would earn N300,000 more a year by taking the paid job instead","He should ignore the forgone salary because it is not paid in cash","His explicit costs are N300,000 too high according to his accounts"],"correctOption":1,"section":"Opportunity Cost in Business","explanation":"An economic loss means the business earns less than the owner's best alternative: the N2,100,000 job pays N300,000 more than the N1,800,000 accounting profit. Option A is wrong because the accounts show a profit, Option C ignores the opportunity cost of his time, and Option D confuses explicit with implicit costs."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 119, $official_bank_source${"itemId":"641c285d-fd19-5369-9e6d-5c58d5bb06bf","questionId":"ecc12865-06ec-5a2c-8670-fe367aac11bd","sourceKey":"bank:LAG-BUA125:OPP-036","payload":{"prompt":"Bisi leaves a job paying N1,800,000 a year to study full-time for one year. Tuition and books cost N600,000. Her living expenses of N900,000 would be the same whether she studies or works. What is the total economic cost of the year of study?","options":["N1,800,000","N3,300,000","N600,000","N2,400,000"],"correctOption":3,"section":"Opportunity Cost in Business","explanation":"Economic cost = explicit costs of study + forgone wages = 600,000 + 1,800,000 = N2,400,000; living expenses are left out because she would pay them anyway. Option B wrongly adds the living expenses, Option C counts only the cash spent, and Option A counts only the forgone wages."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 120, $official_bank_source${"itemId":"8f0c3e2e-c839-5d6f-a768-56e0dbcda02d","questionId":"4d359fc4-dcbc-54a1-b1db-d5d2cd720510","sourceKey":"bank:LAG-BUA125:OPP-037","payload":{"prompt":"A trader owns the shop she trades from. She could rent it to another trader for N150,000 a month. What is the annual implicit rent cost of using the shop for her own business?","options":["N1,800,000","N0, because she pays no rent","N150,000","N900,000"],"correctOption":0,"section":"Opportunity Cost in Business","explanation":"The implicit rent is the income she gives up by not letting the shop: 150,000 x 12 = N1,800,000 a year. Option C is only one month, Option D is only six months, and Option B ignores the opportunity cost of using her own property."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 121, $official_bank_source${"itemId":"6757b7ae-6b0f-550a-957b-5f8f80f73ed7","questionId":"5fbba8ba-5ec9-5ce2-86c4-534ca508c835","sourceKey":"bank:LAG-BUA125:OPP-038","payload":{"prompt":"A company pays N45,000,000 in interest on its debt in a year. If that money could instead have been spent on a marketing campaign expected to return 18% within the year, what is the return given up?","options":["N45,000,000","N53,100,000","N36,900,000","N8,100,000"],"correctOption":3,"section":"Opportunity Cost in Business","explanation":"Return forgone = 18% x 45,000,000 = N8,100,000. Option A is the amount paid, not the return on it, Option B adds the principal to the return, and Option C subtracts 18% from the principal."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 122, $official_bank_source${"itemId":"0f607e81-c54b-5035-a49c-cae9e9cce218","questionId":"363158ce-ab8a-5516-8ded-2951b5f8e250","sourceKey":"bank:LAG-BUA125:OPP-039","payload":{"prompt":"With the same resources, a furniture workshop can make either 200 chairs or 50 tables in a month. What is the opportunity cost of producing one table?","options":["4 chairs","50 chairs","150 chairs","0.25 chairs"],"correctOption":0,"section":"Opportunity Cost in Business","explanation":"Opportunity cost of one table = 200 chairs / 50 tables = 4 chairs. Option D is the opportunity cost of one chair measured in tables (50/200), Option C is the difference 200 - 50, and Option B uses the number of tables."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 123, $official_bank_source${"itemId":"567e4e45-4bcc-5429-b69f-f95fa843d6cb","questionId":"53d5715f-59ab-5ef4-92ce-cd74ac6647b5","sourceKey":"bank:LAG-BUA125:OPP-040","payload":{"prompt":"A consultant earns N25,000 an hour. She can either spend 3 hours queuing at a government office to submit a document herself or pay an agent N5,000 to do it. If she uses the 3 hours for paid work instead of queuing, how much better off is she by paying the agent?","options":["N20,000","N75,000","N5,000","N70,000"],"correctOption":3,"section":"Opportunity Cost in Business","explanation":"The opportunity cost of queuing is 3 x 25,000 = N75,000 of earnings, so paying N5,000 leaves her N75,000 - N5,000 = N70,000 better off. Option B forgets to subtract the agent's fee, Option A uses only one hour, and Option C is just the fee."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 124, $official_bank_source${"itemId":"74ab7150-921d-5525-bda4-25b5af3e64c4","questionId":"88f0ee03-51d2-58e3-985b-844c4ab35072","sourceKey":"bank:LAG-BUA125:OPP-041","payload":{"prompt":"An owner withdraws N8,000,000 from a savings account paying 11% a year and invests it in her own pharmacy. What is the annual implicit (opportunity) cost of using these funds?","options":["N0","N8,880,000","N880,000","N8,000,000"],"correctOption":2,"section":"Opportunity Cost in Business","explanation":"The implicit cost is the interest she gives up: 11% x 8,000,000 = N880,000 a year. Option D is the capital itself, which she still owns, Option B adds the capital to the interest, and Option A ignores the forgone interest because no cash is paid."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 125, $official_bank_source${"itemId":"7a7b422c-cf20-5480-b7b1-b3f7bcef3a3a","questionId":"8d576c61-09f3-5162-87ff-0c7dd580c39e","sourceKey":"bank:LAG-BUA125:OPP-042","payload":{"prompt":"A firm has total revenue of N9,000,000, explicit costs of N6,000,000 and implicit costs of N3,000,000. Which statement is correct?","options":["Economic profit is -N3,000,000, so the firm makes an economic loss","Accounting profit is zero, so the firm should close down","Economic profit is N3,000,000, so the firm earns above-normal profit","Economic profit is zero, so the firm earns just a normal profit"],"correctOption":3,"section":"Opportunity Cost in Business","explanation":"Accounting profit = 9,000,000 - 6,000,000 = N3,000,000, and economic profit = 3,000,000 - 3,000,000 = 0, meaning the owner earns exactly what her resources could earn elsewhere (normal profit). Option C is accounting profit, Option A subtracts implicit costs twice, and Option B is wrong because accounting profit is N3,000,000."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 126, $official_bank_source${"itemId":"59f4b8b2-eba9-519e-94c3-2a0bbf921d95","questionId":"66ca3ae3-066c-5c02-b6d7-e319852fa5c5","sourceKey":"bank:LAG-BUA125:OPP-043","payload":{"prompt":"A firm can fund only one of three projects, each costing N3,000,000. Expected total returns after one year are: Project A N3,540,000, Project B N3,480,000 and Project C N3,600,000. It chooses the best project. Measuring opportunity cost as the net gain of the next best alternative forgone, what is the opportunity cost of its choice?","options":["N600,000","N480,000","N540,000","N1,020,000"],"correctOption":2,"section":"Opportunity Cost in Business","explanation":"Net gains are N540,000 (A), N480,000 (B) and N600,000 (C), so C is chosen and the next best alternative is A, giving an opportunity cost of N540,000. Option A is the gain from the project chosen, Option B is the third-best project, and Option D adds the gains of Projects A and B, though only one could have been taken."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 127, $official_bank_source${"itemId":"ae176a9e-7f57-53c6-87a0-49e7909a0098","questionId":"d2f558b1-55eb-558f-95a9-588bc9b5879b","sourceKey":"bank:LAG-BUA125:OPP-044","payload":{"prompt":"A bottling plant's total cost is N500,000 when it produces 100 crates and N503,200 when it produces 101 crates. What is the marginal cost of the 101st crate?","options":["N503,200","N4,982.18","N5,000","N3,200"],"correctOption":3,"section":"Opportunity Cost in Business","explanation":"Marginal cost = change in total cost from one extra unit = 503,200 - 500,000 = N3,200. Option B is the average cost at 101 crates (about N4,982.18), Option C is the average cost at 100 crates, and Option A is total cost, not the extra cost."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 128, $official_bank_source${"itemId":"03849575-d935-50d3-b590-61fa55a3294b","questionId":"b55a2d0d-d444-5053-b59d-59e8b91c4d56","sourceKey":"bank:LAG-BUA125:OPP-045","payload":{"prompt":"Raising output from 100 crates to 150 crates increases a plant's total cost from N500,000 to N640,000. What is the incremental cost of the extra 50 crates?","options":["N4,266.67","N2,800","N640,000","N140,000"],"correctOption":3,"section":"Opportunity Cost in Business","explanation":"Incremental cost = change in total cost for the whole step = 640,000 - 500,000 = N140,000. Option C is total cost at the new level, Option B is the extra cost per crate (N2,800), and Option A is average cost at 150 crates."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 129, $official_bank_source${"itemId":"5c0b15c4-fa01-5985-b6c2-b718353d1759","questionId":"e8548282-447e-5690-a0d5-c62242779bd7","sourceKey":"bank:LAG-BUA125:PQ-003-a","payload":{"prompt":"Market attractiveness refers to:","options":["How visually appealing a firm's products and packaging are","The potential of a market to provide long-term profitability and growth opportunities for a firm","The power of government to fix prices in a market","The number of shops and stalls located in a marketplace"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Market attractiveness measures how good a market is for a business, that is, its potential to generate profits and growth over the long term, so option B is right. Option D confuses a physical marketplace with the economic idea of a market. Option A is about product design, and option C is about price control, which is only one part of the regulatory environment."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 130, $official_bank_source${"itemId":"e0917744-8b8f-5c8b-8973-e54a7ab46f65","questionId":"337c3a9c-ff5c-5bc6-b1ad-58195843b04a","sourceKey":"bank:LAG-BUA125:PQ-003-b","payload":{"prompt":"Which of the following would make a market LESS attractive to a firm thinking of entering it?","options":["Favourable government regulations and tax incentives","High barriers to entry such as heavy capital requirements","High profit margins in the industry","A large and growing market size"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"High barriers to entry, such as large capital requirements, economies of scale enjoyed by existing firms or strict regulation, make it hard for a newcomer to get in, so option B reduces attractiveness. Options D, A and C all make a market more attractive: a big, growing market, supportive policies and high margins all raise profit potential."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 131, $official_bank_source${"itemId":"00046048-0297-5dba-bf93-f76134e181b6","questionId":"febc55c1-6e29-5a90-92c5-fd09f73eb80d","sourceKey":"bank:LAG-BUA125:PQ-005-a","payload":{"prompt":"The main reason businesses evaluate market attractiveness is to:","options":["Avoid paying company taxes","Make informed decisions about entering or investing in a market","Guarantee that the firm will never make a loss","Decide the salaries of its employees"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Evaluating market attractiveness helps a firm decide whether a market is worth entering or investing in, guiding resource allocation, strategic planning and risk management, so option B is right. It cannot remove taxes (option A) or guarantee profits (option C), since conditions can change and data may be limited. Option D is a human resource decision."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 132, $official_bank_source${"itemId":"58723eb2-3ee9-5722-80ea-f2a8c5ce50ea","questionId":"c811222b-edd7-5c7d-b9b0-ee4af37ed78f","sourceKey":"bank:LAG-BUA125:PQ-005-b","payload":{"prompt":"A firm rates a market using weighted scores: market size (weight 40%, score 8), growth rate (weight 30%, score 6) and competitive intensity (weight 30%, score 5), with scores out of 10. What is the market's total weighted score?","options":["6.5","19.0","5.0","6.3"],"correctOption":0,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Each weighted score is weight times score: 0.4 x 8 = 3.2, 0.3 x 6 = 1.8 and 0.3 x 5 = 1.5, which add up to 6.5, option A. Option B just adds the raw scores and ignores the weights. Option D is the simple average of the scores (6.33 rounded), which wrongly treats all factors as equally important."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 133, $official_bank_source${"itemId":"baa344b4-0ce4-5089-9e1b-d663355ab80b","questionId":"8e2c51ae-4075-5ab5-aca9-5e36e423725a","sourceKey":"bank:LAG-BUA125:PQ-005-c","payload":{"prompt":"Which framework assesses a market by examining political, economic, social, technological, environmental and legal factors?","options":["SWOT analysis","Porter's five forces","BCG matrix","PESTEL analysis"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"PESTEL analysis, option D, looks at the political, economic, social, technological, environmental and legal factors in a firm's external environment. Option A (SWOT) covers strengths, weaknesses, opportunities and threats, option C (BCG) compares market growth with relative market share, and option B analyses the competitive forces within an industry."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 134, $official_bank_source${"itemId":"ec62e306-ce75-54e6-9676-bcceaa53b72d","questionId":"ba880028-ba2b-5ac9-8ed2-91e01d084c6b","sourceKey":"bank:LAG-BUA125:PQ-008-a","payload":{"prompt":"In the BCG matrix, a business unit or product with high market growth and high relative market share is called a:","options":["Cash cow","Star","Dog","Question mark"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"A star, option B, has high market share in a fast-growing market. Option A (cash cow) has high share in a low-growth market, option D (question mark) has low share in a high-growth market, and option C (dog) has low share in a low-growth market."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 135, $official_bank_source${"itemId":"6a369661-b1de-5887-804e-154835432c91","questionId":"b93a5107-04a2-52d0-a10c-c4f9eb4f44cc","sourceKey":"bank:LAG-BUA125:PQ-008-b","payload":{"prompt":"Compared with a saturated market, an emerging market is usually more attractive mainly because it offers:","options":["Lower risk and more reliable market data","More intense price wars among established firms","Stronger customer loyalty to existing brands","Higher growth potential"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"A large and growing market is more attractive than a stagnant one, and emerging markets are attractive mainly for their growth potential, option D. Option A is the opposite of reality, since emerging markets often carry more risk and data limitations. Options C and B describe features of saturated markets, which make entry harder."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 136, $official_bank_source${"itemId":"953f72df-b94a-50e9-84a2-7b6995d6476b","questionId":"1944d983-92df-503b-9e8d-35c164e9fe5e","sourceKey":"bank:LAG-BUA125:PQ-008-c","payload":{"prompt":"Which of the following is one of Porter's five forces?","options":["Rate of inflation","Threat of substitute products","Corporate governance","Purchasing power parity"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Porter's five forces are rivalry among existing competitors, threat of new entrants, bargaining power of suppliers, bargaining power of buyers and threat of substitute products, so option B is right. Options A, C and D can affect how attractive a market is, but they are not among the five forces."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 137, $official_bank_source${"itemId":"f952a962-9dfb-54af-8f54-49b7c7e5c18c","questionId":"b64d6715-d1b6-5bc5-9eb9-df1e228b9dfb","sourceKey":"bank:LAG-BUA125:PQ-010-a","payload":{"prompt":"XYZ Corporation scores two markets out of 10, giving profitability a weight of 60% and competitive intensity (higher score = less competition) a weight of 40%. Market A scores 9 for profitability and 3 for competition; Market B scores 6 for profitability and 8 for competition. Which market is more attractive on these weighted scores?","options":["Market A, with a score of 12","Both markets are equally attractive","Market B, with a score of 6.8","Market A, with a score of 6.6"],"correctOption":2,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Market A scores 0.6 x 9 + 0.4 x 3 = 6.6 and Market B scores 0.6 x 6 + 0.4 x 8 = 6.8, so Market B is slightly more attractive, option C. Option D has A's score right but it is lower than B's. Option A just adds A's raw scores and ignores the weights."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 138, $official_bank_source${"itemId":"9167d0fb-0ed9-535e-a93a-a9b329b1db20","questionId":"ae8c81e9-c702-5d93-bcb4-6f1665a27f41","sourceKey":"bank:LAG-BUA125:PQ-042","payload":{"prompt":"The additional satisfaction a consumer gets from consuming one more unit of a commodity is called:","options":["Marginal utility","Average utility","Consumer surplus","Total utility"],"correctOption":0,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Marginal utility, option A, is the extra utility from one additional unit consumed. Option D is the satisfaction from all units together, and option B is total utility divided by the number of units. Option C is the difference between what a consumer is willing to pay and what they actually pay."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 139, $official_bank_source${"itemId":"3bce257c-8698-5610-bada-ca14d4e1589f","questionId":"b65434ea-772a-5e6e-828c-9abe70e2a039","sourceKey":"bank:LAG-BUA125:PQ-051","payload":{"prompt":"The quantity demanded of Pepsi has decreased. The best explanation for this is that:","options":["Pepsi consumers had an increase in income","The price of Pepsi increased","Pepsi's advertising is less effective than in the past","The price of Coca-Cola increased"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"A change in quantity demanded is a movement along the demand curve, caused only by a change in the good's own price, so a rise in Pepsi's price is the best explanation, option B. Options A and C would shift the whole demand curve rather than change quantity demanded. Option D would actually raise demand for Pepsi, since Coca-Cola is a substitute."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 140, $official_bank_source${"itemId":"a42111fe-946c-544e-a655-036c99959299","questionId":"ee7149d8-bd50-588e-89cc-6751eb06d605","sourceKey":"bank:LAG-BUA125:PQ-052","payload":{"prompt":"A demand curve for a good is drawn while holding constant:","options":["Income, tastes and the price of the good itself","Income, tastes and the prices of other goods","Income and tastes only","Tastes and the prices of other goods only"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"A demand curve shows how quantity demanded responds to the good's own price, so everything else, including income, tastes and the prices of other goods, is held constant, option B. Option A is wrong because the good's own price is exactly what changes along the curve. Options D and C leave out some of the other factors that must be held fixed."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 141, $official_bank_source${"itemId":"a799339a-9054-519f-8f15-b82a610ddafe","questionId":"7c6ed5ba-f30e-53b7-ade7-55da7442d9b0","sourceKey":"bank:LAG-BUA125:PQ-053","payload":{"prompt":"When a decrease in the price of one good causes the demand for another good to decrease, the two goods are:","options":["Complements","Inferior goods","Substitutes","Normal goods"],"correctOption":2,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"If one good becomes cheaper, buyers switch to it and buy less of its rival, so demand for the other good falls; that is the behaviour of substitutes, option C. With complements, option A, a cheaper good would raise demand for the other. Options D and B describe how demand responds to income, not to the price of another good."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 142, $official_bank_source${"itemId":"3fb41119-7107-5727-a8b1-3cc37aba293d","questionId":"bc3f9f87-fa52-52cc-b43b-a8e68b35e31b","sourceKey":"bank:LAG-BUA125:PQ-054","payload":{"prompt":"Suppose the demand for good Z goes up when the price of good Y goes down. Goods Z and Y are:","options":["Substitutes","Complements","Perfect substitutes","Unrelated goods"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"When Y gets cheaper, people buy more Y and also more of Z, which is used with it, so Z and Y are complements, option B, like bread and butter. If they were substitutes, option A or C, a cheaper Y would reduce demand for Z. Option D is wrong because the price of Y clearly affects demand for Z."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 143, $official_bank_source${"itemId":"4fac4984-c3b5-5f18-8048-755b54e3e2eb","questionId":"5bdf5020-647f-5bbd-acc3-72852f222123","sourceKey":"bank:LAG-BUA125:PQ-055","payload":{"prompt":"If the demand for coffee decreases as income decreases, coffee is:","options":["A substitute good","An inferior good","A normal good","A complementary good"],"correctOption":2,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"For a normal good, demand moves in the same direction as income, so falling income reducing coffee demand means coffee is a normal good, option C. For an inferior good, option B, demand would rise as income falls. Options D and A describe relationships between two goods, not how demand responds to income."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 144, $official_bank_source${"itemId":"eb1bc755-343b-5f81-b61f-f3c292cf515a","questionId":"88661712-2bea-5965-919d-ade819424dd0","sourceKey":"bank:LAG-BUA125:PQ-056","payload":{"prompt":"Which of the following will NOT cause a shift in the demand curve for compact discs?","options":["A change in the price of cassette tapes","A change in consumers' wealth","A change in the price of compact discs","A change in consumers' income"],"correctOption":2,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"A change in the good's own price causes a movement along its demand curve, not a shift, so option C is right. Changes in the price of a related good (option A), income (option D) or wealth (option B) change how much is demanded at every price, which shifts the whole curve."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 145, $official_bank_source${"itemId":"f70b0105-b72f-5d0c-9e85-6f8f80c57f43","questionId":"a264e777-e683-531e-a958-94044ad61659","sourceKey":"bank:LAG-BUA125:PQ-057","payload":{"prompt":"When excess demand occurs in an unregulated market, there is a tendency for:","options":["Quantity demanded to increase","Price to rise","Quantity supplied to decrease","Price to fall"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Excess demand means buyers want more than sellers offer at the current price, so competition among buyers pushes the price up, option B, until the shortage disappears. As price rises, quantity supplied increases and quantity demanded decreases, which is the opposite of options C and A. Option D is what happens with excess supply."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 146, $official_bank_source${"itemId":"67656178-dbdf-5705-82ed-6fbb2cdc2fcd","questionId":"2c9db72c-e1ec-53b8-a0bd-64b93de2a9aa","sourceKey":"bank:LAG-BUA125:PQ-058","payload":{"prompt":"Market equilibrium exists when, at the prevailing price:","options":["Quantity demanded is greater than quantity supplied","Quantity supplied is zero","Quantity demanded is less than quantity supplied","Quantity demanded equals quantity supplied"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Equilibrium is the price at which the amount buyers want to buy exactly equals the amount sellers want to sell, option D, so there is no pressure for price to change. Option C describes a surplus, which pushes price down, and option A describes a shortage, which pushes price up."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 147, $official_bank_source${"itemId":"23ac25c3-b007-55a8-a02f-a6fca4c2fd6b","questionId":"97be29a2-782c-56d6-873f-90967558e4cf","sourceKey":"bank:LAG-BUA125:PQ-059","payload":{"prompt":"A movement along a demand curve to the left (a fall in quantity demanded) is caused by:","options":["A rise in the price of a substitute good","A change in consumers' tastes","A fall in consumers' incomes","A rise in the price of the good itself"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Only a change in the good's own price moves buyers along the demand curve, and a higher price moves them up and to the left to a lower quantity demanded, option D. Options C, A and B are non-price factors, so they shift the whole demand curve instead of causing a movement along it."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 148, $official_bank_source${"itemId":"0580566c-4d46-5167-94bf-040a2a3d6cb0","questionId":"eca7e8dc-bd72-57be-81fc-18f6bd19494c","sourceKey":"bank:LAG-BUA125:PQ-060","payload":{"prompt":"The quantity demanded of a product rises whenever:","options":["Incomes increase","The product's price falls","The prices of substitute goods rise","Population increases"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Quantity demanded changes only when the product's own price changes, and by the law of demand a lower price raises quantity demanded, option B. Options A, D and C increase demand, shifting the whole curve to the right, rather than changing quantity demanded along the curve."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 149, $official_bank_source${"itemId":"f3feb418-6ef1-568d-b5c3-b28001ce022e","questionId":"b29f9118-bac7-5721-b336-010f256c1de8","sourceKey":"bank:LAG-BUA125:PQ-061","payload":{"prompt":"Equilibrium quantity must fall when:","options":["Both demand and supply decrease","Both demand and supply increase","Demand increases and supply decreases","Demand decreases and supply increases"],"correctOption":0,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"A fall in demand and a fall in supply both reduce the quantity traded, so together they must lower equilibrium quantity, option A. Option B must raise quantity. In options C and D the two shifts pull quantity in opposite directions, so the result depends on which shift is larger."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 150, $official_bank_source${"itemId":"b7e660ba-df4c-5a7b-bdfe-f15c0b84a111","questionId":"f94174ea-85a1-59e3-b16b-e6bbd2765f27","sourceKey":"bank:LAG-BUA125:PQ-062","payload":{"prompt":"For most consumer goods (normal goods), the demand curve will shift to the left when:","options":["The prices of substitutes fall","The prices of complements increase","Incomes decrease","All of the above"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Each of the three changes reduces demand for a normal good: lower income means people buy less, cheaper substitutes draw buyers away, and dearer complements make the good less useful to buy. Because options C, A and B are all correct, option D is the best answer."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 151, $official_bank_source${"itemId":"ecd7e6d4-6182-5222-b55b-dcf224d5b8d7","questionId":"307f86e8-ee64-52d7-a8c9-0382a95cea01","sourceKey":"bank:LAG-BUA125:PQ-063","payload":{"prompt":"Goods manufactured and used in further manufacturing, processing or resale, such as flour bought by a bakery, are called:","options":["Consumer goods","Producer (intermediate) goods","Free goods","Final goods"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Producer or intermediate goods, option B, are used to make other goods or are resold, like flour used to bake bread. Options A and D refer to goods bought by households for their own use, and option C means goods that are not scarce and have no price, like air."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 152, $official_bank_source${"itemId":"2b8f3aff-5da8-5163-9dda-3ab76ba990c6","questionId":"5565daf5-e69d-5a9b-8c26-af31fae9d424","sourceKey":"bank:LAG-BUA125:PQ-064","payload":{"prompt":"Consumer goods, which are bought by households for their own use, are also called:","options":["Intermediate goods","Capital goods","Producer goods","Final goods"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Consumer goods are also called final goods, option D, because they have reached their final user and will not be processed further. Options A and C are goods used in making other goods, and option B refers to long-lasting goods such as machines used in production."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 153, $official_bank_source${"itemId":"4ebbe4c2-005f-5fe8-8022-fda4db1ad346","questionId":"050ed90e-5304-5eb8-a121-7079ddb46cf5","sourceKey":"bank:LAG-BUA125:PQ-067","payload":{"prompt":"When the demand for a product is tied to the purchase of some parent product, such as the demand for tyres arising from the demand for cars, it is called:","options":["Individual demand","Market demand","Derived (induced) demand","Autonomous demand"],"correctOption":2,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Derived or induced demand, option C, exists because of the demand for another, parent product. Option D is demand that does not depend on any other product. Options A and B describe whose demand is measured, one consumer or all consumers, not why it arises."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 154, $official_bank_source${"itemId":"0619a910-d36c-547c-9cc5-11a90e3d8ecf","questionId":"fd85fb67-a9f1-5175-8918-650109329ba1","sourceKey":"bank:LAG-BUA125:PQ-069","payload":{"prompt":"The law of demand states that, other things being equal:","options":["As price falls, demand increases","As price falls, quantity demanded increases","As price rises, quantity demanded increases","As price rises, demand decreases"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"The law of demand describes an inverse relationship between a good's price and its quantity demanded, so a fall in price raises quantity demanded, option B. Option C gets the direction wrong. Options A and D say demand instead of quantity demanded; a change in demand means the whole curve shifts, which price changes do not cause."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 155, $official_bank_source${"itemId":"8317dda1-bd8d-53be-87fe-ab174e14f4bf","questionId":"b98039dd-3cba-5e39-96e5-dd1dac456bd5","sourceKey":"bank:LAG-BUA125:PQ-070","payload":{"prompt":"When a market operates without interference, price increases distribute what is available to those who are willing and able to pay the most. This process is known as:","options":["Price rationing","Quantity adjustment","Price fixing","Quantity setting"],"correctOption":0,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Price rationing, option A, is the way rising prices allocate scarce goods to buyers who value them most and can pay. Option C is when government or firms set the price, the opposite of a free market. Options B and D describe changes in amounts, not the use of price to share out goods."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 156, $official_bank_source${"itemId":"46e5467b-3ea4-53ca-bd7f-94b12eae1b82","questionId":"c1f12513-e7c2-597c-8a58-aa171b712c5b","sourceKey":"bank:LAG-BUA125:PQ-072","payload":{"prompt":"Consumers expect the price of rice to rise sharply next month. What happens to the demand curve for rice today?","options":["It stays the same","It shifts to the right","It shifts to the left","There is a movement down along the curve"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Expectations are a non-price factor of demand: expecting higher prices, consumers buy more now, so the demand curve shifts to the right, option B. Option C is the opposite. Option D would need a change in today's price of rice, and option A ignores the effect of expectations."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 157, $official_bank_source${"itemId":"702311cc-6463-5043-83cd-2418e5a90d46","questionId":"ae087855-2a85-51a6-bd15-e190caf91975","sourceKey":"bank:LAG-BUA125:PQ-073","payload":{"prompt":"The specific amount of a good that buyers are willing and able to buy at a particular price is called:","options":["Quantity demanded","Consumer surplus","Market supply","Demand"],"correctOption":0,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Quantity demanded, option A, is one specific amount at one specific price, a single point on the demand curve. Option D, demand, is the whole relationship between price and quantity demanded. Option C concerns sellers, and option B is the extra value buyers get above what they pay."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 158, $official_bank_source${"itemId":"ca61bfcb-0e8a-5ec8-9686-3b8ea7995501","questionId":"d0ec9afd-9aa0-562a-960f-274665691f13","sourceKey":"bank:LAG-BUA125:PQ-074","payload":{"prompt":"If the price of a complement increases, all else equal:","options":["Demand for the good will increase","Demand for the good will decrease","Quantity supplied of the good will increase","Quantity demanded of the good will increase"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Complements are used together, so when one becomes dearer people buy less of it and less of the good that goes with it, and the demand curve shifts left, option B. Option A is what happens when the price of a substitute rises. Options D and C refer to movements along curves, which only the good's own price causes."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 159, $official_bank_source${"itemId":"a3863b91-99d3-5268-9413-962f9f4a5a9a","questionId":"84a14775-0087-5f21-93a7-fd0ec0849f33","sourceKey":"bank:LAG-BUA125:PQ-075","payload":{"prompt":"Which of the following would lead to an INCREASE in the demand for golf balls?","options":["An increase in the price of golf clubs","A decrease in the cost of producing golf balls","An increase in average household income, when golf balls are a normal good","A decrease in the price of golf balls"],"correctOption":2,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Higher income raises demand for a normal good, shifting the curve to the right, so option C is right. Option D increases quantity demanded along the curve, not demand. Option A reduces demand because clubs are a complement, and option B affects supply, not demand."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 160, $official_bank_source${"itemId":"54dca22c-ca30-533e-8363-71b6decb28e1","questionId":"2660b3fe-a03c-5fbe-9563-4f50464e7b6c","sourceKey":"bank:LAG-BUA125:PQ-078","payload":{"prompt":"When a vineyard increases the price of its wine from $15 per bottle to $20 per bottle, the result is a decrease in:","options":["The quantity of this wine supplied","The supply of this wine","The quantity of this wine demanded","The demand for this wine"],"correctOption":2,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"A change in the good's own price causes a movement along the demand curve, so a higher price reduces the quantity demanded, option C. Option D would require a shift of the whole demand curve, caused by non-price factors. Option A is wrong because a higher price would encourage more to be supplied, and option B is a shift of the supply curve."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 161, $official_bank_source${"itemId":"0f529779-ebdc-551c-a28e-c271641849bf","questionId":"ca4f74d3-4397-5209-97a9-72950b9e3e84","sourceKey":"bank:LAG-BUA125:PQ-080","payload":{"prompt":"In which of the following cases will the effect on equilibrium quantity be indeterminate, depending on the sizes of the shifts in demand and supply?","options":["Demand decreases and supply decreases","Demand increases and supply increases","Demand decreases and supply increases","Demand remains constant and supply increases"],"correctOption":2,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"A fall in demand lowers quantity while a rise in supply raises it, so the net effect on quantity depends on which shift is bigger, option C. In options A and B both shifts push quantity the same way, down or up, and in option D a supply increase alone clearly raises quantity."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 162, $official_bank_source${"itemId":"3bef4fb0-89ea-56ae-9cb6-5dc349313d10","questionId":"ffef5973-d304-54c2-8fb5-b748456cfc4c","sourceKey":"bank:LAG-BUA125:PQ-082","payload":{"prompt":"A change in demand, as opposed to a change in quantity demanded, means:","options":["Only the price of the good has changed","The entire demand curve shifts","Quantity demanded equals quantity supplied","There is a movement along the same demand curve"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"A change in demand is a change in the entire demand relationship, so the whole curve shifts left or right, option B, because of factors such as income, tastes or prices of related goods. Options D and A describe a change in quantity demanded caused by the good's own price. Option C describes equilibrium."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 163, $official_bank_source${"itemId":"1920ddb9-efe3-5d25-9964-acd6def81a93","questionId":"54263c11-fb05-579b-90da-01f13f392c81","sourceKey":"bank:LAG-BUA125:PQ-083","payload":{"prompt":"The demand for a given product will rise if:","options":["Incomes rise for a normal good or fall for an inferior good","The price of a substitute rises","The price of a complement falls","All of these"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Each listed change shifts demand to the right: income changes in the direction that favours the good, a cheaper complement makes the good more useful to buy, and a dearer substitute pushes buyers towards it. Since options A, C and B are all correct, option D is the answer."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 164, $official_bank_source${"itemId":"55a7b638-9bad-5013-b132-b0518e4021b8","questionId":"437146e4-1932-5496-b4ce-c95836dff4f3","sourceKey":"bank:LAG-BUA125:PQ-084","payload":{"prompt":"Two explanations for the law of demand are the:","options":["Price and quantity effects","Substitutes and inferior goods","Substitution and income effects","Opportunity cost and substitution effects"],"correctOption":2,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"When a good's price rises, buyers switch to cheaper alternatives (substitution effect) and their real income falls so they can afford less (income effect), option C. Option A just restates the price-quantity relationship rather than explaining it. Options D and B each mix in ideas that are not the standard explanation."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 165, $official_bank_source${"itemId":"b996c846-01bb-58e1-9d59-4c41d6337830","questionId":"a2bfe5af-9fbd-5793-9468-7ac9ebe1cc56","sourceKey":"bank:LAG-BUA125:PQ-085","payload":{"prompt":"An increase in demand, ceteris paribus, will usually cause:","options":["A decrease in quantity demanded","An increase in supply","An increase in quantity supplied","A higher quantity and a lower price"],"correctOption":2,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"An increase in demand raises the equilibrium price, and sellers respond by moving up the supply curve, so quantity supplied increases, option C. Option B would be a shift of the supply curve, which a demand change does not cause. Option D is wrong because price rises, not falls."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 166, $official_bank_source${"itemId":"b85eecc4-60ba-5f8d-a832-722536f17895","questionId":"2742da94-ee96-5b57-a5a9-568cc133b00f","sourceKey":"bank:LAG-BUA125:PQ-087","payload":{"prompt":"The demand curve slopes downward because, at a higher price for a good (ceteris paribus), people:","options":["Have higher incomes","Buy fewer substitutes","Buy more complements","Search for substitutes"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"A higher price makes the good relatively dearer, so buyers look for substitutes and buy less of it, option D. Option B is the opposite, since buyers move towards substitutes. Option C is wrong because buying less of a good also means buying fewer of its complements, and option A confuses price with income."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 167, $official_bank_source${"itemId":"d5689d6c-3496-5060-8685-860bf8cb4485","questionId":"019a1e90-48b3-5bf4-86b1-0ebcdb3b864f","sourceKey":"bank:LAG-BUA125:PQ-090","payload":{"prompt":"If the price of crackers goes up when the price of cheese goes down, crackers and cheese are:","options":["Complements","Both substitutes and complements","Inferior goods","Substitutes"],"correctOption":0,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Cheaper cheese means people buy more cheese and also more crackers to eat with it; the higher demand pushes the price of crackers up, so they are complements, option A. With substitutes, option D, cheaper cheese would reduce demand for crackers. Option C relates to income, and option B is impossible because two goods cannot be both at the same time."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 168, $official_bank_source${"itemId":"26a4c1d4-d9b0-56d3-bf5b-74228040eff2","questionId":"f588f016-bd5b-50a9-ae33-2fd7bb188eb4","sourceKey":"bank:LAG-BUA125:PQ-091","payload":{"prompt":"If the price elasticity of demand for a good is 0.75, demand for the good is:","options":["Normal","Elastic","Inferior","Inelastic"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"An elasticity below 1 means quantity demanded changes by a smaller percentage than price, so demand is inelastic, option D. Option B would need a value greater than 1. Options A and C describe how demand responds to income, not price."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 169, $official_bank_source${"itemId":"c3179070-ef12-5204-9b13-d218fcbf4072","questionId":"23b42c65-acd3-5471-a761-55caf4d3533c","sourceKey":"bank:LAG-BUA125:PQ-092","payload":{"prompt":"When the price of a product is increased by 10 percent, quantity demanded decreases by 15 percent. In this price range, demand for the product is:","options":["Unitary elastic","Inelastic","Cross-elastic","Elastic"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Price elasticity is 15% / 10% = 1.5, and a value greater than 1 means demand is elastic, option D. Option B needs a value below 1 and option A needs exactly 1. Option C refers to the effect of another good's price."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 170, $official_bank_source${"itemId":"121d0b9a-9d01-58d8-9bb8-89f3fd75421c","questionId":"dd8cacf1-7a7e-5ee3-bbea-e503c0a97942","sourceKey":"bank:LAG-BUA125:PQ-093","payload":{"prompt":"If the price elasticity of demand for a product is 0.5, a 10 percent decrease in price will:","options":["Decrease quantity demanded by 5 percent","Increase quantity demanded by 5 percent","Increase quantity demanded by 0.5 percent","Decrease quantity demanded by 0.5 percent"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Percentage change in quantity = elasticity x percentage change in price = 0.5 x 10% = 5%, and since price falls, quantity demanded rises, option B. Option C uses the elasticity figure itself as the answer. Options A and D get the direction wrong, since a lower price raises quantity demanded."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 171, $official_bank_source${"itemId":"62bef1d5-4dc2-55a0-8802-26c4a96dc289","questionId":"35fb0249-5d2c-50c3-9ebe-be993c77c8c5","sourceKey":"bank:LAG-BUA125:PQ-094","payload":{"prompt":"If an increase in the supply of a product lowers its price but leaves the quantity exchanged unchanged, then:","options":["The price elasticity of supply is zero","The price elasticity of demand is unitary","The price elasticity of supply is infinite","The price elasticity of demand is zero"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"If buyers buy the same amount whatever the price, demand is perfectly inelastic, meaning price elasticity of demand is zero, option D; the demand curve is vertical, so the supply shift changes only price. Option B would change quantity. Options A and C describe the supply curve, but here it is the shape of demand that keeps quantity fixed."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 172, $official_bank_source${"itemId":"30016ea2-5ae1-5e34-b477-6a9f427a61c0","questionId":"e592dd1c-7ab1-5012-ab84-56f3ec94d5a4","sourceKey":"bank:LAG-BUA125:PQ-095","payload":{"prompt":"If 100 units of product K are sold at a unit price of $10 and 75 units are sold at a unit price of $15, then in this price range demand for product K is:","options":["Perfectly elastic","Elastic","Unitary elastic","Inelastic"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Total revenue rises from $1,000 (100 x $10) to $1,125 (75 x $15) when price goes up, which only happens when demand is inelastic, option D. The elasticity works out to about 0.71 by the midpoint method (0.5 using the starting values), below 1 either way. Option B would make revenue fall as price rises, and option C would leave revenue unchanged."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 173, $official_bank_source${"itemId":"9a7793be-bcaf-5114-ac5f-cf70c509ec93","questionId":"fcf9fbe5-87b2-5144-870c-c9b63e552a5d","sourceKey":"bank:LAG-BUA125:PQ-096","payload":{"prompt":"Total revenue falls as the price of a good increases if price elasticity of demand is:","options":["Perfectly inelastic","Inelastic","Elastic","Unitary elastic"],"correctOption":2,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"With elastic demand, quantity falls by a bigger percentage than price rises, so total revenue falls, option C. With inelastic or perfectly inelastic demand, options B and A, revenue rises when price goes up, and with unitary elasticity, option D, it stays the same."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 174, $official_bank_source${"itemId":"9df38ab9-f7db-51c5-a208-db37945114af","questionId":"70b32bf6-9557-5685-be26-97befc899362","sourceKey":"bank:LAG-BUA125:PQ-097","payload":{"prompt":"The demand for one brand of breakfast cereal is more price-elastic than the demand for breakfast cereals as a whole. This is best explained by the fact that:","options":["Cereals are a necessity","The brand is a luxury good","Total consumption of cereals is greater than consumption of the brand","There are more substitutes for one brand than for cereals as a whole"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"If one brand raises its price, buyers can easily switch to other brands, but there are fewer substitutes for cereal in general, so the brand's demand is more elastic, option D. Options B and A are claims about the goods themselves and do not explain the difference. Option C is about quantities, which do not determine elasticity."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 175, $official_bank_source${"itemId":"528638fb-eb57-5334-8fe2-f3dfc5986877","questionId":"043c65bb-45fc-5c5d-a2bf-e7f82df582a5","sourceKey":"bank:LAG-BUA125:PQ-098","payload":{"prompt":"What is the most likely effect of the growth of home video, streaming services and movie rentals on the cinema industry?","options":["Decreased costs of producing films","Increased price elasticity of demand for cinema tickets","Increased demand for cinema tickets","Cinema tickets becoming an inferior good"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"These services are substitutes for going to the cinema, and more substitutes make demand more sensitive to price, option B. Option C is the opposite, since substitutes would reduce demand. Option A relates to production costs, and option D concerns how demand reacts to income, which these changes do not decide."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 176, $official_bank_source${"itemId":"cac0e826-c4fe-55d2-80d7-bb6be151a426","questionId":"90395ec3-dc8a-5de3-b536-fa6709b7b23d","sourceKey":"bank:LAG-BUA125:PQ-099","payload":{"prompt":"The price elasticity of demand increases with the length of the time period considered because, over time:","options":["Consumers are better able to find substitutes","The demand curve shifts outward","Consumers' incomes increase","All prices increase"],"correctOption":0,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Given more time, buyers learn about and switch to alternatives, so their response to a price change grows, option A. Options C, B and D describe other changes that do not explain why the response to price itself becomes larger."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 177, $official_bank_source${"itemId":"fcfc525b-ee90-5009-af54-67af04983bc4","questionId":"2653d7bc-6693-521a-b750-848b6be112f8","sourceKey":"bank:LAG-BUA125:PQ-101","payload":{"prompt":"A state government wants to raise more tax revenue by increasing the tax on cigarettes. The tax would raise the most new revenue if the price elasticity of demand for cigarettes is:","options":["Perfectly elastic","Unitary elastic","Inelastic","Elastic"],"correctOption":2,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"With inelastic demand, smokers keep buying nearly the same quantity after the price rises, so the tax base stays large and revenue rises, option C. With elastic demand, option D, purchases fall sharply and the extra revenue is small. With perfectly elastic demand, option A, any price rise would wipe out sales."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 178, $official_bank_source${"itemId":"77a4d7d1-3f78-5b35-94bb-749427e1496e","questionId":"3770820d-151c-5e85-8449-1598070f865b","sourceKey":"bank:LAG-BUA125:PQ-102","payload":{"prompt":"A television maker is considering a 10 percent price reduction on its sets. If demand in this price range is inelastic:","options":["Revenue from the sets will increase","Revenue from the sets will remain constant","The number of sets sold will decrease","Revenue from the sets will decrease"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"With inelastic demand, quantity rises by a smaller percentage than price falls, so total revenue decreases, option D. Option A would be true for elastic demand, and option B for unitary elasticity. Option C is wrong because a lower price still raises the quantity sold, just not by enough."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 179, $official_bank_source${"itemId":"a42a5b19-14b0-5883-ae2b-8512961d03b5","questionId":"0a1a6aab-906e-54c3-8a14-0f6d236e1a07","sourceKey":"bank:LAG-BUA125:PQ-103","payload":{"prompt":"The responsiveness of the quantity demanded of a commodity to a change in its own price is called:","options":["Cross elasticity of demand","Price elasticity of supply","Income elasticity of demand","Price elasticity of demand"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Price elasticity of demand, option D, measures how much quantity demanded responds to a change in the good's own price. Option C measures the response to income and option A the response to the price of another good. Option B is about sellers rather than buyers."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 180, $official_bank_source${"itemId":"7489180c-62ba-5569-bb20-f025ff01ec8d","questionId":"e09962cf-61de-54fb-9363-dd5c044934e2","sourceKey":"bank:LAG-BUA125:PQ-104","payload":{"prompt":"Demand for which a very small change in price causes an infinitely large change in quantity demanded is described as:","options":["Perfectly elastic","Unitary elastic","Relatively inelastic","Perfectly inelastic"],"correctOption":0,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Perfectly elastic demand, option A, has an elasticity of infinity and a horizontal demand curve, so even a tiny price change makes quantity demanded change without limit. Option D is the opposite, where quantity does not change at all. Options B and C describe moderate, finite responses."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 181, $official_bank_source${"itemId":"7ae9ce67-aa41-5f4f-bd3f-d4d3d5caa75f","questionId":"fc4a3198-7117-500c-a25f-a3242df554e7","sourceKey":"bank:LAG-BUA125:PQ-105","payload":{"prompt":"Factors that affect the value of the price elasticity of demand include the:","options":["Proportion of income spent on the good","Time period of analysis","Availability of substitutes","All of these"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Demand is more elastic when there are more substitutes, when buyers have more time to adjust, and when the good takes a bigger share of income. Since options C, B and A are all determinants of elasticity, option D is the answer."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 182, $official_bank_source${"itemId":"8cc517e6-c20f-5c21-8c56-4d147aea3e75","questionId":"5b3ecf90-a30e-568f-b6a8-e3d4b50eba93","sourceKey":"bank:LAG-BUA125:PQ-107","payload":{"prompt":"Cross elasticity of demand is:","options":["Unitary for inferior goods","Positive for inferior goods","Negative for complementary goods","Negative for substitute goods"],"correctOption":2,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"For complements, a rise in one good's price lowers demand for the other, so cross elasticity is negative, option C. Option D is wrong because substitutes have positive cross elasticity. Options B and A confuse cross elasticity with income elasticity; inferior goods are defined by a negative income elasticity."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 183, $official_bank_source${"itemId":"f26425b6-e86a-5bf5-a576-5f9e7309818d","questionId":"8d9a7bd8-50ba-5603-a1d5-4ed44fa378a2","sourceKey":"bank:LAG-BUA125:PQ-108","payload":{"prompt":"A positive cross elasticity of demand coefficient indicates that:","options":["A product is an inferior good","The two products are substitutes","The two products are complements","A product is a normal good"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Positive cross elasticity means a rise in one good's price raises demand for the other, which is how substitutes behave, option B. Complements, option C, have negative cross elasticity. Options A and D are classified by income elasticity, not cross elasticity."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 184, $official_bank_source${"itemId":"b28158de-6c6f-58db-8f98-c4f133acf263","questionId":"27506fc2-cea9-53b6-9d9a-1c9d84ff3f2d","sourceKey":"bank:LAG-BUA125:PQ-111","payload":{"prompt":"If, in a particular market, price has risen and the quantity exchanged has increased, it is most likely that:","options":["Supply has decreased","Supply has increased","Demand has decreased","Demand has increased"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"A rightward shift of demand moves the market up along the supply curve, raising both price and quantity, option D. A fall in demand, option C, lowers both. A rise in supply, option B, lowers price, and a fall in supply, option A, raises price but lowers quantity."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 185, $official_bank_source${"itemId":"b2659862-cd95-536a-91df-950cbe297d81","questionId":"3accdc8b-c59a-5f8b-9cc7-e5cac077f336","sourceKey":"bank:LAG-BUA125:PQ-112","payload":{"prompt":"The quantity of a good demanded rises from 1,000 to 1,500 units when the price falls from N150 to N100 per unit. Using the midpoint (arc) method, the price elasticity of demand (in absolute value) is approximately:","options":["2.5","4.0","1.0","16"],"correctOption":2,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"With the midpoint method, the change in quantity is 500 / 1,250 = 40% and the change in price is 50 / 125 = 40%, so elasticity = 40% / 40% = 1.0 (unit elastic). Option A (2.5) and option B (4.0) come from mixing up or misplacing the percentage changes, and option D is far too large for these figures."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 186, $official_bank_source${"itemId":"c3b68f68-da8f-54f7-baee-0962af3a5eee","questionId":"8911000b-d5ae-5fc5-9d7c-945e80f0f1d3","sourceKey":"bank:LAG-BUA125:PQ-113","payload":{"prompt":"If the price elasticity of demand for a commodity is 1.5, then a decrease in price from N210 to N190 (a 10% fall using the midpoint method) would be expected to increase daily sales by about:","options":["5%","50%","15%","1.5%"],"correctOption":2,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Percentage change in quantity = elasticity x percentage change in price = 1.5 x 10% = 15%. Option D simply repeats the elasticity figure, option A wrongly halves the price change, and option B is far bigger than the elasticity allows."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 187, $official_bank_source${"itemId":"0ec447e9-9cef-5a2b-8e61-d611df944d7f","questionId":"73ac9a4a-1346-5859-83d2-864605b659d6","sourceKey":"bank:LAG-BUA125:PQ-114","payload":{"prompt":"Compared with the short-run demand curve for the same commodity, a long-run demand curve is generally:","options":["less elastic","of the same elasticity","perfectly inelastic","more elastic"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Over a longer period, buyers have time to find substitutes and change their habits, so quantity demanded responds more strongly to a price change. Option A has it the wrong way round, and option B ignores the role of time in adjustment."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 188, $official_bank_source${"itemId":"7e141244-b1d5-56b0-8bfe-aa45a4765735","questionId":"6b6ea27b-c57d-5fca-971a-6796e419fd60","sourceKey":"bank:LAG-BUA125:PQ-115","payload":{"prompt":"The price elasticity of demand is 5.0 if a 10 percent increase in price results in a:","options":["10% decrease in quantity demanded","5% decrease in quantity demanded","2% decrease in quantity demanded","50% decrease in quantity demanded"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Elasticity = percentage change in quantity / percentage change in price, so 50% / 10% = 5.0. Option C gives 0.2, option B gives 0.5 and option A gives 1.0, none of which is 5."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 189, $official_bank_source${"itemId":"bf92e2da-965b-5543-9ff1-45d699316e21","questionId":"02470a86-135b-51c1-ad28-f8c109ecb6f5","sourceKey":"bank:LAG-BUA125:PQ-116","payload":{"prompt":"Demand for a good is likely to be more price elastic:","options":["the larger the proportion of monthly income spent on it","the higher the level of the consumer's income","the more the good is regarded as a necessity","the fewer the good substitutes available"],"correctOption":0,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"When a good takes a big share of the budget, a price rise hurts noticeably, so buyers cut back more. Option D and option C describe conditions that make demand less elastic, and higher income (B) usually makes buyers less, not more, sensitive to price."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 190, $official_bank_source${"itemId":"66b84b13-3e81-5f0e-a826-e14f17e9e7cf","questionId":"701a002c-2e18-5d91-8490-e31a1c2cfc68","sourceKey":"bank:LAG-BUA125:PQ-117","payload":{"prompt":"Demand for a good will be more price elastic:","options":["the more urgently consumers need the good","the more substitutes available for the good","the lower the share of income spent on it","the shorter the time since a permanent price increase"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"If many close substitutes exist, buyers can easily switch when the price rises, so quantity demanded falls sharply. Option D is wrong because buyers need time to adjust, so demand is less elastic just after a price change, and options C and A also point to less elastic demand."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 191, $official_bank_source${"itemId":"9f3b1310-b602-53c2-8ac7-0f0e963a458f","questionId":"f17eb190-ac32-5c6c-9f89-bcb5f6eb5d75","sourceKey":"bank:LAG-BUA125:PQ-118","payload":{"prompt":"Price elasticity of demand measures:","options":["the responsiveness of quantity demanded to a change in consumers' income","the responsiveness of quantity supplied to a change in price","the responsiveness of quantity demanded to a change in the price of another good","the responsiveness of quantity demanded to a change in the good's own price"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Price elasticity of demand compares the percentage change in quantity demanded with the percentage change in the good's own price. Option A is income elasticity, option C is cross elasticity, and option B is elasticity of supply."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 192, $official_bank_source${"itemId":"0bfc63ee-9cca-588f-b3e2-ac0084a39ad1","questionId":"718d5be0-8a7b-5065-af6e-dddd63cd8cd1","sourceKey":"bank:LAG-BUA125:PQ-119","payload":{"prompt":"If a good has no close substitutes and is regarded as a necessity by most consumers, its demand is likely to be:","options":["highly price elastic","unit elastic at every price","price inelastic","perfectly elastic"],"correctOption":2,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"People keep buying necessities with no close substitutes even when the price rises, so quantity demanded changes only a little. Options A and D describe goods buyers readily abandon when price rises, which is the opposite case."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 193, $official_bank_source${"itemId":"90564af7-652a-5bd8-b292-2127da111ce6","questionId":"3b408050-f66d-581b-ab9b-ad0d66d3fac5","sourceKey":"bank:LAG-BUA125:PQ-120","payload":{"prompt":"Cross elasticity of demand is the ratio of:","options":["the percentage change in quantity demanded of one good to the percentage change in the price of another good","the percentage change in quantity demanded of a good to the percentage change in income","the change in the price of one good to the change in the price of another good","the percentage change in quantity demanded of a good to the percentage change in its own price"],"correctOption":0,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Cross elasticity links demand for one good to the price of a different good, which is how we tell substitutes from complements. Option D is own-price elasticity, option B is income elasticity, and option C compares two prices with no quantity at all."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 194, $official_bank_source${"itemId":"2702fe26-c6b3-5215-aae1-87d0b91f15b9","questionId":"28eb6e97-260e-5e30-8f8d-8077ab6c88a6","sourceKey":"bank:LAG-BUA125:PQ-121","payload":{"prompt":"A 50 percent increase in price causes a 90 percent decrease in quantity demanded. In this price range, demand is:","options":["inelastic, with an elasticity of 0.56","elastic, with an elasticity of 1.8","perfectly inelastic, with an elasticity of 0","unit elastic, with an elasticity of 1.0"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Elasticity = 90% / 50% = 1.8, and any value greater than 1 means demand is elastic. Option A divides the figures the wrong way round (50 / 90), and options D and C do not match the large fall in quantity."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 195, $official_bank_source${"itemId":"ea7b571a-1637-54fe-aae2-0694cc4ff181","questionId":"9f73cf82-256f-5b9c-a30f-32728ffed23b","sourceKey":"bank:LAG-BUA125:PQ-123","payload":{"prompt":"If two goods are substitutes, an increase in the price of one good will lead to:","options":["a decrease in demand for the other good","no change in demand for the other good","a fall in the price of the first good","an increase in demand for the other good"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"When one good becomes dearer, buyers switch to its substitute, so demand for the substitute rises (positive cross elasticity). Option A describes complements, and option B describes unrelated goods."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 196, $official_bank_source${"itemId":"de5e231b-86e1-585f-a6e8-4b748c168a3a","questionId":"afef0462-bc33-5c29-b97c-e6173df2280f","sourceKey":"bank:LAG-BUA125:PQ-124","payload":{"prompt":"If two goods are complements, a decrease in the price of one good will lead to:","options":["a decrease in demand for the other good","a decrease in the quantity demanded of the first good","no change in demand for the other good","an increase in demand for the other good"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Complements are used together, so when one becomes cheaper people buy more of it and also more of its partner. Option A gets the direction wrong, and option B contradicts the law of demand, since a lower price raises the quantity demanded of the first good."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 197, $official_bank_source${"itemId":"8ac5f7f1-8736-58a9-bf44-93123e1e7d6c","questionId":"a978e3d8-0d18-5053-9869-abc74a858002","sourceKey":"bank:LAG-BUA125:PQ-125","payload":{"prompt":"Along a straight-line, downward-sloping demand curve:","options":["the slope and the price elasticity are the same thing","the slope is constant but price elasticity changes from point to point","both the slope and the price elasticity are constant","price elasticity is the same at every point"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Slope measures absolute changes, while elasticity measures percentage changes, so on a straight line the slope stays the same but elasticity is higher at high prices and lower at low prices. Options A, D and C all wrongly treat elasticity as equal to, or as fixed as, the slope."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 198, $official_bank_source${"itemId":"42f4b667-48b2-5029-8715-48d1196b0be5","questionId":"9a07bf62-b19e-565d-b679-7d923e358faa","sourceKey":"bank:LAG-BUA125:PQ-126","payload":{"prompt":"If demand for a product is price elastic, then:","options":["a fall in price will raise total revenue","a change in price will have no effect on total revenue","a rise in price will raise total revenue","a fall in price will lower the quantity demanded"],"correctOption":0,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"With elastic demand, quantity changes by a bigger percentage than price, so cutting price brings in enough extra sales to raise total revenue. Option C is true only for inelastic demand, option B describes unit elastic demand, and option D breaks the law of demand."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 199, $official_bank_source${"itemId":"42cfd94c-8049-5797-bc29-42e55972faf8","questionId":"5cb59329-6485-57c7-a094-34ca9d54c3fc","sourceKey":"bank:LAG-BUA125:PQ-127","payload":{"prompt":"Complementary goods have:","options":["a positive cross price elasticity of demand with respect to each other","the same price elasticity of demand","a negative cross price elasticity of demand with respect to each other","a cross price elasticity of exactly zero"],"correctOption":2,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"For complements, a rise in the price of one good reduces demand for the other, so the cross elasticity is negative. Option A describes substitutes, option D describes unrelated goods, and option B is not a feature that defines complements."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 200, $official_bank_source${"itemId":"106e550e-316b-5f78-94fd-e8ceb8912ca6","questionId":"a44b2b16-91ae-5525-b9d5-3389a9121544","sourceKey":"bank:LAG-BUA125:PQ-128","payload":{"prompt":"The price elasticity of demand generally tends to be:","options":["unrelated to the length of time","smaller in the short run than in the long run","the same in the short run and the long run","smaller in the long run than in the short run"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Buyers need time to discover substitutes and adjust their habits, so demand becomes more elastic as time passes. Option D reverses this, while options C and A ignore the effect of time on adjustment."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 201, $official_bank_source${"itemId":"40129a28-f2fc-5ecc-84c1-eb0371d6a810","questionId":"a660d9ea-d70f-5464-a0b2-bda9cacdaee5","sourceKey":"bank:LAG-BUA125:PQ-130","payload":{"prompt":"If the cross-price elasticity of demand between two commodities is +1.5, the two goods are:","options":["inferior goods","complements","luxury goods","substitutes"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"A positive cross elasticity means a rise in the price of one good raises demand for the other, which is the mark of substitutes. Option B would need a negative value, and options C and A are judged with income elasticity, not cross elasticity."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 202, $official_bank_source${"itemId":"4e9190a8-70f8-55f3-ae14-65bfd1e1b197","questionId":"9b6297d1-0bba-5dbd-9e4d-82888621d3c3","sourceKey":"bank:LAG-BUA125:PQ-132","payload":{"prompt":"Which of the following will make the demand for a product more price elastic?","options":["The product has no close substitutes","The product is a basic necessity","A long time has passed since the product's price changed","A very small proportion of income is spent on the product"],"correctOption":2,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"The longer buyers have to react to a price change, the more they find substitutes, so demand becomes more elastic over time. Options A, D and B are all conditions that make demand less elastic."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 203, $official_bank_source${"itemId":"03f16e12-3f25-59a0-9ee2-e5f77fcbefb3","questionId":"33fb2929-66d1-5cec-abeb-f0777c8e49ce","sourceKey":"bank:LAG-BUA125:PQ-143","payload":{"prompt":"A normal market demand curve:","options":["is a horizontal line at every price level","slopes upward from left to right, showing that quantity demanded rises as price rises","slopes downward from left to right, showing that quantity demanded falls as price rises","is a vertical line, showing that price has no effect on quantity demanded"],"correctOption":2,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"The law of demand says that, other things being equal, people buy more at lower prices and less at higher prices, so the demand curve slopes downward. Option B describes a typical supply curve, and options D and A are special extreme cases, not the normal curve."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 204, $official_bank_source${"itemId":"7ff67df8-067c-5fa7-b820-df035ba549d9","questionId":"d1804d0e-5dd9-5134-a8eb-36b8c1bf4eee","sourceKey":"bank:LAG-BUA125:PQ-145","payload":{"prompt":"Aglets are the metal or plastic tips on shoelaces that make lacing easier. The demand for aglets is probably:","options":["inelastic","unit elastic","elastic but not perfectly elastic","perfectly elastic"],"correctOption":0,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Aglets cost very little, take a tiny share of income and have no real substitute in shoelaces, so a price change hardly affects how many are bought. Options D and C would require buyers to react strongly to price, which is unlikely for such a cheap, essential part."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 205, $official_bank_source${"itemId":"b1a39390-a944-5f07-a8cd-0153fe26d4cc","questionId":"fd648024-e934-5897-838e-9077eb4ec965","sourceKey":"bank:LAG-BUA125:PQ-146","payload":{"prompt":"Cross elasticity of demand measures the responsiveness of the quantity demanded of a good to changes in the prices of:","options":["its substitutes but not its complements","both its substitutes and its complements","neither its substitutes nor its complements","its complements but not its substitutes"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Cross elasticity can be calculated for any related good: a positive value shows a substitute and a negative value shows a complement. Options D and A wrongly limit it to only one kind of related good."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 206, $official_bank_source${"itemId":"58fd1367-3061-5f84-aa5b-d39148515fec","questionId":"f93d919f-e27d-57f0-a195-aae281884b20","sourceKey":"bank:LAG-BUA125:PQ-148","payload":{"prompt":"If a rise in the price of good 1 decreases the quantity demanded of good 2, then:","options":["the cross elasticity of demand is negative","good 2 is an inferior good","the cross elasticity of demand is positive","good 1 is an inferior good"],"correctOption":0,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"The price of good 1 went up while demand for good 2 went down, so the two changes have opposite signs and the cross elasticity is negative, which shows the goods are complements. Option C would describe substitutes, and options D and B concern income, not the price of another good."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 207, $official_bank_source${"itemId":"d75dda79-1ed0-5a6a-b3b2-88766a2fd5d7","questionId":"3f8582b5-d12e-5642-aa31-1ad81b5d37fc","sourceKey":"bank:LAG-BUA125:PQ-256","payload":{"prompt":"The long-term profits of firms in an industry are most threatened when barriers to entry are:","options":["high","strengthened by patents","low","strengthened by large economies of scale"],"correctOption":2,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Low barriers mean new firms can easily come in, compete for customers and push prices and profits down, which is the threat of new entrants. Option A protects existing firms, because high barriers keep newcomers out. Options B and D are examples of high barriers, so they also protect profits."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 208, $official_bank_source${"itemId":"9397b342-392c-51a6-ba77-1a9c846bb4c5","questionId":"b60faeb2-9560-5e4c-9d14-2108c337523e","sourceKey":"bank:LAG-BUA125:ATT-001","payload":{"prompt":"A place where the factors of production are traded on agreed terms, or an intended destination for the sale of a product that meets a firm's economic objectives and satisfies society's needs, is best described as a:","options":["Factory","Market","Warehouse","Supply chain"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"A market is where exchange takes place: goods, services or factors of production are traded on agreed terms, and it is the destination where a firm sells its product. Option A is where goods are made, while options C and D describe storage and the movement of goods, not the place of exchange itself."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 209, $official_bank_source${"itemId":"ba9c980c-3bd6-5d2d-9e89-de1de5bbb796","questionId":"c604da86-509d-557b-bcfd-3126d1efe675","sourceKey":"bank:LAG-BUA125:ATT-002","payload":{"prompt":"The potential of a market to provide a firm with long-term profitability and growth opportunities is known as:","options":["Market equilibrium","Market attractiveness","Market penetration","Market segmentation"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Market attractiveness measures how good a market is for a business, that is, its potential to generate profits and growth for the firm. Option D is dividing a market into groups of buyers, option A is the point where quantity demanded equals quantity supplied, and option C is a growth strategy of selling more in an existing market."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 210, $official_bank_source${"itemId":"a154e224-f220-54e9-9485-e4f3e753253b","questionId":"143eff42-c16c-5a3b-8930-6488305d26e8","sourceKey":"bank:LAG-BUA125:ATT-003","payload":{"prompt":"Which of the following is NOT a reason why market attractiveness analysis is important in managerial decision-making?","options":["It helps the firm manage risk effectively","It helps the firm make informed decisions about entering or investing in a market","It supports efficient allocation of the firm's resources","It guarantees that the firm will make a profit in any market it enters"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Market attractiveness analysis improves decisions, but no analysis can guarantee profit, because conditions change and data may be imperfect. Options B, C and A are genuine benefits: informed entry and investment decisions, efficient resource allocation and effective risk management."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 211, $official_bank_source${"itemId":"e9ff2e0c-6a2c-5042-bf01-71111b3222c1","questionId":"489067e5-4cd4-5a53-8b5f-3b81c50d107e","sourceKey":"bank:LAG-BUA125:ATT-004","payload":{"prompt":"Which of the following is NOT usually treated as a factor determining market attractiveness?","options":["Market size and growth potential","The number of shareholders in the firm doing the analysis","Regulatory environment","Technological trends"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Market attractiveness factors describe the market itself, such as its size and growth, competition, customer needs, barriers, profitability, regulation, technology, economic stability and risk. The number of shareholders in the analysing firm says nothing about the market, while options A, C and D are all standard attractiveness factors."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 212, $official_bank_source${"itemId":"f3b8aec5-c374-5e26-b56b-3ec4d9036879","questionId":"607fa780-2fff-54d6-a548-4fa775409534","sourceKey":"bank:LAG-BUA125:ATT-005","payload":{"prompt":"When assessing market size as a factor of market attractiveness, market size is measured by:","options":["The total revenue in the market or the number of customers","The percentage change in sales over time","The number of competitors operating in the market","The height of barriers to entry"],"correctOption":0,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Market size is the volume of the market, measured either as total revenue or as the number of customers. Option B describes the growth rate, which is a separate measure, and options C and D belong to the competitive landscape and barriers to entry."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 213, $official_bank_source${"itemId":"325d4d92-972c-5ff6-9f33-69505b576a3e","questionId":"06d9eb9f-9b8d-5f3a-8971-2e10d0eec527","sourceKey":"bank:LAG-BUA125:ATT-006","payload":{"prompt":"Which of the following is NOT one of the factors that shape the structure and competitive landscape of a market?","options":["The distribution of market share","The number of competitors","Price wars and differentiation strategies","The age of the analysing firm's chief executive"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"The competitive landscape is shaped by the number of competitors, how market share is spread among them, barriers to entry and exit, market concentration, and price wars and differentiation. The age of a chief executive is a personal detail, not a feature of the market, while options B, A and C are all structure factors."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 214, $official_bank_source${"itemId":"2fc85097-e5e9-5a20-92e3-3b7f0d99540e","questionId":"84971f49-8688-5610-8cc8-38e7e0dc3e86","sourceKey":"bank:LAG-BUA125:ATT-007","payload":{"prompt":"Kola Foods is considering entering a market where new entrants need very large capital, where existing firms enjoy big economies of scale, and where licences are hard to obtain. For Kola Foods as a potential new entrant, this market is:","options":["More attractive, because barriers to entry are high","More attractive, because competition must be intense","Unaffected, because barriers only matter to existing firms","Less attractive, because barriers to entry are high"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Economies of scale, capital requirements and regulatory hurdles are barriers to entry, and a market with high barriers to entry and exit is less attractive to a firm trying to get in. Option A reverses this for a new entrant, option C is wrong because barriers are exactly what a newcomer faces, and option B does not follow from the facts given."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 215, $official_bank_source${"itemId":"21bf6bb4-7340-5086-9caf-a47803558cc1","questionId":"cc1c00e6-0c43-5114-bc67-964dd44bc418","sourceKey":"bank:LAG-BUA125:ATT-008","payload":{"prompt":"Which of the following is NOT an element of the regulatory environment that affects market attractiveness?","options":["Tariffs, taxes and trade policies","Environmental and labour regulations","Ease of doing business","Customer psychographics"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"The regulatory environment covers tariffs, taxes and trade policies, environmental and labour regulations, registration requirements, ease of doing business and economic freedom. Customer psychographics describe buyers' lifestyles and attitudes, which belong to customer needs and preferences, so it is the odd one out; options A, B and C are regulatory elements."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 216, $official_bank_source${"itemId":"dab53055-e650-57fa-8611-aa451efaefdc","questionId":"3c025b8c-9781-5c89-9a8d-37f9ca41ee46","sourceKey":"bank:LAG-BUA125:ATT-009","payload":{"prompt":"Rising internet penetration in Nigeria is making digital banking and online payments between businesses and consumers easier. Which market attractiveness factor does this mainly illustrate?","options":["Regulatory environment","Technological trends","Barriers to exit","Economic stability"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Internet penetration, digital transformation, AI and automation are technological trends that change market dynamics and can make markets more attractive. Option A is about laws and policies, option C is about the difficulty of leaving a market, and option D is about steady economic conditions, so none fits as well."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 217, $official_bank_source${"itemId":"940d536f-f074-591a-9f92-028fd7203636","questionId":"aa34237e-bfbe-584a-b72d-45153ff372de","sourceKey":"bank:LAG-BUA125:ATT-010","payload":{"prompt":"A new firm finds that the Nigerian telecommunications market is dominated by large players such as MTN, Airtel and Glo, and that entry needs very heavy capital investment. For this new entrant, the telecom market has:","options":["High attractiveness, because the market already has many customers","High attractiveness, because strong rivals guarantee high prices","Low attractiveness, because the market has no customers","Low attractiveness, because of high competition and capital requirements"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Intense competition and high capital requirements reduce a market's attractiveness to a new entrant, which is why the telecom sector is seen as unattractive for newcomers. Option A ignores the strength of competition and the cost of entry, option B wrongly assumes rivalry raises prices, and option C is false because the market has a very large customer base."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 218, $official_bank_source${"itemId":"971c1cae-be50-5f85-b80b-822c41432764","questionId":"7af49586-4ba1-52f3-b188-4d2f889e6577","sourceKey":"bank:LAG-BUA125:ATT-011","payload":{"prompt":"Which of the following is NOT one of the challenges in assessing market attractiveness?","options":["Market conditions and trends can change rapidly","Different firms may perceive attractiveness differently","Accurate data may be hard to obtain","Markets never change once they have been analysed"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"The challenges are data limitations, dynamic factors (conditions change quickly) and subjectivity (different firms judge attractiveness differently). The statement that markets never change is the opposite of the dynamic-factors challenge, while options C, A and B are the three genuine challenges."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 219, $official_bank_source${"itemId":"88f71e15-14c5-5d08-8360-74e279264223","questionId":"4d67bc1a-d64c-50fa-95f8-617f7ad4f065","sourceKey":"bank:LAG-BUA125:ATT-012","payload":{"prompt":"Two Lagos firms examine the same market. One rates it as highly attractive, while the other rates it as unattractive because of its own goals and abilities. This illustrates which challenge of assessing market attractiveness?","options":["Economies of scale","Subjectivity","Dynamic factors","Data limitations"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Subjectivity means different firms may perceive the attractiveness of the same market differently. Option D is about the difficulty of getting accurate data, option C is about conditions changing quickly over time, and option A is a barrier to entry rather than a challenge of assessment."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 220, $official_bank_source${"itemId":"0a0b6f7b-f1b4-5263-ad6f-1b203a851fd9","questionId":"2273c77d-ebfe-5808-a7e0-2be459135611","sourceKey":"bank:LAG-BUA125:ATT-013","payload":{"prompt":"Which of the following is NOT one of Porter's Five Forces?","options":["Threat of substitute products","Power of government regulators","Threat of new entrants","Bargaining power of suppliers"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Porter's Five Forces are rivalry among existing competitors, threat of new entrants, bargaining power of suppliers, bargaining power of buyers and threat of substitute products. Government policy appears only as one influence on the threat of new entrants, not as a separate force, while options C, D and A are all among the five."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 221, $official_bank_source${"itemId":"d7637e8a-3e36-5469-ba65-e535b2ab4292","questionId":"47a6865e-5c44-585e-b40f-ee9eaf527d53","sourceKey":"bank:LAG-BUA125:ATT-014","payload":{"prompt":"In Porter's Five Forces model, which force sits at the centre and is influenced by the number of competitors, industry concentration, industry growth and switching costs?","options":["Rivalry among existing competitors","Threat of substitute products","Threat of new entrants","Bargaining power of buyers"],"correctOption":0,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Rivalry among existing competitors is the central force, shaped by the number and diversity of competitors, industry concentration and growth, quality differences, brand loyalty, exit barriers and switching costs. Options C, D and B are the surrounding forces that act on that rivalry."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 222, $official_bank_source${"itemId":"f8fe4070-24b5-5996-a867-69cc55e74741","questionId":"cf604e50-7300-5cd4-a35f-defb8f7b2d35","sourceKey":"bank:LAG-BUA125:ATT-015","payload":{"prompt":"Customers of a Lagos bottled-water company buy in very large orders, can easily compare prices online and can switch to another brand at almost no cost. In Porter's Five Forces, this mainly increases the:","options":["Bargaining power of buyers","Bargaining power of suppliers","Rivalry among existing competitors","Threat of new entrants"],"correctOption":0,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Large orders, price sensitivity, good information and low switching costs all give customers more power to push down prices, which is the bargaining power of buyers. Option B concerns the firm's input providers, option D concerns new firms coming in, and option C concerns competition among existing sellers."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 223, $official_bank_source${"itemId":"f3e55cd8-07e9-562d-a78e-aadae75e68cc","questionId":"cd504f3a-7791-574c-b51e-6089d4ab4f22","sourceKey":"bank:LAG-BUA125:ATT-016","payload":{"prompt":"A cocoa processor in Ondo can buy beans from only two suppliers, each offering a unique grade that the processor cannot easily replace. In Porter's Five Forces, this situation indicates high:","options":["Bargaining power of buyers","Bargaining power of suppliers","Threat of substitute products","Threat of new entrants"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Supplier power rises when there are few suppliers, when each supplier's product is unique, and when the buying firm cannot easily substitute. Option A concerns the processor's customers, option C concerns alternative products buyers might switch to, and option D concerns firms entering the industry."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 224, $official_bank_source${"itemId":"ecd8a7cf-d492-5360-a557-d92c17bc9c73","questionId":"7e11cc4d-ea35-5d7c-9d05-207b2a594c52","sourceKey":"bank:LAG-BUA125:ATT-017","payload":{"prompt":"Economies of scale, capital requirements, cumulative experience and access to distribution channels are all factors that influence which of Porter's Five Forces?","options":["Threat of substitute products","Bargaining power of buyers","Threat of new entrants","Bargaining power of suppliers"],"correctOption":2,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"These factors decide how easily a new firm can enter an industry, so they shape the threat of new entrants. Option D depends on the number and uniqueness of suppliers, option B on customers' size and price sensitivity, and option A on the availability and price performance of substitutes."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 225, $official_bank_source${"itemId":"13a0b541-51ca-50ac-86be-23f324f31348","questionId":"20b7bf5e-23fe-5a1f-8452-bc780544fe93","sourceKey":"bank:LAG-BUA125:ATT-018","payload":{"prompt":"A cinema operator in Abuja worries that more customers are streaming films at home because streaming is cheaper and convenient. In Porter's Five Forces, this concern relates to the:","options":["Threat of substitute products","Bargaining power of suppliers","Rivalry among existing competitors","Threat of new entrants"],"correctOption":0,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Streaming is a different product that meets the same need, so it is a substitute, and its threat grows with buyers' willingness to switch and the substitute's relative price performance. Option D would be a new cinema opening, option C is rivalry among existing cinemas, and option B concerns the cinema's input providers."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 226, $official_bank_source${"itemId":"85a07d32-086e-52bc-bee3-0a4abccc2586","questionId":"74b7126b-6432-5769-8ca5-790b8f4c787a","sourceKey":"bank:LAG-BUA125:ATT-020","payload":{"prompt":"A food manufacturer in Kano studies how the rise in Nigeria's inflation rate and interest rates will affect consumer spending. In a PESTEL analysis, these are classified as:","options":["Political factors","Social factors","Economic factors","Legal factors"],"correctOption":2,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Inflation and interest rates describe the state of the economy, so they are economic factors in PESTEL. Option A would cover government stability and policy direction, option B would cover population, culture and lifestyles, and option D would cover laws and court rulings."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 227, $official_bank_source${"itemId":"6c9f5c97-5a04-5abe-9050-05d30af50006","questionId":"6a8c672e-7739-528b-8f32-68580ba270d4","sourceKey":"bank:LAG-BUA125:ATT-021","payload":{"prompt":"In a SWOT analysis, which pair of elements refers to factors INTERNAL to the firm?","options":["Opportunities and threats","Strengths and opportunities","Weaknesses and threats","Strengths and weaknesses"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Strengths and weaknesses describe the firm's own resources and capabilities, so they are internal, while opportunities and threats come from the external environment. Option A is the external pair, and options B and C each mix one internal with one external element."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 228, $official_bank_source${"itemId":"99fab94c-12c2-5114-b8a8-267c85ee390e","questionId":"7fa6ebe9-d708-54e5-8eb9-e6033e4a04f4","sourceKey":"bank:LAG-BUA125:ATT-022","payload":{"prompt":"A Port Harcourt logistics company learns that a well-funded foreign rival is about to enter its market. In the company's SWOT analysis, this should be recorded as a:","options":["Opportunity","Threat","Strength","Weakness"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"A threat is an external development that could harm the firm, and a powerful new competitor entering the market is exactly that. Option D would be an internal shortcoming of the company itself, while options A and C are favourable, which a strong new rival is not."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 229, $official_bank_source${"itemId":"aa95fd6f-d9d0-5602-befd-2c497ad69b08","questionId":"c16c3497-d6ce-5201-9d15-7a0ff8d293f2","sourceKey":"bank:LAG-BUA125:ATT-023","payload":{"prompt":"The BCG matrix assesses a firm's products or business units using which two dimensions?","options":["Price and quantity demanded","Market growth rate and relative market share","Strengths and weaknesses","Market size and profit margin"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"The Boston Consulting Group matrix plots each product by the growth rate of its market and its share relative to the largest competitor. Option D lists two attractiveness factors but not the BCG axes, option A describes a demand curve, and option C belongs to SWOT analysis."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 230, $official_bank_source${"itemId":"c7b7a0a3-c924-50b0-bc79-54d7e136457b","questionId":"ebe9c0f5-5aac-514b-839b-36ff3e9442c3","sourceKey":"bank:LAG-BUA125:ATT-024","payload":{"prompt":"In the BCG matrix, a product with a HIGH relative market share in a LOW-growth market is called a:","options":["Cash cow","Question mark","Dog","Star"],"correctOption":0,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"A cash cow leads a mature, slow-growing market, so it earns strong cash flows without needing heavy investment. Option D is high share in a high-growth market, option B is low share in a high-growth market, and option C is low share in a low-growth market."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 231, $official_bank_source${"itemId":"82400ffc-b4df-5327-9853-ddfcd40136b5","questionId":"66875005-4629-5af0-a385-632809926738","sourceKey":"bank:LAG-BUA125:ATT-025","payload":{"prompt":"In the weighted-score method of market attractiveness analysis, the WEIGHT given to a factor represents:","options":["The market share the firm expects to win","How favourable the market is on that factor, rated from 1 to 10","How important that factor is to the business","The total attractiveness of the market"],"correctOption":2,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"The weight shows the relative importance of each factor, for example 20% for a highly important factor such as market size. Option B describes the score, option D describes the total of the weighted scores, and option A is not part of the method."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 232, $official_bank_source${"itemId":"a461356e-d8ce-5aaf-ba35-2a9640f039f3","questionId":"d5ba8693-cf0a-545c-9d78-9a7ce0740330","sourceKey":"bank:LAG-BUA125:ATT-026","payload":{"prompt":"In the weighted-score method, the overall attractiveness of a market is found by:","options":["Adding all the scores and dividing by the number of factors","Multiplying each factor's weight by its score and adding the results","Choosing the highest score among the factors","Multiplying all the weights together"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Each weighted score is weight x score, and the total of all weighted scores is the overall measure of market attractiveness. Option A gives a simple average that ignores the weights, while options D and C do not combine importance and score at all."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 233, $official_bank_source${"itemId":"62859489-bca5-542b-b53b-bda75ea2ea42","questionId":"40d4c8eb-0c99-58b1-a9c7-bef560870280","sourceKey":"bank:LAG-BUA125:ATT-027","payload":{"prompt":"Which of the following is NOT a determinant of the demand for a product?","options":["The cost of producing the product","Consumers' income","Prices of related goods","Consumers' tastes and preferences"],"correctOption":0,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Demand depends on buyers' side factors such as the good's price, income, prices of substitutes and complements, tastes, expectations and the number of buyers. Production cost affects how much firms are willing to supply, so it is a determinant of supply, not demand; options B, C and D are demand determinants."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 234, $official_bank_source${"itemId":"844b4588-e74e-5ed9-92ed-e6e5e3c4f23c","questionId":"ea6b6d79-91dd-5f93-8edd-571c08467568","sourceKey":"bank:LAG-BUA125:ATT-028","payload":{"prompt":"Which of the following goods is generally treated as an exception to the law of demand, because people may buy more of it as its price rises?","options":["A basic loaf of bread sold in many shops","A prestige (Veblen) good such as a luxury designer watch","A daily newspaper","A bottle of soft drink with many close rivals"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Prestige or Veblen goods are bought partly to display status, so a higher price can make them more desirable, which goes against the law of demand. Options A, D and C are ordinary goods with substitutes, for which a higher price reduces quantity demanded as the law predicts."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 235, $official_bank_source${"itemId":"dc31cf4a-f857-50ae-9f2a-79ba7391163f","questionId":"9e5d4529-4e17-57b4-837c-e15ab7b7e4cf","sourceKey":"bank:LAG-BUA125:ATT-029","payload":{"prompt":"Average incomes in Ibadan rise, and at every price residents now buy more chicken than before. On a diagram, this is shown as:","options":["A movement down along the existing demand curve for chicken","A leftward shift of the demand curve for chicken","A rightward shift of the demand curve for chicken","A movement up along the existing demand curve for chicken"],"correctOption":2,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"A change in a non-price determinant such as income changes demand at every price, so the whole curve shifts, and more bought at every price means a shift to the right. Options A and D are movements along the curve, which happen only when the good's own price changes, and option B would mean less is bought at every price."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 236, $official_bank_source${"itemId":"6faca2f7-1c30-5f7f-a59a-2e6cb2e83b38","questionId":"52b9c2d6-7d6d-541a-b30d-9365e121f3b6","sourceKey":"bank:LAG-BUA125:ATT-030","payload":{"prompt":"The ratio (percentage change in quantity demanded) / (percentage change in consumers' income) measures:","options":["Price elasticity of demand","Price elasticity of supply","Income elasticity of demand","Cross elasticity of demand"],"correctOption":2,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Income elasticity of demand shows how responsive quantity demanded is to a change in income. Option A divides by the percentage change in the good's own price, option D divides by the percentage change in the price of another good, and option B concerns quantity supplied rather than demanded."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 237, $official_bank_source${"itemId":"bd2ddc91-6115-5db8-975e-7f6b945431b1","questionId":"7dc5cd2d-3418-5c67-9f95-76a7b79dbb07","sourceKey":"bank:LAG-BUA125:ATT-031","payload":{"prompt":"A good whose income elasticity of demand lies between 0 and 1 is best described as:","options":["An inferior good","A Giffen good","A luxury good","A normal necessity"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"A positive income elasticity means the good is normal, and a value below 1 means demand rises less than proportionately with income, which is typical of necessities. Option C requires an income elasticity greater than 1, while options A and B have negative income elasticity."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 238, $official_bank_source${"itemId":"3538f8cf-ed9d-56e3-991f-f2dd112c4986","questionId":"26ad7152-45c4-54f8-a182-e7f7c4b8e44a","sourceKey":"bank:LAG-BUA125:ATT-032","payload":{"prompt":"Which of the following shows the four main stages of the product life cycle in the correct order?","options":["Growth, introduction, maturity, decline","Introduction, growth, decline, maturity","Introduction, growth, maturity, decline","Introduction, maturity, growth, decline"],"correctOption":2,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"A product is first launched (introduction), then sales rise quickly (growth), then sales level off (maturity), and finally sales fall (decline). Options A, D and B each put at least one stage out of this natural sequence."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 239, $official_bank_source${"itemId":"e8977b8a-57a4-5f7b-b274-25fd64631fd6","questionId":"be972447-90bc-5e58-ae3b-f5e4a56c6006","sourceKey":"bank:LAG-BUA125:ATT-033","payload":{"prompt":"A new Nigerian plant-based yoghurt has just been launched. Sales are low, promotion costs are high to create awareness, and the firm is making little or no profit. The product is in which stage of the product life cycle?","options":["Growth","Maturity","Decline","Introduction"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"The introduction stage follows launch: sales grow slowly, heavy spending on promotion and distribution is needed, and profits are low or negative. Option A has rapidly rising sales and profits, option B has peak sales and intense competition, and option C has falling sales."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 240, $official_bank_source${"itemId":"c9f6bccf-a9df-5b14-ae60-8e529c8e8d54","questionId":"accb67e4-b1a4-5fc1-9542-466c4b4c5631","sourceKey":"bank:LAG-BUA125:ATT-034","payload":{"prompt":"Sales of a fintech payment app are rising rapidly, profits are improving and new competitors are entering the market with similar apps. The app is in which stage of the product life cycle?","options":["Decline","Introduction","Growth","Maturity"],"correctOption":2,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"The growth stage is marked by rapid sales growth, rising profits and the entry of new competitors attracted by the opportunity. Option B has slow sales and low profits, option D has sales levelling off at a peak, and option A has sales falling."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 241, $official_bank_source${"itemId":"8b97c187-37e8-5948-931a-233cd18af24f","questionId":"4416f819-8c20-520a-8251-c00ccf5718b5","sourceKey":"bank:LAG-BUA125:ATT-035","payload":{"prompt":"Sales of a well-known detergent brand have levelled off at their peak, most potential buyers already use such products, and rivals compete fiercely on price and promotion. The brand is in which stage of the product life cycle?","options":["Introduction","Growth","Maturity","Decline"],"correctOption":2,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"In maturity, sales growth slows and peaks, the market is close to saturated and competition becomes intense, often through price cuts and promotions. Option B has rapidly rising sales, option A is just after launch, and option D has sales falling steadily."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 242, $official_bank_source${"itemId":"cae8c6d1-cdaf-5f1d-a063-fde8d37f4c51","questionId":"e43689d0-557e-58d1-a234-95a90c1c1867","sourceKey":"bank:LAG-BUA125:ATT-036","payload":{"prompt":"Which of the following is a typical business decision for a product in the DECLINE stage of the product life cycle?","options":["Harvesting the product by cutting costs, or dropping it from the product line","Spending heavily to build first-time awareness among consumers","Building new factories to keep up with rapidly rising demand","Launching the product for the first time in its home market"],"correctOption":0,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"When sales and profits are falling, firms usually reduce spending to harvest remaining profits or withdraw the product altogether. Options B and D are introduction-stage actions, and option C suits the growth stage, when demand is expanding fast."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 243, $official_bank_source${"itemId":"2f14b7f7-d6be-55af-a561-224a87ff35cf","questionId":"9378dad9-2ebf-5f1f-b642-757247abdd7b","sourceKey":"bank:LAG-BUA125:ATT-037","payload":{"prompt":"A firm whose product is in the maturity stage wants to extend its life. Which of the following is a suitable strategy?","options":["Withdrawing all promotion immediately","Stopping distribution to most retail outlets","Modifying the product or finding new users and new uses for it","Raising the price sharply to the highest level customers have ever paid"],"correctOption":2,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"In maturity, firms try to extend sales by modifying the market (new users or uses), the product (new features or quality) or the marketing mix. Options A and B would speed up the decline of the product, and option D would likely drive buyers to rivals in a market where competition is already intense."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 244, $official_bank_source${"itemId":"cf76bd3c-f5ad-57f4-8e25-cf5679e44b3a","questionId":"b1cb2fce-267c-579a-b703-1bc950c257ce","sourceKey":"bank:LAG-BUA125:ATT-038","payload":{"prompt":"A Lagos beverage company rates a new market on six factors (score 1-10): Market size: weight 25%, score 8; Market growth rate: weight 20%, score 7; Profit margins: weight 15%, score 6; Competitive intensity: weight 15%, score 4; Regulatory environment: weight 10%, score 5; Technological trends: weight 15%, score 9. What is the market's total weighted attractiveness score?","options":["5.40","675.00","6.75","6.50"],"correctOption":2,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Total = sum of (weight x score) = 0.25x8 + 0.20x7 + 0.15x6 + 0.15x4 + 0.10x5 + 0.15x9 = 2.00 + 1.40 + 0.90 + 0.60 + 0.50 + 1.35 = 6.75. Option D is the simple average of the scores, which ignores the weights; option A leaves out technological trends; option B uses the weights as whole numbers instead of decimals."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 245, $official_bank_source${"itemId":"729f1d31-9c77-52f4-a7d6-cb46c9901b61","questionId":"01dfa5ea-32f9-5860-a60b-4aa34c739f8b","sourceKey":"bank:LAG-BUA125:ATT-039","payload":{"prompt":"In a weighted-score attractiveness table, market size carries a weight of 30% and the market is given a score of 7 out of 10 on that factor. What is the weighted score for market size?","options":["2.10","0.21","21.00","23.33"],"correctOption":0,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Weighted score = weight x score = 0.30 x 7 = 2.10. Option B converts the weight wrongly (0.03 x 7), option C uses 30 instead of 0.30, and option D divides the score by the weight instead of multiplying."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 246, $official_bank_source${"itemId":"3ea396f8-e70c-5aa3-993c-bd1b5c090045","questionId":"8753b4b9-6a17-50f6-af84-c7037922093c","sourceKey":"bank:LAG-BUA125:ATT-040","payload":{"prompt":"A distributor compares Abuja and Kano using four factors with weights: market size 40%, growth rate 30%, profit margins 20%, regulatory environment 10%. Abuja scores 6, 8, 7 and 5; Kano scores 9, 5, 6 and 6 (in the same order, out of 10). Based on total weighted scores, which market is more attractive and by how much?","options":["Kano, by 0.50","Neither; both score 6.50","Kano, by 0.20","Abuja, by 0.20"],"correctOption":2,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Abuja = 0.4x6 + 0.3x8 + 0.2x7 + 0.1x5 = 6.70; Kano = 0.4x9 + 0.3x5 + 0.2x6 + 0.1x6 = 6.90, so Kano leads by 0.20. Option B comes from a simple average of the scores, which gives both markets 6.50 and ignores the weights; option D reverses the comparison."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 247, $official_bank_source${"itemId":"1b524263-adfc-5a45-8905-25e2f5d3ef15","questionId":"8cc3ee9a-9b98-5df3-9f56-c37c3cccd96f","sourceKey":"bank:LAG-BUA125:ATT-041","payload":{"prompt":"A firm scores a market on four factors: market size (weight 30%, score 8), growth rate (weight 25%, score 6), customer needs (weight 20%, score 7) and risk factors (score 5). The weights must add up to 100%. What is the total weighted score?","options":["6.55","6.30","5.30","6.50"],"correctOption":0,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"The missing weight for risk factors is 100% - 30% - 25% - 20% = 25%. Total = 0.30x8 + 0.25x6 + 0.20x7 + 0.25x5 = 2.40 + 1.50 + 1.40 + 1.25 = 6.55. Option C leaves out risk factors, option D is the simple average of the scores, and option B wrongly gives risk factors a weight of 20%."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 248, $official_bank_source${"itemId":"e080cf3b-8c6b-564e-87a6-e100ea0daca1","questionId":"f26d97ac-d1db-58db-b800-3e041f383607","sourceKey":"bank:LAG-BUA125:ATT-042","payload":{"prompt":"A market's total weighted attractiveness score is 6.80. After new data, the score for competitive intensity (weight 15%) is revised from 5 to 8, with nothing else changing. What is the new total weighted score?","options":["7.25","9.80","7.55","6.35"],"correctOption":0,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Only competitive intensity changes, so the total rises by weight x change in score = 0.15 x (8 - 5) = 0.45, giving 6.80 + 0.45 = 7.25. Option B adds the 3-point rise without weighting it, option D subtracts the change, and option C adds 0.15 x 5 instead of 0.15 x 3."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 249, $official_bank_source${"itemId":"2f634fbf-8560-5547-b580-ed6d7f6d27ee","questionId":"69acb429-43cd-5472-96db-65bbd0d71a53","sourceKey":"bank:LAG-BUA125:ATT-043","payload":{"prompt":"A company enters a market only if its total weighted score is at least 7.0. Factors with a combined weight of 70% already contribute 4.6 to the total. The only remaining factor, market growth rate, has a weight of 30%. What is the minimum score (out of 10) the market needs on growth rate?","options":["8.00","6.00","7.00","2.40"],"correctOption":0,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Growth rate must contribute 7.0 - 4.6 = 2.4, and 0.30 x score = 2.4 gives score = 2.4 / 0.30 = 8.00. Option D forgets to divide by the weight, option B divides by 0.40 instead of 0.30, and option C simply repeats the target total."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 250, $official_bank_source${"itemId":"bd78e3cd-ceda-589b-a0bb-914e2a64da6b","questionId":"f4d74391-f7db-5cc7-b2ef-d7592e975b8a","sourceKey":"bank:LAG-BUA125:ATT-044","payload":{"prompt":"The Nigerian market for packaged snacks grew from N40 billion last year to N46 billion this year. What is the market growth rate?","options":["15.00%","6.00%","13.04%","115.00%"],"correctOption":0,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Growth rate = (new size - old size) / old size x 100 = (46 - 40) / 40 x 100 = 15.00%. Option C wrongly divides by the new size, option B reports the N6 billion change as if it were a percentage, and option D is the ratio of new to old size, not the change."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 251, $official_bank_source${"itemId":"64dce8e7-4d9e-5de5-ae7c-ce298b60e66a","questionId":"973976b2-bbec-5c02-914f-d927c48c1414","sourceKey":"bank:LAG-BUA125:ATT-045","payload":{"prompt":"A town has 2.4 million mobile data users, and each spends an average of N1,500 per month on data. What is the annual market size in revenue terms?","options":["N43.2 billion","N3.6 billion","N28.8 billion","N4.32 billion"],"correctOption":0,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Annual market size = users x monthly spend x 12 = 2,400,000 x N1,500 x 12 = N43,200,000,000, that is N43.2 billion. Option B is only one month's spending, option D is out by a factor of 10, and option C comes from using 8 months instead of 12."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 252, $official_bank_source${"itemId":"4fc87ffc-d125-5647-8925-01b1b0fcdaff","questionId":"4aed52b0-d631-51f3-a649-1b53b0bf8219","sourceKey":"bank:LAG-BUA125:ATT-046","payload":{"prompt":"A fintech market worth N200 billion is expected to grow at a compound annual growth rate (CAGR) of 15%. What will the market be worth after 2 years?","options":["N260.00 billion","N304.17 billion","N230.00 billion","N264.50 billion"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"With compound growth, value = 200 x (1.15)^2 = 200 x 1.3225 = N264.50 billion. Option A uses simple growth (15% of N200 billion added twice), option C is only one year of growth, and option B compounds for 3 years instead of 2."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 253, $official_bank_source${"itemId":"dbed8534-8d30-5355-84dd-a74c5f99dec8","questionId":"56aaf431-0af3-51d9-9a27-c75dbf7cdb31","sourceKey":"bank:LAG-BUA125:ATT-047","payload":{"prompt":"When the price of a bag of sachet water rises from N200 to N250, the quantity demanded falls from 1,000 bags to 800 bags a week. Using percentage changes based on the ORIGINAL price and quantity, what is the price elasticity of demand (in absolute value)?","options":["0.80","1.00","1.25","4.00"],"correctOption":0,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"%change in Qd = (800 - 1,000) / 1,000 = -20%; %change in P = (250 - 200) / 200 = 25%; PED = -20 / 25 = -0.80, or 0.80 in absolute value, so demand is inelastic. Option C divides the price change by the quantity change, option B uses the midpoint method rather than the stated one, and option D divides the raw changes (200 / 50) instead of percentages."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 254, $official_bank_source${"itemId":"eee4f533-034d-58d3-a834-4f738c07146d","questionId":"7e69dfe9-2a9d-5cec-8e71-eb50d2d33244","sourceKey":"bank:LAG-BUA125:ATT-048","payload":{"prompt":"A Yaba restaurant cuts the price of a plate of jollof rice from N400 to N300, and daily sales rise from 60 plates to 100 plates. Using the midpoint (arc) method, what is the price elasticity of demand (in absolute value, to 2 decimal places)?","options":["0.40","0.57","1.75","2.67"],"correctOption":2,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Midpoint method: %change in Q = 40 / ((60 + 100) / 2) = 40 / 80 = 50%; %change in P = 100 / ((400 + 300) / 2) = 100 / 350 = 28.57%; PED = 50 / 28.57 = 1.75. Option D uses the original values (66.67% / 25%), option B inverts the ratio, and option A divides the raw changes."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 255, $official_bank_source${"itemId":"067d8154-dbf9-5d8f-b29c-526bb44d1527","questionId":"5c5fade6-822f-5eb1-bc52-31c6aff926c8","sourceKey":"bank:LAG-BUA125:ATT-049","payload":{"prompt":"The price elasticity of demand for a brand of toothpaste is -1.5. A shop currently sells 5,000 tubes a month and raises the price by 8%. Other things equal, how many tubes will it now sell per month?","options":["5,600","4,400","4,600","4,733"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"%change in Qd = PED x %change in P = -1.5 x 8% = -12%, so sales fall to 5,000 x (1 - 0.12) = 4,400 tubes. Option C assumes quantity falls by the same 8% as price, option A adds the 12% instead of subtracting it, and option D divides 8% by 1.5 instead of multiplying."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 256, $official_bank_source${"itemId":"42f295b1-9527-5e8e-a78a-57687dbc345d","questionId":"8d7d6e0f-6844-5a18-9ef3-285b29e2cf88","sourceKey":"bank:LAG-BUA125:ATT-050","payload":{"prompt":"A bakery sells 500 loaves a day at N1,000 each. Demand for its bread has a price elasticity of -0.4. If it raises the price to N1,100, what happens to its daily total revenue?","options":["It rises by N50,000","It falls by N20,000","It rises by N28,000","It falls by N28,000"],"correctOption":2,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"The price rises by 10%, so quantity falls by 0.4 x 10% = 4%, to 480 loaves. Revenue goes from 500 x N1,000 = N500,000 to 480 x N1,100 = N528,000, a rise of N28,000, as expected when demand is inelastic. Option A ignores the fall in quantity, and option B counts only the lost sales of 20 loaves at the old price."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 257, $official_bank_source${"itemId":"50daebc3-a47f-536f-b504-6636c54f5252","questionId":"15434d15-21e2-5c7f-94da-c51bef559d8c","sourceKey":"bank:LAG-BUA125:ATT-051","payload":{"prompt":"When a household's monthly income rises from N100,000 to N120,000, its monthly spending on restaurant meals rises from 40 to 52 meals. Using percentage changes based on the original values, what is the income elasticity of demand, and what type of good is this?","options":["0.67; a necessity","1.50; an inferior good","-1.50; an inferior good","1.50; a luxury good"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"%change in Qd = 12 / 40 = 30%; %change in income = 20,000 / 100,000 = 20%; YED = 30 / 20 = 1.50. A positive value above 1 means demand rises more than proportionately with income, so the good is a luxury. Option A inverts the ratio, and options B and C wrongly call it inferior, which requires a negative YED."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 258, $official_bank_source${"itemId":"e18bfc73-d3fa-5fe5-be8e-6c6e4ee9879c","questionId":"ee74a25a-c2db-5064-bf9b-6293e7db4b48","sourceKey":"bank:LAG-BUA125:ATT-052","payload":{"prompt":"When consumers' incomes rise by 25%, the quantity of second-hand clothing they buy falls by 10%. What is the income elasticity of demand for second-hand clothing, and how is it classified?","options":["2.50; a luxury good","0.40; a normal good","-2.50; an inferior good","-0.40; an inferior good"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"YED = %change in Qd / %change in income = -10 / 25 = -0.40. A negative income elasticity means people buy less as they get richer, so the good is inferior. Option B drops the minus sign, and option C divides income change by quantity change."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 259, $official_bank_source${"itemId":"5a5021c9-605e-5c0f-ab2a-48a2d8ae84bb","questionId":"73225400-5eb0-5cc3-baa4-f0238471757f","sourceKey":"bank:LAG-BUA125:ATT-053","payload":{"prompt":"The price of a pack of tea rises from N500 to N600, and the quantity of instant coffee demanded rises from 2,000 to 2,300 packs a month. Using percentage changes based on the original values, what is the cross elasticity of demand for coffee with respect to the price of tea, and how are the goods related?","options":["0.75; substitutes","1.33; substitutes","0.75; complements","-0.75; complements"],"correctOption":0,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"XED = %change in Qd of coffee / %change in price of tea = 15% / 20% = 0.75. A positive cross elasticity means a rise in one price increases demand for the other good, so they are substitutes. Option D adds a wrong minus sign, option B inverts the ratio, and option C misreads a positive value as complements."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 260, $official_bank_source${"itemId":"fe59b7fb-2fc5-516c-adec-b104d07afeab","questionId":"1e242d8b-edcb-5362-82db-5fd8a610908e","sourceKey":"bank:LAG-BUA125:ATT-054","payload":{"prompt":"A shop cuts the price of printers from N80,000 to N72,000, and its monthly sales of ink cartridges rise from 600 to 690. Using percentage changes based on the original values, what is the cross elasticity of demand for cartridges with respect to the price of printers?","options":["1.50; complements","-0.67; complements","1.50; substitutes","-1.50; complements"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"%change in cartridges = 90 / 600 = 15%; %change in printer price = -8,000 / 80,000 = -10%; XED = 15 / -10 = -1.50. A negative cross elasticity means the goods are used together, so they are complements. Option C drops the sign and wrongly concludes substitutes, and option B inverts the ratio."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 261, $official_bank_source${"itemId":"bdbbfbc7-66a8-551c-a447-7841fa4b66b6","questionId":"7e8a0ba3-6fad-5ed8-9f8b-f4515b9dc42e","sourceKey":"bank:LAG-BUA125:ATT-055","payload":{"prompt":"The price elasticity of demand for a brand of noodles is -2.5. By what percentage must the firm cut its price to raise the quantity sold by 15%?","options":["12.5%","37.5%","6.0%","15.0%"],"correctOption":2,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"%change in P = %change in Qd / PED = 15% / 2.5 = 6%. Option B multiplies 15% by 2.5 instead of dividing, option D assumes price must fall by the same percentage as the rise in sales, and option A subtracts 2.5 from 15."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 262, $official_bank_source${"itemId":"b1daa315-4db1-531b-bb25-e2d102461e35","questionId":"4e611ddf-f46c-50a8-aa16-d221ee4f8442","sourceKey":"bank:LAG-BUA125:ATT-056","payload":{"prompt":"The weekly demand for a brand of soap in a market is Qd = 800 - 5P, where P is the price in naira. How many units are demanded when the price is N60?","options":["795","1,100","740","500"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Substitute P = 60: Qd = 800 - 5 x 60 = 800 - 300 = 500 units. Option B adds 300 instead of subtracting it, option C subtracts the price without multiplying by 5, and option A subtracts only the coefficient 5."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 263, $official_bank_source${"itemId":"bd8be9b9-d2ba-5923-a94c-d50eaa161217","questionId":"d63cbd9f-22ec-599d-b6f2-f7f7b3dbb503","sourceKey":"bank:LAG-BUA125:ATT-057","payload":{"prompt":"For the demand function Qd = 800 - 5P, the point price elasticity of demand is Ed = (dQ/dP) x (P/Q). What is the price elasticity of demand (in absolute value) at a price of N60, where Q = 500?","options":["0.12","0.60","1.67","5.00"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Here dQ/dP = -5, so Ed = -5 x (60 / 500) = -0.60, or 0.60 in absolute value, meaning demand is inelastic at this price. Option C inverts the ratio, option D confuses the slope coefficient with elasticity, and option A forgets to multiply P/Q by the slope."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 264, $official_bank_source${"itemId":"b206ab71-5939-5c12-957c-459f18e1993b","questionId":"26d6497e-16dc-52a9-a29c-d360e669f9c3","sourceKey":"bank:LAG-BUA125:ATT-058","payload":{"prompt":"A product's sales are N45 million, while its largest competitor's sales are N30 million, and the market is growing at 14% a year. Using a BCG matrix where growth above 10% is 'high' and a relative market share above 1.0 is 'high', the product is a:","options":["Dog","Question mark","Star","Cash cow"],"correctOption":2,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Relative market share = own sales / largest competitor's sales = 45 / 30 = 1.50, which is high, and 14% growth is also high, so the product is a star. Option D would need low market growth, option B would need a share below 1.0, and option A would need both to be low."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 265, $official_bank_source${"itemId":"3bc7b3f3-f74e-57a2-adf3-9ec53d316758","questionId":"1a05e00c-9247-5a74-971a-b1b0ae558b08","sourceKey":"bank:LAG-BUA125:ATT-059","payload":{"prompt":"A product's sales are N8 million, the market leader's sales are N32 million, and the market is growing at 4% a year. Using a BCG matrix where growth above 10% is 'high' and a relative market share above 1.0 is 'high', what is the product's relative market share and BCG category?","options":["0.25; question mark","0.20; dog","4.00; cash cow","0.25; dog"],"correctOption":3,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Relative market share = 8 / 32 = 0.25, which is low, and 4% growth is also low, so the product is a dog. Option C divides the leader's sales by the product's, option A would need high market growth, and option B divides by total sales of both firms (40) instead of the leader's sales."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 266, $official_bank_source${"itemId":"c8b72073-e056-5003-8047-9aeb766a624e","questionId":"fa76c39b-5bb8-5793-a08a-86cdbc0945f7","sourceKey":"bank:LAG-BUA125:ATT-060","payload":{"prompt":"In a market growing at 20% a year, a product has sales of N12 million while the leader has N48 million. Using a BCG matrix where growth above 10% is 'high' and a relative market share above 1.0 is 'high', which category does the product fall into?","options":["Star","Question mark","Cash cow","Dog"],"correctOption":1,"section":"Market Attractiveness, Demand Analysis and Product Life Cycle","explanation":"Relative market share = 12 / 48 = 0.25, which is low, while 20% growth is high, so the product is a question mark that needs investment or a decision to drop it. Option A would need a share above 1.0, option D would need low market growth, and option C would need high share in a low-growth market."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 267, $official_bank_source${"itemId":"e109bdfc-bcf4-5a8e-af94-61b13efbafb9","questionId":"5f7e93c8-4b54-5ab6-bb86-912a85955fb0","sourceKey":"bank:LAG-BUA125:FOR-001","payload":{"prompt":"A technique for anticipating future demand for a product, which tells a business the estimated quantity that consumers may want to buy over a period of time, is called:","options":["Price discrimination","Inventory control","Market segmentation","Demand forecasting"],"correctOption":3,"section":"Business Forecasting","explanation":"Demand forecasting estimates how much of a product customers will want in a future period so the business can plan production. Option C divides buyers into groups, option B manages stock levels, and option A charges different prices to different buyers; none of them predicts future demand."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 268, $official_bank_source${"itemId":"fc091401-00b9-5933-8237-85244231349a","questionId":"59a17723-b51e-5876-a685-2501c964622b","sourceKey":"bank:LAG-BUA125:FOR-002","payload":{"prompt":"A Lagos cosmetics firm overestimated demand for its new body cream and produced far more than customers bought. The most direct consequence of this forecasting error is:","options":["Higher market share","A shortage of the product","Excess inventory","Lost sales due to stock-outs"],"correctOption":2,"section":"Business Forecasting","explanation":"Overestimating demand leads to producing too much, which leaves the firm with excess inventory and its costs. Options B and D are the results of underestimating demand, and option A does not follow from making too much stock."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 269, $official_bank_source${"itemId":"e7881bbb-7186-5139-8a10-85abddb10b74","questionId":"813ee32a-34c4-5735-9e4a-a2cd0056a75d","sourceKey":"bank:LAG-BUA125:FOR-003","payload":{"prompt":"Which of the following is NOT a major influence on the strength of a demand forecast?","options":["The quantity and quality of the data","The colour scheme used in the forecast report","The level of competence of the user","The methods used to calculate the forecast"],"correctOption":1,"section":"Business Forecasting","explanation":"The strength of a projection depends on the quantity and quality of data, the methods used and the user's competence. How the report looks has no effect on accuracy, while options A, D and C are the real influences."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 270, $official_bank_source${"itemId":"d724f5fc-8724-580e-88e5-9d01f372e525","questionId":"8a2306e3-9856-525b-9786-20d257bd6185","sourceKey":"bank:LAG-BUA125:FOR-004","payload":{"prompt":"Which of the following is NOT a benefit of demand forecasting to a business?","options":["It helps the firm set prices","It removes all uncertainty about future sales","It helps plan production and inventory","It helps adjust marketing and sales efforts"],"correctOption":1,"section":"Business Forecasting","explanation":"Forecasting helps firms plan production and inventory, set pricing and adjust marketing, but it can only reduce uncertainty, never remove it, because unexpected events still occur. Options C, A and D are genuine benefits."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 271, $official_bank_source${"itemId":"98c6b05d-35dd-5676-8473-83c0a45b14c7","questionId":"16383772-bce7-50e0-b7ba-e4f8484f5a2a","sourceKey":"bank:LAG-BUA125:FOR-005","payload":{"prompt":"Which of the following is NOT one of the factors affecting demand forecasting?","options":["Consumer trends","Competition","Economic conditions","The number of directors on the firm's board"],"correctOption":3,"section":"Business Forecasting","explanation":"Factors affecting forecasts include economic conditions, competition, consumer trends, price, availability and advertising, because these drive customer demand. Board size does not drive demand, while options C, B and A all do."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 272, $official_bank_source${"itemId":"d90e980f-0599-5adb-8f18-dd7fbd12ae09","questionId":"96f2d787-1adb-5c0e-83ef-1ead43239404","sourceKey":"bank:LAG-BUA125:FOR-006","payload":{"prompt":"Which group of indicators is cited as part of the economic conditions that affect the level of demand in a forecast?","options":["Brand name, logo, slogan and packaging","Number of salespeople, offices and vehicles","Board meetings, annual reports and audits","GDP, unemployment rate, inflation rate and consumer confidence"],"correctOption":3,"section":"Business Forecasting","explanation":"Economic conditions are measured by indicators such as GDP, unemployment, inflation and consumer confidence, which shape how much customers can and will buy. Options A, B and C are features of a single firm, not of the economy."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 273, $official_bank_source${"itemId":"e313c840-1698-5d24-9fa2-ad989e79caf4","questionId":"5effd7f8-e5f4-5b40-9462-e45cf0022654","sourceKey":"bank:LAG-BUA125:FOR-007","payload":{"prompt":"Ahead of the festive season, a supermarket in Enugu forecasts demand for the next six weeks so it can plan staffing and stock. This is an example of:","options":["Short-term demand forecasting","Passive demand forecasting","Long-term demand forecasting","Macro demand forecasting"],"correctOption":0,"section":"Business Forecasting","explanation":"Short-term demand forecasting predicts demand for a specific near period, here the next six weeks, to plan immediate operations. Option C covers a protracted period for resource allocation, option D covers demand in the whole economy, and option B relies only on past sales records."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 274, $official_bank_source${"itemId":"dddb386b-98cc-53c3-be53-dd824e5408a6","questionId":"2187d601-b556-5c64-a6b3-45efc5bb937a","sourceKey":"bank:LAG-BUA125:FOR-008","payload":{"prompt":"Which of the following is one of the methods that can be used for short-term demand forecasting?","options":["Registering a new trademark","Building a new factory","Customer surveys","Changing the company's name"],"correctOption":2,"section":"Business Forecasting","explanation":"Short-term demand forecasting can be done through statistical analysis, economic models, market research and customer surveys. Options A, B and D are business actions that may follow a forecast, but they are not methods of making one."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 275, $official_bank_source${"itemId":"cd2233dc-a2fb-5f91-bac6-e02fb1ab5d6a","questionId":"fdee4441-1c22-5b12-82fe-98b9441bd8e5","sourceKey":"bank:LAG-BUA125:FOR-009","payload":{"prompt":"Long-term demand forecasting is best described as:","options":["A forecast of demand in one small geographical area","An analytical procedure that predicts demand over a protracted period to plan and allocate resources and identify opportunities and risks","A technique that uses only past sales records and ignores market changes","A method that predicts demand for the next few days using only today's sales"],"correctOption":1,"section":"Business Forecasting","explanation":"Long-term demand forecasting looks far ahead, guiding resource allocation and spotting opportunities and risks, and it typically combines qualitative and quantitative methods. Option D is very short-term, option C describes passive forecasting, and option A describes micro forecasting."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 276, $official_bank_source${"itemId":"8a8569c0-7f95-5964-a645-1e48c89084df","questionId":"6da101ad-ca5b-5737-bc1b-28126e406d36","sourceKey":"bank:LAG-BUA125:FOR-010","payload":{"prompt":"The forecasting method that uses ONLY previous sales data to project future consumer demand is called:","options":["Delphi forecasting","Passive demand forecasting","Macro demand forecasting","Active demand forecasting"],"correctOption":1,"section":"Business Forecasting","explanation":"Passive demand forecasting relies solely on past sales records to project demand. Option D also uses current market trends and other data, option C looks at the whole economy, and option A relies on the opinions of experts."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 277, $official_bank_source${"itemId":"58f14188-af83-558a-bebc-5a4cf3997517","questionId":"c79e9ad5-2884-5f1e-bd45-3d8652428a91","sourceKey":"bank:LAG-BUA125:FOR-011","payload":{"prompt":"What is the main difference between passive and active demand forecasting?","options":["Active forecasting adds current market trends and other data to past demand, while passive forecasting uses only past sales","Passive forecasting is always long-term, while active forecasting is always short-term","Passive forecasting uses expert opinion, while active forecasting uses only past sales","Active forecasting covers the whole economy, while passive forecasting covers one product"],"correctOption":0,"section":"Business Forecasting","explanation":"Passive forecasting projects demand from past sales records alone, while active forecasting also analyses current market trends and other data. Option C reverses and confuses the two, option D describes the macro versus micro distinction, and option B confuses them with the short-term versus long-term distinction."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 278, $official_bank_source${"itemId":"91010b28-52a0-5914-98df-bbc69b7dc273","questionId":"d7396e46-e0b8-5443-8527-1792fa728d10","sourceKey":"bank:LAG-BUA125:FOR-012","payload":{"prompt":"A business forecasts demand for its own goods using past sales, industry trends, economic conditions and customer feedback in order to plan its production and inventory. This is:","options":["Passive demand forecasting","End-user research","Macro demand forecasting","Internal demand forecasting"],"correctOption":3,"section":"Business Forecasting","explanation":"Internal demand forecasting is done by the business for its own products, combining past sales, industry trends, economic conditions and customer feedback to plan production and inventory. Option C concerns the whole economy, option A uses only past sales, and option B is a type of survey of other businesses."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 279, $official_bank_source${"itemId":"98916783-0eca-5803-b845-5eb2cd85ac64","questionId":"a5e72ca7-e6f1-52d1-ae4f-4c4613af673e","sourceKey":"bank:LAG-BUA125:FOR-013","payload":{"prompt":"Which statement correctly distinguishes macro demand forecasting from micro demand forecasting?","options":["Macro forecasting is short-term; micro forecasting is long-term","Macro forecasting predicts demand in the overall economy using indicators such as GDP and income; micro forecasting predicts demand for a specific product in a given market","Macro forecasting predicts demand for one product in one town; micro forecasting predicts demand for the whole economy","Macro forecasting uses only expert opinion; micro forecasting uses only past sales"],"correctOption":1,"section":"Business Forecasting","explanation":"Macro forecasting works at the level of the whole economy using population, GDP, income and spending, while micro forecasting targets a specific product in a given market using local factors. Option C swaps the two, and options D and A describe other distinctions."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 280, $official_bank_source${"itemId":"4a20d0db-8632-5259-bcfb-443f3d7ba2fe","questionId":"dbe65194-761f-53ac-9edd-4bb0676a4c28","sourceKey":"bank:LAG-BUA125:FOR-014","payload":{"prompt":"A soft drink maker forecasts demand in Surulere alone, considering local customer behaviour, seasonality, competition and pricing. This is an example of:","options":["Long-term demand forecasting","Micro demand forecasting","Passive demand forecasting","Macro demand forecasting"],"correctOption":1,"section":"Business Forecasting","explanation":"Micro demand forecasting predicts demand in small geographical areas using local factors like customer behaviour, seasonality, competition and pricing. Option D would use economy-wide indicators, option A refers to a protracted time span, and option C uses only past sales."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 281, $official_bank_source${"itemId":"e13586b7-7db5-5095-8c2c-7a9161cbe424","questionId":"7ab1e1db-6589-548c-9d4e-2b1edd7aee1b","sourceKey":"bank:LAG-BUA125:FOR-015","payload":{"prompt":"A furniture maker that sells to hotels asks the hotel managers what their guests want, in order to estimate future demand. This survey technique is known as:","options":["End-user research","Complete enumeration survey","Sample survey","Sales force composite"],"correctOption":0,"section":"Business Forecasting","explanation":"End-user research involves asking other businesses for their opinions on what clients desire, as the furniture maker does with hotels. Option B contacts as many prospective customers as practical, option C studies a small sample of potential clients, and option D relies on the firm's own salespeople."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 282, $official_bank_source${"itemId":"845b8e97-ee06-58ec-ad66-fe4bfb03d237","questionId":"02eb4a06-37dc-5082-a057-60a33c6c33b0","sourceKey":"bank:LAG-BUA125:FOR-016","payload":{"prompt":"A survey that involves speaking with as many prospective customers as is practical, in order to collect a larger amount of data, is called a:","options":["End-user survey","Complete enumeration survey","Delphi survey","Sample survey"],"correctOption":1,"section":"Business Forecasting","explanation":"A complete enumeration survey tries to reach as many prospective customers as practical, giving a large amount of data. Option D deliberately studies only a small sample, option A asks other businesses, and option C questions a panel of experts in rounds."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 283, $official_bank_source${"itemId":"0588a0a1-6d90-51c7-a8bd-c3bdfa50a934","questionId":"85ae3bc9-d38a-51d3-8af1-e8f08a759905","sourceKey":"bank:LAG-BUA125:FOR-017","payload":{"prompt":"Which statistical forecasting approach is described as the easiest method for predicting demand, simply studying the past to predict the future?","options":["Regression analysis","Decision trees","Trend projection","Econometric modelling"],"correctOption":2,"section":"Business Forecasting","explanation":"Trend projection extends past patterns of demand into the future and is the simplest statistical approach. Option A relates demand to external factors such as price or advertising, option B analyses how different variables affect demand, and option D builds mathematical models of economic systems."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 284, $official_bank_source${"itemId":"a82840c4-66fa-5202-9d2b-55ac1cbd3397","questionId":"7a9e323b-6ab5-5ad4-927f-4de1fb12353c","sourceKey":"bank:LAG-BUA125:FOR-018","payload":{"prompt":"A paint company wants to measure how its sales are related to price, the time of year and its advertising campaigns, so it can forecast demand. The most suitable statistical technique is:","options":["Delphi method","Trend projection","Regression analysis","Complete enumeration survey"],"correctOption":2,"section":"Business Forecasting","explanation":"Regression analysis identifies relationships between demand and external factors such as price, season and advertising. Option B simply extends past patterns, option D is a customer survey, and option A relies on expert opinion rather than statistical relationships."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 285, $official_bank_source${"itemId":"e51ca893-74ed-5c24-a2b0-d945424a9163","questionId":"8c5bfe72-2c4f-5b69-bdb4-7ccdcc319746","sourceKey":"bank:LAG-BUA125:FOR-019","payload":{"prompt":"Time series analysis as a forecasting method is based on the assumption that:","options":["Experts can always predict the future better than data","Demand depends only on the opinions of salespeople","Current demand trends shown in historical data will hold true going forward","Past data is irrelevant to future demand"],"correctOption":2,"section":"Business Forecasting","explanation":"Time series analysis is a quantitative method that uses historical data and assumes the patterns in that data will continue. Option D contradicts this, while options A and B describe qualitative, judgement-based methods."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 286, $official_bank_source${"itemId":"c50a8042-3531-5564-97f5-76f4457ed04e","questionId":"682d133c-e2da-506e-9703-2cdad749e2c4","sourceKey":"bank:LAG-BUA125:FOR-020","payload":{"prompt":"Econometric models used in demand forecasting are best described as:","options":["Charts that simply extend last year's sales line","Panels of experts who answer questions in several rounds","Mathematical models that estimate relationships among economic variables such as prices, demand, supply and consumption","Estimates made by salespeople for their own territories"],"correctOption":2,"section":"Business Forecasting","explanation":"Econometric models are mathematical descriptions of economic systems used to estimate relationships among variables like price, demand, supply and consumption, and to examine the effects of policies. Option B is the Delphi method, option D is the sales force composite, and option A is simple trend projection."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 287, $official_bank_source${"itemId":"e1b6f434-a527-5165-86a7-3d114417ac4e","questionId":"9f0e2340-dfd7-57a6-bc21-902004bbd5ea","sourceKey":"bank:LAG-BUA125:FOR-021","payload":{"prompt":"Why can econometric demand forecasting be extremely difficult in practice?","options":["Econometric models do not use any numbers","Econometric models can only be used by salespeople","Forecasters are rarely able to run controlled trials in which only one variable is changed","Economic variables never change over time"],"correctOption":2,"section":"Business Forecasting","explanation":"Econometrics tries to isolate the effect of each variable, but in real markets many things change at once and controlled experiments are rarely possible. Option A is false because these are mathematical models, option B is false, and option D is false because economic variables change constantly."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 288, $official_bank_source${"itemId":"154fb44b-8a16-51d0-9a0b-b73751affafe","questionId":"c17bc522-b9ce-56ac-a0b6-2c1530f265db","sourceKey":"bank:LAG-BUA125:FOR-022","payload":{"prompt":"The forecasting technique in which salespeople estimate demand in their own territories and these estimates are combined at branch, region and company level is known as:","options":["Barometric forecasting","Complete enumeration","The Delphi method","The sales force composite (collective view) method"],"correctOption":3,"section":"Business Forecasting","explanation":"In the sales force composite, sometimes called the collective view, each salesperson forecasts for their territory and the figures are added up into a company forecast. Option C uses outside experts in rounds, option A uses leading, lagging and coincident indicators, and option B surveys as many customers as practical."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 289, $official_bank_source${"itemId":"c81cad1e-ff46-5b48-bcf2-092e13c1473a","questionId":"d2b9d1b1-6d4b-50dd-9331-6475c5af681a","sourceKey":"bank:LAG-BUA125:FOR-023","payload":{"prompt":"The sales force composite is described as a 'bottom-up' approach. Its main advantage is that:","options":["Salespeople are close to the market and often have first-hand knowledge of customers","It is always free from any bias","It ignores differences between sales territories","It needs no information from customers at all"],"correctOption":0,"section":"Business Forecasting","explanation":"Because salespeople deal with customers directly, their territory estimates are grounded in first-hand market knowledge. Option B is false since salespeople can be over- or under-optimistic, option C is wrong because price, campaigns, affluence and competition vary by area and must be kept in mind, and option D contradicts the whole idea."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 290, $official_bank_source${"itemId":"7b7c8408-1648-550b-843c-5aee846a7eeb","questionId":"ccbcc1ab-b938-53a4-afeb-2330bf091480","sourceKey":"bank:LAG-BUA125:FOR-024","payload":{"prompt":"Which of the following best describes the Delphi method of forecasting?","options":["A technique that uses only the company's past sales records","A qualitative technique in which experts are questioned in a series of rounds and their opinions are consolidated into a prediction","A quantitative technique that fits a straight line to past sales","A technique that adds up the estimates of the firm's salespeople"],"correctOption":1,"section":"Business Forecasting","explanation":"The Delphi method gathers expert opinions over several rounds, then consolidates them to forecast demand; it was developed by the RAND Corporation. Option C is trend projection, option A is passive forecasting, and option D is the sales force composite."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 291, $official_bank_source${"itemId":"50d5f44a-c982-5791-b49e-02131ef576d3","questionId":"fd300de4-2c63-5052-bcbb-2d21f39e3ecf","sourceKey":"bank:LAG-BUA125:FOR-025","payload":{"prompt":"Which of the following is a QUALITATIVE forecasting method?","options":["Expert opinion","Moving average","Exponential smoothing","Trend projection"],"correctOption":0,"section":"Business Forecasting","explanation":"Expert opinion relies on the judgement of knowledgeable people rather than on numerical models, so it is qualitative, like the Delphi method and the sales force composite. Options B, C and D are quantitative methods that calculate forecasts from past data."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 292, $official_bank_source${"itemId":"f6afe6e4-e303-529d-a1bf-9f1ed0416e45","questionId":"d4608acd-6425-5524-88c7-586c20269f92","sourceKey":"bank:LAG-BUA125:FOR-026","payload":{"prompt":"An online retailer notices a sudden surge in customer complaints about delivery delays and treats it as a warning that sales may soon fall. In barometric forecasting, the complaints are a:","options":["Seasonal index","Coincident indicator","Lagging indicator","Leading indicator"],"correctOption":3,"section":"Business Forecasting","explanation":"Leading indicators attempt to predict future events, and a rise in complaints about shipping delays can signal a coming decline in sales. Option C looks back at past outcomes, option B measures what is happening now, and option A is not one of the three barometric indicators."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 293, $official_bank_source${"itemId":"540bc371-2d33-5135-846e-e34ffc9d90b5","questionId":"93569b8a-b93c-5c18-9b48-a3d076cb3c70","sourceKey":"bank:LAG-BUA125:FOR-027","payload":{"prompt":"In barometric forecasting, indicators used to gauge what is happening right now, such as real-time inventory turnover, are called:","options":["Econometric indicators","Leading indicators","Coincident indicators","Lagging indicators"],"correctOption":2,"section":"Business Forecasting","explanation":"Coincident indicators measure current activity, for example real-time inventory turnover showing ongoing sales. Option B predicts the future, option D reviews past outcomes such as last month's sales rise, and option A is not one of the three barometric types."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 294, $official_bank_source${"itemId":"1ea0d2a3-e90b-5d83-8390-a614348db963","questionId":"c86063f4-00bd-5c33-bb4f-7ca147687750","sourceKey":"bank:LAG-BUA125:FOR-028","payload":{"prompt":"Which of the following is NOT one of the challenges of forecasting?","options":["Insufficient resources","Unpredictable external factors","Over-reliance on past data","Having too many accurate and complete data sources"],"correctOption":3,"section":"Business Forecasting","explanation":"Forecasting challenges include lack of data, over-reliance on past data, limited visibility into the future, inaccurate demand models, poor processes, insufficient resources and unpredictable external factors. Plentiful accurate data would help rather than hinder, while options C, B and A are genuine challenges."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 295, $official_bank_source${"itemId":"cedebef5-1c41-5fd2-b766-fc33469a357e","questionId":"956723d4-7176-5969-97c3-d3128dd78360","sourceKey":"bank:LAG-BUA125:FOR-029","payload":{"prompt":"After forecasts have been made, how should a firm check that they are accurate?","options":["Raise all prices until actual sales match the forecast","Compare the actual outcomes with the forecast outcomes and adjust the methods if they are not accurate","Keep the forecasts secret and never review them","Replace the forecast with last year's actual figures"],"correctOption":1,"section":"Business Forecasting","explanation":"Forecasts should be monitored by contrasting actual results with predicted results, and the methods should be adjusted when the forecasts prove inaccurate. Options C and D skip the comparison altogether, and option A distorts the market instead of improving the forecast."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 296, $official_bank_source${"itemId":"3c424d2b-d687-5045-a9a6-4395a63ad536","questionId":"1310d852-3aba-5f11-9689-359006d833cd","sourceKey":"bank:LAG-BUA125:FOR-030","payload":{"prompt":"In forecasting, simulation refers to:","options":["Asking a panel of experts to vote on next year's sales","Averaging the sales of the last three periods","Adding up salespeople's territory estimates","Building a model of the real system and running it under different assumptions to see the likely range of outcomes"],"correctOption":3,"section":"Business Forecasting","explanation":"Simulation imitates the behaviour of a real system with a model, often on a computer, and runs it under different scenarios or random inputs to see what demand might be. Option A is expert opinion or Delphi, option B is a moving average, and option C is the sales force composite."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 297, $official_bank_source${"itemId":"4d0f518f-2c44-5918-acb3-1b493ff0b3a9","questionId":"af61beb1-58ed-5c36-a62e-225577ab38c3","sourceKey":"bank:LAG-BUA125:FOR-031","payload":{"prompt":"In exponential smoothing, F(t+1) = F(t) + alpha x (A(t) - F(t)), where 0 < alpha < 1. Choosing a HIGHER value of alpha makes the forecast:","options":["Respond more quickly to recent changes in actual demand","Respond more slowly to recent changes in demand","Ignore the most recent actual demand","Exactly equal to the long-run average"],"correctOption":0,"section":"Business Forecasting","explanation":"Alpha is the weight given to the latest forecast error, so a larger alpha moves the new forecast further towards the latest actual value, making it more responsive. Option B describes a lower alpha, option C would need alpha = 0, and option D does not follow from the formula."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 298, $official_bank_source${"itemId":"d929fe8d-d8fa-58db-887e-66af7984e0f5","questionId":"b2074793-c5d2-5eea-94e4-a9e9d59d5502","sourceKey":"bank:LAG-BUA125:FOR-032","payload":{"prompt":"A simple moving average forecast is obtained by:","options":["Adding the actual values of all past periods without dividing","Taking the largest value in the whole data set","Multiplying the last actual value by a growth rate chosen by experts","Averaging the actual values of the most recent fixed number of periods and using the result as the next period's forecast"],"correctOption":3,"section":"Business Forecasting","explanation":"A simple moving average takes the mean of the latest n periods, and the window moves forward one period each time, which smooths out random fluctuations. Option B ignores averaging, option C is a judgemental growth projection, and option A forgets to divide by the number of periods."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 299, $official_bank_source${"itemId":"b4ee6472-eecd-524d-a4a9-6fb069f1d993","questionId":"17d7cd2e-3b5d-54b7-8a83-2b3a146c96c5","sourceKey":"bank:LAG-BUA125:FOR-033","payload":{"prompt":"A Surulere bakery sold the following numbers of loaves from January to June: 420, 450, 480, 510, 470 and 500. Using a 3-month simple moving average, what is the forecast for July (to the nearest loaf)?","options":["485","450","493","472"],"correctOption":2,"section":"Business Forecasting","explanation":"A 3-month moving average uses the three most recent months: (510 + 470 + 500) / 3 = 1,480 / 3 = 493.33, about 493 loaves. Option D averages all six months, option B averages the first three months instead of the latest three, and option A uses only the last two months."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 300, $official_bank_source${"itemId":"0f141da3-eef3-534a-a5c8-c0f6c373e6cf","questionId":"6cf9bbde-eed4-5127-b697-0928389a9617","sourceKey":"bank:LAG-BUA125:FOR-034","payload":{"prompt":"A rice seller in Kano sold 60, 64, 70, 66 and 72 bags in weeks 1 to 5. Using a 4-week simple moving average, what is the forecast for week 6?","options":["68.00","69.33","65.00","66.40"],"correctOption":0,"section":"Business Forecasting","explanation":"The 4-week moving average uses weeks 2 to 5: (64 + 70 + 66 + 72) / 4 = 272 / 4 = 68.00 bags. Option B is a 3-week average, option D averages all five weeks, and option C uses weeks 1 to 4, which is out of date."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 301, $official_bank_source${"itemId":"cd7eab7b-9f24-5506-9002-223ceac08feb","questionId":"153ca49c-120a-5616-80ea-02bd4ed250cb","sourceKey":"bank:LAG-BUA125:FOR-035","payload":{"prompt":"A phone accessories shop sold 200, 220 and 250 units in March, April and May respectively. Using a weighted moving average with weights 3, 2 and 1, giving the weight of 3 to the most recent month, what is the forecast for June (to 2 decimal places)?","options":["231.67","1,390","215.00","223.33"],"correctOption":0,"section":"Business Forecasting","explanation":"Weighted average = (3 x 250 + 2 x 220 + 1 x 200) / (3 + 2 + 1) = 1,390 / 6 = 231.67 units. Option C gives the heaviest weight to March instead of May, option D is the simple average, and option B forgets to divide by the sum of the weights."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 302, $official_bank_source${"itemId":"1820c214-2cca-5885-92d4-a60348545edf","questionId":"d93733a1-089c-5495-a6fe-4b754462f96b","sourceKey":"bank:LAG-BUA125:FOR-036","payload":{"prompt":"Monthly sales of a paint distributor (in N million) for the last three months were 70 (oldest), 80 and 90 (most recent). Using weights of 0.5 for the most recent month, 0.3 for the month before and 0.2 for the oldest, what is the weighted moving average forecast for next month?","options":["N77.00 million","N83.00 million","N80.00 million","N27.67 million"],"correctOption":1,"section":"Business Forecasting","explanation":"Forecast = 0.5 x 90 + 0.3 x 80 + 0.2 x 70 = 45 + 24 + 14 = N83.00 million; because the weights add to 1, there is no need to divide. Option A applies the weights in reverse order, option C is the simple average, and option D wrongly divides the weighted total by 3."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 303, $official_bank_source${"itemId":"f6d2b1e5-ffaf-550d-8036-beb8206e65c9","questionId":"7d7608e3-e09a-5509-943f-da88b3218a72","sourceKey":"bank:LAG-BUA125:FOR-037","payload":{"prompt":"A water-treatment company's annual sales (in thousand units) for four years were 120, 135, 150 and 165, increasing by the same amount each year. Using simple trend projection, what is the forecast for the fifth year?","options":["165","142.5","195","180"],"correctOption":3,"section":"Business Forecasting","explanation":"Sales rise by a constant 15 thousand units a year, so the next year's forecast is 165 + 15 = 180 thousand units. Option A simply repeats the last value, option B is the average of the four years, and option C projects two years ahead instead of one."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 304, $official_bank_source${"itemId":"ca6520bd-25c9-5b62-bfaa-ce4282b3111d","questionId":"ffd0b36f-39af-54ee-9d0a-7db4b50882a7","sourceKey":"bank:LAG-BUA125:FOR-038","payload":{"prompt":"A firm's sales trend is estimated as Y = 250 + 18X, where Y is sales in N million and X = 1 for 2021, X = 2 for 2022, and so on. What is the trend forecast of sales for 2027?","options":["N376 million","N394 million","N358 million","N1,876 million"],"correctOption":0,"section":"Business Forecasting","explanation":"2027 corresponds to X = 7, so Y = 250 + 18 x 7 = 250 + 126 = N376 million. Option C uses X = 6 (counting 2021 as zero), option B uses X = 8, and option D multiplies both terms by 7."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 305, $official_bank_source${"itemId":"6c430618-e8ef-5605-b8df-ad437efc74f8","questionId":"b1b7a193-4850-5d67-aa62-273dd7b9c168","sourceKey":"bank:LAG-BUA125:FOR-039","payload":{"prompt":"A firm's sales (N million) for 2021 to 2025 were 40, 44, 50, 54 and 62. Coding the years as X = -2, -1, 0, 1, 2 (so that the sum of X is zero), the least-squares trend line is Y = a + bX with a = (sum of Y)/n and b = (sum of XY)/(sum of X^2). What is the trend forecast for 2026?","options":["N66.20 million","N82.40 million","N67.50 million","N55.40 million"],"correctOption":0,"section":"Business Forecasting","explanation":"a = 250 / 5 = 50 and b = 54 / 10 = 5.4, so Y = 50 + 5.4X. For 2026, X = 3, giving Y = 50 + 5.4 x 3 = N66.20 million. Option D uses X = 1, option C adds the average yearly change to the last value instead of using the fitted line, and option B uses X = 6 by counting 2026 as the sixth year on the coded scale."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 306, $official_bank_source${"itemId":"258ae4c6-c0cd-527f-988e-2d1316de2ba5","questionId":"bdae7d33-7e9e-5d7a-9c30-62ca9b696b26","sourceKey":"bank:LAG-BUA125:FOR-040","payload":{"prompt":"Using exponential smoothing, F(t+1) = F(t) + alpha x (A(t) - F(t)). A shoe shop forecast 500 pairs for May, actual sales were 540 pairs, and alpha = 0.2. What is the forecast for June?","options":["532.00","508.00","540.00","492.00"],"correctOption":1,"section":"Business Forecasting","explanation":"F(June) = 500 + 0.2 x (540 - 500) = 500 + 8 = 508.00 pairs. Option A uses 0.8 (1 - alpha) on the error instead of alpha, option C simply takes the last actual value, and option D subtracts the adjustment even though actual sales were above the forecast."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 307, $official_bank_source${"itemId":"aa4eea97-0110-5c3a-800c-5b5e20fa87df","questionId":"79ce3c84-2977-55ca-92e0-a5a55596991a","sourceKey":"bank:LAG-BUA125:FOR-041","payload":{"prompt":"Using F(t+1) = F(t) + alpha x (A(t) - F(t)) with alpha = 0.4, a firm's forecast for week 1 was 200 units. Actual sales were 220 units in week 1 and 210 units in week 2. What is the forecast for week 3?","options":["212.80","208.00","216.00","208.80"],"correctOption":3,"section":"Business Forecasting","explanation":"First F(2) = 200 + 0.4 x (220 - 200) = 208; then F(3) = 208 + 0.4 x (210 - 208) = 208.80 units. Option B stops after one step, option A reuses week 1's actual in the second step, and option C starts from the week 1 actual instead of the week 2 forecast."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 308, $official_bank_source${"itemId":"08763ea3-6882-52e2-9141-9f7d8aa56746","questionId":"89091a00-fe61-5fb8-8036-242d74ce0280","sourceKey":"bank:LAG-BUA125:FOR-042","payload":{"prompt":"A firm uses F(t+1) = F(t) + alpha x (A(t) - F(t)). Its forecast for last month was 1,000 units, actual sales were 1,200 units, and its forecast for this month is 1,060 units. What value of alpha was used?","options":["0.06","0.70","0.30","0.60"],"correctOption":2,"section":"Business Forecasting","explanation":"The adjustment is 1,060 - 1,000 = 60, and 60 = alpha x (1,200 - 1,000) = alpha x 200, so alpha = 60 / 200 = 0.30. Option B is 1 - alpha, option A divides the adjustment by the old forecast, and option D divides by 100 instead of the 200-unit error."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 309, $official_bank_source${"itemId":"298ccd0d-1502-5ac3-8a60-f199e5313e30","questionId":"68948927-5d2e-5fc6-a57c-a5ba95742668","sourceKey":"bank:LAG-BUA125:FOR-043","payload":{"prompt":"Actual sales for four weeks were 100, 110, 95 and 105 units, while the forecasts were 98, 104, 101 and 103 units. What is the mean absolute deviation (MAD) of the forecast errors?","options":["5.33","1.00","16.00","4.00"],"correctOption":3,"section":"Business Forecasting","explanation":"Errors (actual - forecast) are 2, 6, -6 and 2; their absolute values sum to 16, so MAD = 16 / 4 = 4.00 units. Option B averages the errors with their signs, so the -6 cancels a +6; option C forgets to divide by 4; option A divides by 3 instead of 4."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 310, $official_bank_source${"itemId":"b2250e0a-7685-53e0-9230-4b313c237069","questionId":"22bb071e-be6b-5920-892f-add834736374","sourceKey":"bank:LAG-BUA125:FOR-044","payload":{"prompt":"Using the sales force composite method, a beverage firm's salespeople estimate next quarter's sales in their territories as: Lagos 12,500 cartons, Ibadan 8,300, Abeokuta 4,700 and Ilorin 3,500. What is the firm's overall forecast?","options":["24,300 cartons","29,000 cartons","7,250 cartons","25,500 cartons"],"correctOption":1,"section":"Business Forecasting","explanation":"The sales force composite is a bottom-up method, so the company forecast is the total of the territory estimates: 12,500 + 8,300 + 4,700 + 3,500 = 29,000 cartons. Option C averages the territories instead of adding them, and options D and A each leave out one territory."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 311, $official_bank_source${"itemId":"6a236e10-8195-5f1b-a069-37884866379a","questionId":"c879d2db-0bdd-5923-afaf-1a5012f8f32f","sourceKey":"bank:LAG-BUA125:FOR-045","payload":{"prompt":"Using F(t+1) = F(t) + alpha x (A(t) - F(t)), a firm's forecast for this month was 300 units and actual sales were 340 units. If alpha = 1, what is next month's forecast?","options":["300","340","380","320"],"correctOption":1,"section":"Business Forecasting","explanation":"With alpha = 1, F(t+1) = 300 + 1 x (340 - 300) = 340, so the forecast simply equals the latest actual value (a naive forecast). Option A is the case alpha = 0, option D corresponds to alpha = 0.5, and option C adds the error to the actual instead of to the forecast."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 312, $official_bank_source${"itemId":"7ac5d060-92a4-52ea-9893-ec1af38daa7b","questionId":"5d4b6b76-574e-5fd6-a8c4-25d2cd02a87e","sourceKey":"bank:LAG-BUA125:FOR-046","payload":{"prompt":"Two analysts use F(t+1) = F(t) + alpha x (A(t) - F(t)). Both start from a forecast of 400 units, and actual demand turns out to be 500 units. Analyst A uses alpha = 0.1 and analyst B uses alpha = 0.5. By how many units does B's next forecast exceed A's?","options":["40","50","60","10"],"correctOption":0,"section":"Business Forecasting","explanation":"A: 400 + 0.1 x 100 = 410; B: 400 + 0.5 x 100 = 450; the difference is 40 units, showing that a larger alpha responds more strongly to the latest error. Option B is only B's adjustment, option D is only A's adjustment, and option C adds the two adjustments instead of subtracting one from the other."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 313, $official_bank_source${"itemId":"715823b3-0ce3-54df-9fd3-1439c6d8eaae","questionId":"984d6971-6e98-5792-bb36-3ec97e8aad1c","sourceKey":"bank:LAG-BUA125:FOR-047","payload":{"prompt":"A shop sold 30, 34 and 38 units in periods 1 to 3, and 40 units in period 4. If period 4 had been forecast with a 3-period simple moving average, what would the forecast error (actual minus forecast) for period 4 be?","options":["2","4","6","-6"],"correctOption":2,"section":"Business Forecasting","explanation":"The 3-period moving average forecast for period 4 is (30 + 34 + 38) / 3 = 34, so the error is 40 - 34 = 6 units. Option D computes forecast minus actual, option A compares the actual with period 3's sales instead of the forecast, and option B is the size of each period's increase."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 314, $official_bank_source${"itemId":"924c5ebf-1955-5883-a290-dcfc6981cd3b","questionId":"c2cbdcc4-8a44-5694-8ad1-cfbbb9c2d270","sourceKey":"bank:LAG-BUA125:FOR-048","payload":{"prompt":"A firm's sales were N80 million in 2019 and N116 million in 2025. Assuming sales continue to change by the same average amount each year, what is the forecast for 2027?","options":["N128.00 million","N152.00 million","N126.29 million","N122.00 million"],"correctOption":0,"section":"Business Forecasting","explanation":"From 2019 to 2025 there are 6 yearly changes, so the average change = (116 - 80) / 6 = 6 per year. 2027 is two years after 2025, giving 116 + 2 x 6 = N128.00 million. Option D projects only one year ahead, option C wrongly divides by 7 (the number of years listed) instead of 6, and option B adds the whole six-year increase again."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 315, $official_bank_source${"itemId":"a9b4533c-7074-5205-bf72-3830a8f71d70","questionId":"3190866a-f7ab-52ff-b9b3-505b2e27fefe","sourceKey":"bank:LAG-BUA125:FOR-049","payload":{"prompt":"A firm's sales this year are N50 million, and they are projected to grow at a constant 8% per year (compound). What is the sales forecast for two years from now?","options":["N54.00 million","N62.99 million","N58.32 million","N58.00 million"],"correctOption":2,"section":"Business Forecasting","explanation":"With compound growth, sales in two years = 50 x (1.08)^2 = 50 x 1.1664 = N58.32 million. Option D adds 8% of N50 million twice (simple growth), option A covers only one year, and option B compounds for three years."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 316, $official_bank_source${"itemId":"71b5a5f9-07da-592b-8597-0e42ce266c62","questionId":"f0dafd9c-97c4-5994-9af6-43ae174cd53f","sourceKey":"bank:LAG-BUA125:FOR-050","payload":{"prompt":"Quarterly revenue of a Port Harcourt hotel (N million) for five quarters was 1.2, 1.5, 1.8, 1.4 and 1.7. Using a 4-quarter simple moving average, what is the forecast for the sixth quarter (to 3 decimal places)?","options":["N1.600 million","N1.520 million","N1.633 million","N1.475 million"],"correctOption":0,"section":"Business Forecasting","explanation":"The 4-quarter moving average uses quarters 2 to 5: (1.5 + 1.8 + 1.4 + 1.7) / 4 = 6.4 / 4 = N1.600 million. Option D uses quarters 1 to 4, option B averages all five quarters, and option C is a 3-quarter average."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 317, $official_bank_source${"itemId":"2a6b7b2f-1070-5169-aba4-a566ef179c02","questionId":"1681edfd-4aad-5081-a1c1-ae3de880c978","sourceKey":"bank:LAG-BUA125:PQ-013","payload":{"prompt":"A perfectly competitive firm will most likely decide to shut down in the short run when:","options":["Fixed costs exceed variable costs","Average fixed costs are rising","Marginal cost is above average variable cost","Price is below the minimum of average variable cost"],"correctOption":3,"section":"Cost Analysis: Short Run and Long Run","explanation":"In the short run a firm keeps producing as long as price covers average variable cost; once price falls below minimum AVC, every unit adds to its losses, so it shuts down, option D. Option A does not matter because fixed costs must be paid even if the firm shuts down. Option B is impossible since AFC always falls as output rises, and option C is normal above the AVC minimum."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 318, $official_bank_source${"itemId":"8662a971-5184-550f-8e3d-b6f1a77f0e46","questionId":"cb273b5f-1f3e-5384-9bfd-77f06f35ed41","sourceKey":"bank:LAG-BUA125:PQ-014","payload":{"prompt":"In the long run, a profit-maximising firm will choose to exit a market when:","options":["Marginal cost exceeds marginal revenue at the current level of output","Fixed costs exceed sunk costs","Revenue from production is less than total costs","Average fixed cost is rising"],"correctOption":2,"section":"Cost Analysis: Short Run and Long Run","explanation":"In the long run all costs are variable, so a firm leaves if total revenue cannot cover total cost, option C. Option A only tells the firm to cut output a little, not to leave the industry. Options B and D are not exit conditions, and AFC does not rise with output."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 319, $official_bank_source${"itemId":"6fb2f552-5079-5427-a206-e764de8a9ae9","questionId":"0cf4ea75-267e-5a9f-a384-1794dcf92f82","sourceKey":"bank:LAG-BUA125:PQ-164","payload":{"prompt":"Which statement about costs in decision making is correct?","options":["Only future costs that differ between the alternatives are relevant","Past costs are always relevant to future decisions","All future costs are relevant to every decision","Fixed costs are always relevant to every decision"],"correctOption":0,"section":"Cost Analysis: Short Run and Long Run","explanation":"A cost is relevant only if it lies in the future and changes depending on which option is chosen. Option C is wrong because a future cost that is the same under every option cannot help you choose, and option B ignores the fact that past (sunk) costs cannot be changed."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 320, $official_bank_source${"itemId":"e0dd616a-4e07-50f9-9335-37defcb3b28a","questionId":"27550d14-1c19-5fa2-b521-16db8dfd66f7","sourceKey":"bank:LAG-BUA125:PQ-168","payload":{"prompt":"A cost that does not affect a decision is called:","options":["an irrelevant cost","an avoidable cost","an opportunity cost","an incremental cost"],"correctOption":0,"section":"Cost Analysis: Short Run and Long Run","explanation":"An irrelevant cost stays the same whichever option is chosen, or has already been incurred, so it can be ignored. Options C, D and B are all costs that do change with the choice made, so they matter to the decision."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 321, $official_bank_source${"itemId":"09ae7590-f17b-59e9-a76c-e01558267049","questionId":"321be2df-37fd-55c5-b643-de883c2755fa","sourceKey":"bank:LAG-BUA125:PQ-169","payload":{"prompt":"Costs that differ between the alternatives being considered are called:","options":["sunk costs","historical costs","relevant costs","fixed costs"],"correctOption":2,"section":"Cost Analysis: Short Run and Long Run","explanation":"Relevant costs are future costs that change depending on the option chosen, so they should guide the decision. Option A refers to past spending that cannot change, and option D refers to costs that stay the same as output changes, so neither describes costs that differ between alternatives."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 322, $official_bank_source${"itemId":"ced31c8d-fde3-5750-8d3e-88137487cfcb","questionId":"7ed81c6e-bf0f-5a1b-afe5-1e0e00246668","sourceKey":"bank:LAG-BUA125:PQ-193","payload":{"prompt":"The historical cost of an asset refers to:","options":["the cost of replacing the asset at today's prices","the income given up by using the asset in its present use","the expected cost of maintaining the asset in future","the actual cost incurred at the time the asset was acquired"],"correctOption":3,"section":"Cost Analysis: Short Run and Long Run","explanation":"Historical cost is the original price actually paid for an asset when it was bought. Option A is replacement cost, and option B is the opportunity cost of using the asset."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 323, $official_bank_source${"itemId":"07bcd868-2246-50d3-868b-a98f9e561031","questionId":"46bdd13f-699d-5385-b548-1745b9feee44","sourceKey":"bank:LAG-BUA125:PQ-195","payload":{"prompt":"The cost paid by the individual or firm directly involved in producing or consuming a particular good is called:","options":["social cost","external cost","sunk cost","private cost"],"correctOption":3,"section":"Cost Analysis: Short Run and Long Run","explanation":"Private cost is borne by the producer or consumer who is directly involved, such as a firm paying for its raw materials and labour. Options A and B describe costs that fall on society or third parties, and option C is money already spent that cannot be recovered."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 324, $official_bank_source${"itemId":"444bcf89-38f4-5afc-9f8c-2d47cc1aba15","questionId":"93b7f74a-d872-5a52-8d3d-3870d56a3adb","sourceKey":"bank:LAG-BUA125:PQ-196","payload":{"prompt":"The cost burden carried by people who are not directly involved in the production or consumption of a good, such as residents affected by a factory's pollution, is known as:","options":["private cost","explicit cost","marginal cost","external cost"],"correctOption":3,"section":"Cost Analysis: Short Run and Long Run","explanation":"An external cost falls on third parties outside the transaction, such as neighbours suffering from noise or pollution, and together with private cost it makes up social cost. Option A is borne by the producer or consumer directly involved, while options B and C are cost concepts used within the firm itself."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 325, $official_bank_source${"itemId":"62085cac-df6c-5aa5-a50a-54e149f24667","questionId":"1702a299-26f7-5d3e-b626-d6da83d26fb6","sourceKey":"bank:LAG-BUA125:PQ-197","payload":{"prompt":"Average total cost is equal to:","options":["marginal cost plus average fixed cost","total cost multiplied by output","total fixed cost plus total variable cost","average fixed cost plus average variable cost"],"correctOption":3,"section":"Cost Analysis: Short Run and Long Run","explanation":"Average total cost is total cost divided by output, and since total cost is fixed cost plus variable cost, ATC = AFC + AVC. Option C gives total cost, not average cost, and option B multiplies instead of dividing."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 326, $official_bank_source${"itemId":"81f6829e-4069-57b9-94e3-01a29f64560e","questionId":"4a983329-aea7-52b0-8399-f66a9ba1cad0","sourceKey":"bank:LAG-BUA125:PQ-199","payload":{"prompt":"In the short run, a firm's costs can be classified into:","options":["fixed costs and variable costs","historical costs and replacement costs","sunk costs and opportunity costs","private costs and social costs"],"correctOption":0,"section":"Cost Analysis: Short Run and Long Run","explanation":"In the short run at least one input is fixed, so some costs (such as rent) do not change with output while others (such as raw materials) do. Options C, D and B are real cost concepts, but they are not the basic short-run split based on how costs behave as output changes."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 327, $official_bank_source${"itemId":"0c2d42d0-4ea3-5e9c-a7c5-5ad42d3025c8","questionId":"120b2a18-0b5c-5f52-9224-abd7e0250167","sourceKey":"bank:LAG-BUA125:PQ-200","payload":{"prompt":"In the short run, total fixed cost:","options":["rises in direct proportion to output","is always greater than total variable cost","falls to zero when output rises","remains the same whether output increases or decreases"],"correctOption":3,"section":"Cost Analysis: Short Run and Long Run","explanation":"Fixed costs, such as rent and insurance, must be paid regardless of how much is produced, even at zero output. Option A describes variable cost, and option B is not a general rule. It is average fixed cost, not total fixed cost, that falls as output rises."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 328, $official_bank_source${"itemId":"8b64085a-5d3c-521c-a8a8-500bca70e0a5","questionId":"7278bbf0-9eb0-53d4-a261-250b02021022","sourceKey":"bank:LAG-BUA125:PQ-201","payload":{"prompt":"Marginal cost is the change in total cost resulting from a one-unit change in:","options":["the number of firms in the industry","output","input prices","the selling price"],"correctOption":1,"section":"Cost Analysis: Short Run and Long Run","explanation":"Marginal cost is the extra cost of producing one more unit of output, that is the change in total cost divided by the change in output. Options C, A and D may affect costs, but marginal cost is defined with respect to output."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 329, $official_bank_source${"itemId":"ca5be4ec-2b8d-51e8-9925-dbe346af4cdd","questionId":"72901dcb-1d26-5a15-938c-ee7229f69dbd","sourceKey":"bank:LAG-BUA125:PQ-202","payload":{"prompt":"Average cost falls as output rises until the firm reaches its optimum scale, where marginal cost equals average cost, and then rises. This gives the average cost curve a:","options":["continuously rising shape","vertical straight-line shape","U-shape","horizontal straight-line shape"],"correctOption":2,"section":"Cost Analysis: Short Run and Long Run","explanation":"Because average cost first falls, reaches a minimum where it is cut by marginal cost, and then rises, the curve looks like the letter U. Option D would mean cost per unit never changes, and option A ignores the early fall in average cost."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 330, $official_bank_source${"itemId":"d9f06f1f-1497-5522-9db6-b51cfbd10d6b","questionId":"406a4f7f-cb9f-523b-a701-4a782ceffbb9","sourceKey":"bank:LAG-BUA125:PQ-203","payload":{"prompt":"The U-shape of the long-run average cost curve is mainly explained by:","options":["changes in the selling price of the product","the presence of fixed costs that cannot be changed","economies of scale followed by diseconomies of scale","the law of diminishing returns to a fixed factor"],"correctOption":2,"section":"Cost Analysis: Short Run and Long Run","explanation":"In the long run all inputs are variable, so average cost first falls as the firm enjoys economies of scale and later rises when diseconomies of scale set in. Option D explains the short-run curve, where at least one factor is fixed, and option B cannot apply in the long run because no cost is fixed then."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 331, $official_bank_source${"itemId":"d7eb1bfd-06af-5b66-92d4-1d4e157a005f","questionId":"fea6a9a3-a5a8-5aad-af7b-39791893adcc","sourceKey":"bank:LAG-BUA125:PQ-208","payload":{"prompt":"The long-run average cost curve can be described as:","options":["an envelope of a series of short-run average cost curves","the same as the marginal cost curve","a curve that includes only fixed costs","a single short-run average cost curve"],"correctOption":0,"section":"Cost Analysis: Short Run and Long Run","explanation":"The long run can be seen as a series of short runs, each with a different plant size, and the long-run average cost curve wraps around the lowest parts of those short-run curves. Option D ignores the choice of plant size, and option C cannot be right because there are no fixed costs in the long run."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 332, $official_bank_source${"itemId":"29e1df2f-db15-56e4-9d34-40b4a99aba90","questionId":"a0f944bf-43ec-596f-9871-9235a41b97c3","sourceKey":"bank:LAG-BUA125:PQ-228","payload":{"prompt":"In the short run, which costs depend on the level of output?","options":["Total variable cost only","Total cost only","Both total variable cost and total cost","Total fixed cost only"],"correctOption":2,"section":"Cost Analysis: Short Run and Long Run","explanation":"Total variable cost rises and falls with output, and because total cost is fixed cost plus variable cost, total cost also changes when output changes. Option D is wrong because fixed cost stays the same whatever the output in the short run. Option A is only half the story, since total cost moves with output too."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 333, $official_bank_source${"itemId":"68756941-14d0-5f1e-ab86-038c727e3751","questionId":"202e6964-0035-53bf-8096-a6552148681a","sourceKey":"bank:LAG-BUA125:PQ-229","payload":{"prompt":"In the short run, a firm will shut down if:","options":["it is making any loss at all","its total revenue cannot cover its total variable cost","its total cost exceeds its revenue","its fixed costs exceed its revenue"],"correctOption":1,"section":"Cost Analysis: Short Run and Long Run","explanation":"In the short run fixed costs must be paid whether the firm produces or not, so the firm keeps producing as long as revenue covers its variable costs. Once revenue falls below variable cost, producing only adds to the loss, so it shuts down. Options C and A describe a loss, but a firm can make a loss and still stay open if it is covering its variable costs."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 334, $official_bank_source${"itemId":"6807d0ef-a7a0-5f09-8bfd-a48d66f3147d","questionId":"40d339d9-b73a-5174-9d0a-d5ddece0f7c2","sourceKey":"bank:LAG-BUA125:PQ-230","payload":{"prompt":"Which statement about costs in the long run is correct?","options":["All costs are variable; there are no fixed costs","All costs are fixed","Only labour costs are variable","Fixed costs are higher than in the short run"],"correctOption":0,"section":"Cost Analysis: Short Run and Long Run","explanation":"The long run is a period long enough for the firm to change all its inputs, including plant size and machinery, so every cost becomes variable. Option B is the opposite of the truth. Option D is wrong because fixed costs only exist in the short run, when at least one input cannot be changed."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 335, $official_bank_source${"itemId":"1bffe173-9b84-5f03-a567-5b73f31f8cb4","questionId":"2802a923-2ed8-561f-9b85-b58e95f3e03e","sourceKey":"bank:LAG-BUA125:PQ-272","payload":{"prompt":"A variable cost is a cost that:","options":["may not be incurred, depending on management discretion","varies per unit at every level of activity","occurs at various times during the year","varies in total in proportion to changes in the level of activity"],"correctOption":3,"section":"Cost Analysis: Short Run and Long Run","explanation":"Variable costs, such as raw materials, rise in total as output rises and fall as output falls, while the cost per unit stays roughly the same. Option B gets it backwards, because it is the total, not the per-unit amount, that changes. Option C is about timing, not about how the cost responds to output."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 336, $official_bank_source${"itemId":"2336d3ed-1f0d-5546-82c3-734bb9129aaf","questionId":"6573441e-d2d5-5519-9b99-d66894affb73","sourceKey":"bank:LAG-BUA125:PQ-273","payload":{"prompt":"A cost which remains constant per unit at various levels of activity is a:","options":["mixed cost","variable cost","fixed cost","sunk cost"],"correctOption":1,"section":"Cost Analysis: Short Run and Long Run","explanation":"A variable cost changes in total with output but stays the same for each unit, for example the same amount of flour in every loaf. Option C is the trap: a fixed cost is constant in total, so its cost per unit falls as output rises. Option A has both a fixed and a variable part, so its per-unit cost is not constant."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 337, $official_bank_source${"itemId":"cf9900c5-e73b-51b0-b7c6-4c18ce2dd6ae","questionId":"f3087b49-e0a6-5083-8218-e9a2fda9bea3","sourceKey":"bank:LAG-BUA125:PQ-274","payload":{"prompt":"A fixed cost is a cost which:","options":["remains constant in total when the level of activity changes","varies inversely in total with changes in the level of activity","varies in total with changes in the level of activity","remains constant per unit when the level of activity changes"],"correctOption":0,"section":"Cost Analysis: Short Run and Long Run","explanation":"Fixed costs, such as rent, stay the same in total whether the firm produces a little or a lot, at least in the short run. Option C describes a variable cost. Option D is also a variable cost feature; a fixed cost per unit actually falls as output rises, because the same total is spread over more units."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 338, $official_bank_source${"itemId":"270a9333-e87e-5725-ba15-8439d5f2ac99","questionId":"c5a6d29f-61ec-51fe-b914-fe66a1023042","sourceKey":"bank:LAG-BUA125:PQ-277","payload":{"prompt":"The relevant range of activity refers to the:","options":["activity level at which all costs are curvilinear","geographical areas where the firm plans to operate","range of activity levels over which the firm expects to operate","activity level at which all costs are constant"],"correctOption":2,"section":"Cost Analysis: Short Run and Long Run","explanation":"The relevant range is the band of output levels a firm normally works within, and over this range fixed costs stay fixed and variable cost per unit stays roughly constant. Option B confuses activity level with location. Option D is wrong because variable costs still change in total within the range."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 339, $official_bank_source${"itemId":"8e2b8acb-6d54-5407-9ba4-025e0c601ce9","questionId":"274b40fa-ec84-54ec-b132-53aba825a315","sourceKey":"bank:LAG-BUA125:PQ-282","payload":{"prompt":"A mixed (semi-variable) cost contains:","options":["a fixed cost element and a variable cost element","both retailing and manufacturing costs","both selling and administrative costs","both operating and non-operating costs"],"correctOption":0,"section":"Cost Analysis: Short Run and Long Run","explanation":"A mixed cost has a part that is paid no matter what and a part that rises with usage, for example a phone bill with a fixed monthly charge plus a charge per call. Options C, B and D mix different departments or types of expense, which says nothing about how the cost behaves when output changes."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 340, $official_bank_source${"itemId":"8a9ea42c-9bdf-53af-a08a-6bf96a44b548","questionId":"7545023c-6045-5592-b9d2-01cefbba8494","sourceKey":"bank:LAG-BUA125:PQ-289","payload":{"prompt":"The level of activity at which total revenue equals total cost is the:","options":["shutdown point","break-even point","fixed point","semi-variable point"],"correctOption":1,"section":"Cost Analysis: Short Run and Long Run","explanation":"At the break-even point the firm makes neither profit nor loss, because its revenue exactly covers all its fixed and variable costs. Option A is the trap: the shutdown point is where revenue only just covers variable cost, not total cost. Options D and C are not standard terms for any output level."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 341, $official_bank_source${"itemId":"1341d856-e0fe-5c65-87de-e2e02f7cbd45","questionId":"55e67ddc-8b55-556b-a412-88c0a6b415e5","sourceKey":"bank:LAG-BUA125:PQ-290","payload":{"prompt":"At the break-even point:","options":["total sales equal total fixed cost","total sales equal total variable cost","total variable cost equals total fixed cost","total contribution margin equals total fixed cost"],"correctOption":3,"section":"Cost Analysis: Short Run and Long Run","explanation":"Contribution is sales minus variable costs, and it is what is left to pay the fixed costs. The firm breaks even when this contribution exactly covers fixed costs, leaving zero profit. Options B and A each leave out one type of cost, and option C compares two costs with no reference to revenue at all."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 342, $official_bank_source${"itemId":"1158076d-4b76-5cd5-96d1-53cf485fd292","questionId":"50a42e93-e9fa-5764-b60f-e5f5d7519ff8","sourceKey":"bank:LAG-BUA125:CST-001","payload":{"prompt":"A pure-water producer in Ikorodu has the following short-run cost schedule. Output: 0, 1, 2, 3, 4, 5 units; Total cost: N600, N900, N1,100, N1,260, N1,480, N1,800. What is the firm's total fixed cost?","options":["N600","N1,200","N900","N360"],"correctOption":0,"section":"Cost Analysis: Short Run and Long Run","explanation":"Total fixed cost is the cost incurred even when output is zero, so it is read off the total cost at Q = 0, which is N600. Option C is the total cost of the first unit, which includes variable cost. Option B is total variable cost at 5 units (N1,800 - N600), not fixed cost."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 343, $official_bank_source${"itemId":"f9f477c0-b914-5506-b5be-3be1976a1256","questionId":"439f6b1f-270a-501c-a9d3-74a50abb3105","sourceKey":"bank:LAG-BUA125:CST-002","payload":{"prompt":"Using this cost schedule for a small bakery: Output: 0, 1, 2, 3, 4, 5 units; Total cost: N600, N900, N1,100, N1,260, N1,480, N1,800. What is total variable cost at 3 units of output?","options":["N1,260","N160","N660","N1,860"],"correctOption":2,"section":"Cost Analysis: Short Run and Long Run","explanation":"Total variable cost is total cost minus total fixed cost: TVC = 1,260 - 600 = N660 at 3 units. Option A is total cost itself, which still contains the fixed cost. Option B is the marginal cost of the 3rd unit, not total variable cost."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 344, $official_bank_source${"itemId":"122f3c0c-1f5d-5857-9573-388abcd96df2","questionId":"8798bccd-2e23-507b-b8cd-4076d3764369","sourceKey":"bank:LAG-BUA125:CST-003","payload":{"prompt":"A firm's short-run costs are: Output: 0, 1, 2, 3, 4, 5 units; Total cost: N600, N900, N1,100, N1,260, N1,480, N1,800. What is average fixed cost at 4 units?","options":["N370","N220","N120","N150"],"correctOption":3,"section":"Cost Analysis: Short Run and Long Run","explanation":"Average fixed cost is total fixed cost divided by output: AFC = 600 / 4 = N150. Option A is average total cost (1,480 / 4), and option B is average variable cost (880 / 4). Option C divides fixed cost by 5 units instead of 4."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 345, $official_bank_source${"itemId":"cda308d4-bdcc-5de8-8244-43d7ef089220","questionId":"9340ee3a-b8c3-54df-b18c-54fb2667e997","sourceKey":"bank:LAG-BUA125:CST-004","payload":{"prompt":"A firm's short-run costs are: Output: 0, 1, 2, 3, 4, 5 units; Total cost: N600, N900, N1,100, N1,260, N1,480, N1,800. What is average variable cost at 5 units?","options":["N240","N320","N120","N360"],"correctOption":0,"section":"Cost Analysis: Short Run and Long Run","explanation":"Average variable cost is TVC / Q = (1,800 - 600) / 5 = 1,200 / 5 = N240. Option D forgets to remove fixed cost and gives average total cost. Option B is the marginal cost of the 5th unit."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 346, $official_bank_source${"itemId":"e38d8fa7-e021-5d86-b0c5-d3603770f66a","questionId":"01968cc8-d895-5214-b25c-413bafef24e6","sourceKey":"bank:LAG-BUA125:CST-005","payload":{"prompt":"A firm's short-run costs are: Output: 0, 1, 2, 3, 4, 5 units; Total cost: N600, N900, N1,100, N1,260, N1,480, N1,800. What is average total cost at 3 units?","options":["N160","N420","N315","N220"],"correctOption":1,"section":"Cost Analysis: Short Run and Long Run","explanation":"Average total cost is total cost divided by output: ATC = 1,260 / 3 = N420. Option D is average variable cost (660 / 3), which leaves out fixed cost. Option A is the marginal cost of the 3rd unit."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 347, $official_bank_source${"itemId":"0c9729ee-c89d-5e67-bd8c-1cd5a10aa4d5","questionId":"cc211199-c07b-5310-a8de-54ad606ccfdd","sourceKey":"bank:LAG-BUA125:CST-006","payload":{"prompt":"A firm's short-run costs are: Output: 0, 1, 2, 3, 4, 5 units; Total cost: N600, N900, N1,100, N1,260, N1,480, N1,800. What is the marginal cost of the 4th unit?","options":["N220","N370","N160","N1,480"],"correctOption":0,"section":"Cost Analysis: Short Run and Long Run","explanation":"Marginal cost is the extra cost of one more unit: MC = TC(4) - TC(3) = 1,480 - 1,260 = N220. Option B is average total cost at 4 units, not the change in cost. Option C is the marginal cost of the 3rd unit, the wrong step in the table."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 348, $official_bank_source${"itemId":"4d4e4eb1-2fe0-51fa-8cf4-6c24297a2b60","questionId":"f53b174d-6529-57ea-a7d3-cce25b36f0a3","sourceKey":"bank:LAG-BUA125:CST-007","payload":{"prompt":"A firm's short-run costs are: Output: 0, 1, 2, 3, 4, 5 units; Total cost: N600, N900, N1,100, N1,260, N1,480, N1,800. Over which unit is marginal cost at its lowest?","options":["The 1st unit","The 5th unit","The 3rd unit","The 4th unit"],"correctOption":2,"section":"Cost Analysis: Short Run and Long Run","explanation":"Marginal costs of units 1 to 5 are N300, N200, N160, N220 and N320, so MC is lowest for the 3rd unit and rises after it as diminishing returns set in. Option A has the highest early MC, and options D and B are on the rising part of the MC curve."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 349, $official_bank_source${"itemId":"32bf8f44-7fd0-5531-ae41-23c28b87719b","questionId":"92af6683-cd79-5a52-aaed-c51745576b1d","sourceKey":"bank:LAG-BUA125:CST-008","payload":{"prompt":"Total fixed cost is N120 at every output. Total variable cost at outputs 1, 2, 3, 4, 5 and 6 units is N60, N100, N135, N180, N240, N330 respectively. At what output is average total cost at its minimum?","options":["6 units","5 units","3 units","4 units"],"correctOption":1,"section":"Cost Analysis: Short Run and Long Run","explanation":"ATC = (120 + TVC) / Q gives N180, N110, N85, N75, N72 and N75, so the minimum ATC of N72 is at 5 units. Option C and option D are where average variable cost is lowest (N45), which happens at a smaller output than minimum ATC because AFC keeps falling."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 350, $official_bank_source${"itemId":"c93bafe7-392a-59ff-a4ee-fc5a526773fc","questionId":"151139fe-4e24-54cb-995e-10fb4ad24572","sourceKey":"bank:LAG-BUA125:CST-009","payload":{"prompt":"Total fixed cost is N120 at every output. Total variable cost at outputs 1, 2, 3, 4, 5 and 6 units is N60, N100, N135, N180, N240, N330 respectively. What is the lowest average variable cost the firm can achieve?","options":["N45","N50","N72","N60"],"correctOption":0,"section":"Cost Analysis: Short Run and Long Run","explanation":"AVC = TVC / Q gives N60, N50, N45, N45, N48 and N55, so the minimum AVC is N45 (at 3 and 4 units). Option C is the minimum average total cost, which also includes fixed cost per unit. Option D is the smallest total variable cost, not a per-unit figure."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 351, $official_bank_source${"itemId":"bf7c9bb8-df6e-5590-9296-217cb6f593c6","questionId":"2af80b61-da71-585f-a2c4-8a342cdbcf57","sourceKey":"bank:LAG-BUA125:CST-010","payload":{"prompt":"A garri processor's total cost rises from N50,000 to N62,000 when output rises from 200 bags to 260 bags. What is the marginal cost per bag over this range?","options":["N12,000","N1,033","N238","N200"],"correctOption":3,"section":"Cost Analysis: Short Run and Long Run","explanation":"Marginal cost = change in TC / change in Q = (62,000 - 50,000) / (260 - 200) = 12,000 / 60 = N200 per bag. Option A is the total change in cost, not per bag. Option C is average total cost at 260 bags, which is a different measure."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 352, $official_bank_source${"itemId":"a523c3af-16b3-53ba-88f4-81d170fc6953","questionId":"b1b33266-c4c6-5188-8a99-b42ad2fdecaa","sourceKey":"bank:LAG-BUA125:CST-011","payload":{"prompt":"At an output of 500 cartons, a juice maker's average fixed cost is N80 and its average variable cost is N220. What is its total cost?","options":["N300","N40,220","N110,000","N150,000"],"correctOption":3,"section":"Cost Analysis: Short Run and Long Run","explanation":"Average total cost is AFC + AVC = 80 + 220 = N300, so total cost is ATC x Q = 300 x 500 = N150,000. Option A stops at average total cost and forgets to multiply by output. Option C is total variable cost only."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 353, $official_bank_source${"itemId":"f435184e-b428-5ab5-9db8-3dda3398e4ce","questionId":"6ecc4408-c8db-5c8d-bca4-5dfc57433c74","sourceKey":"bank:LAG-BUA125:CST-012","payload":{"prompt":"A firm's average total cost is N95 and its average fixed cost is N30 at its current output. What is its average variable cost?","options":["N95","N65","N125","N30"],"correctOption":1,"section":"Cost Analysis: Short Run and Long Run","explanation":"Since ATC = AFC + AVC, AVC = ATC - AFC = 95 - 30 = N65. Option C adds the two figures instead of subtracting. Options D and A simply repeat the given AFC and ATC."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 354, $official_bank_source${"itemId":"abc34868-2898-5305-b026-f7c131e470bf","questionId":"b64c5665-3256-5ffa-8c29-ea3356e856d7","sourceKey":"bank:LAG-BUA125:CST-013","payload":{"prompt":"A printing press has an average fixed cost of N18 per copy when it prints 400 copies. If output rises to 900 copies with no change in plant, what will average fixed cost be?","options":["N16","N40","N18","N8"],"correctOption":3,"section":"Cost Analysis: Short Run and Long Run","explanation":"Total fixed cost is AFC x Q = 18 x 400 = N7,200 and stays the same in the short run, so the new AFC = 7,200 / 900 = N8. Option C wrongly assumes AFC is constant per unit. Option B scales AFC up with output, as if fixed cost rose."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 355, $official_bank_source${"itemId":"3210ccdb-fba1-58ee-9c02-1e3e95c22a3b","questionId":"d38863cf-eb8c-531b-b961-4e057453e94c","sourceKey":"bank:LAG-BUA125:CST-014","payload":{"prompt":"A tailoring firm's total cost is TC = 36,000 + 1,500Q, where Q is the number of outfits. What is its average total cost when it makes 30 outfits?","options":["N1,500","N2,700","N81,000","N1,200"],"correctOption":1,"section":"Cost Analysis: Short Run and Long Run","explanation":"TC at 30 outfits = 36,000 + 1,500 x 30 = N81,000, so ATC = 81,000 / 30 = N2,700. Option A is AVC (and MC) only, and option D is AFC only (36,000 / 30). Option C is total cost, not cost per outfit."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 356, $official_bank_source${"itemId":"713ec181-021e-56c4-a08a-1dee6cee5073","questionId":"fe396c02-2db7-5e7c-937e-eec7f406ac90","sourceKey":"bank:LAG-BUA125:CST-015","payload":{"prompt":"For the cost function TC = 36,000 + 1,500Q, what is the marginal cost of producing one more unit at any output level?","options":["N36,000","N2,700","N1,500","N37,500"],"correctOption":2,"section":"Cost Analysis: Short Run and Long Run","explanation":"With TC = 36,000 + 1,500Q, each extra unit raises total cost by exactly N1,500, so MC = N1,500 at every output. Option D adds the fixed cost to one unit's variable cost, but fixed cost does not change when output changes. Option A is total fixed cost."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 357, $official_bank_source${"itemId":"34f4d19d-c5cc-50a9-8ba3-91708c33bf92","questionId":"afde3f76-b2a5-555f-b7bd-685ae1794d87","sourceKey":"bank:LAG-BUA125:CST-016","payload":{"prompt":"A firm's total cost function is TC = 800 + 20Q + 2Q^2. What is average variable cost at Q = 10?","options":["N80","N120","N40","N58"],"correctOption":2,"section":"Cost Analysis: Short Run and Long Run","explanation":"Variable cost is the part that depends on Q: TVC = 20(10) + 2(10)^2 = 200 + 200 = N400, so AVC = 400 / 10 = N40. Option B is ATC (1,200 / 10), which wrongly keeps the N800 fixed cost. Option D is the marginal cost of the 10th unit."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 358, $official_bank_source${"itemId":"9586d1c6-0eec-5776-9e45-7803e319b103","questionId":"b4a55626-ac76-59a9-b978-eca95590130d","sourceKey":"bank:LAG-BUA125:CST-017","payload":{"prompt":"A firm's total cost function is TC = 800 + 20Q + 2Q^2. What is the marginal cost of the 10th unit, found as TC(10) - TC(9)?","options":["N120","N40","N58","N1,200"],"correctOption":2,"section":"Cost Analysis: Short Run and Long Run","explanation":"TC(10) = 800 + 200 + 200 = N1,200 and TC(9) = 800 + 180 + 162 = N1,142, so MC = 1,200 - 1,142 = N58. Option A is average total cost at 10 units. Option B is average variable cost, and option D is total cost at 10 units, not the extra cost of the 10th unit."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 359, $official_bank_source${"itemId":"33c6aa32-e58b-523b-b5fd-ec8bd5c80a94","questionId":"28d151b0-c115-56a4-8471-0cfe3e0a85b1","sourceKey":"bank:LAG-BUA125:CST-018","payload":{"prompt":"A shoe maker's average variable cost is N2,500 at 4 pairs and N2,600 at 5 pairs. What is the marginal cost of the 5th pair?","options":["N3,000","N2,550","N2,600","N100"],"correctOption":0,"section":"Cost Analysis: Short Run and Long Run","explanation":"Total variable cost is AVC x Q: 4 x 2,500 = N10,000 and 5 x 2,600 = N13,000, so MC = 13,000 - 10,000 = N3,000. Option D is just the change in average cost, a common mistake. Option C is the AVC of the 5th pair, not the extra cost."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 360, $official_bank_source${"itemId":"fcb41d20-427e-5548-833e-cfc2f4c55f39","questionId":"b217e011-3dd6-558a-b646-87ca758cc63c","sourceKey":"bank:LAG-BUA125:CST-019","payload":{"prompt":"A firm's average total cost is N48 at 9 units and N46 at 10 units. What is the marginal cost of the 10th unit?","options":["N46","N460","N28","N2"],"correctOption":2,"section":"Cost Analysis: Short Run and Long Run","explanation":"TC(9) = 9 x 48 = N432 and TC(10) = 10 x 46 = N460, so MC = 460 - 432 = N28. Option D uses the change in ATC instead of the change in total cost, and option B is total cost at 10 units. Because MC (N28) is below ATC, ATC is falling, which fits the data."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 361, $official_bank_source${"itemId":"f52f0c85-dac9-5eee-b6b6-0f5f3133873c","questionId":"22f1fa4e-2526-5b7a-ab79-69d3cc0aeb62","sourceKey":"bank:LAG-BUA125:CST-020","payload":{"prompt":"A firm has total fixed cost of N500. The marginal costs of its 1st, 2nd and 3rd units are N120, N90 and N110. What is its total cost of producing 3 units?","options":["N610","N820","N273","N320"],"correctOption":1,"section":"Cost Analysis: Short Run and Long Run","explanation":"Total cost = TFC + sum of marginal costs = 500 + 120 + 90 + 110 = N820. Option D is total variable cost only, leaving out fixed cost. Option A adds only the last unit's marginal cost to fixed cost."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 362, $official_bank_source${"itemId":"147a4489-0663-597a-ac42-7d1cfcc3d822","questionId":"0b6e667b-0721-5aea-9acf-1e2ae4a31010","sourceKey":"bank:LAG-BUA125:CST-021","payload":{"prompt":"A firm's total cost is N3,000 at zero output and N7,200 at 60 units. What is its average variable cost at 60 units?","options":["N4,200","N70","N50","N120"],"correctOption":1,"section":"Cost Analysis: Short Run and Long Run","explanation":"Fixed cost is the cost at zero output, N3,000, so TVC at 60 units = 7,200 - 3,000 = N4,200 and AVC = 4,200 / 60 = N70. Option D is ATC (7,200 / 60). Option C is AFC at 60 units."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 363, $official_bank_source${"itemId":"50baf658-6d4a-56d6-9af8-e84ad32be58c","questionId":"77c30989-e07a-5028-9033-8ee7325dd44c","sourceKey":"bank:LAG-BUA125:CST-022","payload":{"prompt":"A bakery uses 2 bags of flour per batch of bread. Its fixed cost is N40,000 a week. The price of flour rises by N3,000 per bag. By how much does the marginal cost of a batch rise?","options":["N6,000","N3,000","N0","N46,000"],"correctOption":0,"section":"Cost Analysis: Short Run and Long Run","explanation":"Each batch uses 2 bags, so the variable cost of a batch rises by 2 x 3,000 = N6,000, and marginal cost rises by the same amount. Option B forgets that each batch uses two bags. Option C would be right only if the change were in fixed cost, which does not affect marginal cost."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 364, $official_bank_source${"itemId":"874bb0cc-7351-558b-adde-f1f0357631c3","questionId":"6c41c178-d7ed-5f43-a658-4c4a863662f3","sourceKey":"bank:LAG-BUA125:CST-023","payload":{"prompt":"A firm's monthly rent (a fixed cost) rises from N200,000 to N260,000. Before the change, its marginal cost at 1,000 units was N150. What is its marginal cost at 1,000 units after the rent rise?","options":["N210","N195","N60","N150"],"correctOption":3,"section":"Cost Analysis: Short Run and Long Run","explanation":"Marginal cost depends only on how variable cost changes with output, and rent does not change when one more unit is made, so MC stays N150. Option A adds the N60 rise in fixed cost per unit, which affects AFC and ATC, not MC. Option B wrongly raises MC by the 30% rise in rent."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 365, $official_bank_source${"itemId":"bfe48b80-90ea-5169-9cd8-2fe8ccc3a91c","questionId":"859a5d11-868d-5ea2-b160-9b6e27308e9b","sourceKey":"bank:LAG-BUA125:CST-024","payload":{"prompt":"A poultry farm sells crates of eggs at N800 each. Its variable cost is N500 per crate and its total fixed cost is N240,000. What is the break-even output?","options":["480 crates","300 crates","185 crates","800 crates"],"correctOption":3,"section":"Cost Analysis: Short Run and Long Run","explanation":"Break-even quantity = TFC / (P - AVC) = 240,000 / (800 - 500) = 240,000 / 300 = 800 crates. Option B divides fixed cost by price and ignores variable cost. Option A divides by variable cost instead of the contribution per crate."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 366, $official_bank_source${"itemId":"548b60bc-65c9-5e48-a367-e119db9518d7","questionId":"507f1aac-c533-50e1-8cb9-2071355c5809","sourceKey":"bank:LAG-BUA125:CST-025","payload":{"prompt":"A poultry farm sells crates of eggs at N800 each, with variable cost of N500 per crate and total fixed cost of N240,000. What sales revenue does it need to break even?","options":["N240,000","N240,800","N400,000","N640,000"],"correctOption":3,"section":"Cost Analysis: Short Run and Long Run","explanation":"Break-even output is 240,000 / (800 - 500) = 800 crates, and break-even revenue = 800 x N800 = N640,000. Option C values the break-even output at variable cost instead of price. Option A is just total fixed cost, which is what contribution must cover, not total revenue."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 367, $official_bank_source${"itemId":"e133cffc-5605-5d23-90fa-b4eb83596737","questionId":"6d010c89-2eaa-54de-95c9-363741f474d5","sourceKey":"bank:LAG-BUA125:CST-026","payload":{"prompt":"A recharge-card vendor sells at N1,000 per unit with variable cost of N850 per unit and fixed costs of N90,000 a month. How many units must it sell to make a monthly profit of N60,000?","options":["400 units","600 units","1,000 units","150 units"],"correctOption":2,"section":"Cost Analysis: Short Run and Long Run","explanation":"Required units = (TFC + target profit) / (P - AVC) = (90,000 + 60,000) / (1,000 - 850) = 150,000 / 150 = 1,000 units. Option B is the break-even output, which gives zero profit. Option D divides by price rather than by contribution per unit."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 368, $official_bank_source${"itemId":"e40cd7cd-6262-5a27-a7e0-e0f473a8dd18","questionId":"e79ba256-8c17-576e-b5ad-60e9973857c0","sourceKey":"bank:LAG-BUA125:CST-027","payload":{"prompt":"A firm sells 2,000 units at N450 each. Its total fixed cost is N300,000 and its average variable cost is N250. What is its profit?","options":["N600,000","N400,000","N599,750","N100,000"],"correctOption":3,"section":"Cost Analysis: Short Run and Long Run","explanation":"Profit = TR - TC = (2,000 x 450) - (300,000 + 2,000 x 250) = 900,000 - 800,000 = N100,000. Option B is total contribution, which forgets fixed cost. Option A forgets to subtract variable cost."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 369, $official_bank_source${"itemId":"c1fb6904-496f-53fc-b366-7ca883eba283","questionId":"926db592-5041-5dbf-88ab-a20042f1ed0d","sourceKey":"bank:LAG-BUA125:CST-028","payload":{"prompt":"In the long run, a firm can produce 1,000, 2,000, 3,000, 4,000 or 5,000 units, with lowest long-run total costs of N60,000, N100,000, N120,000, N160,000, N225,000 respectively. Over which range of output does the firm enjoy economies of scale?","options":["From 1,000 to 3,000 units","From 3,000 to 4,000 units","From 4,000 to 5,000 units","From 1,000 to 5,000 units"],"correctOption":0,"section":"Cost Analysis: Short Run and Long Run","explanation":"LRAC = LRTC / Q is N60, N50, N40, N40 and N45, so long-run average cost falls from 1,000 to 3,000 units, which is economies of scale. Option B is where LRAC is constant (constant returns), and option C is where LRAC rises, which is diseconomies of scale."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 370, $official_bank_source${"itemId":"787609c2-7f87-5b2a-addd-cd05ad05540a","questionId":"d5574cab-3bd1-5d13-b78b-f5a03b4c7a96","sourceKey":"bank:LAG-BUA125:CST-029","payload":{"prompt":"In the long run, a firm can produce 1,000, 2,000, 3,000, 4,000 or 5,000 units, with lowest long-run total costs of N60,000, N100,000, N120,000, N160,000, N225,000 respectively. What is the long-run average cost at 5,000 units, and what does it show?","options":["N225; diseconomies of scale have set in","N40; constant returns to scale","N45; diseconomies of scale have set in","N45; economies of scale are still present"],"correctOption":2,"section":"Cost Analysis: Short Run and Long Run","explanation":"LRAC at 5,000 units = 225,000 / 5,000 = N45, which is above the N40 reached at 4,000 units, so average cost is rising with scale: diseconomies of scale. Option D has the right figure but the wrong meaning. Option A wrongly uses a thousandth of total cost as if it were average cost."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 371, $official_bank_source${"itemId":"9b25f87b-8584-5888-8c87-da75b3624a6f","questionId":"d7cd36b4-f114-5460-a8ee-66137ed23ff7","sourceKey":"bank:LAG-BUA125:CST-030","payload":{"prompt":"A firm's short-run ATC at 250 units is N1,240 and its total fixed cost is N60,000. What is its total variable cost at 250 units?","options":["N250,000","N1,000","N310,000","N370,000"],"correctOption":0,"section":"Cost Analysis: Short Run and Long Run","explanation":"Total cost = ATC x Q = 1,240 x 250 = N310,000, so TVC = 310,000 - 60,000 = N250,000. Option C is total cost, which still includes fixed cost. Option B is AVC per unit (N1,000), not the total."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 372, $official_bank_source${"itemId":"75c08a20-c073-5378-b39e-ccdfc6a260c5","questionId":"94cdc316-322b-58cc-b341-16cacb987746","sourceKey":"bank:LAG-BUA125:CST-031","payload":{"prompt":"Total fixed cost is N120 at every output. Total variable cost at outputs 1, 2, 3, 4, 5 and 6 units is N60, N100, N135, N180, N240, N330 respectively. If the firm is a price taker, what is the lowest price at which it would keep producing in the short run rather than shut down?","options":["N120","N60","N45","N72"],"correctOption":2,"section":"Cost Analysis: Short Run and Long Run","explanation":"In the short run a firm keeps producing as long as price covers average variable cost, so the shutdown point is minimum AVC, N45. Option D is minimum ATC, which is the long-run break-even price, not the short-run shutdown price. Option A is total fixed cost, which must be paid whether the firm produces or not."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 373, $official_bank_source${"itemId":"1f1d7367-e3fe-5e1b-a359-d7c48d6be348","questionId":"6d25d5b0-fcb2-5c33-9a1e-3ac14c30eb58","sourceKey":"bank:LAG-BUA125:CST-032","payload":{"prompt":"A cost that does not change with the level of output in the short run, and must be paid even when output is zero, is called a","options":["marginal cost","average variable cost","variable cost","fixed cost"],"correctOption":3,"section":"Cost Analysis: Short Run and Long Run","explanation":"A fixed cost stays the same whatever the level of output in the short run, such as rent or insurance, and is paid even if nothing is produced. Option C rises and falls with output. Option A is the extra cost of one more unit, which is zero at no output change."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 374, $official_bank_source${"itemId":"df0f1b63-8136-52f8-8e07-9389716e81cd","questionId":"cac4526c-7ff6-52db-b226-8f1e73c83611","sourceKey":"bank:LAG-BUA125:CST-033","payload":{"prompt":"Which of the following is a variable cost for a bread bakery in Lagos?","options":["Annual fire insurance premium","Flour used in each batch of bread","Monthly rent on the bakery","Salary of the bakery manager"],"correctOption":1,"section":"Cost Analysis: Short Run and Long Run","explanation":"Flour is a variable cost because more of it is used as more bread is baked. Options C, A and D are fixed costs: rent, insurance and a fixed salary are paid at the same amount whether the bakery bakes much or little."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 375, $official_bank_source${"itemId":"5f155a28-6b09-5313-995a-5d6ad98bd8f2","questionId":"1e5a3155-a3fa-530c-b2b4-1e6c01f2ef41","sourceKey":"bank:LAG-BUA125:CST-034","payload":{"prompt":"Which of the following is NOT a fixed cost in the short run for a transport company?","options":["Diesel used on each trip","Rent on the company's park","Annual vehicle licence fees","Interest on a loan for buying buses"],"correctOption":0,"section":"Cost Analysis: Short Run and Long Run","explanation":"Diesel is used up in proportion to the trips made, so it is a variable cost. Options D, C and B must be paid at the same amount whatever the number of trips in the period, so they are fixed costs."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 376, $official_bank_source${"itemId":"b80ad8cc-4ca3-568d-a512-83f9a4b183a1","questionId":"410f8b4b-81a3-5dec-8514-596de3c02952","sourceKey":"bank:LAG-BUA125:CST-035","payload":{"prompt":"In cost analysis, the short run is best described as a period in which","options":["all factors of production can be varied","at least one factor of production is fixed","the firm has no fixed costs","the firm cannot change its output at all"],"correctOption":1,"section":"Cost Analysis: Short Run and Long Run","explanation":"The short run is defined by the presence of at least one fixed input, such as plant size, so the firm changes output only by changing variable inputs. Option A describes the long run. Option C is wrong because fixed costs exist only in the short run, and option D is wrong because output can still change through variable inputs."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 377, $official_bank_source${"itemId":"386298f7-a947-5a20-a4a7-71942520c783","questionId":"801173b7-b6cd-5a2c-a6b0-395306195792","sourceKey":"bank:LAG-BUA125:CST-036","payload":{"prompt":"Which statement correctly distinguishes the long run from the short run?","options":["The long run is always exactly one year and the short run less than one year","In the long run all costs are fixed, while in the short run all costs are variable","In the long run all costs are variable, while in the short run some costs are fixed","In the long run only labour can be changed, while in the short run only capital can be changed"],"correctOption":2,"section":"Cost Analysis: Short Run and Long Run","explanation":"In the long run the firm can vary every input, including plant size, so there are no fixed costs, whereas the short run has at least one fixed input. Option A is wrong because the periods are defined by flexibility of inputs, not by calendar time. Option B reverses the distinction."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 378, $official_bank_source${"itemId":"edf9fd7a-f649-5f66-838a-bf651946ef9c","questionId":"9a27b57b-c4e0-59fb-87fd-1aea84fa06b3","sourceKey":"bank:LAG-BUA125:CST-037","payload":{"prompt":"The formula MC = change in TC / change in Q measures","options":["the total cost per unit of output","the addition to total cost from producing one more unit of output","the cost that remains constant at all outputs","the fixed cost per unit of output"],"correctOption":1,"section":"Cost Analysis: Short Run and Long Run","explanation":"Marginal cost is the change in total cost caused by a one-unit change in output. Option A is average total cost (TC / Q). Option D is average fixed cost (TFC / Q)."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 379, $official_bank_source${"itemId":"49fc63c3-930b-5f6f-b9c2-41c791ba4746","questionId":"a01c5d0a-6cd4-5308-a237-728d44ad8a32","sourceKey":"bank:LAG-BUA125:CST-038","payload":{"prompt":"The marginal cost curve cuts the average total cost curve","options":["at the point where average fixed cost is lowest","at the minimum point of the average total cost curve","at the maximum point of the average total cost curve","where average total cost is still falling steeply"],"correctOption":1,"section":"Cost Analysis: Short Run and Long Run","explanation":"When MC is below ATC it pulls the average down, and when MC is above ATC it pulls the average up, so MC must cross ATC at its lowest point. Option C is wrong because the ATC curve is U-shaped and has no maximum in the relevant range. Option A is wrong because AFC keeps falling and has no minimum."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 380, $official_bank_source${"itemId":"de79564f-22a2-5026-958d-5117d80501d9","questionId":"29b89d13-a93e-5e9c-84ef-9cb784304a91","sourceKey":"bank:LAG-BUA125:CST-039","payload":{"prompt":"Which of the following statements about short-run cost curves is NOT correct?","options":["Average fixed cost falls continuously as output increases","The marginal cost curve cuts the average variable cost curve at the maximum point of AVC","When marginal cost is below average total cost, average total cost is falling","The vertical gap between ATC and AVC equals average fixed cost"],"correctOption":1,"section":"Cost Analysis: Short Run and Long Run","explanation":"MC cuts AVC at the minimum point of AVC, not the maximum, so the statement in option B is false. Option C is true because a lower marginal value pulls an average down. Options D and A are true because ATC - AVC = AFC, and AFC = TFC / Q falls as Q rises."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 381, $official_bank_source${"itemId":"9c301d07-2447-5acc-8483-0720ffc29c2d","questionId":"346e2ae4-a574-563a-9f55-3e2eb30f09f4","sourceKey":"bank:LAG-BUA125:CST-040","payload":{"prompt":"If a firm's marginal cost is greater than its average variable cost, then average variable cost is","options":["rising","constant","equal to average fixed cost","falling"],"correctOption":0,"section":"Cost Analysis: Short Run and Long Run","explanation":"When the cost of the extra unit is above the current average, adding that unit raises the average, so AVC is rising. Option D would happen if MC were below AVC. Option B happens only where MC equals AVC, at the minimum of AVC."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 382, $official_bank_source${"itemId":"3fff5268-39ec-5ff9-baed-e4b4d6e54528","questionId":"8511770c-87bc-57fb-9656-837255dbec63","sourceKey":"bank:LAG-BUA125:CST-041","payload":{"prompt":"As output increases in the short run, the vertical distance between the ATC curve and the AVC curve","options":["becomes smaller because marginal cost falls","becomes smaller because average fixed cost falls","becomes larger because fixed cost rises","stays exactly the same at every output"],"correctOption":1,"section":"Cost Analysis: Short Run and Long Run","explanation":"The gap between ATC and AVC is AFC, and AFC = TFC / Q falls as the same fixed cost is spread over more units. Option C is wrong because fixed cost does not rise with output. Option A gives the wrong reason; MC eventually rises, yet the gap still narrows."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 383, $official_bank_source${"itemId":"11422a88-c891-58bf-a433-a08c8c5055aa","questionId":"ef0bd62d-9894-5fff-aad5-754445020833","sourceKey":"bank:LAG-BUA125:CST-042","payload":{"prompt":"The average fixed cost curve","options":["slopes downward throughout and never touches the output axis","is a horizontal straight line","is U-shaped","slopes upward as output increases"],"correctOption":0,"section":"Cost Analysis: Short Run and Long Run","explanation":"Since AFC = TFC / Q and TFC is constant, AFC keeps falling as Q rises but never reaches zero, giving a curve that approaches the axis without touching it. Option C describes ATC, AVC and MC. Option B describes the total fixed cost curve, not the per-unit curve."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 384, $official_bank_source${"itemId":"215ab88c-397d-5062-985b-e7cf84222764","questionId":"7937bc74-8990-5e41-a5d5-d1d13990337f","sourceKey":"bank:LAG-BUA125:CST-043","payload":{"prompt":"When total cost is plotted against output, the total fixed cost curve is","options":["a straight line rising from the origin","a curve that falls as output rises","a U-shaped curve","a horizontal straight line"],"correctOption":3,"section":"Cost Analysis: Short Run and Long Run","explanation":"Total fixed cost is the same at every output in the short run, so its graph is a horizontal line at the level of fixed cost. Option A describes a variable cost that rises in proportion to output. Option B describes average fixed cost, not total fixed cost."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 385, $official_bank_source${"itemId":"b72233f9-dd01-523a-b2ab-a94ae50e53f0","questionId":"09760984-6bb7-5e43-856b-21826cadbba5","sourceKey":"bank:LAG-BUA125:CST-044","payload":{"prompt":"Which statement about the total cost (TC) and total variable cost (TVC) curves is correct?","options":["The TVC curve lies above the TC curve","Both TC and TVC start from the origin","The gap between TC and TVC widens as output increases","The TC curve starts at the level of fixed cost and lies above TVC by that same amount at every output"],"correctOption":3,"section":"Cost Analysis: Short Run and Long Run","explanation":"TC = TFC + TVC, so TC starts at the fixed-cost level when Q = 0 and stays above TVC by a constant gap equal to TFC. Option B is wrong because TC is positive at zero output. Option C is wrong because TFC does not change with output."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 386, $official_bank_source${"itemId":"0a02ab5a-5851-52cf-b0b7-463ac42020cd","questionId":"93f8880d-c9bd-5056-bcd0-e79754fe71ee","sourceKey":"bank:LAG-BUA125:CST-045","payload":{"prompt":"The short-run average cost curve is U-shaped mainly because of","options":["a fall in total fixed cost as output rises","economies and diseconomies of scale","the law of diminishing returns (variable proportions)","changes in the size of the plant"],"correctOption":2,"section":"Cost Analysis: Short Run and Long Run","explanation":"In the short run plant size is fixed, so adding more of the variable input first raises and then lowers its marginal product, making AVC and ATC fall and then rise. Options B and D explain the long-run average cost curve, where plant size can change. Option A is wrong because total fixed cost does not change."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 387, $official_bank_source${"itemId":"f038fce2-ce2f-5070-ac0c-9b7a6505da0a","questionId":"898ad6d6-66ca-5501-b9bb-48a94bee12eb","sourceKey":"bank:LAG-BUA125:CST-046","payload":{"prompt":"The long-run average cost curve is U-shaped mainly because of","options":["the law of diminishing returns to a fixed factor","a fixed plant size that cannot be changed","fixed costs being spread over more units","economies of scale at low outputs followed by diseconomies of scale at high outputs"],"correctOption":3,"section":"Cost Analysis: Short Run and Long Run","explanation":"In the long run all inputs vary, so the shape of LRAC comes from scale effects: economies of scale make it fall and diseconomies of scale make it rise. Option A explains the short-run curve, where one factor is fixed. Option B contradicts the long run, in which plant size can change."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 388, $official_bank_source${"itemId":"b5c0c3da-012d-5ef1-873c-20741de2a71f","questionId":"1d245f79-c2ab-5bc5-8407-ec6edce4180e","sourceKey":"bank:LAG-BUA125:CST-047","payload":{"prompt":"The fall in long-run average cost that a firm enjoys as it increases the scale of its operations is known as","options":["diseconomies of scale","economies of scale","diminishing returns","average fixed cost"],"correctOption":1,"section":"Cost Analysis: Short Run and Long Run","explanation":"Economies of scale are the cost savings per unit that come from producing on a larger scale, shown by a falling LRAC curve. Option A is the opposite, a rise in LRAC as scale grows. Option C is a short-run idea about adding a variable input to a fixed one."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 389, $official_bank_source${"itemId":"d3f79984-98d2-53ab-8c50-0ba27fbd43f9","questionId":"a4e09774-0954-57f0-b2a3-ff2b58b3e988","sourceKey":"bank:LAG-BUA125:CST-048","payload":{"prompt":"A large cement manufacturer gets bank loans at lower interest rates than small firms because lenders see it as less risky. This is an example of","options":["external diseconomies of scale","financial economies of scale","managerial diseconomies of scale","technical economies of scale"],"correctOption":1,"section":"Cost Analysis: Short Run and Long Run","explanation":"Cheaper and easier access to finance for a big firm is a financial economy of scale, an internal cost advantage of size. Option D refers to savings from large, efficient machinery and production methods. Options A and C are rises in cost, not savings."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 390, $official_bank_source${"itemId":"23c263bb-c558-5630-aee4-20636d07abe5","questionId":"ee54cf23-ed48-5197-9735-2e67c13ade98","sourceKey":"bank:LAG-BUA125:CST-049","payload":{"prompt":"A large supermarket chain buys rice in very large quantities and gets a big discount per bag from suppliers. This is an example of","options":["marketing (bulk-buying) economies of scale","external economies of scale","diseconomies of scale","risk-bearing economies of scale"],"correctOption":0,"section":"Cost Analysis: Short Run and Long Run","explanation":"Discounts from buying inputs in bulk are a purchasing or marketing economy of scale, which lowers average cost as the firm grows. Option D comes from spreading risk over many products or markets. Option B would come from growth of the whole industry, not from the firm's own size."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 391, $official_bank_source${"itemId":"e1ed192b-bbe9-5963-82f7-840d8e04bbad","questionId":"0aeb9c49-893b-5719-a60b-df4b8310f9bf","sourceKey":"bank:LAG-BUA125:CST-050","payload":{"prompt":"Many electronics firms cluster in one area of a city, so a pool of skilled technicians and specialist suppliers develops there and every firm's costs fall. This is best described as","options":["external economies of scale","internal economies of scale","the law of diminishing returns","internal diseconomies of scale"],"correctOption":0,"section":"Cost Analysis: Short Run and Long Run","explanation":"External economies arise from the growth or concentration of the whole industry, benefiting all firms in it whatever their own size. Option B comes from the growth of the individual firm itself. Option C is a short-run production idea, not a cost saving from industry growth."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 392, $official_bank_source${"itemId":"5e02a70e-0ec7-5395-b857-455f9329e0d3","questionId":"173b8c52-4370-5223-807e-afa5c5f6b418","sourceKey":"bank:LAG-BUA125:CST-051","payload":{"prompt":"A company grows so large that decisions pass through many layers of management, communication slows down, and long-run average cost begins to rise. This illustrates","options":["economies of scale","constant returns to scale","falling average fixed cost","diseconomies of scale"],"correctOption":3,"section":"Cost Analysis: Short Run and Long Run","explanation":"When a firm becomes too large to coordinate and control well, its long-run average cost rises, which is a diseconomy of scale. Option A is a fall in average cost from growth. Option B would mean LRAC stays the same as scale increases."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 393, $official_bank_source${"itemId":"a7509eaf-ffce-5936-aec8-8ae87e266241","questionId":"e4a11a39-3807-509a-a805-d30fea890664","sourceKey":"bank:LAG-BUA125:CST-052","payload":{"prompt":"The long-run average cost curve, which shows the lowest average cost of producing each output when all inputs can be varied, is also called the","options":["short-run average cost curve","marginal revenue curve","planning curve (envelope curve)","total fixed cost curve"],"correctOption":2,"section":"Cost Analysis: Short Run and Long Run","explanation":"The LRAC curve is called a planning or envelope curve because it wraps around the short-run average cost curves of all possible plant sizes and is used to choose the best plant. Option A applies to one fixed plant only. Option B relates to revenue, not cost."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 394, $official_bank_source${"itemId":"14520107-54fe-585b-9a09-fd49d271c5d8","questionId":"05768caa-4781-5f7a-a2d7-8140abd7e3aa","sourceKey":"bank:LAG-BUA125:CST-053","payload":{"prompt":"If a firm experiences constant returns to scale over a range of output, its long-run average cost curve over that range is","options":["upward sloping","vertical","horizontal","downward sloping"],"correctOption":2,"section":"Cost Analysis: Short Run and Long Run","explanation":"With constant returns to scale, output rises in the same proportion as inputs, so cost per unit stays the same and LRAC is flat. Option D shows economies of scale. Option A shows diseconomies of scale."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 395, $official_bank_source${"itemId":"0331151c-5adc-5b8a-a1ca-b16dcfbfe6d9","questionId":"fe29de7a-074a-5b86-9eff-bd9e00c29f9c","sourceKey":"bank:LAG-BUA125:CST-054","payload":{"prompt":"If the price of a variable input such as fuel rises, which cost curve does NOT shift?","options":["Marginal cost","Average variable cost","Average fixed cost","Average total cost"],"correctOption":2,"section":"Cost Analysis: Short Run and Long Run","explanation":"A rise in a variable input price raises variable cost per unit, so AVC, MC and ATC all shift up, but fixed cost per unit is unaffected. Options B, D and A all depend on variable cost and therefore shift upward."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 396, $official_bank_source${"itemId":"673e4697-8a29-5445-95d6-c9b8c34a50a6","questionId":"2e4a2e26-9c6a-57b3-94a6-db6f253aca23","sourceKey":"bank:LAG-BUA125:CST-055","payload":{"prompt":"At the break-even level of output, a firm's","options":["total revenue exactly equals its total cost, so profit is zero","marginal cost is at its minimum","total revenue is at its maximum","variable cost equals fixed cost"],"correctOption":0,"section":"Cost Analysis: Short Run and Long Run","explanation":"Break-even is where TR = TC, so the firm makes neither profit nor loss; equivalently, total contribution just covers fixed cost. Option C confuses break-even with revenue maximisation. Option D has no special meaning for profit."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 397, $official_bank_source${"itemId":"2645a94c-955f-5d61-81f2-c88adbb8281a","questionId":"61f8e63b-c17c-5d82-b181-7fa8fedb1239","sourceKey":"bank:LAG-BUA125:PQ-212","payload":{"prompt":"Income and population are two variables that can be used in ______ segmentation.","options":["lifestyle","behavioural","demographic","psychographic"],"correctOption":2,"section":"Market Segmentation","explanation":"Demographic segmentation divides a market using measurable population characteristics such as age, gender, income, family size and occupation. Options D and A group buyers by personality, values and lifestyle, while option B groups them by how they use or respond to a product."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 398, $official_bank_source${"itemId":"e338dd39-d9ed-54db-8e96-31a7e3f0c528","questionId":"7b6aad32-58a0-5663-b08b-022e0850a21b","sourceKey":"bank:LAG-BUA125:SEG-001","payload":{"prompt":"The process of dividing a total market into distinct groups of buyers who have different needs, characteristics or behaviours, and who might require separate products or marketing programmes, is called","options":["market penetration","market segmentation","mass marketing","market positioning"],"correctOption":1,"section":"Market Segmentation","explanation":"Market segmentation splits a broad market into smaller groups of buyers with similar needs or behaviour so that each can be served more precisely. Option D is about creating a distinct image in customers' minds after a target has been chosen. Option C is the opposite approach, treating the whole market as one."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 399, $official_bank_source${"itemId":"da6b3ce0-2b08-5580-815e-1e925b52fdf8","questionId":"f02bd6f9-dda3-582f-8d22-929cc72faa69","sourceKey":"bank:LAG-BUA125:SEG-002","payload":{"prompt":"A market segment is best described as","options":["a group of consumers who respond in a similar way to a given set of marketing efforts","a single customer who buys in very large quantities","the total number of firms selling in an industry","the share of industry sales held by the largest firm"],"correctOption":0,"section":"Market Segmentation","explanation":"A segment is a group of buyers who share similar needs or characteristics and so react in a similar way to the same marketing mix. Option C describes the supply side of an industry, not buyers. Option D is a market share measure."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 400, $official_bank_source${"itemId":"895a105f-7212-58c8-96ec-6e58bc551e31","questionId":"f4bbaaf0-1a30-59c1-9c6b-8488c5769e72","sourceKey":"bank:LAG-BUA125:SEG-003","payload":{"prompt":"Which of the following is NOT one of the major bases for segmenting consumer markets?","options":["Production capacity of the selling firm","Psychographic factors","Behavioural factors","Geographic factors"],"correctOption":0,"section":"Market Segmentation","explanation":"Consumer markets are segmented by characteristics of the buyers: geographic, demographic, psychographic and behavioural. The production capacity of the seller describes the firm, not its customers, so it is not a basis of consumer segmentation. Options D, B and C are all standard bases."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 401, $official_bank_source${"itemId":"ba5d1042-1e00-51aa-a68f-820e9c75e01a","questionId":"71d3e582-82fd-5d6f-ae1c-b90ab0404908","sourceKey":"bank:LAG-BUA125:SEG-004","payload":{"prompt":"A paint company sells different product ranges in the rainy south and the dry, hot north of Nigeria because of differences in climate. This is","options":["psychographic segmentation","geographic segmentation","demographic segmentation","behavioural segmentation"],"correctOption":1,"section":"Market Segmentation","explanation":"Dividing a market by location, region or climate is geographic segmentation. Option C uses variables such as age, gender and income. Option A uses lifestyle, personality and values, and option D uses how buyers use or respond to the product."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 402, $official_bank_source${"itemId":"3d999162-d334-5a3e-9b4f-a0f887b4eb84","questionId":"730da8be-c4d3-52db-8870-caf1050527ec","sourceKey":"bank:LAG-BUA125:SEG-005","payload":{"prompt":"A bank designs a special savings account for customers aged 18 to 25 who are in tertiary institutions. The bank is mainly using","options":["demographic segmentation","psychographic segmentation","geographic segmentation","behavioural segmentation"],"correctOption":0,"section":"Market Segmentation","explanation":"Age and occupation (student) are demographic variables, so the bank is segmenting demographically. Option C would divide by location. Option D would divide by usage, loyalty or benefits sought, and option B by lifestyle or personality."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 403, $official_bank_source${"itemId":"9b7595d1-28b1-5841-95f9-b406f16e900d","questionId":"acde9202-0e98-5f32-b5d1-a5bba0cb3a69","sourceKey":"bank:LAG-BUA125:SEG-006","payload":{"prompt":"Which of the following groups of variables are all demographic?","options":["Age, gender, income and family size","Usage rate, loyalty status and benefits sought","Lifestyle, personality and values","Region, city size and climate"],"correctOption":0,"section":"Market Segmentation","explanation":"Demographic segmentation uses measurable population characteristics such as age, gender, income, family size, education and occupation. Option D lists geographic variables. Option C lists psychographic variables, and option B lists behavioural variables."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 404, $official_bank_source${"itemId":"9ae65949-b34e-5fbf-bbc0-8bb388c6f9c5","questionId":"8f75cbac-0058-579b-a291-7de6344165c8","sourceKey":"bank:LAG-BUA125:SEG-007","payload":{"prompt":"Dividing buyers into groups based on their lifestyle, personality characteristics or values is called","options":["demographic segmentation","psychographic segmentation","geographic segmentation","behavioural segmentation"],"correctOption":1,"section":"Market Segmentation","explanation":"Psychographic segmentation groups people by how they live and think, such as lifestyle, personality and values. Option A uses measurable characteristics such as age and income. Option D uses buyers' knowledge of, attitude to, use of or response to a product."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 405, $official_bank_source${"itemId":"472c5c6b-93ef-547a-b0d9-da05d000e1e2","questionId":"9c0c0fb5-a487-5ef1-943b-c50156d99bae","sourceKey":"bank:LAG-BUA125:SEG-008","payload":{"prompt":"A gym in Lekki targets young professionals who see fitness, healthy eating and an active social life as central to the way they live. This is mainly","options":["psychographic segmentation","behavioural segmentation by usage rate","demographic segmentation","geographic segmentation"],"correctOption":0,"section":"Market Segmentation","explanation":"The gym is grouping customers by lifestyle and values, which is psychographic segmentation. Option D would be based only on location. Option C would be based on facts such as age or income alone, while the central idea here is the way people choose to live."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 406, $official_bank_source${"itemId":"6075b900-37a1-5c98-bcb1-44a5181ffb3b","questionId":"bfe69ceb-2aa5-5b4d-b2e8-f8496e13e746","sourceKey":"bank:LAG-BUA125:SEG-009","payload":{"prompt":"Dividing a market into groups based on consumers' knowledge, attitudes, uses or responses to a product is called","options":["psychographic segmentation","geographic segmentation","demographic segmentation","behavioural segmentation"],"correctOption":3,"section":"Market Segmentation","explanation":"Behavioural segmentation groups buyers by how they actually relate to the product: occasions, benefits sought, user status, usage rate and loyalty. Option A groups people by lifestyle and personality rather than their behaviour towards the product. Options C and B use population and location data."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 407, $official_bank_source${"itemId":"2163fb09-d317-5259-be20-6e10027bda22","questionId":"b5eead26-43ad-5fbc-8d9a-ee2b57f684a5","sourceKey":"bank:LAG-BUA125:SEG-010","payload":{"prompt":"A telecom operator offers a special data bundle to customers who use more than 20GB a month, and a different plan to light users. Which segmentation variable is being used?","options":["Usage rate (behavioural)","Personality (psychographic)","Region (geographic)","Income (demographic)"],"correctOption":0,"section":"Market Segmentation","explanation":"Grouping customers into heavy, medium and light users is segmentation by usage rate, a behavioural variable. Option D would group by how much customers earn, not how much they use. Option C would be based on location."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 408, $official_bank_source${"itemId":"29c58c03-25a1-596e-b944-2107c74ef3b0","questionId":"457686d1-804c-54f1-9277-4f285163debd","sourceKey":"bank:LAG-BUA125:SEG-011","payload":{"prompt":"A biscuit company produces special gift packs sold only during Christmas and Sallah festivities. Which basis of segmentation does this mainly reflect?","options":["Geographic segmentation by region","Demographic segmentation by religion","Behavioural segmentation by occasion","Psychographic segmentation by personality"],"correctOption":2,"section":"Market Segmentation","explanation":"Grouping buyers by the occasion on which they buy or use a product, such as festive seasons, is occasion segmentation, a behavioural basis. Option B is tempting, but the packs are aimed at anyone buying for the festive occasion, not at people of one faith. Option A would require different offers for different places."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 409, $official_bank_source${"itemId":"bc5a5b7e-207e-5c68-80d4-6280a1ea88ba","questionId":"e72180a0-9198-5c23-a25a-2654408fd19b","sourceKey":"bank:LAG-BUA125:SEG-012","payload":{"prompt":"A toothpaste maker offers one brand for customers who want whiter teeth, another for those who want fresh breath and a third for those with sensitive teeth. This is","options":["loyalty-status segmentation","demographic segmentation","benefit segmentation","geographic segmentation"],"correctOption":2,"section":"Market Segmentation","explanation":"Benefit segmentation divides the market by the main benefit buyers seek from the product, which is a form of behavioural segmentation. Option A would group buyers by how loyal they are to a brand. Options D and B group buyers by location or population characteristics, not by what they want from the product."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 410, $official_bank_source${"itemId":"74877aae-7b45-53a3-a3ff-22d30eb16443","questionId":"0239e265-c6f7-5e4f-b833-d55d85e8a97d","sourceKey":"bank:LAG-BUA125:SEG-013","payload":{"prompt":"An airline gives extra rewards to passengers who fly with it repeatedly and never switch to rival airlines. The airline is segmenting by","options":["life-cycle stage","loyalty status","user status","geographic location"],"correctOption":1,"section":"Market Segmentation","explanation":"Grouping customers by how loyal they are to a brand is loyalty-status segmentation, a behavioural basis. Option C groups people as non-users, first-time users or regular users, not by their faithfulness to one brand. Option A is a demographic basis linked to age and family situation."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 411, $official_bank_source${"itemId":"47503d08-f14c-570f-b317-33d482916eeb","questionId":"ff9c171a-8f6f-5c46-9de0-628764435244","sourceKey":"bank:LAG-BUA125:SEG-014","payload":{"prompt":"Which of the following is NOT a behavioural segmentation variable?","options":["Purchase occasion","User status","Family size","Benefits sought"],"correctOption":2,"section":"Market Segmentation","explanation":"Family size is a demographic variable because it describes the household, not how it behaves towards the product. Options D, B and A all describe buyers' behaviour or response to a product, so they are behavioural variables."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 412, $official_bank_source${"itemId":"67bb19a4-d83a-51f6-85b8-1cad5412415d","questionId":"0407a9ba-b8ad-5d5c-a237-4da69161abae","sourceKey":"bank:LAG-BUA125:SEG-015","payload":{"prompt":"Which of the following is NOT a requirement for an effective market segment?","options":["It must contain every consumer in the market","It must be substantial","It must be measurable","It must be accessible"],"correctOption":0,"section":"Market Segmentation","explanation":"Useful segments must be measurable, accessible, substantial, differentiable and actionable. A segment that contains every consumer is not a segment at all, but the whole market. Options C, D and B are standard requirements."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 413, $official_bank_source${"itemId":"9ba22ec3-1252-550f-88ed-ee7a7de59c0b","questionId":"7d49822d-26d0-57ef-941d-a476b572e278","sourceKey":"bank:LAG-BUA125:SEG-016","payload":{"prompt":"A market segment is said to be measurable when","options":["it can be reached and served effectively","it responds differently from other segments","it is large enough to be profitable","its size, purchasing power and profile can be estimated"],"correctOption":3,"section":"Market Segmentation","explanation":"Measurability means the firm can estimate how big the segment is and how much it can buy. Option A describes accessibility. Option C describes substantiality, and option B describes differentiability."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 414, $official_bank_source${"itemId":"359ffda9-249a-52ba-9baa-1161ac9796fc","questionId":"a4b05983-c1b4-5de0-b1f2-225a9247763a","sourceKey":"bank:LAG-BUA125:SEG-017","payload":{"prompt":"A market segment is said to be accessible when","options":["it has no competitors at all","its size can be estimated","the firm can effectively reach and serve it","it is the largest segment in the market"],"correctOption":2,"section":"Market Segmentation","explanation":"Accessibility means the firm can reach the segment through suitable channels and media and can deliver to it. Option B is measurability. Option A is not a requirement; segments often have competitors."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 415, $official_bank_source${"itemId":"a72256e0-246c-5c15-b6f0-a6f54b4580d4","questionId":"87616250-6c9e-50fb-95ab-bcaf4380fc07","sourceKey":"bank:LAG-BUA125:SEG-018","payload":{"prompt":"A firm finds a group of customers with clear needs, but the group has only a few dozen buyers and would not cover the cost of a separate marketing programme. Which requirement of an effective segment does this group fail?","options":["Measurable","Accessible","Substantial","Differentiable"],"correctOption":2,"section":"Market Segmentation","explanation":"A substantial segment is large or profitable enough to be worth serving with its own marketing programme, and a few dozen buyers fail that test. Option A is not the problem, since the group's size is known. Option B is about reaching the buyers, which is not in doubt here."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 416, $official_bank_source${"itemId":"a0fb24fe-c6a7-5a47-b734-bdc7ecaf82af","questionId":"f759eea8-5833-5e33-9a60-ec13b523b951","sourceKey":"bank:LAG-BUA125:SEG-019","payload":{"prompt":"A segment is said to be differentiable when","options":["it is conceptually distinct and responds differently to marketing mix elements than other segments","its members all live in the same area","it is large enough to be profitable","the firm can reach it through its usual channels"],"correctOption":0,"section":"Market Segmentation","explanation":"Differentiable segments are distinct from one another, so a change in the marketing mix produces a different response in each. If two groups respond in the same way, they are not really separate segments. Option C is substantiality and option D is accessibility."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 417, $official_bank_source${"itemId":"24c5c02d-bbfa-57fa-bddd-38f416c94921","questionId":"5b86f13c-fab1-5251-8e50-837aed5e7948","sourceKey":"bank:LAG-BUA125:SEG-020","payload":{"prompt":"A segment is said to be actionable when","options":["it is large enough to be profitable","it is distinct from other segments","the firm can design effective programmes to attract and serve it","it can be measured accurately"],"correctOption":2,"section":"Market Segmentation","explanation":"Actionability means the firm has the resources and ability to build a marketing programme that attracts and serves the segment. A small firm may see several attractive segments but lack the staff or money to act on all of them. Options D, B and A describe measurability, differentiability and substantiality."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 418, $official_bank_source${"itemId":"cb75d104-e3ef-5fe8-a513-59439aa19fea","questionId":"98884d4c-1c11-5686-8beb-f4d2790a42d5","sourceKey":"bank:LAG-BUA125:SEG-021","payload":{"prompt":"Evaluating the attractiveness of each market segment and selecting one or more segments to enter is called","options":["product differentiation","market targeting","market positioning","market segmentation"],"correctOption":1,"section":"Market Segmentation","explanation":"Targeting comes after segmentation: the firm compares segments and chooses which to serve. Option D is the earlier step of dividing the market. Option C is the later step of creating a clear place for the product in target customers' minds."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 419, $official_bank_source${"itemId":"0a7f94cd-2bad-59b0-94af-311fb8baeddb","questionId":"69cb157a-2d62-559d-9799-ce3a4d4f852b","sourceKey":"bank:LAG-BUA125:SEG-022","payload":{"prompt":"Which of the following shows the correct order of the main steps in target marketing?","options":["Positioning, segmentation, targeting","Segmentation, targeting, positioning","Segmentation, positioning, targeting","Targeting, positioning, segmentation"],"correctOption":1,"section":"Market Segmentation","explanation":"A firm first divides the market into segments, then chooses target segments, and then positions its offer in the minds of the chosen buyers. Option C is tempting, but you cannot position a product before deciding whom it is for. Options A and D start with steps that depend on segmentation."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 420, $official_bank_source${"itemId":"505bb6f2-4ff2-5b30-888b-9c8f40832231","questionId":"e62be083-44b1-58b7-8f1e-ff573642c149","sourceKey":"bank:LAG-BUA125:SEG-023","payload":{"prompt":"A firm that ignores segment differences and targets the whole market with one offer is using","options":["micromarketing","differentiated marketing","undifferentiated (mass) marketing","concentrated marketing"],"correctOption":2,"section":"Market Segmentation","explanation":"Undifferentiated or mass marketing treats the market as one group with common needs and uses a single marketing mix. Option B uses separate offers for several segments. Option D focuses on one segment or niche, and option A tailors offers to local groups or individuals."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 421, $official_bank_source${"itemId":"c2e11b14-1836-5e9c-b44d-5363f098b5bd","questionId":"e6a09aef-a616-552d-9f6d-1411634ef881","sourceKey":"bank:LAG-BUA125:SEG-024","payload":{"prompt":"A beverage company sells a low-priced sachet drink for low-income buyers, a premium bottled range for upper-income buyers and a sugar-free version for health-conscious buyers, each with its own advertising. This targeting strategy is","options":["mass marketing","differentiated (segmented) marketing","undifferentiated marketing","concentrated marketing"],"correctOption":1,"section":"Market Segmentation","explanation":"Serving several segments with a separate product and marketing programme for each is differentiated marketing. Options C and A use one offer for the whole market. Option D focuses on just one segment."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 422, $official_bank_source${"itemId":"b6ce0863-0338-511e-913d-d7da2400748a","questionId":"8f8a7164-2862-56bc-8846-fbc0d3d57bd2","sourceKey":"bank:LAG-BUA125:SEG-025","payload":{"prompt":"When a firm with limited resources goes after a large share of one small segment or niche, it is using","options":["differentiated marketing","mass customisation","undifferentiated marketing","concentrated (niche) marketing"],"correctOption":3,"section":"Market Segmentation","explanation":"Concentrated or niche marketing focuses the firm's effort on one segment, allowing it to know that group well and serve it efficiently. Option A serves several segments at once. Option C serves the whole market with one offer."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 423, $official_bank_source${"itemId":"ee5eb1b2-8a19-52b1-891f-625eb6a64db3","questionId":"9bed22c0-f7a8-58f4-a69a-4b3a60905362","sourceKey":"bank:LAG-BUA125:SEG-026","payload":{"prompt":"The main risk of a concentrated (niche) targeting strategy is that","options":["the firm cannot learn about its customers' needs","its marketing costs are always higher than those of mass marketing","the firm depends heavily on one segment, so a change in that segment can hurt it badly","the firm must design many different products at the same time"],"correctOption":2,"section":"Market Segmentation","explanation":"Putting all effort into one segment means that a fall in demand or a strong new rival in that segment can seriously damage the firm. Option D is a feature of differentiated marketing. Option A is wrong because a niche firm usually knows its customers very well."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 424, $official_bank_source${"itemId":"b0f03db4-d01d-5e0b-af44-37fabaa15964","questionId":"60be2054-72e1-52a7-813c-9105eea9298b","sourceKey":"bank:LAG-BUA125:SEG-027","payload":{"prompt":"Compared with undifferentiated marketing, a key disadvantage of differentiated marketing is that it","options":["raises the costs of product development, production and promotion","cannot increase total sales","ignores differences in customer needs","serves only one small niche"],"correctOption":0,"section":"Market Segmentation","explanation":"Running separate products and marketing programmes for several segments usually increases costs, so the firm must check that the extra sales justify them. Option C describes undifferentiated marketing. Option D describes concentrated marketing."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 425, $official_bank_source${"itemId":"458a8e62-ddb7-5f7e-b1e7-315ac499f8e9","questionId":"c02282ac-e651-52c3-9fb9-f5801b291fa6","sourceKey":"bank:LAG-BUA125:SEG-028","payload":{"prompt":"Arranging for a product to occupy a clear, distinctive and desirable place relative to competing products in the minds of target consumers is called","options":["market research","targeting","segmentation","positioning"],"correctOption":3,"section":"Market Segmentation","explanation":"Positioning is about the image and value the target customers associate with a brand compared with rivals. Option C divides the market into groups. Option B selects which groups to serve."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 426, $official_bank_source${"itemId":"de03cb20-6018-5a17-bd4c-92d1348efcba","questionId":"90078f56-3340-5e33-ac1e-324059b81a78","sourceKey":"bank:LAG-BUA125:SEG-029","payload":{"prompt":"A new fast-food chain advertises itself as 'the fastest affordable meal for busy office workers in Lagos'. This statement is mainly an example of","options":["undifferentiated mass marketing","segmenting the market by geography only","measuring the size of a segment","positioning the brand in the minds of its target market"],"correctOption":3,"section":"Market Segmentation","explanation":"The slogan tells a chosen target group (busy office workers) what distinct value the brand offers compared with rivals, which is positioning. Option A is wrong because the firm has clearly picked a target group. Option B is only partly present; the main purpose of the statement is to set the brand's place in customers' minds."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 427, $official_bank_source${"itemId":"1ba388d9-0a91-568b-bd80-8f8c04be5094","questionId":"a57c5a1a-fef6-5b61-b577-a274c2a873ad","sourceKey":"bank:LAG-BUA125:SEG-030","payload":{"prompt":"Which of the following is a major benefit of market segmentation to a firm?","options":["It removes the need for any market research","It allows the firm to charge the same price to every buyer","It guarantees that the firm will have no competitors","It helps the firm match its products and marketing mix more closely to customers' needs"],"correctOption":3,"section":"Market Segmentation","explanation":"By understanding the needs of each group, the firm can design products, prices, distribution and promotion that fit those needs better, which can raise sales and loyalty. Option A is wrong because segmentation depends on research. Option C is wrong because rivals can still target the same segment."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 428, $official_bank_source${"itemId":"ecb8fc0e-8c87-5aa7-9fab-6044f415f7a9","questionId":"d13c07b1-dbce-573c-af2a-c4d31bd3a15e","sourceKey":"bank:LAG-BUA125:SEG-031","payload":{"prompt":"From a managerial economics point of view, market segmentation helps a firm to use its resources efficiently mainly because","options":["it eliminates fixed costs of production","it allows the firm to spread its budget equally over all consumers","it can concentrate spending on the segments that offer the best returns","it makes demand perfectly elastic in every segment"],"correctOption":2,"section":"Market Segmentation","explanation":"Segmentation shows where demand, purchasing power and profit potential are greatest, so scarce marketing money goes where it earns most. Option B is the opposite of a targeted approach. Option A is wrong because segmentation does not affect the firm's fixed costs."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 429, $official_bank_source${"itemId":"a4b1e1bb-1171-56be-ad88-e9035f15ae4b","questionId":"ecb9d03b-5421-5ad4-98ed-da19819f839b","sourceKey":"bank:LAG-BUA125:SEG-032","payload":{"prompt":"A cinema charges lower ticket prices to students than to working adults. If the firm separates the two groups and wants to maximise profit, it should charge the higher price to the group whose demand is","options":["perfectly elastic","unrelated to price","more price elastic","less price elastic"],"correctOption":3,"section":"Market Segmentation","explanation":"Charging different prices to segments (price discrimination) raises profit when the higher price goes to the group less sensitive to price, since they cut purchases less when price rises. Students usually have more elastic demand, so they get the discount. Option C reverses the rule; raising price for an elastic group cuts sales sharply."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 430, $official_bank_source${"itemId":"e9afcd62-196e-5cc1-839d-5266f35dee93","questionId":"ac5c7d16-b4ce-5af7-b2ce-c32a5f4f5d9c","sourceKey":"bank:LAG-BUA125:SEG-033","payload":{"prompt":"Which of the following is NOT usually a benefit of market segmentation?","options":["It helps the firm compete more effectively in chosen segments","It always lowers the firm's total marketing costs","It allows better design of the marketing mix","It helps the firm spot new market opportunities"],"correctOption":1,"section":"Market Segmentation","explanation":"Segmentation often increases some costs, because serving different groups needs different products and campaigns, so it does not always lower total marketing costs. Options D, A and C are genuine benefits: spotting unmet needs, focusing competitive effort and fitting the mix to buyers."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 431, $official_bank_source${"itemId":"4e756e17-4bec-53be-9986-3b026373a72a","questionId":"87d3d6bf-a15d-5621-b908-882c99ab5fa9","sourceKey":"bank:LAG-BUA125:SEG-034","payload":{"prompt":"A campus food delivery start-up estimates that 48,000 students are on campus, that 35% of them order food online, and that each such student spends N2,500 a month on deliveries. What is the estimated monthly value of this segment?","options":["N120,000,000","N504,000,000","N78,000,000","N42,000,000"],"correctOption":3,"section":"Market Segmentation","explanation":"Segment value = number of buyers x share in the segment x spending per buyer = 48,000 x 0.35 x 2,500 = N42,000,000 a month. Option A forgets that only 35% of students are in the segment. Option C uses the 65% who do not order online, and option B is a yearly figure, not a monthly one."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 432, $official_bank_source${"itemId":"67e601b3-84ac-560e-8f59-5b85c563c55f","questionId":"a638a40d-6432-5afa-8395-c027a23c3dec","sourceKey":"bank:LAG-BUA125:SEG-035","payload":{"prompt":"A town has 120,000 households. 40% have monthly incomes above N300,000, and a survey shows 25% of those households want a home-cleaning service. How many households are in this target segment?","options":["30,000 households","12,000 households","48,000 households","78,000 households"],"correctOption":1,"section":"Market Segmentation","explanation":"The segment is households that meet both conditions: 120,000 x 0.40 x 0.25 = 12,000 households. Option C stops at the income filter and ignores interest in the service. Option D adds the percentages instead of applying one after the other."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 433, $official_bank_source${"itemId":"37ff8995-d100-56cd-b2fd-e9340888ffd8","questionId":"da25169d-2a7e-5a8d-874e-ca56559243ad","sourceKey":"bank:LAG-BUA125:PQ-173","payload":{"prompt":"Limited liability is a key benefit enjoyed by the owners of:","options":["sole proprietorships","all of these types of business","limited liability companies","ordinary (general) partnerships"],"correctOption":2,"section":"Theory of Firms","explanation":"In a limited liability company, shareholders can lose only what they invested, because the company is a separate legal person responsible for its own debts. Owners in options A and D have unlimited liability, so their personal assets can be used to pay business debts, which also rules out option B."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 434, $official_bank_source${"itemId":"634ba99f-7250-5601-a108-6f91b5ac9a02","questionId":"d2576bc5-49a5-524b-be0d-98fcd7998ac7","sourceKey":"bank:LAG-BUA125:FRM-001","payload":{"prompt":"A business that is owned, financed and controlled by one person, who takes all the profit and bears all the risk, is a","options":["public corporation","private limited company","sole proprietorship","partnership"],"correctOption":2,"section":"Theory of Firms","explanation":"A sole proprietorship has a single owner who provides the capital, makes the decisions, keeps all the profit and bears all the losses. Option D has two or more owners. Options B and A are owned by shareholders and by government respectively."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 435, $official_bank_source${"itemId":"cece9006-1da4-5d96-a482-1b62e872c8fd","questionId":"8dbad58d-9119-5b84-8b42-6594c205be35","sourceKey":"bank:LAG-BUA125:FRM-002","payload":{"prompt":"Which of the following is a typical advantage of a sole proprietorship?","options":["Limited liability of the owner","Easy access to large amounts of capital","Continuity of the business after the owner's death","Quick decision-making because the owner does not need to consult anyone"],"correctOption":3,"section":"Theory of Firms","explanation":"The sole trader makes decisions alone, so the business can respond quickly to customers and changes in the market. Option A is wrong because the sole trader has unlimited liability. Options B and C are actually weaknesses of this form: capital is limited and the business may end with the owner."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 436, $official_bank_source${"itemId":"1aa1dfc4-ba9f-581c-9b14-195ef551496c","questionId":"aa72f462-a490-52be-aeb5-590a3a16c72d","sourceKey":"bank:LAG-BUA125:FRM-003","payload":{"prompt":"Which of the following is NOT a disadvantage of a sole proprietorship?","options":["The owner has unlimited liability","Capital for expansion is limited","The owner keeps all the profits","The business may lack continuity"],"correctOption":2,"section":"Theory of Firms","explanation":"Keeping all the profit is an advantage, since the owner does not share it with anyone. Options A, D and B are well-known drawbacks: personal assets can be lost, the business may end with the owner's death or illness, and one person can raise only limited capital."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 437, $official_bank_source${"itemId":"25aa7e40-9979-5864-854f-a2702e14ed7a","questionId":"d457b968-c5c3-5c65-9c6a-e5dd2fe6f038","sourceKey":"bank:LAG-BUA125:FRM-004","payload":{"prompt":"Mama Bisi runs a provision shop alone. The shop fails and owes suppliers N2 million, which is more than the shop's assets are worth. Creditors take her personal car to recover the debt. This shows that a sole proprietor has","options":["perpetual succession","unlimited liability","limited liability","a separate legal personality"],"correctOption":1,"section":"Theory of Firms","explanation":"Unlimited liability means the owner is personally responsible for all business debts, so private assets can be taken to pay them. Option C would protect her personal assets. Options A and D are features of a registered company, which exists separately from its owners."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 438, $official_bank_source${"itemId":"ee0672aa-73f7-52b5-8b95-e46b2caf526d","questionId":"d27e0670-4b9a-5c99-8144-65b22ab6fcc4","sourceKey":"bank:LAG-BUA125:FRM-005","payload":{"prompt":"The most common way for a sole proprietor in Nigeria to raise starting capital is","options":["personal savings and loans from family and friends","grants voted by the National Assembly","selling debentures on the stock exchange","issuing shares to the general public"],"correctOption":0,"section":"Theory of Firms","explanation":"A one-person business usually starts with the owner's savings, help from relatives and friends, and later small bank loans or trade credit. Options D and C are open only to public limited companies. Option B applies to government-owned enterprises."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 439, $official_bank_source${"itemId":"109e340b-5c84-5937-8080-fa87837d76b1","questionId":"d81358c3-0859-5ade-89aa-43618e98a3a6","sourceKey":"bank:LAG-BUA125:FRM-006","payload":{"prompt":"One reason the sole proprietorship is the most common form of business in Nigeria is that it","options":["can sell its shares on the stock exchange","must have at least two directors","gives the owner limited liability","is easy and cheap to set up, with few legal formalities"],"correctOption":3,"section":"Theory of Firms","explanation":"Starting a sole proprietorship needs little capital and few formalities, which suits petty trading and small services. Option C is wrong because the owner has unlimited liability. Options A and B describe companies, not one-person businesses."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 440, $official_bank_source${"itemId":"044a4976-755e-580a-a8de-ffd772e1af2a","questionId":"b73a99cc-3247-5b1f-8ffa-b9b9d63dc6aa","sourceKey":"bank:LAG-BUA125:FRM-007","payload":{"prompt":"The relationship between persons carrying on a business in common with a view of profit, who share capital, management and profits, is called","options":["a sole proprietorship","a partnership","a cooperative society","a public corporation"],"correctOption":1,"section":"Theory of Firms","explanation":"A partnership is formed when two or more people agree to run a business together and share its profits. Option A has only one owner. Option D is owned by government, and option C is owned by members mainly to serve their own needs rather than for profit."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 441, $official_bank_source${"itemId":"af948ab2-4eca-57a1-8039-9b4ae7e738b9","questionId":"192ef601-bd95-5140-9032-dcb8447c01b7","sourceKey":"bank:LAG-BUA125:FRM-008","payload":{"prompt":"A deed of partnership is","options":["a share certificate given to each partner","the written agreement that sets out the rights, duties and profit-sharing arrangements of the partners","a loan document issued to partnership creditors","the certificate that makes a partnership a separate legal person"],"correctOption":1,"section":"Theory of Firms","explanation":"The partnership deed records matters such as capital contributed, profit-sharing ratio, duties of partners and how disputes or admission of new partners are handled. Option D is wrong because an ordinary partnership does not become a separate legal person. Option A describes companies, which issue shares."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 442, $official_bank_source${"itemId":"032cdc7c-13a2-5dcf-90fc-6e6eff98c55e","questionId":"986c4bf3-dc34-5bd5-a581-007d06750fbd","sourceKey":"bank:LAG-BUA125:FRM-009","payload":{"prompt":"Chidi contributes N5 million to a partnership business but takes no part in running it, while his partners manage it daily. Chidi is best described as a","options":["sleeping (dormant) partner","minor partner","managing (active) partner","nominal partner"],"correctOption":0,"section":"Theory of Firms","explanation":"A sleeping or dormant partner contributes capital and shares profit but does not take part in managing the business. Option D lends only their name and reputation, usually without contributing capital. Option C is involved in day-to-day management."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 443, $official_bank_source${"itemId":"eb4a8ed5-639f-5551-8859-e867ee8a531e","questionId":"916cc792-db96-55ba-b199-5f15292e05fe","sourceKey":"bank:LAG-BUA125:FRM-010","payload":{"prompt":"A partner who allows his name to be used by the firm to give it credibility, but who contributes no capital and takes no part in management, is a","options":["sleeping partner","limited partner","general partner","nominal partner"],"correctOption":3,"section":"Theory of Firms","explanation":"A nominal partner lends only their name and reputation to the firm. Option A contributes capital but does not manage. Option B contributes capital with liability limited to that capital."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 444, $official_bank_source${"itemId":"9c268219-5df3-5526-a35c-a1ba84f21cfa","questionId":"3bea7ba8-7fe0-5ec3-8b4c-0f64041bf8dd","sourceKey":"bank:LAG-BUA125:FRM-011","payload":{"prompt":"In a limited partnership, a limited partner","options":["can never share in the profits of the firm","is liable only up to the capital contributed and does not take part in managing the business","must manage the business on behalf of other partners","is personally liable for all debts of the firm"],"correctOption":1,"section":"Theory of Firms","explanation":"A limited partner's risk is limited to the capital put in, and in return they do not take part in management. Option D describes a general partner. Option A is wrong because limited partners do share profits."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 445, $official_bank_source${"itemId":"d0f0dd0c-6c71-5cc1-a845-ead25f98e04b","questionId":"acffeb9a-8b43-5bb4-8bac-c0a3588b2d7a","sourceKey":"bank:LAG-BUA125:FRM-012","payload":{"prompt":"In an ordinary (general) partnership, the liability of the partners for the debts of the firm is","options":["borne only by the most senior partner","limited to the value of their shares","unlimited, so partners' private assets can be used to pay the firm's debts","limited to the amount of their capital contributions"],"correctOption":2,"section":"Theory of Firms","explanation":"General partners are jointly liable for the firm's debts without limit, just like a sole proprietor. Options D and B describe limited partners and company shareholders. Option A is wrong because liability is shared by all general partners."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 446, $official_bank_source${"itemId":"5d69fb33-a666-5ae3-be3f-01f1ec4199e7","questionId":"51a95e2f-1bb9-5f90-80d2-207345c48239","sourceKey":"bank:LAG-BUA125:FRM-013","payload":{"prompt":"Which of the following is NOT an advantage of a partnership over a sole proprietorship?","options":["More capital can be raised from several owners","Each partner can be bound by the actions of the other partners","Partners can share skills and specialise","Losses and responsibilities are shared"],"correctOption":1,"section":"Theory of Firms","explanation":"The fact that one partner's business actions bind all the others is a risk, not an advantage, and it can lead to losses or disputes. Options A, C and D are genuine gains from having more than one owner."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 447, $official_bank_source${"itemId":"b1cb8d36-4cab-5d8c-b869-19d98c143d95","questionId":"86dab9d8-3d87-55c2-bdf9-01bce7e7e49f","sourceKey":"bank:LAG-BUA125:FRM-014","payload":{"prompt":"Three friends run a law firm as a partnership without any special continuation clause. One of them dies. In general, the partnership is","options":["taken over by the government","converted automatically into a public limited company","unaffected, because it has perpetual succession","dissolved, though the remaining partners may form a new one"],"correctOption":3,"section":"Theory of Firms","explanation":"An ordinary partnership lacks continuity: the death, bankruptcy or withdrawal of a partner generally ends the existing agreement. Option C describes a registered company, which continues whatever happens to its members. Options B and A have no basis in law."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 448, $official_bank_source${"itemId":"d694c153-7a51-5670-835e-81fefd4fdb4f","questionId":"882710f8-ba73-5985-bc5f-873796ddf322","sourceKey":"bank:LAG-BUA125:FRM-015","payload":{"prompt":"The right of a registered company to continue in existence even when its shareholders die or sell their shares is called","options":["limited liability","price discrimination","unlimited liability","perpetual succession"],"correctOption":3,"section":"Theory of Firms","explanation":"Perpetual succession means the company's life does not depend on its members, because it exists as a separate legal person. Option A concerns how much shareholders can lose, not how long the company lasts. Option C is a feature of sole traders and general partners."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 449, $official_bank_source${"itemId":"487ec037-20fb-564d-86f4-d05e37e6b2ee","questionId":"06e2c0c5-5534-556f-b3cc-ea954b8f9383","sourceKey":"bank:LAG-BUA125:FRM-016","payload":{"prompt":"The phrase 'a company is a separate legal entity' means that","options":["the owners are personally responsible for all company debts","the company is owned and controlled by the government","the company can own property, sue and be sued in its own name, apart from its owners","the company can only be formed by one person"],"correctOption":2,"section":"Theory of Firms","explanation":"Once registered, a company is a legal person distinct from its shareholders, so it holds assets, enters contracts and goes to court in its own name. Option B describes a public enterprise. Option A describes unlimited liability, which is the opposite of the protection a company gives."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 450, $official_bank_source${"itemId":"8c514ef4-ae88-5b82-8a3a-249492f69351","questionId":"d15cdf5c-1c6a-56f2-b715-6ea0377c45df","sourceKey":"bank:LAG-BUA125:FRM-017","payload":{"prompt":"Ade owns 10,000 fully paid shares in a limited company that goes into liquidation owing large debts. What is the most Ade can lose?","options":["Nothing at all, because shares are always refunded","All his personal assets","Twice the value of his shares","The amount he paid for his shares"],"correctOption":3,"section":"Theory of Firms","explanation":"Shareholders in a limited liability company can lose at most what they invested in (or still owe on) their shares; their private property is protected. Option B describes unlimited liability. Option A is wrong because shares can become worthless when a company fails."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 451, $official_bank_source${"itemId":"2385941e-a208-5396-9af1-a238bbe75c50","questionId":"b57a8e4c-4b9b-5faf-8cee-93fb5728cd81","sourceKey":"bank:LAG-BUA125:FRM-018","payload":{"prompt":"Which of the following is the key difference between a private limited company (Ltd) and a public limited company (Plc)?","options":["A Plc has no separate legal personality, while an Ltd does","Shareholders of an Ltd have unlimited liability, while those of a Plc have limited liability","A Plc can invite the general public to buy its shares, while an Ltd cannot","An Ltd is owned by government, while a Plc is owned by individuals"],"correctOption":2,"section":"Theory of Firms","explanation":"The main distinction is that a public company may offer its shares to the public and have them traded on the stock exchange, while a private company restricts the transfer of its shares and cannot invite the public to subscribe. Option B is wrong because both have limited liability. Option A is wrong because both are separate legal entities."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 452, $official_bank_source${"itemId":"87f3c408-c256-52f4-ba03-4188c101bec0","questionId":"ef65c24b-15ee-544c-a624-2a603d68f45e","sourceKey":"bank:LAG-BUA125:FRM-019","payload":{"prompt":"Which of the following is NOT a feature of a private limited company?","options":["Its shareholders have limited liability","It restricts the right to transfer its shares","Its shares are freely sold to the public on the stock exchange","It has a separate legal identity"],"correctOption":2,"section":"Theory of Firms","explanation":"A private company may not invite the public to buy its shares, so they are not traded on the stock exchange. Options A, D and B are all features of a private limited company."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 453, $official_bank_source${"itemId":"ba7bbe63-50b3-5a83-9e25-3c1137f6f943","questionId":"886d9357-bc63-5c27-9ee3-e317f55c2d22","sourceKey":"bank:LAG-BUA125:FRM-020","payload":{"prompt":"Which of the following is a major advantage of a public limited company?","options":["It can be formed quickly with very few legal formalities","It can raise very large amounts of capital from the public","Its affairs can be kept completely secret","The owners always manage the business directly"],"correctOption":1,"section":"Theory of Firms","explanation":"Selling shares and debentures to the public lets a Plc raise far more capital than a sole trader, partnership or private company. Option A is wrong because forming a public company involves many formalities. Option C is wrong because a Plc must disclose a great deal of information, and option D because ownership and management are often separate."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 454, $official_bank_source${"itemId":"63734cab-4b06-510f-9d31-8e1f07ddb14f","questionId":"08eee813-07b3-5caa-9361-5bae0fff628a","sourceKey":"bank:LAG-BUA125:FRM-021","payload":{"prompt":"Which of the following is NOT a common disadvantage of a public limited company?","options":["Shareholders have unlimited liability for its debts","It must disclose much of its financial information to the public","Ownership is separated from control","Formation is costly and involves many legal requirements"],"correctOption":0,"section":"Theory of Firms","explanation":"Shareholders of a Plc have limited liability, so option A is not a disadvantage of this form at all. Options C, D and B are real drawbacks: managers may pursue their own aims, formation is expensive, and much of its information must be made public."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 455, $official_bank_source${"itemId":"91c57439-fc7f-5f60-8c0b-a9c285b204f9","questionId":"9949888c-52dd-5537-a839-7f0fb859eb1e","sourceKey":"bank:LAG-BUA125:FRM-022","payload":{"prompt":"In Nigeria, the body responsible for registering companies and issuing certificates of incorporation is the","options":["Corporate Affairs Commission (CAC)","Federal Inland Revenue Service (FIRS)","Central Bank of Nigeria (CBN)","Nigerian Ports Authority (NPA)"],"correctOption":0,"section":"Theory of Firms","explanation":"The Corporate Affairs Commission registers businesses and companies and issues the certificate of incorporation that gives a company its legal existence. Option C regulates banks and monetary policy. Option B collects federal taxes."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 456, $official_bank_source${"itemId":"d24973d6-6c11-5f65-be65-defaada1ef9b","questionId":"6909904f-b420-5a96-834c-d1462f92b8e9","sourceKey":"bank:LAG-BUA125:FRM-023","payload":{"prompt":"The memorandum of association of a company is the document that","options":["sets out the internal rules for running the company's meetings and management","sets out the company's name, objects and relationship with the outside world","records the daily cash sales of the company","is the contract between the company and its bankers"],"correctOption":1,"section":"Theory of Firms","explanation":"The memorandum is the company's charter, stating basic facts such as its name, objects and liability of members, and governing its external relationships. Option A describes the articles of association, which cover internal rules. Options C and D are routine business records, not formation documents."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 457, $official_bank_source${"itemId":"d13f9eac-dd59-5edf-98fd-a92af02f2282","questionId":"67e33f57-5fa0-56d8-a18a-c7f63508b7a4","sourceKey":"bank:LAG-BUA125:FRM-024","payload":{"prompt":"Which statement correctly compares ordinary shareholders and debenture holders of a company?","options":["Ordinary shareholders are owners who receive variable dividends, while debenture holders are creditors who receive fixed interest","Both receive a fixed rate of interest whether or not the company makes a profit","Ordinary shareholders are paid first when a company is wound up","Debenture holders are owners with voting rights, while ordinary shareholders are creditors"],"correctOption":0,"section":"Theory of Firms","explanation":"Ordinary shares give part-ownership, voting rights and dividends that depend on profit, while debentures are long-term loans that earn fixed interest. Option D reverses the two roles. Option C is wrong because creditors, including debenture holders, are paid before ordinary shareholders."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 458, $official_bank_source${"itemId":"f9366a5f-38e7-5fb3-8dee-1070d3ccbc09","questionId":"ae6957c6-a8af-599d-8d7c-5139278ffcb1","sourceKey":"bank:LAG-BUA125:FRM-025","payload":{"prompt":"Which of the following is a form of internal finance for a limited company?","options":["Issue of debentures","Issue of new ordinary shares","Retained earnings (ploughed-back profits)","Bank overdraft"],"correctOption":2,"section":"Theory of Firms","explanation":"Retained earnings are profits kept in the business instead of being paid out as dividends, so the money comes from within the firm. Options B, A and D all bring in money from outside investors or lenders."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 459, $official_bank_source${"itemId":"4fbea724-5c49-5543-a4af-8e9c2536fc29","questionId":"130002ec-d3f7-5ec0-9357-9c0c254100fe","sourceKey":"bank:LAG-BUA125:FRM-026","payload":{"prompt":"Shares that carry a fixed rate of dividend and are paid before ordinary shareholders, but usually carry limited voting rights, are","options":["debentures","preference shares","bonus shares","ordinary shares"],"correctOption":1,"section":"Theory of Firms","explanation":"Preference shareholders get a fixed dividend and priority over ordinary shareholders for dividends and repayment of capital. Option D carries variable dividends and full voting rights. Option A is a loan, not a share."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 460, $official_bank_source${"itemId":"9fe291c3-a85e-5f9f-9090-d71dd77ce0dd","questionId":"86190022-69a8-53f3-bf81-70ad76adf284","sourceKey":"bank:LAG-BUA125:FRM-027","payload":{"prompt":"A business organisation that is established by an Act of the legislature, owned and financed by government, and run by a board appointed by government to provide essential services, is a","options":["private limited company","partnership","public limited company","public corporation (public enterprise)"],"correctOption":3,"section":"Theory of Firms","explanation":"A public corporation is created by statute and owned by the state, mainly to provide essential services in the public interest. Option C sounds similar, but a Plc is owned by private shareholders who buy its shares. Options A and B are private-sector businesses."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 461, $official_bank_source${"itemId":"ee62d847-ddb5-5c74-adc4-ed84bab26add","questionId":"174d7283-f3cb-5126-806c-bc1aeeca5ed9","sourceKey":"bank:LAG-BUA125:FRM-028","payload":{"prompt":"Which of the following is a main reason governments set up public enterprises?","options":["To reduce the supply of basic infrastructure","To avoid any form of accountability to the public","To maximise dividends paid to private shareholders","To provide essential services that private firms may not provide adequately or at affordable prices"],"correctOption":3,"section":"Theory of Firms","explanation":"Governments often run strategic or essential services, such as utilities, transport and ports, where huge capital is needed or the public interest matters more than profit. Option C describes the goal of private companies. Option B is wrong because public enterprises answer to government and the legislature."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 462, $official_bank_source${"itemId":"649ecea5-598a-5786-a35a-c9fd208ef8d5","questionId":"5f03cc82-a690-5e45-839a-64431488ed52","sourceKey":"bank:LAG-BUA125:FRM-029","payload":{"prompt":"Which of the following is NOT a common problem of public enterprises in Nigeria?","options":["Excessive pressure from private shareholders to pay dividends","Political interference in management","Inefficiency and dependence on government subsidies","Bureaucracy and slow decision-making"],"correctOption":0,"section":"Theory of Firms","explanation":"Public enterprises are owned by government, not private shareholders, so dividend pressure from private owners is not their problem. Options B, D and C are frequently cited weaknesses that led to calls for privatisation and commercialisation."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 463, $official_bank_source${"itemId":"4875902e-4de6-5e02-a733-32a7436860f9","questionId":"75713c47-203f-556b-a12b-de76f49bcbb6","sourceKey":"bank:LAG-BUA125:FRM-030","payload":{"prompt":"What is the difference between privatisation and commercialisation of a public enterprise?","options":["Privatisation transfers ownership to private investors, while commercialisation keeps government ownership but requires the enterprise to run on profit-oriented lines","Both mean that the government closes the enterprise down","Privatisation applies only to partnerships and commercialisation only to sole proprietorships","Privatisation keeps government ownership, while commercialisation sells the enterprise to private investors"],"correctOption":0,"section":"Theory of Firms","explanation":"Privatisation sells all or part of the government's stake to private owners, while a commercialised enterprise stays in government hands but must operate efficiently and cover its costs. Option D reverses the two terms. Option B confuses both with liquidation."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 464, $official_bank_source${"itemId":"03ee253c-a6be-54e6-a65b-143fda5caf2f","questionId":"76685cd6-a537-542d-b0cf-e9fcc3873cc1","sourceKey":"bank:LAG-BUA125:FRM-031","payload":{"prompt":"The main source of capital for a public corporation is","options":["government funding through budget allocations, grants and loans","contributions from partners under a deed","personal savings of its managing director","sale of ordinary shares to the general public"],"correctOption":0,"section":"Theory of Firms","explanation":"Because it is owned by the state, a public corporation is financed mainly by government allocations, grants and government-backed loans, plus any revenue it earns. Option D is how a Plc raises capital. Options C and B apply to sole proprietorships and partnerships."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 465, $official_bank_source${"itemId":"bf299723-ad7d-5f7b-bd7f-eda6d5cf1e74","questionId":"34f937a9-e5ac-5589-82b7-956ae0dafcc8","sourceKey":"bank:LAG-BUA125:FRM-032","payload":{"prompt":"Which of the following pairs of business forms both give their owners limited liability?","options":["Sole proprietorship and ordinary partnership","Ordinary partnership and public limited company","Private limited company and public limited company","Sole proprietorship and private limited company"],"correctOption":2,"section":"Theory of Firms","explanation":"Both private and public limited companies protect shareholders' personal assets, since liability is limited to their shares. Option A lists two forms with unlimited liability. Options D and B each pair a limited company with a form whose owners have unlimited liability."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 466, $official_bank_source${"itemId":"7067f538-e0f8-532e-86ec-0874dccc817d","questionId":"18f47a48-3e53-57b0-ae51-2ded8c1b04eb","sourceKey":"bank:LAG-BUA125:FRM-033","payload":{"prompt":"The traditional (neoclassical) theory of the firm assumes that the main objective of the firm is to","options":["achieve satisfactory rather than maximum results","maximise profit by producing where marginal revenue equals marginal cost","maximise sales revenue subject to a minimum profit","maximise the size of the management staff"],"correctOption":1,"section":"Theory of Firms","explanation":"Traditional theory sees the firm as run by an owner-entrepreneur who aims at maximum profit, reached where MR = MC. Option C is the sales revenue maximisation model. Option A describes satisficing in the behavioural theory."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 467, $official_bank_source${"itemId":"be1154ce-590c-5a07-87c9-1ffa2e52bff6","questionId":"04ada903-38d2-5f5d-ae1b-d1e95bfe6a4e","sourceKey":"bank:LAG-BUA125:FRM-034","payload":{"prompt":"Managerial theories of the firm developed mainly because in large modern companies","options":["ownership by shareholders is separated from control by professional managers","there are no shareholders at all","the owner always manages the business personally","firms have perfect information about all costs and demand"],"correctOption":0,"section":"Theory of Firms","explanation":"When shareholders own the firm but salaried managers control it, managers may pursue their own goals, such as sales, growth or status, instead of maximum profit. Option C describes the owner-managed firm of traditional theory. Option D is an assumption of traditional theory that managerial theories question."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 468, $official_bank_source${"itemId":"48dd60d1-9868-5fbb-9a7f-04a3d2763cd4","questionId":"f569247a-1534-5642-ba89-3bf777000894","sourceKey":"bank:LAG-BUA125:FRM-035","payload":{"prompt":"The model in which managers aim to make total sales revenue as large as possible, provided profit does not fall below the minimum level that keeps shareholders satisfied, is the","options":["profit maximisation model","behavioural (satisficing) model","sales revenue maximisation model","growth of the public sector model"],"correctOption":2,"section":"Theory of Firms","explanation":"In the sales revenue maximisation model, managers prefer higher sales because their pay and prestige are linked to the firm's size, subject to a minimum profit constraint. Option A aims at maximum profit with no such trade-off. Option B describes firms seeking satisfactory levels across several goals."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 469, $official_bank_source${"itemId":"e4ab1a75-d40f-5f5c-bcfb-f765402805f7","questionId":"dd0bba98-b943-5b93-ab33-82bb782abc03","sourceKey":"bank:LAG-BUA125:FRM-036","payload":{"prompt":"Managers of a large Plc spend heavily on extra staff, luxury official cars and large offices because these raise their own satisfaction and status, as long as profits stay acceptable to shareholders. This behaviour is best explained by","options":["perfect competition theory","the traditional profit maximisation theory","the law of diminishing returns","the managerial utility maximisation theory"],"correctOption":3,"section":"Theory of Firms","explanation":"Managerial utility theory says managers maximise their own satisfaction through spending on staff, perks and discretionary investment, subject to a minimum profit. Option B would cut such spending to raise profit. Option C is a production law, not a theory of managers' goals."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 470, $official_bank_source${"itemId":"eda07893-d91f-5ec1-a56a-9c4cf3073a7f","questionId":"a4a63a33-641b-56e3-891f-0d58a10d9a8e","sourceKey":"bank:LAG-BUA125:FRM-037","payload":{"prompt":"In the behavioural theory of the firm, 'satisficing' means that the firm","options":["maximises sales revenue only","always maximises profit","aims at satisfactory levels of performance rather than the maximum possible","aims to produce at zero cost"],"correctOption":2,"section":"Theory of Firms","explanation":"Satisficing means setting acceptable targets for profit, sales, market share and other goals, because information is limited and many groups must be satisfied. Option B is the traditional assumption. Option A is a managerial model with one main goal."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 471, $official_bank_source${"itemId":"2dec689c-c5d2-5ab7-9c86-6b74f7e4ec5d","questionId":"c891f457-14be-5b83-bc7d-9c4988bba51c","sourceKey":"bank:LAG-BUA125:FRM-038","payload":{"prompt":"The behavioural theory of the firm views the firm as","options":["a firm that always has perfect information","a coalition of groups, such as managers, workers, shareholders and customers, with different and often conflicting goals","a single owner with one clear goal of maximum profit","a government agency that ignores costs"],"correctOption":1,"section":"Theory of Firms","explanation":"Behavioural theory treats the firm as a coalition whose goals come from bargaining among its groups, so it pursues several targets and settles for satisfactory results. Option C describes the traditional view. Option A contradicts the behavioural idea that information and rationality are limited."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 472, $official_bank_source${"itemId":"f620e344-e71b-5342-9659-0c42bd42ee5e","questionId":"6423b981-ce98-52b8-98fc-7b19abf1dfa5","sourceKey":"bank:LAG-BUA125:FRM-039","payload":{"prompt":"Which of the following is NOT an assumption of the traditional profit maximisation theory of the firm?","options":["The firm is a coalition of groups that settles for satisfactory results","The firm is managed by its owner-entrepreneur","The firm has a single goal of maximum profit","The firm has full knowledge of its costs and revenues"],"correctOption":0,"section":"Theory of Firms","explanation":"The coalition and satisficing idea belongs to the behavioural theory, not the traditional theory. Options B, C and D are standard assumptions of the profit maximisation model."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 473, $official_bank_source${"itemId":"c4493045-7701-5d16-ab08-6502a2f67ad8","questionId":"bcb50599-b627-537d-bdf8-2a2682b432bf","sourceKey":"bank:LAG-BUA125:FRM-040","payload":{"prompt":"A managerial theory which holds that managers aim mainly at the fastest possible expansion of the firm, subject to keeping the firm safe from takeover, is the","options":["satisficing theory","profit maximisation theory","sales revenue maximisation theory","growth maximisation theory"],"correctOption":3,"section":"Theory of Firms","explanation":"Growth maximisation theory argues that managers gain power, pay and security when the firm grows, so they pursue the highest sustainable rate of growth while keeping the share price high enough to avoid takeover. Option B is the traditional single-goal model. Option C focuses on the level of sales revenue in a period rather than the growth of the firm over time."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 474, $official_bank_source${"itemId":"27aacb96-1650-55be-862a-3649df73c28e","questionId":"5f2a7492-7b52-5bda-9be8-b7b1b612354c","sourceKey":"bank:LAG-BUA125:PQ-011","payload":{"prompt":"Which of the following is a characteristic of a perfectly competitive market?","options":["Firms can enter and exit the market freely","Firms are price setters","There are few sellers in the market","Products are highly differentiated"],"correctOption":0,"section":"Market Structure","explanation":"Perfect competition has no barriers to entry or exit, so option A is right. Option B is wrong because firms are price takers, and option C is wrong because there are many sellers. Option D describes monopolistic competition, since products in perfect competition are homogeneous."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 475, $official_bank_source${"itemId":"9b95f697-bfe6-5e16-b2b8-a3e78f1b080a","questionId":"c4ad3443-0fad-56e5-b548-9f91117867ad","sourceKey":"bank:LAG-BUA125:PQ-012","payload":{"prompt":"If a perfectly competitive firm is producing where price is greater than marginal cost, it:","options":["Will increase its profits by producing more","Is making positive economic profits","Will increase its profits by producing less","Is making negative economic profits"],"correctOption":0,"section":"Market Structure","explanation":"When price exceeds marginal cost, each extra unit adds more to revenue than to cost, so producing more raises profit until P = MC, option A. Option C is the opposite. Options B and D cannot be concluded, because whether profit is positive or negative depends on price compared with average total cost, not marginal cost."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 476, $official_bank_source${"itemId":"708b404f-f4c7-5c1d-910e-d08e5d790805","questionId":"6584df00-714f-5be3-95f0-1739e70b7ddc","sourceKey":"bank:LAG-BUA125:PQ-015","payload":{"prompt":"When firms have an incentive to exit a competitive market, their exit will:","options":["Drive down the profits of the firms that remain","Leave market price and output unchanged","Decrease the quantity of goods supplied in the market","Drive down market prices"],"correctOption":2,"section":"Market Structure","explanation":"When firms leave, market supply falls, so the quantity supplied decreases, option C. The lower supply pushes price up, not down, so option D is wrong, and the higher price raises the profits of the remaining firms, which rules out option A. Option B ignores the fall in supply."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 477, $official_bank_source${"itemId":"b5b9bbe0-3821-5762-8a54-31ed6ece2d8a","questionId":"2f5a755e-a166-5ea1-84ee-0f7ce6c8d18c","sourceKey":"bank:LAG-BUA125:PQ-016","payload":{"prompt":"In a perfectly competitive market, the process of entry or exit of firms ends when:","options":["Firms are making zero economic profit","Price is equal to marginal cost","Firms are operating with excess capacity","Firms experience decreasing marginal revenue"],"correctOption":0,"section":"Market Structure","explanation":"Entry happens while firms earn economic profit and exit happens while they make losses, so the movement stops when economic profit is zero, option A. Option B is true for a competitive firm at every profit-maximising output, even while profits are still attracting entry, so it is not what ends the process. Option D is wrong because marginal revenue equals the constant market price."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 478, $official_bank_source${"itemId":"cd113f85-f72a-54cf-9d6f-7f8afa6a68ed","questionId":"5891b39b-7014-5f8a-a905-18f4aba0cd2d","sourceKey":"bank:LAG-BUA125:PQ-017","payload":{"prompt":"Compared with other market structures, the equilibrium quantity in an oligopoly market is usually:","options":["Higher than in monopoly and lower than in perfect competition","Lower than in both monopoly and perfect competition","Higher than in both monopoly and perfect competition","Lower than in monopoly and higher than in perfect competition"],"correctOption":0,"section":"Market Structure","explanation":"An oligopoly has a few interdependent firms with some market power, so output usually falls between the restricted output of a monopoly and the large output of perfect competition, option A. Option D reverses the order, and options B and C put oligopoly outside the range set by the two extreme structures."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 479, $official_bank_source${"itemId":"552ed32b-2ee8-5774-95dc-a5126286e811","questionId":"72ad6eb2-3b33-5ff9-a9ce-0e4cce795570","sourceKey":"bank:LAG-BUA125:PQ-068","payload":{"prompt":"A group of firms producing similar or identical products is called:","options":["A plant","An industry","A monopsony","A cartel"],"correctOption":1,"section":"Market Structure","explanation":"An industry, option B, is the aggregate of all firms producing the same or similar products, for example the cement industry. Option A is a single production unit of a firm. Option D is a group of firms that agree to fix prices or output, and option C is a market with only one buyer."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 480, $official_bank_source${"itemId":"4cf42981-2f51-5bef-ba9c-a1b9470ab923","questionId":"c5b6b4c7-2fb8-5825-9971-49e8077fec0e","sourceKey":"bank:LAG-BUA125:PQ-211","payload":{"prompt":"Which of the following cannot be classed as a market structure?","options":["Perfect competition","Monopolistic competition","Oligopoly","Communism"],"correctOption":3,"section":"Market Structure","explanation":"Communism is an economic and political system for organising a whole society, not a way of classifying an industry by its degree of competition. Options C, A and B are all market structures, distinguished by things like the number of firms and how similar their products are."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 481, $official_bank_source${"itemId":"c8689323-119a-5dd9-90c7-79bf199934e8","questionId":"1270aa23-6693-51dc-88f2-0010ba5f9e60","sourceKey":"bank:LAG-BUA125:PQ-216","payload":{"prompt":"A market structure in which a small number of firms account for most or all of the industry's output is called:","options":["perfect competition","oligopoly","monopoly","monopolistic competition"],"correctOption":1,"section":"Market Structure","explanation":"In an oligopoly a few firms dominate the industry, and each firm's actions affect the others, so they are interdependent. Options A and D have a large number of firms, while option C has only one firm."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 482, $official_bank_source${"itemId":"fbf1e863-d24a-57c4-af2f-d03425bc3e9b","questionId":"ab09ee5b-d9e0-5522-ab7e-d68d6479bdc4","sourceKey":"bank:LAG-BUA125:PQ-217","payload":{"prompt":"Which pair of factors is most important in classifying market structures by the nature of competition?","options":["The size of the firms' offices and their staff strength","The firms' accounting methods and year-end dates","The age of the firms and their location","The number of firms and the degree of product differentiation"],"correctOption":3,"section":"Market Structure","explanation":"Market structures are told apart mainly by how many sellers there are and how similar or different their products are, for example many firms with identical products in perfect competition or one firm in monopoly. Options C, A and B are business details that do not define the degree of competition."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 483, $official_bank_source${"itemId":"95bf3529-e7cb-53ec-ac2d-a6c8d205d3fc","questionId":"efc89a68-9c9e-5c76-b9f3-23c2e41f73d8","sourceKey":"bank:LAG-BUA125:PQ-221","payload":{"prompt":"When the minimum efficient scale of production is very large relative to total market demand, the industry is most likely to have:","options":["no barriers to entry at all","a very large number of small firms, as in perfect competition","only one or a few firms, as in monopoly or oligopoly","many firms selling differentiated products"],"correctOption":2,"section":"Market Structure","explanation":"If a firm must produce a large share of total market output to reach its lowest average cost, the market can support only one or a few efficient producers, which is why economies of scale can give rise to monopoly. Options B and D need many firms, and option A ignores the cost advantage large firms enjoy."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 484, $official_bank_source${"itemId":"b0adf6e9-6f1e-5976-9a1d-2a3b8a12e396","questionId":"b1ac90e0-5c20-518c-a8bb-fc931138be87","sourceKey":"bank:LAG-BUA125:PQ-222","payload":{"prompt":"A profit-maximising firm will choose the level of output at which:","options":["price equals average fixed cost","marginal revenue equals marginal cost","average cost is at its minimum","total revenue is at its maximum"],"correctOption":1,"section":"Market Structure","explanation":"Profit is maximised where producing one more unit adds as much to revenue as it adds to cost (MR = MC), so the decision depends on both demand and costs. Option D maximises sales revenue, not profit, and option C gives the most efficient output, which need not be the most profitable one."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 485, $official_bank_source${"itemId":"bb41c3d9-d4ea-57a2-a1fa-0822951283b7","questionId":"5b2293a3-56cd-51e6-a2eb-f2c780c6764d","sourceKey":"bank:LAG-BUA125:PQ-231","payload":{"prompt":"A perfectly competitive firm will maximise profit at the quantity at which the firm's marginal revenue equals:","options":["marginal cost","average fixed cost","total revenue","total cost"],"correctOption":0,"section":"Market Structure","explanation":"Profit is maximised where marginal revenue equals marginal cost (MR = MC): producing one more unit beyond that point would add more to cost than to revenue. Option D compares a marginal figure with a total figure, which is not the profit rule. Option B has nothing to do with the output decision, since fixed costs do not change with output."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 486, $official_bank_source${"itemId":"88e82003-4ca1-5b30-884d-08a43b34b919","questionId":"c8b1bf2b-7e22-5e5a-b21d-0cb0081bda3e","sourceKey":"bank:LAG-BUA125:PQ-232","payload":{"prompt":"Which of the following is NOT a valid option for a perfectly competitive firm?","options":["Increasing its output","Decreasing its output","Leaving the industry","Increasing its price above the market price"],"correctOption":3,"section":"Market Structure","explanation":"A perfectly competitive firm is a price taker: the price is fixed by market demand and supply, and if it charges more, buyers simply move to the many other sellers of the identical product. It can still change how much it produces, as in options A and B. Option C is also open to it because there are no barriers to exit."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 487, $official_bank_source${"itemId":"e970f5c5-6445-53af-8140-6af1040fa0f6","questionId":"c8d56d5c-9b47-5464-9262-06691fcfc2af","sourceKey":"bank:LAG-BUA125:PQ-233","payload":{"prompt":"In the long run, a perfectly competitive firm will achieve all of the following EXCEPT:","options":["economic (supernormal) profit","productive efficiency","normal profit","allocative efficiency"],"correctOption":0,"section":"Market Structure","explanation":"With free entry, any economic profit attracts new firms, which pushes price down until firms earn only normal profit in the long run. At that point price equals marginal cost and minimum average cost, so the firm is allocatively and productively efficient, which is why options D and B are achieved. Option C, normal profit, is exactly what remains in the long run."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 488, $official_bank_source${"itemId":"a5a97526-a25f-5b59-b667-f17c333c7b90","questionId":"c4b020cf-dba7-5745-8348-5b880a6d48ee","sourceKey":"bank:LAG-BUA125:PQ-234","payload":{"prompt":"If the price a firm receives for its product is equal to the marginal cost of producing it, the firm is:","options":["always earning an economic profit","allocatively efficient","always productively efficient","always making an economic loss"],"correctOption":1,"section":"Market Structure","explanation":"Allocative efficiency means price (what buyers value the last unit at) equals marginal cost (what it costs to make that unit), so resources go where consumers value them most. Option C is a different idea: productive efficiency means producing at the lowest average cost. Options A and D cannot be read from P = MC alone, because profit depends on average cost."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 489, $official_bank_source${"itemId":"a431d462-8748-55f7-a685-8e88b9734b01","questionId":"ee927287-765a-5ea6-b0f5-c81ecfb16d55","sourceKey":"bank:LAG-BUA125:PQ-235","payload":{"prompt":"A firm that is producing at the lowest possible average cost is:","options":["dominating the other firms in the market","allocatively efficient by definition","always earning an economic profit","productively efficient"],"correctOption":3,"section":"Market Structure","explanation":"Productive efficiency means producing output at the minimum average cost, so no resources are wasted in making it. Option B is a different concept: allocative efficiency is about price equalling marginal cost. Option C is wrong because a firm at minimum average cost may earn only normal profit if price equals that cost."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 490, $official_bank_source${"itemId":"51a56f0f-8963-571d-9512-c32c3cccad32","questionId":"4fdeff88-a8ac-5776-ac74-c29a90a14a79","sourceKey":"bank:LAG-BUA125:PQ-236","payload":{"prompt":"Which of the following is the best example of a nearly perfectly competitive market?","options":["Diamonds","Soft drinks","Branded athletic shoes","Farming of a staple crop"],"correctOption":3,"section":"Market Structure","explanation":"Farming comes closest to perfect competition: there are very many small farmers selling an almost identical product, and none of them can change the market price. Option A is controlled by a few big producers, while options C and B are dominated by brands with differentiated products and heavy advertising."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 491, $official_bank_source${"itemId":"98d55aca-0c8d-5aa1-8979-715dbbff90b5","questionId":"aa643fdd-9bc0-54df-b1fc-bb2af63a94e4","sourceKey":"bank:LAG-BUA125:PQ-237","payload":{"prompt":"Perfect competition is an industry with:","options":["many firms producing identical goods","a few firms producing goods that differ somewhat in quality","a few firms producing identical goods","many firms producing goods that differ somewhat"],"correctOption":0,"section":"Market Structure","explanation":"Perfect competition has a large number of firms selling a homogeneous product, so no single firm can influence the price. Option D describes monopolistic competition, where products are differentiated. Options C and B describe oligopoly, where only a few firms operate."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 492, $official_bank_source${"itemId":"fcba0332-2fd4-5285-9635-940907f3044c","questionId":"b7754dcd-f8a9-5709-82dd-0eebf6473f5d","sourceKey":"bank:LAG-BUA125:PQ-238","payload":{"prompt":"In a perfectly competitive industry, there are:","options":["many buyers and many sellers","one firm that sets the price for the others to follow","many sellers, but possibly only one or two buyers","many buyers, but possibly only one or two sellers"],"correctOption":0,"section":"Market Structure","explanation":"Perfect competition needs large numbers on both sides of the market, so no single buyer or seller can affect the price. Option C describes monopsony or duopsony, where one or two buyers dominate. Option D describes monopoly or duopoly, and option B describes price leadership, which belongs to oligopoly."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 493, $official_bank_source${"itemId":"1539d687-9363-543d-8084-a5f0c02db610","questionId":"c33c3d71-e7a3-55d0-9b17-98c6ae28a3a7","sourceKey":"bank:LAG-BUA125:PQ-239","payload":{"prompt":"In perfect competition, the product of a single firm:","options":["has many perfect complements produced by other firms","is sold under many different brand names","has many perfect substitutes produced by other firms","is sold to different customers at different prices"],"correctOption":2,"section":"Market Structure","explanation":"Because all firms sell a homogeneous product, each firm's output can be replaced exactly by another firm's output, so it has many perfect substitutes. Option D is price discrimination, which a price taker cannot practise. Option B is wrong because branding is a form of product differentiation, which does not exist in perfect competition."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 494, $official_bank_source${"itemId":"551c9902-f830-5da3-b529-533adc4d7354","questionId":"9b2444c2-9f25-5c89-b0b3-67efb35954d9","sourceKey":"bank:LAG-BUA125:PQ-240","payload":{"prompt":"In perfect competition, restrictions on entry into the industry:","options":["do not exist","apply to capital but not to labour","apply to labour but not to capital","apply to both capital and labour"],"correctOption":0,"section":"Market Structure","explanation":"One of the defining features of perfect competition is free entry and exit: firms can join or leave the industry without any barriers or government restrictions. Options C, D and B all describe some kind of barrier to entry, which is a feature of monopoly and oligopoly instead."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 495, $official_bank_source${"itemId":"665d06b6-efcf-5b94-b8c0-21f8c6883445","questionId":"0bbf3a98-bea0-5687-9365-91c9c73e7c56","sourceKey":"bank:LAG-BUA125:PQ-242","payload":{"prompt":"In the long run, monopolistically competitive firms tend to earn:","options":["zero economic profit (only normal profit)","substantial economic losses","high economic profits","negative economic profits"],"correctOption":0,"section":"Market Structure","explanation":"Entry into monopolistic competition is free, so short-run profits attract new firms with close substitutes, which takes customers away until only normal profit is left. Option C cannot last because of that entry. Options D and B cannot last either, because loss-making firms leave the industry until the remaining firms break even."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 496, $official_bank_source${"itemId":"7ddeb231-4c16-5124-892e-0c09a7497008","questionId":"6d796ace-2f24-5d94-81e4-fc9b926dd159","sourceKey":"bank:LAG-BUA125:PQ-243","payload":{"prompt":"For a monopolist, marginal revenue is:","options":["equal to price","equal to average revenue","less than price","greater than price"],"correctOption":2,"section":"Market Structure","explanation":"A monopolist faces a downward-sloping demand curve, so to sell one more unit it must lower the price on all the units it sells. That makes the extra revenue from the last unit smaller than its price. Option A is true only for a price taker in perfect competition, and option B says the same thing as A, since average revenue equals price."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 497, $official_bank_source${"itemId":"d0fe11d8-046f-5ae3-9dc2-82d15be8ad03","questionId":"2bc079a9-25d3-58f3-ae34-1da60ebd842a","sourceKey":"bank:LAG-BUA125:PQ-244","payload":{"prompt":"Which statement best describes perfect competition?","options":["It is a theoretical model whose strict assumptions rarely all hold in real-world markets","It exists wherever the government regulates prices","It describes markets dominated by a few large firms","It is the most common market structure in modern economies"],"correctOption":0,"section":"Market Structure","explanation":"Perfect competition assumes many firms, identical products, perfect knowledge and completely free entry and exit, and real markets rarely meet all of these at once, so it serves mainly as a benchmark. Option D is wrong because most real markets have some product differentiation or market power. Option C describes oligopoly."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 498, $official_bank_source${"itemId":"606de113-95ac-5975-91eb-fb81cd9a05be","questionId":"9ce13cff-4904-573c-9744-4c3d607eaf4c","sourceKey":"bank:LAG-BUA125:PQ-245","payload":{"prompt":"Monopolistic competition is a market structure characterised by:","options":["a few large firms whose decisions are interdependent","a large number of firms selling differentiated products that are close substitutes","a single firm selling a product with no close substitutes","many firms selling an identical product"],"correctOption":1,"section":"Market Structure","explanation":"In monopolistic competition there are many buyers and sellers, but each firm's product is slightly different from its rivals', for example through branding, quality or design, though they remain close substitutes. Option C is monopoly, option A is oligopoly, and option D is perfect competition, where products are homogeneous."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 499, $official_bank_source${"itemId":"d9fa68b8-3ac9-54b6-b129-d5ad873c045c","questionId":"d8b47526-6cbe-5a58-a6f8-8b16252f1911","sourceKey":"bank:LAG-BUA125:PQ-246","payload":{"prompt":"The demand curve facing a monopolist is:","options":["downward sloping, so it can sell more only by lowering its price","perfectly elastic (horizontal) at the market price","upward sloping, so it sells more at higher prices","perfectly inelastic (vertical) at all prices"],"correctOption":0,"section":"Market Structure","explanation":"Because the monopolist is the whole industry, it faces the market demand curve, which slopes downward: a higher price means fewer sales, and selling more means cutting the price. Option B describes a price-taking firm in perfect competition. Option D would mean buyers ignore price completely, which does not happen across all prices."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 500, $official_bank_source${"itemId":"897a2b39-36eb-5ebe-aaac-e3cbfa0fd847","questionId":"33422fcc-72e7-5dfa-9573-46b920620fc6","sourceKey":"bank:LAG-BUA125:PQ-247","payload":{"prompt":"A monopoly is a market structure in which there is:","options":["many sellers of differentiated products","two dominant sellers","only one seller of a product with no close substitutes","only one buyer of a product"],"correctOption":2,"section":"Market Structure","explanation":"In a monopoly a single firm makes up the whole industry and sells to many buyers, and it is protected by barriers to entry such as patents, licences or control of raw materials. Option B is a duopoly. Option D is a monopsony, where the single party is the buyer, not the seller. Option A is monopolistic competition."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 501, $official_bank_source${"itemId":"26a0c3aa-4d94-50cf-9bec-23bd74e23682","questionId":"7f26d26c-699f-5b05-95b6-fc757bed9360","sourceKey":"bank:LAG-BUA125:PQ-250","payload":{"prompt":"A perfectly competitive firm's short-run supply curve is the part of its marginal cost curve that lies above the:","options":["minimum point of the average variable cost curve","maximum point of the average variable cost curve","maximum point of the total revenue curve","minimum point of the average fixed cost curve"],"correctOption":0,"section":"Market Structure","explanation":"Below the lowest point of average variable cost, the price would not cover variable costs and the firm would shut down, so it supplies nothing there. Above that point, the firm produces where price equals marginal cost, which makes the marginal cost curve its supply curve. Option B is wrong because the AVC curve is U-shaped and has a minimum, not a maximum. Option D is wrong because average fixed cost keeps falling and has no minimum."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 502, $official_bank_source${"itemId":"c1c0d561-8cac-51b5-84e0-a555c6e7756f","questionId":"d34cfa83-21e6-56e5-86a1-c7c269e47ae5","sourceKey":"bank:LAG-BUA125:PQ-251","payload":{"prompt":"An agreement among firms to fix prices and quantities is known as:","options":["price leadership","game theory","price concentration","collusion"],"correctOption":3,"section":"Market Structure","explanation":"Collusion is when rival firms, usually in an oligopoly, agree with each other on prices or output instead of competing. Option A, price leadership, is when one firm sets a price and others follow without a formal agreement on quantities. Option B is a tool for analysing strategic decisions, not an agreement."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 503, $official_bank_source${"itemId":"770f3392-35d5-54df-8282-1c146bfaffe3","questionId":"52726cfa-7219-55d1-846c-79f91dc03425","sourceKey":"bank:LAG-BUA125:PQ-252","payload":{"prompt":"A group of firms that comes together formally to make joint price and output decisions is called:","options":["a concentrated industry","an oligopoly","price leadership","a cartel"],"correctOption":3,"section":"Market Structure","explanation":"A cartel is a formal collusive organisation of firms, such as OPEC, which agree on prices, output or market shares to act like a single monopolist. Option A is the market structure in which cartels usually form, not the group itself. Option B involves one firm leading on price without a formal joint decision."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 504, $official_bank_source${"itemId":"5237e559-2e97-53de-8395-ec21414f628b","questionId":"e43118e4-b559-5336-9e79-ace5cf5e9975","sourceKey":"bank:LAG-BUA125:PQ-253","payload":{"prompt":"Products produced by oligopolistic firms are:","options":["differentiated only","either homogeneous or differentiated","homogeneous only","always unique, with no substitutes"],"correctOption":1,"section":"Market Structure","explanation":"Oligopoly can be pure, where a few firms sell a nearly identical product such as cement or petroleum, or differentiated, where a few firms sell branded products such as cars or soft drinks. That is why options C and A are each only half right. Option D is wrong because oligopolists' products are substitutes for one another."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 505, $official_bank_source${"itemId":"7e959688-7019-5cea-9090-94b3fd1b115d","questionId":"d62dfdda-4e2c-5d6f-808f-199e3a882f76","sourceKey":"bank:LAG-BUA125:PQ-254","payload":{"prompt":"A key feature that distinguishes oligopoly is:","options":["a large number of small price-taking firms","profit-maximising behaviour","free entry and exit of firms","interdependence, because each firm's price and output decisions affect its rivals"],"correctOption":3,"section":"Market Structure","explanation":"With only a few firms in the market, each one must consider how its rivals will react before changing its price or output, so the firms are interdependent. Option B is common to firms in every market structure. Options A and C describe perfect competition, while oligopoly has a small number of firms and high barriers to entry."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 506, $official_bank_source${"itemId":"0c0c830d-bbee-55d2-965f-0ae4b3f4b910","questionId":"f128a987-29ca-5121-af90-cbb510ae875f","sourceKey":"bank:LAG-BUA125:PQ-255","payload":{"prompt":"Oligopoly is characterised by all of the following EXCEPT:","options":["high barriers to entry","a complete absence of rivalry among firms","interdependence among firms","a few large firms"],"correctOption":1,"section":"Market Structure","explanation":"In oligopoly, rivalry is intense: each of the few firms watches and reacts to the others, which is why advertising and strategic moves matter so much. A complete absence of rivalry is a feature of perfect competition, where firms are too small to affect each other. Options D, A and C are all standard features of oligopoly."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 507, $official_bank_source${"itemId":"13459a2a-00c1-5559-bcde-87a70eed10d2","questionId":"77ca12e1-dad5-56c9-9e3e-e94c9353295d","sourceKey":"bank:LAG-BUA125:PQ-257","payload":{"prompt":"Under the kinked demand curve theory, oligopoly prices are predicted to be:","options":["relatively rigid or 'sticky'","fixed by the government","always equal to marginal cost","highly volatile"],"correctOption":0,"section":"Market Structure","explanation":"The kinked demand model assumes rivals match a price cut but ignore a price rise, so a firm loses sales if it raises price and gains little if it cuts it, and it prefers to leave price unchanged. Option D is the opposite of what the model predicts. Option C is the perfect competition result, not an oligopoly one."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 508, $official_bank_source${"itemId":"286e3e54-fdb2-582a-acc9-a230b4bbe50a","questionId":"ab51b6ba-bcf1-5503-90ce-59dafad866da","sourceKey":"bank:LAG-BUA125:PQ-258","payload":{"prompt":"In a perfectly contestable market, large oligopolistic firms end up behaving like:","options":["monopolistically competitive firms","a cartel","perfectly competitive firms","a monopoly"],"correctOption":2,"section":"Market Structure","explanation":"A contestable market is one where entry and exit are free and costless, so even a few large firms face the constant threat of hit-and-run entry. To keep entrants away they charge prices close to average cost and earn only normal profit, just as perfectly competitive firms do. Options D and B describe firms that can keep prices high, which the threat of entry prevents."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 509, $official_bank_source${"itemId":"b9b47064-bc35-52f0-970b-7d69f130b91b","questionId":"2c78f9c2-64a2-5593-a717-b05348879f2c","sourceKey":"bank:LAG-BUA125:PQ-259","payload":{"prompt":"Other things equal, and with firms selling identical products, which type of oligopoly competition would you expect to give the highest market output?","options":["Stackelberg competition","Collusion","Cournot competition","Bertrand (price) competition"],"correctOption":3,"section":"Market Structure","explanation":"In the Bertrand model, firms selling identical products compete on price and keep undercutting each other until price falls to marginal cost, giving the competitive level of output. Cournot and Stackelberg firms compete on quantity and keep price above marginal cost, so options C and A give less output. Option B, collusion, restricts output the most to raise price."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 510, $official_bank_source${"itemId":"d97d4938-fbdc-57bf-93b3-3481fc7b026a","questionId":"251a1651-8e20-5663-a241-f0f5ecfa1f78","sourceKey":"bank:LAG-BUA125:PQ-261","payload":{"prompt":"A profit-maximising oligopolistic firm produces at the output level where:","options":["MR = MC","MR = ATC","AVC > MR","P = ATC"],"correctOption":0,"section":"Market Structure","explanation":"Every profit-maximising firm, whatever its market structure, chooses the output where marginal revenue equals marginal cost. Option D, price equal to average total cost, is the break-even point where only normal profit is earned. Options B and C do not compare the right quantities for a profit decision."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 511, $official_bank_source${"itemId":"402ac560-7ad3-5079-855e-4499fe3dd835","questionId":"8bef72fd-9826-58a7-8c27-c3123af7a2ea","sourceKey":"bank:LAG-BUA125:PQ-262","payload":{"prompt":"Cartels are most likely to arise in which of the following market structures?","options":["Perfect competition","Monopolistic competition","Monopoly","Oligopoly"],"correctOption":3,"section":"Market Structure","explanation":"A cartel needs a small number of firms that can agree and monitor one another, which is exactly the situation in oligopoly. Options A and B have too many firms for an agreement to work. Option C has only one firm, so there is nobody to collude with."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 512, $official_bank_source${"itemId":"5a33354d-a22d-5017-be57-43e8da6a9dad","questionId":"d5331400-6b6b-5073-ae63-0cffe070b992","sourceKey":"bank:LAG-BUA125:PQ-267","payload":{"prompt":"Which of the following is a model of NON-collusive oligopoly?","options":["A cartel","The kinked demand curve model","A market-sharing cartel","Joint profit maximisation"],"correctOption":1,"section":"Market Structure","explanation":"Non-collusive models assume oligopolists act independently while guessing how rivals will react; the kinked demand curve model and the Cournot model are the classic examples. Options A, D and C all involve firms agreeing with one another on prices, output or market shares, which is collusion."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 513, $official_bank_source${"itemId":"13a61291-fbc2-5ede-b041-79496b4d5025","questionId":"ae8c0e3c-3631-5f0c-8360-576afb8f742f","sourceKey":"bank:LAG-BUA125:PQ-270","payload":{"prompt":"The petroleum industry is an example of:","options":["monopolistic competition","differentiated oligopoly","duopoly","pure oligopoly"],"correctOption":3,"section":"Market Structure","explanation":"A pure oligopoly is a market with a few large firms selling a largely identical product, and crude oil and petroleum products are a standard example. Option B applies to industries like cars, where the few firms sell branded, different products. Option A needs many small firms, and option C needs exactly two."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 514, $official_bank_source${"itemId":"ecf3d1c0-2b05-5f89-9495-1696221310e5","questionId":"7122ced0-f1ca-5709-b140-7790a4eea0ef","sourceKey":"bank:LAG-BUA125:PQ-271","payload":{"prompt":"The kinked demand curve model assumes that rivals:","options":["ignore both price increases and price cuts","match both price increases and price cuts","match price cuts but do not match price increases","match price increases but not price cuts"],"correctOption":2,"section":"Market Structure","explanation":"The kink comes from asymmetric reactions: if one firm cuts its price, rivals cut too so they do not lose customers, but if it raises its price, rivals keep theirs and take its customers. Option D reverses this. Options B and A would give a smooth demand curve with no kink."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 515, $official_bank_source${"itemId":"0808243c-ebae-534d-b79c-a2c343bf0eae","questionId":"c65d0ab9-f8a6-5abf-b0dd-315c68844e0a","sourceKey":"bank:LAG-BUA125:STR-001","payload":{"prompt":"The classification of industries according to the degree and nature of competition among the firms operating in them is known as","options":["market segmentation","market structure","market equilibrium","market research"],"correctOption":1,"section":"Market Structure","explanation":"Market structure describes how industries differ in the degree and nature of competition, for example in the number of firms, type of product and ease of entry. Option A divides buyers into groups. Option C is the point where demand equals supply."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 516, $official_bank_source${"itemId":"dd509dd0-c2a1-59ae-ab2e-b65f84bb1794","questionId":"4374f79c-0025-5d20-ae51-11b29324c5b8","sourceKey":"bank:LAG-BUA125:STR-002","payload":{"prompt":"A market with a complete absence of rivalry among firms, a large number of buyers and sellers, homogeneous products and perfect knowledge of the market is","options":["monopolistic competition","perfect competition","oligopoly","duopoly"],"correctOption":1,"section":"Market Structure","explanation":"These are the defining features of perfect competition: many buyers and sellers, identical products, perfect knowledge and no rivalry because no firm can affect price. Option A has many firms but differentiated products. Options C and D have few firms that react to each other's actions."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 517, $official_bank_source${"itemId":"b9407c73-b99c-54d0-8905-140f23379643","questionId":"2e87e6bd-d339-5e63-80f0-f345d2cdd04a","sourceKey":"bank:LAG-BUA125:STR-003","payload":{"prompt":"In perfect competition, firms are described as price takers because","options":["the government fixes the price for every product","the price is set by market demand and supply, and no single firm can alter it","firms agree among themselves on a common price","each firm sets its own price to maximise profit"],"correctOption":1,"section":"Market Structure","explanation":"Under perfect competition, the equilibrium price comes from the price mechanism, the interaction of market demand and supply, and each firm is too small to influence it. Option D describes a price maker such as a monopolist. Option C describes collusion, which is linked to oligopoly."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 518, $official_bank_source${"itemId":"d333568e-5db1-5068-9135-1ce9c4a4fcaf","questionId":"4b19dbfe-1b39-51c1-ae58-93fcc132297f","sourceKey":"bank:LAG-BUA125:STR-004","payload":{"prompt":"Under perfect competition, the demand curve facing an individual firm is","options":["kinked at the current price","perfectly inelastic (vertical)","downward sloping, like the market demand curve","perfectly elastic (horizontal) at the market price"],"correctOption":3,"section":"Market Structure","explanation":"Because the firm is a price taker, it can sell any quantity at the market price but nothing above it, so its demand curve is horizontal and P = AR = MR. Option C describes firms with some price-setting power, such as a monopolist. Option A is associated with the kinked-demand model of oligopoly."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 519, $official_bank_source${"itemId":"6b8a93d7-fe31-5a26-9e4b-a49990bb20ab","questionId":"ba9ed9ec-3957-529b-8a02-523018012fe4","sourceKey":"bank:LAG-BUA125:STR-005","payload":{"prompt":"Which of the following is NOT a feature of a perfectly competitive market?","options":["A single firm cannot alter the market price","No barriers to entry into or exit from the market","Firms differentiate their products through branding","The exit of one firm has no influence on price"],"correctOption":2,"section":"Market Structure","explanation":"Products under perfect competition are homogeneous, so there is no room for product differentiation or branding. Options B, A and D are all features of perfect competition."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 520, $official_bank_source${"itemId":"fdb8f32a-e9f0-57e2-9605-57578f4e718d","questionId":"83981582-3ef7-5634-adf8-3b6c4ec17c4e","sourceKey":"bank:LAG-BUA125:STR-006","payload":{"prompt":"In a large market, thousands of farmers sell identical tomatoes to thousands of buyers who know every seller's price, and anyone can start or stop farming freely. If one farmer tries to sell above the market price, he sells nothing. This market is closest to","options":["monopoly","monopsony","perfect competition","oligopoly"],"correctOption":2,"section":"Market Structure","explanation":"Many sellers and buyers, an identical product, full information and free entry and exit make this close to perfect competition, where each seller is a price taker. Option A has one seller. Option B has one buyer, while here there are thousands."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 521, $official_bank_source${"itemId":"d04826d2-4954-5f6d-9ca8-c19276d4273a","questionId":"8a58924a-4dcd-53ff-9341-b7ebb0947a6b","sourceKey":"bank:LAG-BUA125:STR-007","payload":{"prompt":"In the long run under perfect competition, if firms are earning supernormal profits, what happens?","options":["Each firm raises its price to protect its profit","Firms leave the industry, raising the price further","The government stops new firms from entering","New firms enter, market supply rises and price falls until only normal profit is earned"],"correctOption":3,"section":"Market Structure","explanation":"With free entry, supernormal profit attracts new firms, which increases supply and pushes price down until price equals minimum average cost and only normal profit remains. Option B is what happens when firms are making losses. Option A is impossible because each firm is a price taker."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 522, $official_bank_source${"itemId":"f26dfc24-6ab0-5248-9949-1c71d648658f","questionId":"1c033aad-5770-564f-a112-3f10c15b0165","sourceKey":"bank:LAG-BUA125:STR-008","payload":{"prompt":"A market in which a single firm makes up the whole industry and sells to many buyers is a","options":["monopoly","duopoly","monopsony","monopolistic competition"],"correctOption":0,"section":"Market Structure","explanation":"A monopoly has one seller, so the firm is the industry and serves many buyers. Option C is the reverse case of one buyer facing many sellers. Option B has two dominant sellers."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 523, $official_bank_source${"itemId":"d59a8e9f-dcc7-537b-abb5-307d1d747086","questionId":"6d470d30-683c-5542-9d69-8c9f1d4fead6","sourceKey":"bank:LAG-BUA125:STR-009","payload":{"prompt":"Which of the following correctly describes a monopolist's pricing power?","options":["It must accept the price set by its rivals","It cannot change its price without government approval","It is a price maker","It is a price taker"],"correctOption":2,"section":"Market Structure","explanation":"A monopolist faces the whole market demand curve and has no close rivals, so it chooses its price (or output) and is a price maker. Option D describes firms in perfect competition. Option A assumes rivals exist, which is not the case in pure monopoly."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 524, $official_bank_source${"itemId":"13b0fb2a-b766-533d-9b97-67d87125db8f","questionId":"6ed5f74f-3a37-551d-9f1d-21bb723199c0","sourceKey":"bank:LAG-BUA125:STR-010","payload":{"prompt":"When a monopolist sells the same product at different prices to different buyers for reasons not related to cost differences, it is practising","options":["product differentiation","price leadership","predatory pricing","price discrimination"],"correctOption":3,"section":"Market Structure","explanation":"Price discrimination means charging different buyers different prices for the same product, which a monopolist can do because it controls supply. Option B is where one oligopoly firm sets a price that others follow. Option A is about making products distinct, not pricing."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 525, $official_bank_source${"itemId":"ea23088d-c203-5232-87cb-d2619147e001","questionId":"d7d1f8cb-70ba-5144-9498-21f8926b3ac0","sourceKey":"bank:LAG-BUA125:STR-011","payload":{"prompt":"Which of the following is NOT a cause of monopoly?","options":["Ownership of a strategic raw material","Patent rights","A very large number of firms selling identical products","Government licensing"],"correctOption":2,"section":"Market Structure","explanation":"Many firms selling identical products is the opposite of monopoly; it describes perfect competition. Options B, A and D are classic barriers that allow one firm to become or remain the only seller."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 526, $official_bank_source${"itemId":"29f12989-6f9c-58a7-a558-75d6a4d96967","questionId":"e120b3a1-f765-5c13-8775-747c47e202c6","sourceKey":"bank:LAG-BUA125:STR-012","payload":{"prompt":"A pharmaceutical company in Nigeria is the only firm legally allowed to produce a new drug for 20 years because it holds the exclusive right to the invention. Its monopoly arises mainly from","options":["price discrimination","ownership of a strategic raw material","economies of scale in a small market","a patent right"],"correctOption":3,"section":"Market Structure","explanation":"A patent gives the inventor the sole legal right to make and sell the invention for a period, which blocks entry and creates monopoly. Option B would arise if the firm controlled an essential input. Option A is a pricing strategy a monopolist may use, not a cause of monopoly."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 527, $official_bank_source${"itemId":"59bcf04e-e89a-59ce-a9e6-ad0720b389b2","questionId":"6e64c035-ebac-5793-be23-5b3ef9fc5ee9","sourceKey":"bank:LAG-BUA125:STR-013","payload":{"prompt":"A small town can support only one water-supply firm, because the cost of laying pipes means a second firm could never cover its costs. This type of monopoly arises mainly because","options":["the firm is in perfect competition","the firm holds a patent on water","the firm practises price discrimination","the market size does not require more than one producer, and one firm enjoys economies of scale"],"correctOption":3,"section":"Market Structure","explanation":"When average cost keeps falling over the whole market's output, one large firm can supply more cheaply than two, so the market supports only one producer. Option B is wrong because water is not a patented invention. Option C is a pricing practice, not the reason only one firm exists."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 528, $official_bank_source${"itemId":"cc5cb564-6765-5935-826d-24c34976ac88","questionId":"63749f33-9d81-56ec-83d2-90b36ee095e2","sourceKey":"bank:LAG-BUA125:STR-014","payload":{"prompt":"Why can a monopolist continue to earn supernormal profit in the long run, unlike a firm in perfect competition?","options":["It faces a perfectly elastic demand curve","Barriers to entry prevent new firms from entering and competing the profit away","It produces where marginal cost is at its minimum","Its marginal revenue is always equal to its price"],"correctOption":1,"section":"Market Structure","explanation":"Supernormal profit normally attracts new firms, but a monopolist's barriers to entry, such as patents, licences or control of key inputs, keep rivals out. Option D describes perfect competition; for a monopolist MR is below price. Option A also describes a perfectly competitive firm."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 529, $official_bank_source${"itemId":"d44a601f-7cfc-5aef-9a56-5d0d03d67852","questionId":"ab0a0339-3c04-515b-8394-8552849929d4","sourceKey":"bank:LAG-BUA125:STR-015","payload":{"prompt":"For a monopolist facing a downward-sloping demand curve, marginal revenue is less than price because","options":["to sell an extra unit it must lower the price on all the units it sells","its marginal cost is always rising","it is a price taker","it must pay higher wages as output rises"],"correctOption":0,"section":"Market Structure","explanation":"A single-price monopolist must cut price to sell more, and the lower price applies to every unit, so the extra revenue from one more unit is less than the price of that unit. Option B is about cost, not revenue. Option C is wrong because a monopolist is a price maker."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 530, $official_bank_source${"itemId":"e2d85138-b9e6-512a-887c-02114a46f0b3","questionId":"d75b0a5d-731c-552d-a503-2936e8bf1245","sourceKey":"bank:LAG-BUA125:STR-016","payload":{"prompt":"An industry dominated by two firms whose decisions on price and output affect each other is a","options":["duopsony","monopoly","duopoly","monopsony"],"correctOption":2,"section":"Market Structure","explanation":"A duopoly has two prominent sellers who interact and are strategically interdependent. Option A also has two firms, but they are the main buyers, not sellers. Options B and D have one seller and one buyer respectively."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 531, $official_bank_source${"itemId":"1ad27e9d-16a6-5a20-9db0-bd38a7d2acee","questionId":"2b0c0862-0b05-5668-821f-430f7378a82d","sourceKey":"bank:LAG-BUA125:STR-017","payload":{"prompt":"In a duopoly, the quantity demanded of one firm's product depends on","options":["both its own price and the price charged by the rival firm","only the government's price control","only consumers' incomes","only its own price"],"correctOption":0,"section":"Market Structure","explanation":"Because the two firms' products are close substitutes, a price change by one firm shifts buyers towards or away from the other, so demand depends on both prices. Option D ignores the rival, which is the central feature of duopoly. Options B and C leave out price competition entirely."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 532, $official_bank_source${"itemId":"fe01f8ed-2957-5539-a2b7-f23183e9d281","questionId":"66416ebb-4944-504b-8530-4d3d9e1ab790","sourceKey":"bank:LAG-BUA125:STR-018","payload":{"prompt":"Only two firms supply nearly all the cooking gas cylinders in a state. When one cuts its price, the other quickly matches it to avoid losing customers. This market is best described as a","options":["monopoly","monopsony","perfect competition","duopoly"],"correctOption":3,"section":"Market Structure","explanation":"Two dominant sellers that watch and react to each other's prices form a duopoly, marked by interdependence and price competition. Option A would have only one seller. Option C would have many sellers who cannot influence price."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 533, $official_bank_source${"itemId":"4134635c-a129-5e57-b865-c483d9d16ad7","questionId":"2a33819d-e499-5632-b698-acd63e7da1e0","sourceKey":"bank:LAG-BUA125:STR-019","payload":{"prompt":"A market with a small number of firms, each with significant influence on market behaviour but none able to dominate the others, is","options":["monopolistic competition","oligopoly","monopoly","perfect competition"],"correctOption":1,"section":"Market Structure","explanation":"Oligopoly has a few firms whose actions all matter for the market, so none dominates and each must consider the others. Option C has one firm. Options A and D have many firms, each with little effect on the market."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 534, $official_bank_source${"itemId":"ecb1cd8d-7e7a-5dfa-9349-39094b30feb7","questionId":"55de9430-0eb8-5243-9b1d-c04dcc4c1bef","sourceKey":"bank:LAG-BUA125:STR-020","payload":{"prompt":"Which of the following is a key feature of oligopoly?","options":["Firms are price takers","No barriers to entry","Interdependence, because one firm's action affects the other firms","A very large number of small firms"],"correctOption":2,"section":"Market Structure","explanation":"With only a few firms, each firm's price, output or advertising decision affects its rivals, so firms must anticipate each other's reactions. Option D describes perfect or monopolistic competition. Options B and A are wrong because oligopoly has high barriers and firms set prices."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 535, $official_bank_source${"itemId":"4fedf039-ee19-5370-9b21-86932accce11","questionId":"cfb73cdf-b6e2-5226-b561-1185218aa954","sourceKey":"bank:LAG-BUA125:STR-021","payload":{"prompt":"Which of the following is NOT a feature of oligopoly?","options":["A small number of producers","Firms are price setters","Strategic use of advertising","Free and easy entry of new firms"],"correctOption":3,"section":"Market Structure","explanation":"Oligopoly is protected by high barriers to entry, so free and easy entry is not one of its features. Options A, B and C all describe oligopoly."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 536, $official_bank_source${"itemId":"338bfe17-4265-5eae-91ad-56ba307b5939","questionId":"b8676ca3-9eb0-5f82-a7e9-e48b264edf84","sourceKey":"bank:LAG-BUA125:STR-022","payload":{"prompt":"Nigeria's mobile telecom market is served by a few large operators. Each spends heavily on advertising and quickly responds when a rival launches a new data price. This market structure is best described as","options":["oligopoly","monopoly","monopsony","perfect competition"],"correctOption":0,"section":"Market Structure","explanation":"A few large firms, high entry barriers such as licences and network costs, strategic advertising and reactions to rivals' prices are signs of oligopoly. Option D would have many small price-taking firms. Option B would have only one operator."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 537, $official_bank_source${"itemId":"78fd5b1b-541c-54a3-84b2-4d072cc4dd73","questionId":"2e732886-e54f-5e86-99f3-9c3b684e58ca","sourceKey":"bank:LAG-BUA125:STR-023","payload":{"prompt":"The kinked demand curve model of oligopoly is used to explain why","options":["prices tend to remain stable even when costs change","an oligopolist faces a horizontal demand curve","oligopoly products are always homogeneous","oligopolists always earn zero profit"],"correctOption":0,"section":"Market Structure","explanation":"The model assumes rivals match a price cut but ignore a price rise, so demand is elastic above the current price and inelastic below it. The resulting gap in the MR curve means MC can change within it without changing the profit-maximising price, so prices are sticky. Options D and B are not predictions of the model."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 538, $official_bank_source${"itemId":"501eab3a-9ee9-5245-a50a-2b7cd564b099","questionId":"86b554a7-4cf4-5cba-91a0-51edfe0cc98e","sourceKey":"bank:LAG-BUA125:STR-025","payload":{"prompt":"An industry with many buyers and sellers whose products are differentiated but close substitutes, with free entry and exit, is","options":["oligopoly","monopolistic competition","monopoly","perfect competition"],"correctOption":1,"section":"Market Structure","explanation":"Monopolistic competition combines many firms and free entry, as in perfect competition, with product differentiation, which gives each firm a little market power. Option D has identical products. Option A has only a few firms protected by barriers."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 539, $official_bank_source${"itemId":"e156758b-82e1-5e02-9535-c48e7412136c","questionId":"3c8cf4c2-d2cf-594f-bef0-96514aad7353","sourceKey":"bank:LAG-BUA125:STR-026","payload":{"prompt":"A Lagos street has dozens of hair salons. Each offers slightly different styles, service and ambience, and new salons open easily whenever business looks good. This market is best described as","options":["oligopoly","duopsony","monopoly","monopolistic competition"],"correctOption":3,"section":"Market Structure","explanation":"Many sellers, differentiated but substitutable services and free entry are the features of monopolistic competition. Option A would have only a few dominant firms with high barriers. Option B is a market with two large buyers."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 540, $official_bank_source${"itemId":"c8fe28d7-60e2-54cb-a607-4cd2a1d96e7e","questionId":"c4189cf8-ecf9-55fa-8e7f-fa4b88d87589","sourceKey":"bank:LAG-BUA125:STR-027","payload":{"prompt":"Short-run supernormal profit in monopolistic competition tends to disappear in the long run because","options":["it attracts new firms into the industry, which wipes away the profit","products become perfect substitutes for each other","the government taxes it away","firms are forced to merge into a monopoly"],"correctOption":0,"section":"Market Structure","explanation":"Free entry means that when firms earn supernormal profit, new firms enter with similar products, demand for each firm falls, and only normal profit remains in the long run. Option D is wrong because free entry keeps the number of firms large. Option B is wrong because products remain differentiated."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 541, $official_bank_source${"itemId":"8bb72984-20e5-5e83-8bba-efa789e36335","questionId":"52abef46-abf8-5bf9-9870-178b7d007698","sourceKey":"bank:LAG-BUA125:STR-028","payload":{"prompt":"Which of the following is a feature of monopolistic competition?","options":["Very high barriers to entry","Imperfect consumer knowledge of the firms' brands","Only one seller in the industry","Products that are perfect substitutes"],"correctOption":1,"section":"Market Structure","explanation":"Buyers in monopolistic competition do not know everything about every brand, which helps firms use advertising, quality and branding to compete. Option C describes monopoly. Option D describes perfect competition, where products are homogeneous."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 542, $official_bank_source${"itemId":"5459bbd5-3a54-5b03-8638-29926e7bd224","questionId":"367a88e9-c4bc-5eed-ae41-9d940833ff2a","sourceKey":"bank:LAG-BUA125:STR-029","payload":{"prompt":"What is the main difference between perfect competition and monopolistic competition?","options":["Perfect competition has one buyer while monopolistic competition has many","Products are homogeneous in perfect competition but differentiated in monopolistic competition","Perfect competition has a few firms while monopolistic competition has one","Entry is free in monopolistic competition but blocked in perfect competition"],"correctOption":1,"section":"Market Structure","explanation":"Both structures have many firms and free entry, but perfectly competitive firms sell identical products while monopolistically competitive firms sell differentiated close substitutes. Option C confuses the number of firms. Option D is wrong because entry is free in both."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 543, $official_bank_source${"itemId":"2472ef68-9c58-54a7-9475-59f60ba6cb50","questionId":"365b1027-903c-59c4-944a-3cf2ea1da32d","sourceKey":"bank:LAG-BUA125:STR-030","payload":{"prompt":"A market in which there is only one buyer of the goods produced by many suppliers is","options":["monopsony","duopsony","monopoly","oligopoly"],"correctOption":0,"section":"Market Structure","explanation":"Monopsony means a single buyer facing many sellers, so the buyer has great power over price and quantity. Option C is a single seller facing many buyers. Option B has two large buyers."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 544, $official_bank_source${"itemId":"c4bb2f75-dd37-521d-9c3d-92a5ccc732c8","questionId":"f16efb29-c3a1-516e-828c-2c0f03ce59af","sourceKey":"bank:LAG-BUA125:STR-031","payload":{"prompt":"In a monopsony, the prices received by suppliers tend to be","options":["unrelated to the buyer's power","high, because suppliers can choose among many buyers","low, because the single buyer has strong bargaining power","fixed at the perfectly competitive level"],"correctOption":2,"section":"Market Structure","explanation":"Since sellers have no other buyer to turn to, the monopsonist can push prices down, so suppliers have low bargaining power. Option B is wrong because there is only one buyer. Option D ignores the buyer's market power."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 545, $official_bank_source${"itemId":"850c44e4-1d02-58cf-813c-9adb98446f2e","questionId":"9a1bf3cf-5897-5181-913a-e878489150f3","sourceKey":"bank:LAG-BUA125:STR-032","payload":{"prompt":"In a remote mining town, one mining company is the only employer of labour, and hundreds of workers have no other job options nearby. The labour market in this town is an example of","options":["monopsony","monopoly","perfect competition","duopoly"],"correctOption":0,"section":"Market Structure","explanation":"A single buyer of labour facing many workers is a monopsony, and geographical location is one of its causes. Option B is about a single seller of a product, not a single buyer. Option D has two sellers."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 546, $official_bank_source${"itemId":"025111a4-2a35-5a68-887c-a63937b6311f","questionId":"2b389a20-b698-5c18-9a3d-bd0e86d8b5a8","sourceKey":"bank:LAG-BUA125:STR-033","payload":{"prompt":"Which of the following is NOT a likely cause of monopsony?","options":["Unregulated mergers and acquisitions among buyers","Geographical location","Government regulations","A large number of competing buyers in the market"],"correctOption":3,"section":"Market Structure","explanation":"Monopsony requires a single buyer, so many competing buyers rule it out. Options C, B and A can all leave sellers facing just one buyer."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 547, $official_bank_source${"itemId":"cefaa603-2a1b-5f6a-abd0-35272ac08e5e","questionId":"f89b64ee-8a0a-54de-a275-295de4999220","sourceKey":"bank:LAG-BUA125:STR-034","payload":{"prompt":"Which of the following is a likely effect of monopsony on the market?","options":["Free entry of many new buyers","Very high prices paid to suppliers","Perfect knowledge among all buyers and sellers","Low innovation and market inefficiency, because competition is low"],"correctOption":3,"section":"Market Structure","explanation":"With only one buyer, competition is weak, which tends to reduce innovation and make the market less efficient. Option B is wrong because the single buyer pushes prices down. Option A is wrong because monopsony has barriers to entry."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 548, $official_bank_source${"itemId":"2386a05d-ca9f-51e0-a8c7-42c99af21fbb","questionId":"8b85c9dc-9aaf-58a5-9818-88d6c0aa82ff","sourceKey":"bank:LAG-BUA125:STR-035","payload":{"prompt":"A market in which two large firms are the main buyers of the goods and services of many producers is","options":["duopsony","oligopoly","monopsony","duopoly"],"correctOption":0,"section":"Market Structure","explanation":"Duopsony means two dominant buyers facing many sellers. Option D has two dominant sellers instead of buyers. Option C has only one buyer."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 549, $official_bank_source${"itemId":"e40a2b64-dd77-5879-93c9-e670569543fa","questionId":"9ed26838-36d6-5300-8dd0-7355a4c81bae","sourceKey":"bank:LAG-BUA125:STR-036","payload":{"prompt":"In a cocoa-growing area, thousands of farmers can sell their beans only to two large processing companies, which together determine how much cocoa is bought and at what price. This market is a","options":["perfect competition","monopoly","duopoly","duopsony"],"correctOption":3,"section":"Market Structure","explanation":"Two large buyers facing many sellers is a duopsony; the two firms determine market demand and enjoy strong bargaining power. Option C would have two sellers, but here the farmers are many sellers. Option A would have many buyers."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 550, $official_bank_source${"itemId":"6e605a55-ee26-5861-b267-f2f66ae596aa","questionId":"e85fe44c-442c-5179-b8ba-18ab208088a4","sourceKey":"bank:LAG-BUA125:STR-037","payload":{"prompt":"Which of the following is NOT a feature of duopsony?","options":["Low barriers to entry for new buyers","Less competition and higher profit for the two firms","The firms enjoy great bargaining power","The two firms determine market demand"],"correctOption":0,"section":"Market Structure","explanation":"Duopsony is protected by high barriers to entry, so low barriers are not one of its features. Options D, C and B are all features of duopsony."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 551, $official_bank_source${"itemId":"e06fc5ff-ea32-572c-96cc-2de46dfecabb","questionId":"2e8e8f14-095b-5a0b-9d3c-91a6faf35435","sourceKey":"bank:LAG-BUA125:STR-038","payload":{"prompt":"Which pair correctly matches the market structure with its description?","options":["Monopoly: one seller; monopsony: one buyer","Duopoly: two buyers; duopsony: two sellers","Monopoly: one buyer; monopsony: one seller","Monopsony: two buyers; duopsony: one buyer"],"correctOption":0,"section":"Market Structure","explanation":"The '-poly' structures count sellers and the '-psony' structures count buyers, so monopoly is one seller and monopsony is one buyer. Option C reverses the two terms. Option B reverses duopoly (two sellers) and duopsony (two buyers)."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 552, $official_bank_source${"itemId":"0e147879-8bb8-5255-b317-851e9c8a6781","questionId":"f01d3a9c-5876-5def-b7f8-b10f85e7eac1","sourceKey":"bank:LAG-BUA125:STR-040","payload":{"prompt":"Which of the following is a barrier to entry that can protect firms in a monopoly or oligopoly?","options":["Free movement of firms into and out of the industry","Homogeneous products sold by many firms","The need for a government licence to operate","Perfect knowledge of the market by all buyers"],"correctOption":2,"section":"Market Structure","explanation":"A licence requirement legally limits who can operate, so it keeps potential rivals out and protects existing firms. Options D and B are features of perfect competition, where there are no barriers. Option A is the absence of barriers."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 553, $official_bank_source${"itemId":"7f435a88-7d37-5465-aa54-1b43a7da5cce","questionId":"7d9799a8-0904-5d67-94e4-bfc317455359","sourceKey":"bank:LAG-BUA125:STR-041","payload":{"prompt":"Which statement best describes the products sold in an oligopoly?","options":["Each firm's product has no relationship to its rivals' products","There is only one product with no substitutes","They may be homogeneous and substitutable, although product differentiation also happens","They are always perfectly identical and never branded"],"correctOption":2,"section":"Market Structure","explanation":"Oligopoly products are substitutes for one another and can be fairly similar, but firms often differentiate them through branding and advertising. Option D is too strict, since differentiation does happen. Option B describes monopoly."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 554, $official_bank_source${"itemId":"1065d250-4898-5b8e-9389-029caaa19b96","questionId":"270d08cf-0fec-5207-8bc0-47fbd58a688b","sourceKey":"bank:LAG-BUA125:STR-042","payload":{"prompt":"Apart from economies of scale and legal barriers, which of the following can put a monopolist in a superior position in its industry?","options":["Access to market intelligence or technology that other firms cannot obtain","Having no control over the price of its product","Selling a product that has many close substitutes","Facing a perfectly elastic demand curve"],"correctOption":0,"section":"Market Structure","explanation":"A monopolist often has unique information or technology that rivals cannot get, which strengthens its hold on the market. Option C would weaken monopoly power, since buyers could switch. Options B and D describe a price taker in perfect competition."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 555, $official_bank_source${"itemId":"0da2e277-ff18-5bcd-881e-0bc0eb046933","questionId":"21416a68-b3f6-5f67-b07b-6cfd62b3604a","sourceKey":"bank:LAG-BUA125:STR-043","payload":{"prompt":"Normal profit is best described as","options":["total revenue minus fixed cost","the minimum profit needed to keep a firm in its present industry, earned when total revenue just covers total cost including opportunity cost","any profit above the level needed to keep the firm in the industry","profit earned only by monopolists"],"correctOption":1,"section":"Market Structure","explanation":"Normal profit is the return that just keeps the entrepreneur in the industry, so economic profit is zero when TR equals TC including opportunity cost. Option C defines supernormal (abnormal) profit. Option A ignores variable cost."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 556, $official_bank_source${"itemId":"0f8faaef-c101-515c-add5-d2e2a6bf04a9","questionId":"1cd39923-bdc2-56a5-bd63-440969e7b28b","sourceKey":"bank:LAG-BUA125:STR-044","payload":{"prompt":"A perfectly competitive sachet-water producer sells at the market price of N250 per bag. If it sells 640 bags, what are its total revenue and its marginal revenue per bag?","options":["TR = N640; MR = N250","TR = N160,000; MR = N125","TR = N160,000; MR = N250","TR = N160,000; MR = N0"],"correctOption":2,"section":"Market Structure","explanation":"TR = P x Q = 250 x 640 = N160,000, and since a price taker can sell each extra bag at the same N250, MR = P = N250. Option D assumes extra sales add no revenue. Option B halves the price, as for a straight-line monopoly demand curve, which does not apply to a price taker."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 557, $official_bank_source${"itemId":"58131530-1638-5eae-b2dc-802c27349ee4","questionId":"9716057e-8216-5561-ba7d-38461b036dcd","sourceKey":"bank:LAG-BUA125:STR-045","payload":{"prompt":"A monopolist's demand schedule is: Quantity 1, 2, 3, 4, 5, 6 units; Price N900, N800, N700, N600, N500, N400 respectively. What is the total revenue at 4 units?","options":["N2,400","N600","N300","N2,500"],"correctOption":0,"section":"Market Structure","explanation":"Total revenue = price x quantity = 600 x 4 = N2,400. Option B is the price (average revenue) at 4 units, not the total. Option C is the marginal revenue of the 4th unit (2,400 - 2,100)."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 558, $official_bank_source${"itemId":"2f703780-0010-59d4-80f9-561002210ccd","questionId":"298f879b-ed19-5a2c-82f8-705750220f0b","sourceKey":"bank:LAG-BUA125:STR-046","payload":{"prompt":"A monopolist's demand schedule is: Quantity 1, 2, 3, 4, 5, 6 units; Price N900, N800, N700, N600, N500, N400 respectively. What is the marginal revenue of the 3rd unit?","options":["N700","N100","N2,100","N500"],"correctOption":3,"section":"Market Structure","explanation":"MR = TR(3) - TR(2) = (700 x 3) - (800 x 2) = 2,100 - 1,600 = N500. Option A is the price of the 3rd unit; MR is lower because the price cut applies to all units sold. Option C is total revenue at 3 units."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 559, $official_bank_source${"itemId":"592dba79-5888-5652-a6ec-7349f73c175d","questionId":"6017cef9-23ad-5ecf-9751-7b1d152d5ee7","sourceKey":"bank:LAG-BUA125:STR-047","payload":{"prompt":"A monopolist's demand schedule is: Quantity 1, 2, 3, 4, 5, 6 units; Price N900, N800, N700, N600, N500, N400 respectively. At what output is the monopolist's total revenue at its maximum?","options":["1 unit","6 units","5 units","4 units"],"correctOption":2,"section":"Market Structure","explanation":"TR is N900, N1,600, N2,100, N2,400, N2,500 and N2,400, so it peaks at 5 units, where MR is still positive (N100) and the next unit has negative MR (-N100). Option B is wrong because the 6th unit lowers TR. Option A has the highest price but the lowest revenue."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 560, $official_bank_source${"itemId":"501c355a-1f3c-527b-97c5-e949f90dd46a","questionId":"e3775919-9f35-52bb-95d6-731ed271fbc7","sourceKey":"bank:LAG-BUA125:STR-048","payload":{"prompt":"A monopolist's demand schedule is: Quantity 1, 2, 3, 4, 5, 6 units; Price N900, N800, N700, N600, N500, N400 respectively. What is the average revenue at 5 units?","options":["N2,500","N417","N500","N100"],"correctOption":2,"section":"Market Structure","explanation":"Average revenue = TR / Q = 2,500 / 5 = N500, which equals the price at that output, as it always does when one price is charged. Option D is the marginal revenue of the 5th unit (N100). Option A is total revenue."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 561, $official_bank_source${"itemId":"a13de305-922b-505c-b6ec-6790c8263c47","questionId":"62fa23bd-c7a5-5c17-95db-2affb2c95a8b","sourceKey":"bank:LAG-BUA125:STR-049","payload":{"prompt":"A monopolist's demand schedule is: Quantity 1, 2, 3, 4, 5, 6 units; Price N900, N800, N700, N600, N500, N400 respectively. Its fixed cost is N400 and the marginal costs of units 1 to 6 are N300, N200, N250, N280, N400, N500 respectively. What output maximises the monopolist's profit?","options":["5 units","6 units","2 units","4 units"],"correctOption":3,"section":"Market Structure","explanation":"Marginal revenues are N900, N700, N500, N300, N100 and -N100. The 4th unit adds N300 to revenue but only N280 to cost, while every later unit adds more to cost than to revenue, so profit is highest at 4 units. Option A is the revenue-maximising output, where the 5th unit adds N100 of revenue but N400 of cost. Option C is where MC is lowest, which is not the profit rule."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 562, $official_bank_source${"itemId":"df36f800-345c-5ac7-9be6-4506e702ab7f","questionId":"7ca17832-1ccc-5889-9917-eec3aca82d9e","sourceKey":"bank:LAG-BUA125:STR-050","payload":{"prompt":"A monopolist's demand schedule is: Quantity 1, 2, 3, 4, 5, 6 units; Price N900, N800, N700, N600, N500, N400 respectively. Its fixed cost is N400 and the marginal costs of units 1 to 6 are N300, N200, N250, N280, N400, N500 respectively. What is the maximum profit the monopolist can earn?","options":["N2,400","N1,370","N970","N670"],"correctOption":2,"section":"Market Structure","explanation":"At the profit-maximising output of 4 units, TR = 600 x 4 = N2,400 and TC = 400 + 300 + 200 + 250 + 280 = N1,430, so profit = N970. Option B forgets the N400 fixed cost. Option D is the profit at 5 units, which is lower because the 5th unit costs more than it earns."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 563, $official_bank_source${"itemId":"7cdfe898-9987-5628-a823-76c65046a112","questionId":"06526d3d-a9c1-579a-a405-1d9d60bc1c17","sourceKey":"bank:LAG-BUA125:STR-051","payload":{"prompt":"A perfectly competitive firm maximises profit where MR = MC at 300 units. The market price is N80 and its average total cost at that output is N65. What is its total profit?","options":["N19,500","N4,500","N15","N24,000"],"correctOption":1,"section":"Market Structure","explanation":"Profit = (P - ATC) x Q = (80 - 65) x 300 = 15 x 300 = N4,500. Option C is profit per unit only. Options D and A are total revenue and total cost, not profit."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 564, $official_bank_source${"itemId":"92c2132d-a463-5528-a632-dd2a410d4d0c","questionId":"5b32bd07-a564-545f-8fec-6c4dfc7971b9","sourceKey":"bank:LAG-BUA125:STR-052","payload":{"prompt":"A competitive firm produces 500 units where MR = MC. The price is N40, its average total cost is N46 and its average variable cost is N35. What is its profit or loss, and should it keep producing in the short run?","options":["A profit of N2,500; it should keep producing","A loss of N3,000; it should shut down","A loss of N5,500; it should shut down","A loss of N3,000; it should keep producing"],"correctOption":3,"section":"Market Structure","explanation":"Loss = (P - ATC) x Q = (40 - 46) x 500 = -N3,000. Because price (N40) is above AVC (N35), the firm covers its variable cost and part of its fixed cost, so it should keep producing in the short run. Option B applies the shutdown rule wrongly, and option A uses AVC instead of ATC to find profit."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 565, $official_bank_source${"itemId":"b0a26469-0d3b-5c66-9b54-0dec69b5f9f1","questionId":"411e8c11-a515-5353-875a-e3b74cb51b5e","sourceKey":"bank:LAG-BUA125:STR-053","payload":{"prompt":"A competitive firm faces a price of N30. At its best output of 1,000 units, its average variable cost is N34 and its average fixed cost is N10. If it shuts down it loses only its fixed cost. By how much is its loss smaller if it shuts down instead of producing?","options":["N4,000","N14,000","N10,000","N0"],"correctOption":0,"section":"Market Structure","explanation":"Producing: loss = (30 - 44) x 1,000 = N14,000. Shutting down: loss = fixed cost = 10 x 1,000 = N10,000. So shutting down reduces the loss by N4,000, the amount by which price falls short of AVC on each unit. Option B is the total loss from producing, not the difference."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 566, $official_bank_source${"itemId":"9b77efec-d90d-5a44-b45a-c86dd48f555f","questionId":"c5ef70ab-edae-5966-9b99-4a615643faae","sourceKey":"bank:LAG-BUA125:STR-054","payload":{"prompt":"The market shares of the six largest cement producers in a country are 32%, 21%, 14%, 9%, 7% and 6%. What is the four-firm concentration ratio (CR4)?","options":["53%","76%","36%","89%"],"correctOption":1,"section":"Market Structure","explanation":"CR4 is the combined market share of the four largest firms: 32 + 21 + 14 + 9 = 76%. Option D adds all six firms. Option C adds the wrong four firms (the 3rd to 6th largest)."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 567, $official_bank_source${"itemId":"3933cc49-dc65-5aac-af2f-b0ee86fb3c45","questionId":"05c7f750-5e4c-5e15-a6dc-71fa7730b32d","sourceKey":"bank:LAG-BUA125:STR-055","payload":{"prompt":"Total industry sales of paint are N2,500 million. The four largest firms have sales of N450 million, N300 million, N150 million and N100 million. What is the four-firm concentration ratio?","options":["30%","40%","67%","18%"],"correctOption":1,"section":"Market Structure","explanation":"CR4 = (sales of the top four / total industry sales) x 100 = (1,000 / 2,500) x 100 = 40%. Option C divides by the sales of the other firms instead of total industry sales. Option A includes only the two largest firms."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_lag_bua125', 'add', 568, $official_bank_source${"itemId":"01517d0e-df28-5914-9a93-9f75ea3ae597","questionId":"817aa4a5-7137-5fd0-8cf9-fabeed48757c","sourceKey":"bank:LAG-BUA125:STR-056","payload":{"prompt":"In an industry, the two largest firms hold 48% and 39% of total sales, and the remaining 13% is shared by many tiny firms. What is the two-firm concentration ratio, and which structure does it suggest?","options":["87%; perfect competition","87%; a duopoly-like market dominated by two firms","13%; monopolistic competition","48%; monopoly"],"correctOption":1,"section":"Market Structure","explanation":"CR2 = 48 + 39 = 87%, so two firms dominate the industry, which points to a duopoly-type structure. Option A has the right ratio but the wrong meaning, since perfect competition has no dominant firms. Option C uses the share of the small firms instead."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 569, $official_bank_source${"itemId":"3f8fbbd7-96d4-5571-add0-b3c98ca0df28","questionId":"05b17d55-745a-5378-bc1e-1ff9563cd076","sourceKey":"bank:LAG-BUA125:STR-057","payload":{"prompt":"A firm's total revenue rises from N48,000 to N54,000 when its sales rise from 120 to 140 units. What is its marginal revenue per unit over this range?","options":["N6,000","N300","N386","N400"],"correctOption":1,"section":"Market Structure","explanation":"MR = change in TR / change in Q = (54,000 - 48,000) / (140 - 120) = 6,000 / 20 = N300. Option C is average revenue at 140 units. Option D is average revenue at 120 units."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 570, $official_bank_source${"itemId":"3d7b0f66-fe3a-5108-b4ce-1d47b9c89182","questionId":"ae5434db-0f0e-50ac-84e6-281e4e819103","sourceKey":"bank:LAG-BUA125:STR-058","payload":{"prompt":"A perfectly competitive egg farm sells 1,200 crates at N4,500 each. Its total cost is N4,860,000. What is its average total cost per crate, and is it earning supernormal profit?","options":["N4,050; no, because price is below ATC","N4,050; yes, because price is above ATC","N3,600; yes, because price is above ATC","N4,500; it is just breaking even"],"correctOption":1,"section":"Market Structure","explanation":"ATC = TC / Q = 4,860,000 / 1,200 = N4,050. Since price (N4,500) exceeds ATC, the farm earns supernormal profit of (4,500 - 4,050) x 1,200 = N540,000. Option A has the right ATC but the wrong comparison. Option D wrongly treats the price as the average cost."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 571, $official_bank_source${"itemId":"88e7037b-64cf-5d74-8d49-ca13a5522adb","questionId":"320ed47f-031c-5478-862e-d74a1bb2aa57","sourceKey":"bank:LAG-BUA125:STR-059","payload":{"prompt":"A monopolist's demand schedule is: Quantity 1, 2, 3, 4, 5, 6 units; Price N900, N800, N700, N600, N500, N400 respectively. Its fixed cost is N400 and the marginal costs of units 1 to 6 are N300, N200, N250, N280, N400, N500 respectively. What price will the monopolist charge at its profit-maximising output?","options":["N2,400","N500","N280","N600"],"correctOption":3,"section":"Market Structure","explanation":"Profit is maximised at 4 units, the last unit for which MR (N300) is not below MC (N280), and the monopolist then charges the highest price buyers will pay for 4 units, read from the demand schedule: N600. Option C sets price equal to MC, which a monopolist does not do because its price is above MR. Option B is the price at 5 units."}}$official_bank_source$::jsonb),
  ('official_bank_lag_bua125', 'add', 572, $official_bank_source${"itemId":"4d48cab0-e2d3-51ea-b6ce-b92dd4514a04","questionId":"2ac50bc9-be28-5d64-babc-6770cf2ab5c9","sourceKey":"bank:LAG-BUA125:STR-060","payload":{"prompt":"A perfectly competitive firm sells at a market price of N50. The marginal costs of its 1st to 6th units are N20, N30, N40, N48, N60 and N70. How many units should it produce to maximise profit?","options":["3 units","6 units","4 units","1 unit"],"correctOption":2,"section":"Market Structure","explanation":"For a price taker MR = P = N50, so it should produce every unit whose MC is below N50: the 4th unit costs N48 and adds N2 to profit, but the 5th costs N60. Option B would include units costing N60 and N70 that earn only N50 each. Option A stops early and gives up the profit on the 4th unit."}}$official_bank_source$::jsonb);
